@app.route("/admin/stock")
@owner_required
def admin_stock():
    conn = get_db()
    data = stock_overview(conn)
    vendors = conn.execute("SELECT id, name FROM vendors ORDER BY name").fetchall()
    recent = conn.execute(
        """SELECT stock_movements.*, stock_items.name AS item, stock_items.unit,
                  users.name AS who
           FROM stock_movements
           JOIN stock_items ON stock_items.id = stock_movements.stock_item_id
           LEFT JOIN users ON users.id = stock_movements.created_by_user_id
           ORDER BY stock_movements.id DESC LIMIT 40"""
    ).fetchall()
    # What is already promised to guests. A reorder level answers "is this
    # low?" — it cannot answer "is this enough?", which is the question that
    # matters. Two bottles is plenty until three guests have ordered champagne
    # on arrival.
    promised = committed_stock(conn, [r["item"]["id"] for r in data["rows"]])
    conn.close()
    for r in data["rows"]:
        r["promised"] = promised.get(r["item"]["id"], 0)
        r["after_promises"] = r["level"] - r["promised"]
    short = [r for r in data["rows"] if r["after_promises"] < 0]

    overview = [
        overview_cell("Items tracked", data["count"]),
        overview_cell("Short of what's promised", len(short), alert=len(short),
                      hint="already sold to a guest"),
        overview_cell("Need reordering", len(data["low"]), alert=len(data["low"])),
        overview_cell("Stock value", euro(data["value"]), hint="at cost"),
    ]
    vendor_names = {v["id"]: v["name"] for v in vendors}

    def level_state(r):
        # Ordered by how bad it is. "Short of what's promised" outranks
        # "running low": one is a forecast, the other is a guest who has
        # already been told yes.
        if r["level"] <= 0:
            return "Out"
        if r["after_promises"] < 0:
            return "Short of what's promised"
        return "Running low" if r["is_low"] else "In stock"

    lv = list_view(
        data["rows"], request.args,
        search=[lambda r: r["item"]["name"], lambda r: r["item"]["location"] or "",
                lambda r: STOCK_CATEGORIES.get(r["item"]["category"], "")],
        search_hint="Search item, category or where it's kept",
        facets=[
            # "Out" first: an empty shelf is a different problem from a low one,
            # and on a list sorted by name they look identical.
            facet("state", "Level", level_state,
                  order=["Out", "Short of what's promised", "Running low", "In stock"]),
            facet("category", "Category",
                  lambda r: STOCK_CATEGORIES.get(r["item"]["category"], r["item"]["category"])),
            facet("supplier", "Supplier",
                  lambda r: vendor_names.get(r["item"]["vendor_id"]), limit=10),
            facet("where", "Where it's kept", lambda r: (r["item"]["location"] or "").strip() or None,
                  limit=8),
        ],
        sorts=[
            # Shortest against real promises first — that is the one somebody
            # has already been told yes about.
            sort_option("urgent", "Most short first",
                        lambda r: (-r["after_promises"], r["short_by"]), reverse=True),
            sort_option("name", "Name", lambda r: (r["item"]["name"] or "").lower()),
            sort_option("value", "Most valuable",
                        lambda r: r["level"] * (r["item"]["unit_cost"] or 0), reverse=True),
            sort_option("category", "Category",
                        lambda r: (r["item"]["category"] or "", (r["item"]["name"] or "").lower())),
        ],
        default_sort="urgent",
    )
    return render_template("admin_stock.html", data=data, overview=overview, lv=lv,
                           rows=lv["rows"], vendors=vendors, recent=recent,
                           stock_categories=STOCK_CATEGORIES, stock_reasons=STOCK_REASONS)


@app.route("/admin/stock/new", methods=["POST"])
@owner_required
def new_stock_item():
    name = request.form.get("name", "").strip()
    if not name:
        flash("Give the item a name.", "error")
        return redirect(url_for("admin_stock"))
    category = request.form.get("category", "other")
    if category not in STOCK_CATEGORIES:
        category = "other"

    def num(field, default=0.0):
        raw = (request.form.get(field, "") or "").strip().replace(",", ".")
        try:
            return float(raw) if raw else default
        except ValueError:
            return default

    vendor_raw = request.form.get("vendor_id", "").strip()
    vendor_id = int(vendor_raw) if vendor_raw.isdigit() else None
    opening = num("opening_qty", 0.0)
    conn = get_db()
    if vendor_id is not None and missing_row(conn, "vendors", vendor_id):
        conn.close()
        flash("That supplier no longer exists — pick another, or add the item "
              "without one.", "error")
        return redirect(url_for("admin_stock"))
    conn.execute(
        """INSERT INTO stock_items (name, category, unit, reorder_level, unit_cost,
           vendor_id, location, notes, created_at) VALUES (?,?,?,?,?,?,?,?,?)""",
        (name, category, request.form.get("unit", "each").strip() or "each",
         num("reorder_level"), num("unit_cost", None) or None,
         vendor_id,
         request.form.get("location", "").strip() or None,
         request.form.get("notes", "").strip() or None,
         datetime.now(timezone.utc).isoformat()),
    )
    item_id = conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]
    # An opening balance is a movement like any other, so day one is on the
    # ledger rather than being an unexplained starting number.
    if opening:
        record_stock_movement(conn, item_id, opening, "opening",
                              user_id=(current_user() or {})["id"],
                              note="Opening balance")
    conn.commit()
    conn.close()
    flash(f"{name} added.", "success")
    return redirect(url_for("admin_stock"))


@app.route("/admin/stock/<int:item_id>/move", methods=["POST"])
@owner_required
def move_stock(item_id):
    reason = request.form.get("reason", "")
    if reason not in STOCK_REASONS:
        abort(400)
    raw = (request.form.get("quantity", "") or "").strip().replace(",", ".")
    try:
        qty = float(raw)
    except ValueError:
        flash("Enter a quantity.", "error")
        return redirect(url_for("admin_stock"))

    conn = get_db()
    # A movement against an item that is not there used to reach the INSERT and
    # raise a FOREIGN KEY error: a 500 with a stack trace instead of a 404, and
    # -- worse -- the connection was never closed, so it held its write lock and
    # the next query anywhere got "database is locked". Checking first is both
    # the right answer and the safe one.
    if not conn.execute("SELECT 1 FROM stock_items WHERE id = ?", (item_id,)).fetchone():
        conn.close()
        abort(404)
    if reason == "stocktake":
        # A stocktake is a COUNT, not a change: the movement is whatever it
        # takes to make the ledger agree with what's on the shelf, and the
        # difference is the interesting number.
        current = stock_levels(conn, [item_id]).get(item_id, 0)
        delta = qty - current
        note = f"Counted {qty:g} (was {current:g})"
    else:
        delta = abs(qty) if reason in ("purchase", "opening") else -abs(qty)
        note = request.form.get("note", "").strip() or None
    if delta or reason == "stocktake":
        record_stock_movement(conn, item_id, delta, reason,
                              user_id=(current_user() or {})["id"], note=note)
        conn.commit()
    conn.close()
    flash("Stock updated.", "success")
    return redirect(url_for("admin_stock"))


@app.route("/pos")
@login_required
def pos_home():
    """The floor. Every table, where it is in its service, and what it owes.

    A pass at this used to be a list of tabs with a total on each. What a
    section actually needs to know is which table has been waiting longest for
    food, which has ordered nothing yet, and which is ready for its bill.
    """
    conn = get_db()
    # The service's own day, not the calendar's — at one in the morning the
    # floor is still working tonight's covers and tonight's bookings.
    today = service_day()
    orders = conn.execute(
        "SELECT pos_orders.*, users.name AS opened_by FROM pos_orders "
        "LEFT JOIN users ON users.id = pos_orders.opened_by_user_id "
        "WHERE pos_orders.status = 'open' ORDER BY pos_orders.opened_at").fetchall()

    tables = []
    for o in orders:
        bill = pos_bill(conn, o["id"])
        waiting = conn.execute(
            """SELECT MIN(sent_at) AS since FROM pos_order_lines
               WHERE order_id = ? AND voided = 0 AND state = 'sent'""", (o["id"],)).fetchone()
        ctx = pos_table_context(conn, o)
        tables.append({
            "order": o, "total": bill["total"], "unsent": len(bill["unsent"]),
            "waiting_minutes": minutes_since(waiting["since"]) if waiting["since"] else None,
            "sitting_minutes": minutes_since(o["opened_at"]),
            "guest": ctx["booking"]["guest_name"] if ctx else None,
            "dietary": ctx["dietary"] if ctx else "",
            "state": o["service_state"] or "seated",
        })

    # Tonight's reservations that have not been sat yet — so a table can be
    # opened against its booking, and the allergy taken at booking travels
    # with it instead of being retyped or forgotten.
    seated_ids = {o["restaurant_booking_id"] for o in orders if o["restaurant_booking_id"]}
    expected = [b for b in conn.execute(
        """SELECT * FROM restaurant_bookings
           WHERE dinner_date = ? AND status = 'confirmed' AND no_show_at IS NULL
           ORDER BY guest_name""", (today.isoformat(),)).fetchall()
        if b["id"] not in seated_ids]

    report = pos_day_report(conn, today)
    settled_today = report["taken"]

    # The room itself. Each tile carries the live figures worked out above when
    # the table is occupied, so a free table and a busy one are the same object
    # to the template and the floor reads as one grid.
    by_order_id = {t["order"]["id"]: t for t in tables}
    floor = pos_floor(conn)
    for area in floor["areas"]:
        for tile in area["tiles"]:
            tile["live"] = by_order_id.get(tile["order"]["id"]) if tile["order"] else None
    off_plan = [by_order_id[o["id"]] for o in floor["off_plan"] if o["id"] in by_order_id]
    free_tables = [t for a in floor["areas"] for t in a["tiles"] if not t["order"]]
    conn.close()

    overview = [
        overview_cell("Open tables", len(orders)),
        overview_cell("Covers sitting", sum(t["order"]["covers"] or 0 for t in tables)),
        overview_cell("On open tabs", euro(sum(t["total"] for t in tables))),
        overview_cell("Taken today", euro(settled_today), endpoint="pos_day"),
        overview_cell("Still to arrive", len(expected)),
    ]
    return render_template(
        "pos_home.html", tables=tables, expected=expected, overview=overview,
        today=today, service_states=POS_SERVICE_STATES,
        floor=floor, off_plan=off_plan, free_tables=free_tables,
        # Worked out here rather than in the template: the till bar is a strip
        # of four figures, and a strip is not the place for arithmetic.
        open_count=len(orders),
        covers_sitting=sum(t["order"]["covers"] or 0 for t in tables),
        on_tabs=round(sum(t["total"] for t in tables), 2),
        taken_today=settled_today)


