def _expense_pennylane_lines(conn, expense):
    """The invoice lines to send.

    If the invoice was read into stock, each stock line becomes an accounting
    line on the code of the item it stocked — so the classification already
    done here is the classification the accountant receives.
    """
    vat = tax_rate(conn, "vat_food") or 20.0
    stocked = conn.execute(
        """SELECT stock_movements.delta, stock_movements.unit_cost,
                  stock_items.name, stock_items.ledger_code
           FROM stock_movements JOIN stock_items ON stock_items.id = stock_movements.stock_item_id
           WHERE stock_movements.expense_id = ? AND stock_movements.delta > 0""",
        (expense["id"],)).fetchall()

    lines, accounted = [], 0.0
    for row in stocked:
        if not row["unit_cost"]:
            continue
        net = round(row["delta"] * row["unit_cost"], 2)
        accounted += net
        line = {"currency_amount": f"{net:.2f}",
                "currency_tax": f"{round(net * vat / 100, 2):.2f}",
                "vat_rate": f"FR_{int(vat) * 10:03d}", "label": row["name"][:200]}
        if row["ledger_code"]:
            line["ledger_account_number"] = row["ledger_code"]
        lines.append(line)

    total = float(expense["amount"] or 0)
    # Whatever the stock lines didn't account for goes on one balancing line —
    # Pennylane rejects an invoice whose lines don't add up to its total.
    remainder = round(total - round(accounted * (1 + vat / 100), 2), 2)
    if not lines or abs(remainder) >= 0.01:
        gross = remainder if lines else total
        net = round(gross / (1 + vat / 100), 2)
        line = {"currency_amount": f"{net:.2f}", "currency_tax": f"{round(gross - net, 2):.2f}",
                "vat_rate": f"FR_{int(vat) * 10:03d}",
                "label": (expense["description"] or "Other")[:200]}
        if expense["ledger_code"]:
            line["ledger_account_number"] = expense["ledger_code"]
        lines.append(line)
    return lines


@app.route("/expenses/<int:expense_id>/send-to-pennylane", methods=["POST"])
@owner_required
def send_to_pennylane(expense_id):
    """Push a cost, with its document, into Pennylane."""
    conn = get_db()
    expense = conn.execute("SELECT * FROM expenses WHERE id = ?", (expense_id,)).fetchone()
    if not expense:
        conn.close()
        abort(404)
    if expense["pennylane_invoice_id"]:
        conn.close()
        flash("That's already in Pennylane.", "error")
        return redirect(url_for("expenses"))
    if not pennylane_configured():
        conn.close()
        flash("Pennylane isn't connected — add PENNYLANE_API_TOKEN. See DEPLOY.md.", "error")
        return redirect(url_for("expenses"))
    if not expense["filename"]:
        conn.close()
        flash("Attach the invoice or a photo of it first.", "error")
        return redirect(url_for("expenses"))
    path = os.path.join(UPLOAD_DIR, expense["filename"])
    if not os.path.exists(path):
        conn.close()
        flash("The file is missing from the server.", "error")
        return redirect(url_for("expenses"))
    with open(path, "rb") as fh:
        raw = fh.read()
    guessed = "application/pdf" if expense["filename"].lower().endswith(".pdf") else "image/jpeg"
    pdf_bytes, _ = ensure_pdf(raw, guessed, expense["vendor_name"] or "Invoice")

    ok, supplier_id = pennylane_find_supplier((expense["vendor_name"] or "").strip())
    if not ok:
        conn.close()
        flash(f"Couldn't set up the supplier in Pennylane: {supplier_id}", "error")
        return redirect(url_for("expenses"))
    ok, file_id = pennylane_upload_file(
        pdf_bytes, f"{secure_filename(expense['vendor_name'] or 'invoice')}-{expense_id}.pdf")
    if not ok:
        conn.execute("UPDATE expenses SET pennylane_error = ? WHERE id = ?",
                     (str(file_id)[:400], expense_id))
        conn.commit()
        conn.close()
        flash(f"Pennylane wouldn't take the file: {file_id}", "error")
        return redirect(url_for("expenses"))

    # The invoice's own facts, not facts about the upload. Every one of these
    # used to be invented here: the date it happened to be uploaded standing in
    # for the date printed on it, the same day again as the payment deadline so
    # that everything arrived already overdue, and the DESCRIPTION sent as the
    # invoice number, which meant nothing could ever be reconciled against a
    # supplier's own statement.
    # The date on the paper, whichever kind of paper it is. A supplier invoice
    # carries invoice_date; a staff claim carries spent_on. This read only the
    # first, so fixing the date for supplier invoices left every STAFF claim
    # still dated by the day it happened to be handed in -- half a fix, and
    # the helper written for both was sitting there uncalled.
    issued = (expense_document_date(expense)
              or house_date_iso(expense["submitted_at"]) or house_today_iso())
    deadline = expense["due_date"] or issued
    total = float(expense["amount"] or 0)
    stated_tax, _why = supplier_invoice_tax(conn, expense)
    if stated_tax is None:
        # Derived only as a last resort, and only for invoices that predate
        # the field. Guessing a rate is a wrong number on the return rather
        # than a missing one, so anything new is asked for instead.
        vat = tax_rate(conn, "vat_food") or 20.0
        stated_tax = round(total - total / (1 + vat / 100), 2)
    ok, result = pennylane_import_supplier_invoice(
        file_attachment_id=file_id, supplier_id=supplier_id, date=issued, deadline=deadline,
        amount=total, tax=stated_tax,
        lines=_expense_pennylane_lines(conn, expense),
        invoice_number=(expense["invoice_number"] or expense["description"] or "")[:60] or None,
        external_reference=f"gudanes-expense-{expense_id}")
    if not ok:
        conn.execute("UPDATE expenses SET pennylane_error = ? WHERE id = ?",
                     (str(result)[:400], expense_id))
        conn.commit()
        conn.close()
        flash(f"Pennylane refused the invoice: {result}", "error")
        return redirect(url_for("expenses"))

    invoice_id = str(result.get("id") or (result.get("invoice") or {}).get("id") or "")
    conn.execute(
        """UPDATE expenses SET pennylane_invoice_id = ?, pennylane_synced_at = ?,
           pennylane_error = NULL WHERE id = ?""",
        (invoice_id, datetime.now(timezone.utc).isoformat(), expense_id))
    log_audit(conn, "pennylane_sent", f"expense #{expense_id}",
              f"{expense['vendor_name']} — Pennylane invoice {invoice_id}")
    conn.commit()
    conn.close()
    flash("Sent to Pennylane with the document attached.", "success")
    return redirect(url_for("expenses"))


@app.route("/expenses/scan", methods=["POST"])
@owner_required
def scan_expense():
    """Pull a page straight off the network scanner and file it as an invoice."""
    if not scanner_configured():
        flash("No scanner is set up. Add SCANNER_URL, or photograph it instead.", "error")
        return redirect(url_for("expenses"))
    reachable, info = scanner_status()
    if not reachable:
        flash(f"{info} Photograph it instead if you're not at the château.", "error")
        return redirect(url_for("expenses"))
    source = "Feeder" if request.form.get("feeder") and (info or {}).get("feeder") else "Platen"
    ok, data, mimetype = scan_document(source=source)
    if not ok:
        flash(f"The scan didn't work: {data}", "error")
        return redirect(url_for("expenses"))
    pdf_bytes, ext = ensure_pdf(data, mimetype, "Scan")
    stored = f"scan_{secrets.token_hex(6)}.{ext}"
    with open(os.path.join(UPLOAD_DIR, stored), "wb") as fh:
        fh.write(pdf_bytes)
    conn = get_db()
    conn.execute(
        """INSERT INTO expenses (kind, vendor_name, description, amount, filename, status,
           submitted_by_user_id, submitted_at)
           VALUES ('supplier_invoice', ?, 'Scanned — needs details', 0, ?, 'pending', ?, ?)""",
        ((request.form.get("vendor_name", "") or "").strip() or "Scanned invoice", stored,
         (current_user() or {})["id"], datetime.now(timezone.utc).isoformat()))
    conn.commit()
    conn.close()
    flash("Scanned. Add the supplier and amount, then send it to Pennylane.", "success")
    return redirect(url_for("expenses"))


@app.route("/expenses/<int:expense_id>/read-invoice", methods=["POST"])
@owner_required
def read_invoice(expense_id):
    """Read a supplier invoice PDF and propose what it delivered.

    Proposes only — an invoice misread by one decimal would otherwise corrupt
    both the stock level and its valuation, silently.
    """
    conn = get_db()
    expense = conn.execute("SELECT * FROM expenses WHERE id = ?", (expense_id,)).fetchone()
    if not expense:
        conn.close()
        abort(404)
    if not expense["filename"]:
        conn.close()
        flash("There's no file attached to this invoice.", "error")
        return redirect(url_for("expenses"))
    if not expense["filename"].lower().endswith(".pdf"):
        conn.close()
        flash("Only PDF invoices can be read automatically — add the stock by hand.", "error")
        return redirect(url_for("expenses"))
    if not claude_configured():
        conn.close()
        flash("Invoice reading needs ANTHROPIC_API_KEY to be set — see DEPLOY.md.", "error")
        return redirect(url_for("expenses"))
    already = conn.execute(
        "SELECT COUNT(*) AS c FROM stock_movements WHERE expense_id = ?", (expense_id,)).fetchone()["c"]
    items = conn.execute("SELECT * FROM stock_items WHERE active = 1 ORDER BY name").fetchall()
    conn.close()

    path = os.path.join(UPLOAD_DIR, expense["filename"])
    if not os.path.exists(path):
        flash("The invoice file is missing from the server.", "error")
        return redirect(url_for("expenses"))
    with open(path, "rb") as fh:
        pdf_bytes = fh.read()
    result = read_invoice_with_claude(pdf_bytes, expense["filename"], items)
    if not result:
        flash("Couldn't read that invoice — add the stock by hand.", "error")
        return redirect(url_for("expenses"))
    by_id = {i["id"]: i for i in items}
    for line in result["lines"]:
        match = by_id.get(line.get("stock_item_id"))
        line["match_name"] = match["name"] if match else None
        line["match_unit"] = match["unit"] if match else None
    return render_template("invoice_review.html", expense=expense, result=result,
                           items=items, already=already)


@app.route("/expenses/<int:expense_id>/apply-invoice", methods=["POST"])
@owner_required
def apply_invoice(expense_id):
    """Book the confirmed lines into stock. Only what was ticked, at whatever
    quantity the owner left in the form — their edit beats the suggestion."""
    conn = get_db()
    if not conn.execute("SELECT 1 FROM expenses WHERE id = ?", (expense_id,)).fetchone():
        conn.close()
        abort(404)
    user_id = (current_user() or {})["id"]
    applied = 0
    for idx in request.form.getlist("apply"):
        item_raw = (request.form.get(f"item_{idx}", "") or "").strip()
        qty_raw = (request.form.get(f"qty_{idx}", "") or "").strip().replace(",", ".")
        cost_raw = (request.form.get(f"cost_{idx}", "") or "").strip().replace(",", ".")
        if not item_raw.isdigit():
            continue
        try:
            qty = float(qty_raw)
        except ValueError:
            continue
        if qty <= 0:
            continue
        try:
            unit_cost = float(cost_raw) if cost_raw else None
        except ValueError:
            unit_cost = None
        # What the invoice charged for, if it differs from what turned up.
        # Optional and normally blank: on the ordinary delivery where
        # everything arrived, filling it in is typing the same number
        # twice. It is for the day it does not.
        invoiced = parse_quantity(request.form.get(f"invoiced_{idx}", ""))
        record_stock_movement(conn, int(item_raw), qty, "purchase", unit_cost=unit_cost,
                              expense_id=expense_id, user_id=user_id,
                              note=(request.form.get(f"desc_{idx}", "") or "").strip()[:120] or None,
                              invoiced_quantity=(invoiced if invoiced is not None
                                                 and invoiced != qty else None))
        # Keep the item's cost current, so the valuation reflects what was last
        # actually paid rather than whatever was typed when it was created.
        if unit_cost:
            conn.execute("UPDATE stock_items SET unit_cost = ? WHERE id = ?", (unit_cost, int(item_raw)))
        applied += 1
    if applied:
        log_audit(conn, "invoice_stocked", f"expense #{expense_id}", f"{applied} line(s)")
        conn.commit()
    conn.close()
    flash(f"{applied} line{'' if applied == 1 else 's'} added to stock." if applied
          else "Nothing was ticked, so nothing changed.", "success" if applied else "error")
    return redirect(url_for("admin_stock"))


# ---------------------------------------------------------------------------
# The guest's account.
#
# Everything they have with the château on one page: stays, dinners, workshops,
# events. No password — they prove the email owns the bookings by receiving a
# link at it. Every action from here still runs through the SAME routes as the
# per-booking manage pages, so there is one implementation of "cancel" and one
# of "add an extra", not two that drift apart.
# ---------------------------------------------------------------------------

GUEST_SESSION_HOURS = 48


def guest_account_bookings(conn, email):
    """Everything this address has with the château, newest first."""
    e = (email or "").strip().lower()
    rooms = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE LOWER(bookings.guest_email) = ? AND bookings.status != 'declined'
           ORDER BY bookings.arrival_date DESC""", (e,)).fetchall()
    dinners = conn.execute(
        """SELECT * FROM restaurant_bookings WHERE LOWER(guest_email) = ?
           AND status != 'declined' ORDER BY dinner_date DESC""", (e,)).fetchall()
    workshops = conn.execute(
        """SELECT workshop_bookings.*, workshops.title AS workshop_title,
                  workshop_sessions.start_date, workshop_sessions.end_date
           FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE LOWER(workshop_bookings.guest_email) = ?
             AND workshop_bookings.status != 'declined'
           ORDER BY workshop_sessions.start_date DESC""", (e,)).fetchall()
    events = conn.execute(
        """SELECT * FROM event_inquiries WHERE LOWER(contact_email) = ?
           ORDER BY preferred_date DESC""", (e,)).fetchall()
    return {"rooms": rooms, "dinners": dinners, "workshops": workshops, "events": events}


def guest_account_balance(conn, data):
    """What this account owes across every stay on it, and per stay.

    The account page used to print each booking's total_price and stop there,
    which is the price of the stay rather than the money still owed — two
    different numbers the moment anything is paid, and a third once a dinner
    charged to the room lands on the bill as an extra. A guest with two stays
    had to open each one to find out where they stood.

    Built on booking_bill, so it is the same arithmetic the manage page and the
    statement already show; there is one definition of what is owed and this is
    not a second one. Cancelled stays are excluded — the bill still exists for
    the record, but it is not money anybody is being asked for.
    """
    per_booking, total = {}, 0.0
    for booking in data.get("rooms", []):
        if booking["status"] in ("cancelled", "declined"):
            continue
        bill = booking_bill(conn, booking["id"])
        if not bill:
            continue
        owed = bill["owed"]
        per_booking[booking["id"]] = {
            "owed": owed,
            "total": bill["total"],
            "paid": bill["paid"],
            "due_date": booking["balance_due_date"],
            "manage_token": booking["manage_token"],
        }
        total += owed
    return {"per_booking": per_booking, "total": round(total, 2)}


@app.route("/my-account", methods=["GET", "POST"])
def guest_account_request():
    """Ask for a link to your account.

    Deliberately gives the SAME answer whether or not the address has bookings.
    Telling a stranger "no bookings found" turns this into a way of asking
    whether someone has stayed at the château, which is not ours to answer.
    """
    sent = False
    if request.method == "POST":
        email = (request.form.get("email", "") or "").strip().lower()
        conn = get_db()
        if rate_limited(conn, "guest_account_link", 5):
            conn.commit()
            conn.close()
            flash("Too many requests just now — try again shortly.", "error")
            return render_template("guest_account_request.html", sent=False)
        if EMAIL_RE.match(email):
            data = guest_account_bookings(conn, email)
            if any(data.values()):
                token = secrets.token_urlsafe(32)
                now = datetime.now(timezone.utc)
                conn.execute(
                    """INSERT INTO guest_sessions (email, token, created_at, expires_at, requested_ip)
                       VALUES (?,?,?,?,?)""",
                    (email, token, now.isoformat(),
                     (now + timedelta(hours=GUEST_SESSION_HOURS)).isoformat(),
                     (request.headers.get("X-Forwarded-For") or request.remote_addr or "")[:64]))
                link = url_for("guest_account", token=token, _external=True)
                # Commit the session row before sending. send_email's outbox
                # fallback opens its own connection and cannot write while this
                # one is open, so the link was being dropped instead of held —
                # and this page deliberately says "sent" whether or not the
                # address is known, so nobody at either end would ever find out.
                conn.commit()
                send_email(
                    email, "Your Château de Gudanes bookings",
                    f"Here is the link to everything you have booked with us:\n\n{link}\n\n"
                    f"It works for the next {GUEST_SESSION_HOURS} hours. If you didn't ask "
                    "for this, you can ignore it — nothing has changed.")
        conn.commit()
        conn.close()
        sent = True          # same answer either way
    return render_template("guest_account_request.html", sent=sent)


def _valid_guest_session(conn, token):
    row = conn.execute(
        "SELECT * FROM guest_sessions WHERE token = ?", (token,)).fetchone()
    if not row:
        return None
    if row["expires_at"] < datetime.now(timezone.utc).isoformat():
        return None
    return row


@app.route("/my-account/<token>/ask", methods=["POST"])
def guest_account_message(token):
    """A message to the house from the account page.

    Until now the only way to reach anybody was from inside a specific booking,
    which is the wrong shape for half the reasons a guest writes: a question
    about the next stay, an address that is wrong, or something that touches
    two bookings at once. The page listed everything they had and offered no
    way to say anything about it.

    Deliberately not a booking action. It is a note from a person the house
    already knows, so it goes to the owner with the address the link was issued
    to — the guest cannot type a different one, and nothing here is taken on
    trust from the form except the words.
    """
    conn = get_db()
    session_row = _valid_guest_session(conn, token)
    if not session_row:
        conn.close()
        return render_template("guest_account_expired.html"), 404

    message = (request.form.get("message", "") or "").strip()[:2000]
    if not message:
        conn.close()
        flash("Write something first and we will read it.", "error")
        return redirect(url_for("guest_account", token=token))

    if rate_limited(conn, "guest_account_message", BOOKING_RATE_LIMIT_PER_HOUR):
        conn.commit()
        conn.close()
        flash("Thank you — we have that.", "success")   # same answer either way
        return redirect(url_for("guest_account", token=token))

    owner_to = owner_email(conn)
    log_audit(conn, "guest_wrote_in", target=session_row["email"],
              details=message[:200])
    # Committed before the send: send_email falls back to the outbox on its own
    # connection, which cannot write while this transaction is open. That is
    # the fault that lost six routes' worth of held mail.
    conn.commit()
    conn.close()
    if owner_to:
        send_email(
            owner_to, f"A guest wrote in — {session_row['email']}",
            f"From {session_row['email']}, through their account page:\n\n"
            f"{message}\n\n— Château de Gudanes")
    flash("Thank you — we have that, and will come back to you.", "success")
    return redirect(url_for("guest_account", token=token))


@app.route("/my-account/<token>")
def guest_account(token):
    conn = get_db()
    session_row = _valid_guest_session(conn, token)
    if not session_row:
        conn.close()
        return render_template("guest_account_expired.html"), 404
    # Mark first use, but keep the link working for the rest of its life — a
    # guest will open it, wander off, and come back. Single-use-on-first-click
    # would just generate support calls.
    if not session_row["used_at"]:
        conn.execute("UPDATE guest_sessions SET used_at = ? WHERE id = ?",
                     (datetime.now(timezone.utc).isoformat(), session_row["id"]))
        conn.commit()

    data = guest_account_bookings(conn, session_row["email"])
    today = house_today_iso()
    extras = conn.execute(
        """SELECT * FROM extras WHERE active = 1 AND guest_bookable = 1
           ORDER BY category, sort_order, name""").fetchall()
    # Read before the connection closes, and read at all: this line referred to
    # a `restaurant_settings` that was never defined in the function, so every
    # visit raised NameError and the whole page 500'd. A guest asked for their
    # account link, received it, clicked it, and got an error — the one part of
    # this flow they could not work around, since the link IS the way in.
    restaurant_settings = get_restaurant_settings(conn)
    balance = guest_account_balance(conn, data)
    # What they keep on their own record. None when this address has no
    # profile, in which case the form does not render -- there is nothing to
    # write to, and a form that silently saves nowhere is worse than none.
    own = guest_own_record(conn, session_row["email"])
    conn.close()
    return render_template(
        "guest_account.html", email=session_row["email"], token=token,
        data=data, today=today, extras=extras, balance=balance,
        can_pay_online=stripe_enabled(), own=own,
        restaurant_open=bool(restaurant_settings and restaurant_settings["enabled"]),
        expires=session_row["expires_at"])


@app.route("/my-account/<token>/details", methods=["POST"])
def save_guest_details(token):
    """Let a guest keep their own details, and empty them.

    Emptying is half the feature. A form that can only ever add is data
    somebody holds about you; one you can clear is a record you keep.
    """
    conn = get_db()
    session_row = _valid_guest_session(conn, token)
    if not session_row:
        conn.close()
        return render_template("guest_account_expired.html"), 404
    saved = save_guest_own_record(
        conn, session_row["email"],
        dietary=request.form.get("dietary_notes"),
        access=request.form.get("access_needs"),
        arrival=request.form.get("usual_arrival_time"),
        phone=request.form.get("phone"))
    conn.commit()
    conn.close()
    flash("Kept. We will offer these back next time." if saved
          else "There is nothing to save this against yet \u2014 it appears "
               "once you have stayed.",
          "success" if saved else "error")
    return redirect(url_for("guest_account", token=token))


@app.route("/booking/<manage_token>/statement/email", methods=["POST"])
@csrf.exempt
def email_booking_statement(manage_token):
    """Send the guest their own statement.

    The bill is already a page they can open with their manage token, and a
    business guest needs it as something they can forward to whoever pays.
    Asking them to print a web page to PDF is asking them to do our job.

    Sent only to the address ON THE BOOKING, never to one typed into the form.
    The token is the credential, so letting the form choose the recipient would
    turn every guest's bill into something anybody holding a link could post to
    themselves. That is why there is no address field.

    CSRF-exempt for the same reason the unsubscribe route is: the guest arrives
    from their own confirmation with no session, and the worst a forged POST can
    do is send a guest their own bill to their own address.
    """
    conn = get_db()
    booking = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
             JOIN rooms ON rooms.id = bookings.room_id
            WHERE bookings.manage_token = ?""", (manage_token,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    address = (booking["guest_email"] or "").strip()
    if not address:
        conn.close()
        flash("There is no email address on this booking.", "error")
        return redirect(url_for("manage_booking", manage_token=manage_token))

    statement = guest_statement(conn, booking)
    company = conn.execute("SELECT * FROM company_info WHERE id = 1").fetchone()
    conn.close()

    # Built from the statement's own fields: accommodation, each extra by name,
    # taxe de sejour on its own because it carries no VAT, then the VAT bands.
    lines = [f"  {statement['nights']} night(s), {booking['room_name']}"
             f"   €{statement['accommodation']:.2f}"]
    for extra in statement["extras"]:
        amount = (extra["unit_price"] or 0) * (extra["quantity"] or 0)
        lines.append(f"  {extra['quantity']} x {extra['name']}   €{amount:.2f}")
    if statement["city_tax"]:
        lines.append(f"  Taxe de sejour   €{statement['city_tax']:.2f}")
    for band in statement["vat"]:
        lines.append(f"  of which VAT at {band['rate']}%   €{band['vat']:.2f}")

    who = []
    if company:
        for key in ("legal_name", "registered_address", "registration_number",
                    "vat_number"):
            value = " ".join((company[key] or "").split())
            if value:
                who.append(value)

    body = (
        f"Hi {booking['guest_name']},\n\n"
        f"Your statement for {booking['room_name']}, "
        f"{format_date_human(booking['arrival_date'])} to "
        f"{format_date_human(booking['departure_date'])}.\n\n"
        + "\n".join(lines) + "\n\n"
        f"  Total   €{statement['total']:.2f}\n"
        f"  Received   €{statement['paid']:.2f}\n"
        f"  Still to pay   €{statement['balance'] if statement['balance'] > 0 else 0:.2f}\n\n"
        f"Reference code: {booking['reference_code']}\n"
        f"The full statement, and the way to settle it, is here:\n"
        f"{url_for('booking_statement', manage_token=manage_token, _external=True)}\n"
        + (("\n" + "\n".join(who) + "\n") if who else "")
        + "\n— Château de Gudanes")
    if send_email(address, f"Your statement — {booking['reference_code']}", body):
        flash(f"Sent to {address}.", "success")
    else:
        flash("No email provider is connected yet, so it is being held and will "
              "go out once one is.", "error")
    return redirect(url_for("booking_statement", manage_token=manage_token))


@app.route("/booking/<manage_token>/statement")
def booking_statement(manage_token):
    """The guest's bill.

    Opened with the booking's own manage token, so a guest reaches it from
    their confirmation without an account — the same way they already manage
    the booking. A business guest needs this document to reclaim their VAT.
    """
    conn = get_db()
    booking = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.manage_token = ?""", (manage_token,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    statement = guest_statement(conn, booking)
    company = conn.execute("SELECT * FROM company_info WHERE id = 1").fetchone()
    conn.close()
    return render_template("guest_statement.html", booking=booking, s=statement,
                           company=company, employer=EMPLOYER_LEGAL_NAME)


