@app.route("/guests/<int:guest_id>/link-bookings", methods=["POST"])
@owner_required
def link_guest_bookings(guest_id):
    """Attach the stays that match this profile's address to the profile.

    They already show on the record \u2014 matched on the address rather than
    linked \u2014 and this makes the inference a fact. Worth doing rather than
    leaving implicit, because a guest who later changes their address keeps
    the history that was linked and loses the history that was only guessed.
    """
    conn = get_db()
    guest = conn.execute("SELECT * FROM guests WHERE id = ?", (guest_id,)).fetchone()
    if not guest:
        conn.close()
        abort(404)
    email = (guest["email"] or "").strip().lower()
    if not email:
        conn.close()
        flash("This profile has no address to match on.", "error")
        return redirect(url_for("guest_detail", guest_id=guest_id))
    cur = conn.execute(
        """UPDATE bookings SET linked_guest_id = ?
            WHERE LOWER(TRIM(guest_email)) = ? AND linked_guest_id IS NULL""",
        (guest_id, email))
    log_audit(conn, "guest_bookings_linked", target=guest["name"],
              details=f"{cur.rowcount} stay(s)")
    conn.commit()
    conn.close()
    flash(f"{cur.rowcount} stay{'' if cur.rowcount == 1 else 's'} attached to "
          f"{guest['name']}.", "success")
    return redirect(url_for("guest_detail", guest_id=guest_id))


@app.route("/guests/<int:guest_id>/edit", methods=["GET", "POST"])
@owner_required
def edit_guest(guest_id):
    conn = get_db()
    guest = conn.execute("SELECT * FROM guests WHERE id = ?", (guest_id,)).fetchone()
    if not guest:
        conn.close()
        abort(404)

    if request.method == "POST":
        name = request.form.get("name", "").strip()
        email = request.form.get("email", "").strip().lower() or None
        phone = request.form.get("phone", "").strip()
        dietary_notes = request.form.get("dietary_notes", "").strip()
        preferences = request.form.get("preferences", "").strip()
        vip = 1 if request.form.get("vip") else 0
        notes = request.form.get("notes", "").strip()
        access_needs = request.form.get("access_needs", "").strip()[:600]

        if email and conn.execute(
            "SELECT id FROM guests WHERE email = ? COLLATE NOCASE AND id != ?", (email, guest_id)
        ).fetchone():
            conn.close()
            flash(f"Another guest profile already uses the email {email}.", "error")
            return redirect(url_for("edit_guest", guest_id=guest_id))
        conn.execute(
            """UPDATE guests SET name=?, email=?, phone=?, dietary_notes=?,
               preferences=?, vip=?, notes=?, access_needs=?,
               -- Stamped only when there is something to stamp, and cleared
               -- with it. A date left behind on an emptied field is a record
               -- that somebody told us something, which is the fact we said
               -- we would stop holding.
               access_needs_updated_at=? WHERE id=?""",
            (name, email, phone or None, dietary_notes or None,
             preferences or None, vip, notes or None, access_needs or None,
             datetime.now(timezone.utc).isoformat() if access_needs else None,
             guest_id),
        )
        conn.commit()
        conn.close()
        flash("Guest profile updated.", "success")
        return redirect(url_for("guests"))

    conn.close()
    return render_template("guest_form.html", guest=guest)


