@app.route("/supplier-invoices/submit/<token>", methods=["GET", "POST"])
def supplier_invoice_submit(token):
    """A supplier sending in an invoice, through their own link or the shared one.

    TWO KINDS OF LINK, and the difference matters. A supplier the house has set
    up has their own: it names them, so they are not asked to type a company
    name that could be mistyped or borrowed, it can be withdrawn from them
    alone, and their invoices are attributed without anybody matching text.
    The shared link still works for a supplier nobody has set up yet — but
    what arrives through it is marked as unidentified rather than trusted.

    THE INVOICE'S OWN FACTS are asked for here, which is the whole point. The
    number, the date on the paper and the VAT stated on it used to be invented
    later from what was to hand: the upload date standing in for the invoice
    date, and the description standing in for the invoice number.
    """
    conn = get_db()
    vendor = vendor_for_token(conn, token)
    if not vendor:
        stored = conn.execute(
            "SELECT value FROM app_settings WHERE key = 'supplier_upload_token'"
        ).fetchone()
        if not stored or not hmac.compare_digest(token, stored["value"]):
            conn.close()
            abort(404)

    def form(**kw):
        return render_template("supplier_invoice_form.html", vendor=vendor,
                               today=house_today_iso(), **kw)

    if request.method == "POST":
        # Rate limited per link. Without this the address is a way for whoever
        # holds it to put any number of rows into the house's payables, and
        # the shared one has been forwarded around for a year.
        if rate_limited(conn, f"supplier_invoice:{token[:16]}", BOOKING_RATE_LIMIT_PER_HOUR):
            conn.commit()
            conn.close()
            flash("That is a lot of invoices at once. Please try again shortly, "
                  "or email them to us.", "error")
            return form()

        vendor_name = (vendor["name"] if vendor
                       else request.form.get("vendor_name", "").strip())
        description = request.form.get("description", "").strip()
        amount_raw = request.form.get("amount", "").strip()
        invoice_number = request.form.get("invoice_number", "").strip()[:60]
        invoice_date_raw = request.form.get("invoice_date", "").strip()
        tax_raw = request.form.get("tax_amount", "").strip()
        file = request.files.get("invoice")

        try:
            amount = float(amount_raw)
        except ValueError:
            amount = None
        try:
            tax_amount = float(tax_raw) if tax_raw else None
        except ValueError:
            tax_amount = None

        invoice_date = parse_date(invoice_date_raw)
        if not vendor_name or not description or amount is None or amount <= 0:
            flash("Company name, a description, and a valid amount are required.", "error")
            conn.close()
            return form()
        if not invoice_date:
            flash("The date on the invoice is required \u2014 it is what the invoice "
                  "is filed and paid against.", "error")
            conn.close()
            return form()
        # An invoice dated in the future is a typo often enough to be worth
        # refusing: 2027 for 2026 puts it a year down the ageing report where
        # nobody will look for it.
        if invoice_date > house_today() + timedelta(days=1):
            flash("That invoice date is in the future \u2014 please check it.", "error")
            conn.close()
            return form()
        if tax_amount is not None and (tax_amount < 0 or tax_amount > amount):
            flash("The VAT cannot be negative or larger than the total.", "error")
            conn.close()
            return form()

        stored_name = save_expense_file(file)
        if stored_name is False:
            flash(f"File type not allowed. Allowed: {', '.join(sorted(ALLOWED_EXTENSIONS))}", "error")
            conn.close()
            return form()

        duplicate = find_duplicate_invoice(
            conn, vendor_id=vendor["id"] if vendor else None, vendor_name=vendor_name,
            invoice_number=invoice_number, amount=amount,
            invoice_date=invoice_date.isoformat())

        due = invoice_due_date(invoice_date,
                               vendor["payment_terms"] if vendor else None)
        conn.execute(
            """INSERT INTO expenses
               (kind, vendor_id, vendor_name, description, amount, filename,
                invoice_number, invoice_date, due_date, tax_amount,
                duplicate_of_id, submitted_at)
               VALUES ('supplier_invoice', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (vendor["id"] if vendor else None, vendor_name, description, amount,
             stored_name, invoice_number or None, invoice_date.isoformat(), due,
             tax_amount, duplicate["id"] if duplicate else None,
             datetime.now(timezone.utc).isoformat()),
        )
        if vendor:
            conn.execute("UPDATE vendors SET last_submitted_at = ? WHERE id = ?",
                         (datetime.now(timezone.utc).isoformat(), vendor["id"]))
        log_audit(conn, "supplier_invoice_received",
                  target=vendor_name,
                  details=f"{amount:.2f} {invoice_number or 'no number'}"
                          + (" POSSIBLE DUPLICATE" if duplicate else ""))
        conn.commit()
        conn.close()
        # The supplier is told it arrived either way. A duplicate is the
        # house's problem to look at, not theirs to be refused over, and a
        # supplier who re-sends a chaser has done nothing wrong.
        return render_template("supplier_invoice_submitted.html", vendor=vendor)

    conn.close()
    return form()


# ---------------------------------------------------------------------------
# Public booking site — replaces the third-party widget. No login required;
# guests manage their own booking with a reference code + email, or a saved
# link. No live payment is taken here (see module docstring's payment note)
# — requests land as 'pending' and lock the calendar immediately either way,
# so nothing can double-book while you decide.
# ---------------------------------------------------------------------------

def guest_availability_grid(conn, rooms, month_arg):
    """Read-only per-day free/unavailable grid for the guest booking page —
    same underlying data as /admin/calendar (bookings + iCal blocks + manual
    blocks), collapsed to two states so nothing about a specific guest, an
    external platform, or a block's reason is exposed publicly."""
    today = house_today()
    try:
        year, month = map(int, month_arg.split("-"))
        first_day = date(year, month, 1)
    except (ValueError, AttributeError):
        first_day = today.replace(day=1)

    next_month = date(first_day.year + 1, 1, 1) if first_day.month == 12 else date(first_day.year, first_day.month + 1, 1)
    prev_month = date(first_day.year - 1, 12, 1) if first_day.month == 1 else date(first_day.year, first_day.month - 1, 1)
    days = [first_day + timedelta(days=i) for i in range((next_month - first_day).days)]

    room_rows = []
    for room in rooms:
        bookings = conn.execute(
            """SELECT arrival_date, departure_date FROM bookings WHERE room_id = ? AND status IN ('pending','confirmed')
               AND arrival_date < ? AND departure_date > ?""",
            (room["id"], next_month.isoformat(), first_day.isoformat()),
        ).fetchall()
        blocked = conn.execute(
            "SELECT start_date, end_date FROM blocked_dates WHERE room_id = ? AND start_date < ? AND end_date > ?",
            (room["id"], next_month.isoformat(), first_day.isoformat()),
        ).fetchall()
        manual_blocks = conn.execute(
            "SELECT start_date, end_date FROM room_blocks WHERE room_id = ? AND start_date < ? AND end_date > ?",
            (room["id"], next_month.isoformat(), first_day.isoformat()),
        ).fetchall()
        taken_ranges = (
            [(parse_date(b["arrival_date"]), parse_date(b["departure_date"])) for b in bookings]
            + [(parse_date(r["start_date"]), parse_date(r["end_date"])) for r in blocked]
            + [(parse_date(r["start_date"]), parse_date(r["end_date"])) for r in manual_blocks]
        )
        cells = []
        for d in days:
            unavailable = any(start <= d < end for start, end in taken_ranges)
            cells.append({"date": d, "status": "unavailable" if unavailable else "free"})
        room_rows.append({"room": room, "cells": cells})

    return {
        "days": days, "room_rows": room_rows, "first_day": first_day, "today": today,
        "prev_month": prev_month.strftime("%Y-%m"), "next_month": next_month.strftime("%Y-%m"),
    }


@app.route("/book")
def book_rooms():
    conn = get_db()
    rooms = conn.execute("SELECT * FROM rooms WHERE active = 1 ORDER BY sort_order, name").fetchall()

    arrival_raw = request.args.get("arrival", "").strip()
    departure_raw = request.args.get("departure", "").strip()
    arrival, departure = parse_date(arrival_raw), parse_date(departure_raw)

    availability = {}
    unavailable_reason = {}
    searched = bool(arrival and departure and departure > arrival)
    if searched:
        stay_nights = (departure - arrival).days
        for room in rooms:
            ok, _ = is_range_available(conn, room["id"], arrival, departure)
            too_short = stay_nights < room["min_nights"]
            availability[room["id"]] = ok and not too_short
            if too_short:
                unavailable_reason[room["id"]] = f"Requires a {room['min_nights']}-night minimum stay"
            elif not ok:
                unavailable_reason[room["id"]] = "Not available these dates"
    nothing_available = searched and rooms and not any(availability.values())

    grid = guest_availability_grid(conn, rooms, request.args.get("month", ""))
    featured_reviews = conn.execute(
        """SELECT guest_feedback.*, rooms.name AS room_name FROM guest_feedback
           LEFT JOIN bookings ON bookings.id = guest_feedback.booking_id
           LEFT JOIN rooms ON rooms.id = bookings.room_id
           -- Consent as well as the flag, and HERE rather than on the
           -- admin page. A page can be got round and the next person to
           -- add a review carousel would write this query again; wiring it
           -- into the query that builds the public page is what makes
           -- "nothing is published without asking you first" true even when
           -- somebody ticks the wrong row.
           WHERE guest_feedback.featured = 1 AND guest_feedback.rating IS NOT NULL
             AND guest_feedback.publish_consent = 1
           ORDER BY guest_feedback.rating DESC, guest_feedback.submitted_at DESC LIMIT 6"""
    ).fetchall()
    # Computed before the connection closes. Only when nobody has searched:
    # somebody who has just been told their dates are taken does not want a
    # second list of dates that are not theirs, they want to change one of
    # their own.
    next_free = next_free_nights(conn) if not searched else []
    # A cached reading or None. Never a network call from a page render: a
    # render that can block on somebody else's network is one that eventually
    # does, and this is the booking page.
    weather = weather_now(conn)
    conn.close()
    return render_template(
        "book_rooms.html", rooms=rooms, arrival=arrival_raw, departure=departure_raw,
        availability=availability, unavailable_reason=unavailable_reason, searched=searched,
        nothing_available=nothing_available, next_free=next_free,
        weather=weather,
        prefill_name=request.args.get("name", ""), prefill_email=request.args.get("email", ""),
        prefill_phone=request.args.get("phone", ""), prefill_party_size=request.args.get("party_size", ""),
        featured_reviews=featured_reviews,
        **grid,
    )


@app.route("/waitlist/join", methods=["POST"])
def join_waitlist():
    name = request.form.get("name", "").strip()
    email = request.form.get("email", "").strip().lower()
    phone = request.form.get("phone", "").strip()
    desired_arrival = request.form.get("desired_arrival", "").strip()
    desired_departure = request.form.get("desired_departure", "").strip()
    party_size_raw = request.form.get("party_size", "").strip()
    notes = request.form.get("notes", "").strip()

    conn = get_db()
    if rate_limited(conn, "join_waitlist", BOOKING_RATE_LIMIT_PER_HOUR):
        conn.commit()
        conn.close()
        flash("Too many attempts from this connection — please try again in a bit.", "error")
        return redirect(url_for("book_rooms", arrival=desired_arrival, departure=desired_departure))

    if not name or not email:
        conn.commit()
        conn.close()
        flash("Name and email are required.", "error")
        return redirect(url_for("book_rooms", arrival=desired_arrival, departure=desired_departure))
    if not EMAIL_RE.match(email):
        conn.commit()
        conn.close()
        flash("Enter a valid email address.", "error")
        return redirect(url_for("book_rooms", arrival=desired_arrival, departure=desired_departure))

    party_size = int(party_size_raw) if party_size_raw.isdigit() else None
    conn.execute(
        """INSERT INTO waitlist_entries
           (name, email, phone, desired_arrival, desired_departure, party_size, notes, status, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'open', ?)""",
        (name, email, phone or None, desired_arrival or None, desired_departure or None,
         party_size, notes or None, datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
    owner_to = owner_email(conn)
    if owner_to:
        send_email(
            owner_to, "New waitlist request",
            f"{name} ({email}) would like {desired_arrival or '?'} to {desired_departure or '?'}, "
            f"but nothing was available.\n\n{notes or ''}",
        )
    conn.close()
    flash("You're on the waitlist — we'll reach out if those dates open up.", "success")
    return redirect(url_for("book_rooms", arrival=desired_arrival, departure=desired_departure))


