@app.route("/restaurant/manage/<manage_token>", methods=["GET", "POST"])
def restaurant_manage(manage_token):
    conn = get_db()
    booking = conn.execute("SELECT * FROM restaurant_bookings WHERE manage_token = ?", (manage_token,)).fetchone()
    if not booking:
        conn.close()
        abort(404)

    # Changing the covers or the dietary notes without emailing anybody.
    #
    # Cancelling was the only thing a guest could do here, so "we are four now,
    # not two" and "one of us cannot eat shellfish" both arrived as an email
    # somebody had to read and re-key — which is the commonest reason anyone
    # writes in about a booking they could have fixed themselves.
    #
    # The capacity rule is the booking form's, not a second one: at most the
    # room's capacity, and at most what is left on that date. `exclude_id` takes
    # this booking's own covers out of what is "left", or going from two to
    # three would be refused by the two already counted.
    #
    # The price moves with the covers, through compute_restaurant_total — the
    # same helper the booking used. What has been PAID is never touched: a
    # smaller party does not trigger a refund here, because a refund is a
    # decision somebody makes, not a consequence of a form.
    # The action name is "update" because that is what the shipped
    # templates post. Both have carried this form for several handovers
    # with nothing behind it: the guest filled it in, pressed Save, and
    # the page came back unchanged with no message. A form that silently
    # discards what somebody typed is worse than no form.
    if request.method == "POST" and request.form.get("action") == "update":
        if booking["status"] not in ("pending", "confirmed"):
            conn.close()
            flash("This reservation is no longer open to changes.", "error")
            return redirect(url_for("restaurant_manage", manage_token=manage_token))
        if booking["dinner_date"] < house_today_iso():
            conn.close()
            flash("That dinner has already passed — do get in touch if something "
                  "needs correcting.", "error")
            return redirect(url_for("restaurant_manage", manage_token=manage_token))

        raw = (request.form.get("party_size", "") or "").strip()
        dietary = (request.form.get("dietary_notes", "") or "").strip()
        settings = get_restaurant_settings(conn)
        capacity = settings["capacity"] if settings else 20
        party_size = int(raw) if raw.isdigit() else None

        if party_size is None or party_size < 1:
            conn.close()
            flash("How many are coming?", "error")
            return redirect(url_for("restaurant_manage", manage_token=manage_token))
        if party_size > capacity:
            conn.close()
            flash(f"We can seat a maximum of {capacity} at once — please call us "
                  "for a larger party.", "error")
            return redirect(url_for("restaurant_manage", manage_token=manage_token))
        room_left = restaurant_remaining_capacity(
            conn, booking["dinner_date"], exclude_id=booking["id"])
        if party_size > room_left:
            conn.close()
            flash(f"We only have room for {room_left} that evening. Reduce the "
                  "party, or get in touch and we will see what we can do.", "error")
            return redirect(url_for("restaurant_manage", manage_token=manage_token))

        was_party, was_dietary = booking["party_size"], booking["dietary_notes"] or ""
        if party_size == was_party and dietary == was_dietary:
            conn.close()
            flash("Nothing changed.", "success")
            return redirect(url_for("restaurant_manage", manage_token=manage_token))

        # compute_restaurant_total returns 0 when no per-person rate is on file
        # for that date — which is the state of a restaurant that has not had
        # its price set. Recalculating from that would rewrite a real €130 total
        # to zero and tell the guest their dinner is free, so the rate is
        # checked first and a figure nobody can derive is left exactly as it is.
        rate = restaurant_night_rate(conn, booking["dinner_date"])
        if rate:
            subtotal = compute_restaurant_total(conn, booking["dinner_date"], party_size)
            new_total = round(subtotal - (booking["discount_amount"] or 0), 2)
        else:
            new_total = booking["total_price"]
        conn.execute(
            """UPDATE restaurant_bookings SET party_size = ?, dietary_notes = ?,
               total_price = ? WHERE id = ?""",
            (party_size, dietary or None, new_total, booking["id"]))
        conn.commit()

        owner_to = owner_email(conn)
        if owner_to:
            changes = []
            if party_size != was_party:
                changes.append(f"party of {was_party} → {party_size}")
            if dietary != was_dietary:
                changes.append(f"dietary notes now: {dietary or '(none)'}")
            paid_note = ""
            if booking["payment_status"] == "paid" and party_size != was_party:
                paid_note = ("\n\nThey have already paid. The total has been "
                             "recalculated but no money has moved — settle the "
                             "difference at the restaurant, or refund from the "
                             "admin page if that is the right call.")
            if not rate and party_size != was_party:
                paid_note += ("\n\nNo per-person price is set for that date, so the "
                              f"total is still €{new_total:.2f} against the OLD party "
                              "size. Set a price, or correct the total by hand.")
            send_email(
                owner_to,
                f"Dinner reservation changed — {booking['reference_code']}",
                f"{booking['guest_name']} changed their reservation for "
                f"{format_date_human(booking['dinner_date'])}:\n\n"
                + "\n".join(f"- {c}" for c in changes)
                + f"\n\nTotal now €{new_total:.2f}." + paid_note,
            )
        conn.close()
        flash("Your reservation has been updated. We have let the château know.",
              "success")
        return redirect(url_for("restaurant_manage", manage_token=manage_token))

    if request.method == "POST" and request.form.get("action") == "cancel":
        cur = conn.execute(
            "UPDATE restaurant_bookings SET status = 'cancelled', decided_at = ? WHERE id = ? AND status IN ('pending', 'confirmed')",
            (datetime.now(timezone.utc).isoformat(), booking["id"]),
        )
        conn.commit()
        if cur.rowcount:
            owner_to = owner_email(conn)
            if owner_to:
                paid_note = " They had paid — refund it from the restaurant admin page if appropriate." if booking["payment_status"] == "paid" else ""
                send_email(
                    owner_to,
                    f"Dinner reservation cancelled — {booking['reference_code']}",
                    f"{booking['guest_name']} cancelled their dinner reservation for "
                    f"{format_date_human(booking['dinner_date'])}, party of {booking['party_size']}.{paid_note}",
                )
            flash("Your reservation has been cancelled.", "success")
        conn.close()
        return redirect(url_for("restaurant_manage", manage_token=manage_token))

    conn.close()
    return render_template("restaurant_manage.html", booking=booking)


def make_workshop_reference_code():
    return "WRK-" + "".join(secrets.choice(string.ascii_uppercase + string.digits) for _ in range(6))


def compute_workshop_payment_terms(total_price, deposit_percent, start_date):
    """A workshop registration is really a whole-château retreat package, so
    it follows the same deposit/balance convention as the real thing: a
    percentage deposit at booking, the remainder due 30 days before the stay
    — unless the booking itself happens inside that 30-day window, in which
    case the full amount is due immediately (mirrors 'full payment required
    for bookings within 30 days'). Returns (deposit_amount, balance_amount,
    balance_due_date_iso_or_None)."""
    if not total_price:
        return None, None, None
    today = house_today()
    if (start_date - today).days < 30:
        return round(total_price, 2), 0.0, None
    deposit_amount = round(total_price * deposit_percent / 100, 2)
    balance_amount = round(total_price - deposit_amount, 2)
    balance_due_date = (start_date - timedelta(days=30)).isoformat()
    return deposit_amount, balance_amount, balance_due_date


# What a text may be sent for. Transactional messages are about something the
# person already asked for; marketing is everything else, and the difference
# decides whether silence counts as permission.
SMS_PURPOSES = ("transactional", "marketing")


def sms_enabled():
    """Whether there is any way to send a text at all."""
    return bool(SMS_PROVIDER_SID and SMS_PROVIDER_TOKEN and SMS_FROM_NUMBER)


def can_text(conn, raw_number, purpose="transactional"):
    """(number_or_None, refusal_or_None) — whether this may be texted, and why not.

    One gate in front of every send, rather than each caller remembering the
    rules. It returns the normalised number on success so a caller cannot send
    to the raw string by accident.

    The order matters and is deliberate:

      1. it has to be a number at all;
      2. it has to be able to receive a text — a landline cannot, and the
         provider would take it, charge for the attempt and report a failure
         nobody reads;
      3. nobody who has asked to be left alone is texted, for any purpose,
         ever;
      4. and marketing additionally needs an explicit yes on file. Silence is
         not consent for a message somebody did not ask for, and a phone is
         more intrusive than an inbox — it goes off at the table.
    """
    if purpose not in SMS_PURPOSES:
        return None, "unknown purpose"
    number = normalise_phone(raw_number)
    if not number:
        return None, "no usable number on file"
    if is_mobile_number(number) is False:
        return None, "that is a landline"
    if conn.execute("SELECT 1 FROM sms_optouts WHERE phone = ?", (number,)).fetchone():
        return None, "they asked not to be texted"
    if purpose == "marketing":
        if not conn.execute("SELECT 1 FROM sms_consents WHERE phone = ?",
                            (number,)).fetchone():
            return None, "no consent on file for marketing"
    return number, None


def record_sms_optout(conn, raw_number, reason=None):
    """Add a number to the do-not-text list, and drop any marketing consent.

    Both halves, because leaving the consent row behind would mean a later
    'they opted back in' read as still true. Asking to stop is the more recent
    instruction and has to win.
    """
    number = normalise_phone(raw_number)
    if not number:
        return None
    conn.execute(
        "INSERT OR IGNORE INTO sms_optouts (phone, reason, created_at) VALUES (?, ?, ?)",
        (number, reason, datetime.now(timezone.utc).isoformat()))
    conn.execute("DELETE FROM sms_consents WHERE phone = ?", (number,))
    return number


def record_sms_consent(conn, raw_number, source=None):
    """Record an explicit yes to marketing texts, and lift any earlier no.

    The mirror of the newsletter's confirm step: coming back is a deliberate
    act by the person themselves, so it clears the older refusal rather than
    being silently overridden by it.
    """
    number = normalise_phone(raw_number)
    if not number:
        return None
    conn.execute("DELETE FROM sms_optouts WHERE phone = ?", (number,))
    conn.execute(
        "INSERT OR IGNORE INTO sms_consents (phone, source, granted_at) VALUES (?, ?, ?)",
        (number, source, datetime.now(timezone.utc).isoformat()))
    return number


def send_sms(conn, raw_number, body, purpose="transactional", hold=True):
    """Send a text, or keep it until there is a way to.

    Returns (sent, refusal). A refusal is a decision — the wrong number, a
    landline, somebody who said no — and is never queued, because it will not
    become sendable by waiting. Only a message that could go and cannot right
    now is held.

    hold=False for a message that is only true at the moment it is written.
    "A room has come free for your dates" is the example: held and delivered
    the week a provider is finally connected, it arrives on somebody's phone
    about dates resold a month ago. The email side already refuses to queue
    this one for the same reason and says so; a text is worse, because a phone
    goes off in a pocket. A message nobody can send now and that will be false
    later is better lost than kept.

    Takes the caller's connection and writes on it, unlike the mail outbox
    which opens its own. That is on purpose: the mail one has to survive being
    called from a failure path, and paid for it with a whole class of lost
    messages when the caller held a write open. This one is called from
    ordinary code and can simply join the caller's transaction.
    """
    number, refusal = can_text(conn, raw_number, purpose)
    if refusal:
        return False, refusal
    if not sms_enabled():
        if not hold:
            return False, "no way to send, and this message would be stale later"
        conn.execute(
            """INSERT INTO sms_outbox (phone, body, purpose, reason, created_at)
               VALUES (?, ?, ?, 'no provider configured', ?)""",
            (number, body, purpose, datetime.now(timezone.utc).isoformat()))
        return False, None          # held, not refused
    ok, result = sms_provider_send(number, body)
    conn.execute(
        """INSERT INTO sms_outbox (phone, body, purpose, reason, created_at,
           sent_at, provider_message_id, last_error)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
        (number, body, purpose, "sent" if ok else "send failed",
         datetime.now(timezone.utc).isoformat(),
         datetime.now(timezone.utc).isoformat() if ok else None,
         result if ok else None, None if ok else str(result)[:400]))
    return bool(ok), None


def sms_provider_send(number, body):
    """The one place a text actually leaves the building.

    Deliberately the only function that talks to the provider, so the test
    harness has exactly one thing to block — the lesson from the morning the
    suite turned out to be able to reach Stripe. Nothing else in this file
    opens a connection to send a message.
    """
    if not sms_enabled():
        return False, "no provider configured"
    # Stdlib only, like every other outbound call in this file.
    payload = urlencode({"To": number, "From": SMS_FROM_NUMBER, "Body": body}).encode()
    url = (f"https://api.twilio.com/2010-04-01/Accounts/"
           f"{quote(SMS_PROVIDER_SID)}/Messages.json")
    auth = base64.b64encode(
        f"{SMS_PROVIDER_SID}:{SMS_PROVIDER_TOKEN}".encode()).decode()
    req = Request(url, data=payload, method="POST")
    req.add_header("Authorization", f"Basic {auth}")
    req.add_header("Content-Type", "application/x-www-form-urlencoded")
    try:
        with urlopen(req, timeout=15) as resp:
            answer = json.loads(resp.read().decode())
        return True, answer.get("sid")
    except Exception as e:                       # pragma: no cover - network
        return False, str(e)


# The texts a guest gets about their own stay, as data rather than as two
# near-identical functions. They differ in four things and nothing else — the
# setting that holds the wording, the column that stops it repeating, the date
# it counts from and which way it counts — so the alternative was a second copy
# of the job, and a second copy is how the two quietly stop agreeing about who
# is skipped.
#
# Each message's wording is a setting, not a constant: it is the owner's words
# to their own guests and will be reworded far more often than this file is
# touched. The merge tags are the same single braces the promo blast uses.
GUEST_TEXTS = {
    "checkin": {
        "setting": "sms_checkin_template",
        "stamp": "checkin_text_sent_at",
        "date_column": "arrival_date",
        # The day before is the point: they are travelling, away from a
        # computer, and this is when "where do I actually go" is the only
        # question left.
        "days_before": 1,
        "label": "arrival",
        # Sized to ONE billed message with a real url and a long first name.
        # The url is most of the budget — about 71 characters once the live
        # host and a 32-character token are in it, out of 160 — so there are
        # roughly 75 left for words after allowing for a name like
        # Marie-Christine. The first version of this read beautifully and cost
        # two messages per arrival, which is invisible until the bill.
        "default": (
            "Bonjour {guest_name}, we look forward to seeing you tomorrow. "
            "How to find us: {manage_url}"
        ),
    },
    "checkout": {
        "setting": "sms_checkout_template",
        "stamp": "checkout_text_sent_at",
        "date_column": "departure_date",
        # The evening before, not the morning of. A guest reading "checkout is
        # at eleven" at ten past ten has been told too late to act on it.
        "days_before": 1,
        "label": "departure",
        # The statement url is longer again, so this is terser still.
        "default": (
            "Bonjour {guest_name}, checkout is 11am. Keys in the bowl by the "
            "door. Bill: {statement_url}"
        ),
    },
}

# Kept so anything still calling these reads the same value. The arrival text
# was here first and other code refers to it by name.
CHECKIN_TEXT_SETTING = GUEST_TEXTS["checkin"]["setting"]
CHECKIN_TEXT_DEFAULT = GUEST_TEXTS["checkin"]["default"]
CHECKIN_TEXT_DAYS_BEFORE = GUEST_TEXTS["checkin"]["days_before"]
# A text is billed per 160-character segment, so a template somebody has grown
# over a season quietly triples the cost of every arrival. Not a limit — the
# owner may have something long and necessary to say — but the page says what
# each message will cost in segments before it is saved.
SMS_SEGMENT_CHARS = 160


def sms_segments(body):
    """How many billed parts a message will arrive in."""
    if not body:
        return 0
    return max(1, -(-len(body) // SMS_SEGMENT_CHARS))


def guest_text_body(conn, booking, kind="checkin"):
    """The message for one booking, with the tags filled in."""
    spec = GUEST_TEXTS[kind]
    row = conn.execute(
        "SELECT value FROM app_settings WHERE key = ?", (spec["setting"],)).fetchone()
    template = (row["value"] if row and (row["value"] or "").strip()
                else spec["default"])
    first = (booking["guest_name"] or "").strip().split(" ")[0] or "there"
    token = booking["manage_token"]
    try:
        manage_url = url_for("manage_booking", manage_token=token, _external=True)
        statement_url = url_for("booking_statement", manage_token=token, _external=True)
    except RuntimeError:                     # no request context, e.g. a cron run
        base = PUBLIC_BASE_URL.rstrip("/")
        manage_url = f"{base}/book/manage/{token}"
        statement_url = f"{base}/booking/{token}/statement"
    return (template
            .replace("{guest_name}", first)
            .replace("{reference}", booking["reference_code"] or "")
            .replace("{arrival_date}", format_date_human(booking["arrival_date"]))
            .replace("{departure_date}", format_date_human(booking["departure_date"]))
            .replace("{manage_url}", manage_url)
            .replace("{statement_url}", statement_url))


def run_guest_text_job(conn, kind="checkin", days_before=None):
    """Text tomorrow's arrivals where the house has a number it may use.

    Only confirmed stays, only once each, and only through can_text — so a
    guest who has asked not to be texted, or gave a landline, or gave something
    that is not a number, is simply not in the list. None of those is an error
    and none is worth waking the owner for.

    Stamped and committed per booking rather than after the loop. The mail side
    lost a whole class of messages to exactly that shape: with the stamp held
    open, the NEXT guest's send cannot write its own row and the message is
    neither sent nor kept. Per-row also means a job that dies halfway keeps
    what already went.
    """
    spec = GUEST_TEXTS[kind]          # KeyError rather than a silent no-op
    days = spec["days_before"] if days_before is None else days_before
    when = (house_today() + timedelta(days=days)).isoformat()
    # The two column names come from GUEST_TEXTS above and nowhere else, so
    # they are the app's own words rather than anything a request carried.
    arriving = conn.execute(
        f"""SELECT * FROM bookings
            WHERE status = 'confirmed' AND {spec["date_column"]} = ?
              AND {spec["stamp"]} IS NULL""", (when,)).fetchall()

    # ONE MESSAGE TO A PARTY, not one per room. A family taking three rooms
    # was getting three identical texts to the same telephone on the same
    # morning, each billed. The rooms they are not written about are stamped
    # all the same, or the next run would text them again for the same stay.
    leads = set(party_lead_bookings(conn, [b["id"] for b in arriving]))
    quiet = [b for b in arriving if b["id"] not in leads]
    arriving = [b for b in arriving if b["id"] in leads]
    for b in quiet:
        conn.execute(f"UPDATE bookings SET {spec['stamp']} = ? WHERE id = ?",
                     (datetime.now(timezone.utc).isoformat(), b["id"]))
        conn.commit()

    sent = held = skipped = 0
    with_party = len(quiet)
    reasons = {}
    for booking in arriving:
        number, refusal = can_text(conn, booking["guest_phone"], "transactional")
        if refusal:
            skipped += 1
            reasons[refusal] = reasons.get(refusal, 0) + 1
            continue
        went, send_refusal = send_sms(conn, number,
                                      guest_text_body(conn, booking, kind),
                                      purpose="transactional")
        if send_refusal:
            skipped += 1
            reasons[send_refusal] = reasons.get(send_refusal, 0) + 1
            continue
        # Stamped whether it went now or is waiting, because the outbox holds
        # it either way and stamping only on success would send it twice the
        # day a provider is switched on.
        conn.execute(f'UPDATE bookings SET {spec["stamp"]} = ? WHERE id = ?',
                     (datetime.now(timezone.utc).isoformat(), booking["id"]))
        conn.commit()
        if went:
            sent += 1
        else:
            held += 1

    if not arriving:
        verb = "arrives" if kind == "checkin" else "leaves"
        return f"nobody {verb} in {days} day(s)"
    parts = [f"{sent} sent"] if sent else []
    if held:
        parts.append(f"{held} waiting for a provider")
    if skipped:
        parts.append(f"{skipped} with no number we could use")
    if with_party:
        # Said out loud, because a run that texted four people yesterday and
        # two today looks like something breaking rather than two of them
        # being in the same family.
        parts.append(f"{with_party} covered by somebody else's message "
                     "in the same party")
    return ", ".join(parts) or "nothing to send"


# How long after a stay to ask. Long enough to be home and have unpacked,
# short enough that the place is still in mind. The workshop job uses the same
# shape and the same reasoning.
ROOM_FEEDBACK_DAYS_AFTER = 3


def morning_digest(conn, today=None):
    """What today looks like: who comes, who goes, who is eating, what is wrong.

    Returns (subject, body, has_anything). The last is the point — a note that
    arrives every morning saying nothing becomes furniture, which is the same
    lesson the warnings panel already carries. So on a genuinely empty day
    nothing is sent, and the job says so rather than writing an empty page.

    It reuses owner_home_warnings rather than asking the same questions again.
    Two lists of what needs attention would eventually disagree, and the one in
    the email would be the one nobody corrected.
    """
    day = today or house_today()
    iso = day.isoformat()

    arriving = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.status = 'confirmed' AND bookings.arrival_date = ?
           ORDER BY rooms.name""", (iso,)).fetchall()
    leaving = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.status = 'confirmed' AND bookings.departure_date = ?
           ORDER BY rooms.name""", (iso,)).fetchall()
    staying = conn.execute(
        """SELECT COUNT(*) AS c FROM bookings
           WHERE status = 'confirmed' AND arrival_date <= ? AND departure_date > ?""",
        (iso, iso)).fetchone()["c"]
    dinners = conn.execute(
        """SELECT * FROM restaurant_bookings
           WHERE status = 'confirmed' AND dinner_date = ?
           ORDER BY guest_name""", (iso,)).fetchall()
    covers = sum((d["party_size"] or 0) for d in dinners)

    warnings = owner_home_warnings(conn, day)

    lines = [f"{format_date_human(iso)} at Château de Gudanes.", ""]
    if arriving:
        lines.append(f"Arriving ({len(arriving)}):")
        for b in arriving:
            when = f" — {b['estimated_arrival_time']}" if b["estimated_arrival_time"] else ""
            lines.append(f"  {b['room_name']}: {b['guest_name']}, "
                         f"party of {b['party_size'] or 1}{when}")
        lines.append("")
    if leaving:
        lines.append(f"Leaving ({len(leaving)}):")
        for b in leaving:
            lines.append(f"  {b['room_name']}: {b['guest_name']}")
        lines.append("")
    if staying:
        lines.append(f"In the house tonight: {staying} room(s).")
        lines.append("")
    if dinners:
        lines.append(f"Dinner ({len(dinners)} booking(s), {covers} cover(s)):")
        for d in dinners:
            note = f" — {d['dietary_notes']}" if (d["dietary_notes"] or "").strip() else ""
            lines.append(f"  {d['guest_name']}, {d['party_size'] or 1}{note}")
        lines.append("")
    if warnings:
        lines.append("Wants looking at:")
        for w in warnings:
            lines.append(f"  {w['title']}")
        lines.append("")

    # Deliberately NOT counting warnings. Several of them are standing facts —
    # "no backup is arriving" is true every morning until somebody fixes it —
    # so including them here means the note goes out every single day and
    # becomes the thing you stop opening. They are already on the home page,
    # they close themselves, and they are listed here when a note goes anyway.
    #
    # This note answers one question: what does TODAY look like. A standing
    # warning is not a fact about today.
    has_anything = bool(arriving or leaving or dinners)
    if not has_anything:
        lines.append("Nothing arriving, nothing leaving and no dinners booked.")

    parts = []
    if arriving:
        parts.append(f"{len(arriving)} in")
    if leaving:
        parts.append(f"{len(leaving)} out")
    if dinners:
        parts.append(f"{covers} at dinner")
    if warnings:
        parts.append(f"{len(warnings)} to look at")
    subject = f"Today: {', '.join(parts)}" if parts else "Today: a quiet one"
    return subject, "\n".join(lines).rstrip() + "\n", has_anything


def run_workshop_decision_job(conn, today=None):
    """Tell the owner a workshop needs deciding, once per stage.

    Two stages, because they are different messages. "You have a week to
    decide" is information; "you were supposed to decide on Tuesday and it
    is still short" deserves to interrupt. Sending the first one again
    every morning until the date passes would turn both into wallpaper.
    """
    day = today or house_today()
    at_risk = [w for w in sessions_at_risk(conn, day) if w["urgent"]]
    if not at_risk:
        return "no workshop needs deciding"

    already = {(r["session_id"], r["stage"]) for r in conn.execute(
        "SELECT session_id, stage FROM workshop_decision_reminders").fetchall()}

    sent = 0
    for w in at_risk:
        stage = "overdue" if w["overdue"] else "due"
        if (w["session"]["id"], stage) in already:
            continue

        if w["waitlist_could_fill"]:
            what = (f"{w['waiting']} on the waiting list could cover it. "
                    "Ring them before deciding anything else.")
        elif w["overdue"]:
            what = (f"The date for deciding passed on "
                    f"{format_date_short(w['decide_by'].isoformat())}.")
        else:
            what = (f"Decide by {format_date_short(w['decide_by'].isoformat())}"
                    f" \u2014 {w['days_left']} day"
                    f"{'' if w['days_left'] == 1 else 's'}.")

        for owner in conn.execute(
                "SELECT id FROM users WHERE role = 'owner'").fetchall():
            send_notification(
                conn, owner["id"], "workshop_decision",
                f"{w['title']} has {w['confirmed']} of {w['minimum']}",
                f"{format_date_short(w['session']['start_date'])}. {what}",
                link=url_for("admin_workshops"))
        conn.execute(
            """INSERT OR IGNORE INTO workshop_decision_reminders
                   (session_id, stage, sent_at) VALUES (?, ?, ?)""",
            (w["session"]["id"], stage,
             datetime.now(timezone.utc).isoformat()))
        sent += 1

    conn.commit()
    return (f"{sent} reminder(s) sent" if sent
            else "already reminded about every one of these")


def run_morning_digest_job(conn, today=None):
    """Send the morning note, unless there is genuinely nothing in it.

    Nothing is stamped, because this is not a message to a guest and sending
    it twice costs nothing but a second copy — whereas a stamp would mean a
    job that ran at 6am and failed could not be run again at 7.
    """
    day = today or house_today()
    subject, body, has_anything = morning_digest(conn, day)
    if not has_anything:
        return "nothing happening today, so nothing sent"
    to = owner_email(conn)
    if not to:
        return "no owner address on file"
    send_email(to, subject, body)
    return f"sent — {subject}"


def run_room_feedback_job(conn, days_after=None):
    """Ask departed room guests how it was.

    Workshop guests have been asked since the beginning; room guests never
    were, and rooms are most of what the house sells. The form, the table and
    the page have all existed the whole time — nothing pointed anybody at them.

    Skipped rather than asked: a guest who has already left feedback, one who
    asked not to be written to, and any stay that did not actually happen.
    None of those is an error, and a job that treated them as one would report
    a failure every morning.
    """
    days = ROOM_FEEDBACK_DAYS_AFTER if days_after is None else days_after
    when = (house_today() - timedelta(days=days)).isoformat()
    departed = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.status = 'confirmed'
             AND bookings.departure_date = ?
             AND bookings.feedback_requested_at IS NULL
             AND NOT EXISTS (SELECT 1 FROM guest_feedback
                             WHERE guest_feedback.booking_id = bookings.id)
             AND LOWER(bookings.guest_email) NOT IN
                 (SELECT LOWER(email) FROM email_optouts)""",
        (when,)).fetchall()

    asked = 0
    for booking in departed:
        subject, body = render_email_template(conn, "room_feedback_request", {
            "guest_name": (booking["guest_name"] or "").strip().split(" ")[0] or "there",
            "room_name": booking["room_name"],
            "feedback_url": url_for("guest_feedback",
                                    token=booking["manage_token"], _external=True),
        })
        if not subject:
            continue
        # Stamped before the send and committed per booking, for the two
        # reasons this app has learned the hard way: a stamp held open stops
        # the NEXT guest's message being queued at all, and stamping only on
        # success asks everybody again the day a provider is connected.
        conn.execute("UPDATE bookings SET feedback_requested_at = ? WHERE id = ?",
                     (datetime.now(timezone.utc).isoformat(), booking["id"]))
        conn.commit()
        send_email(booking["guest_email"], subject, body)
        asked += 1

    if not departed:
        return f"nobody left {days} day(s) ago who has not been asked"
    return f"asked {asked} guest(s) how their stay was"


def run_checkin_text_job(conn, days_before=None):
    """The arrival run. Kept because the page and its tests call it by name."""
    return run_guest_text_job(conn, "checkin", days_before)


def run_checkout_text_job(conn, days_before=None):
    """The departure run."""
    return run_guest_text_job(conn, "checkout", days_before)


def normalise_phone(raw, default_country=None):
    """A typed phone number as +33612345678, or None if it cannot be one.

    Every form in the app has taken a phone number since the beginning and
    none of them has ever looked at it, so what is on file is whatever people
    typed: "06 12 34 56 78", "06.12.34.56.78", "+33 (0)6 12 34 56 78" and
    "ask my wife". None of those can be sent to. Storing the raw string in a
    column something later has to dial is the same fault as storing an
    unparsed date in a date column — the page looks right, the send goes
    nowhere, and it surfaces as a guest who did not turn up.

    Deliberately conservative: it converts the shapes people actually write
    and returns None for anything else, rather than guessing. A number it
    cannot read is better refused at the form than stored and never used.
    """
    text = re.sub(r"[\s.\-() /]", "", (raw or ""))
    if not text:
        return None
    country = default_country or DEFAULT_PHONE_COUNTRY
    if text.startswith("00"):            # 0033... — the older international form
        text = "+" + text[2:]
    # "+33 (0)6 ..." is extremely common on French business cards and websites:
    # the 0 is the trunk prefix, correct when dialling inside France and wrong
    # once the country code is there. The parenthesis is already stripped above.
    if text.startswith(country + "0"):
        text = country + text[len(country) + 1:]
    if text.startswith("+"):
        digits = text[1:]
        if not digits.isdigit() or not 8 <= len(digits) <= 15:   # E.164 caps at 15
            return None
        return "+" + digits
    if not text.isdigit():
        return None
    if text.startswith("0"):             # a national number: 0612345678
        return country + text[1:]
    return None                          # a bare string of digits is too ambiguous


def is_mobile_number(number):
    """Whether a normalised number can receive a text.

    Only answerable for France, where the prefix says so. For anywhere else
    this returns None — "not known" rather than "no", because refusing to text
    a foreign guest on the grounds that we cannot tell would be worse than
    trying.
    """
    if not number:
        return False
    if number.startswith(DEFAULT_PHONE_COUNTRY):
        return number.startswith(FR_MOBILE_PREFIXES)
    return None


def phone_from_form(field="guest_phone"):
    """A phone number off a form, normalised where it can be.

    The policy, in one place because it is a judgement rather than a rule:

      - a number that normalises is stored normalised, so anything that later
        has to send to it can, and normalise_phone is idempotent so re-reading
        a stored value gives the same answer;
      - a number that does not normalise is stored exactly as typed, and NOT
        refused. Turning away a booking over a phone number would trade a real
        stay for a tidy column. The sending side calls normalise_phone again
        and simply finds nothing it can use, which is the truth.

    So a bad number costs a text message, never a booking.
    """
    raw = (request.form.get(field, "") or "").strip()
    return normalise_phone(raw) or raw


def parse_quantity(raw):
    """A typed-in amount of something. None if the box was empty or junk.

    Three decimal places rather than parse_money's two: this weighs clay,
    not euros, and grams on a kilo are a real quantity. Negative is refused
    — a workshop that uses minus two kilos of anything is a typo.
    """
    text = (raw or "").strip().replace(",", ".")
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        return None
    return round(value, 3) if value >= 0 else None


def parse_money(raw):
    """A typed-in amount, or None if the box was left empty or filled with junk.

    None and 0 mean different things here: None is "no supplement is charged",
    0 is "the owner has decided it is free". Both behave the same when charging,
    but only the first should read as unset on the form.
    """
    text = (raw or "").strip().replace("€", "").replace(",", ".")
    # 1 200,50 is how the owner writes a price. The comma was handled; the
    # thousands separator was not, and in French it is a SPACE -- so every
    # amount over a thousand came back None, which here means "the box was
    # left empty", so the form saved with the field silently blank.
    #
    # Only BETWEEN DIGITS, and only a normal space, a no-break space or the
    # narrow no-break space French typography actually uses. A bare
    # "45 euros" still fails, which is right: it is not a number.
    text = re.sub(r"(?<=\d)[ \u00a0\u202f]+(?=\d)", "", text)
    if not text:
        return None
    try:
        value = float(text)
    except ValueError:
        return None
    return round(value, 2) if value >= 0 else None


# What a guest may choose for themselves on the public registration form.
#
# 'solo' is deliberately absent. A private room on an atelier is arranged with
# the château directly: the price depends on the atelier, the dates and what is
# actually free, so it is quoted per enquiry rather than carried as a standing
# supplement. Staff can still set solo on a booking by hand, which is how one
# that was arranged over the phone gets recorded.
PUBLIC_OCCUPANCY_TYPES = ("double", "triple")
ALL_OCCUPANCY_TYPES = ("solo", "double", "triple")


def workshop_single_supplement(workshop, occupancy_type):
    """The per-person supplement for a private room, or 0.

    Only 'solo' pays it. The published price includes a shared room, so double
    and triple occupancy are what the headline figure already covers.
    """
    if occupancy_type != "solo":
        return 0.0
    try:
        return round(float(workshop["single_supplement"] or 0), 2)
    except (KeyError, IndexError, TypeError, ValueError):
        # Older databases predate the column; no supplement is the honest answer.
        return 0.0


def workshop_subtotal(workshop, party_size, occupancy_type="double"):
    """(subtotal, supplement_per_person) before any promo discount.

    Every place that works out what a registration costs goes through here —
    the booking itself, the promo preview and the figure shown on the form. When
    the deposit is calculated from one sum and the guest was quoted another, the
    two disagree by exactly the supplement, and nobody notices until the balance
    invoice.
    """
    price = workshop["price_per_person"] or 0
    if not price:
        return 0, 0.0
    supplement = workshop_single_supplement(workshop, occupancy_type)
    return round((price + supplement) * party_size, 2), supplement


def rooms_needed(occupancy_type, party_size):
    """How many rooms a party of this size takes at this occupancy.

    The château has a fixed number of rooms, and a session's capacity counts
    heads, not rooms — so ten guests sharing need five rooms and ten guests
    each wanting their own need ten. Since the single supplement made a private
    room something a guest deliberately buys, the difference has to be counted.
    """
    party = max(int(party_size or 0), 0)
    if not party:
        return 0
    if occupancy_type == "solo":
        return party
    per_room = 3 if occupancy_type == "triple" else 2
    return -(-party // per_room)          # ceiling division


def bookable_room_count(conn):
    return conn.execute("SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"]


def workshop_rooms(conn):
    """Every room a workshop may put somebody in.

    Wider than the stay inventory by design. A room can be right for four
    nights of a course and not be something the house lists nightly, and
    reading only `active` capped every workshop at the nightly list and
    reported people as unplaceable who were not.
    """
    return conn.execute(
        """SELECT * FROM rooms
            WHERE active = 1 OR workshop_room = 1
            ORDER BY sort_order, name""").fetchall()


def _room_party(booking):
    """How many beds this booking needs in one room."""
    return max(int(booking["party_size"] or 1), 1)


def rooming_plan(conn, session_id):
    """Who is in which room, who is not, and what looks wrong.

    Reports rather than decides. Every problem here is one a person has to
    settle, and half of them are only visible when the whole session is
    looked at at once -- which is the reason a per-registration dropdown
    was never enough.
    """
    people = conn.execute(
        """SELECT workshop_bookings.*, rooms.name AS room_name,
                  rooms.max_occupancy
             FROM workshop_bookings
             LEFT JOIN rooms ON rooms.id = workshop_bookings.assigned_room_id
            WHERE workshop_bookings.session_id = ?
              AND workshop_bookings.status IN ('pending', 'confirmed')
            ORDER BY workshop_bookings.guest_name""", (session_id,)).fetchall()
    rooms = workshop_rooms(conn)

    by_room, unassigned = {}, []
    for p in people:
        if p["assigned_room_id"]:
            by_room.setdefault(p["assigned_room_id"], []).append(p)
        else:
            unassigned.append(p)

    # Who asked for whom, matched on name because that is what the guest
    # typed. Compared case- and space-insensitively; anything that does not
    # match a name on this session is reported rather than guessed at.
    names = {(p["guest_name"] or "").strip().lower(): p for p in people}
    asked = {}
    for p in people:
        want = (p["requested_roommate"] or "").strip().lower()
        if want:
            asked[p["id"]] = names.get(want)

    problems = []
    for p in people:
        want_raw = (p["requested_roommate"] or "").strip()
        if not want_raw:
            continue
        other = asked.get(p["id"])
        if other is None:
            problems.append({
                "kind": "unknown_roommate", "who": p,
                "detail": f"asked to share with {want_raw}, who is not booked "
                          "on this session"})
            continue
        # Mutual, or one-sided? A chain is a person's problem, not a
        # solver's.
        theirs = asked.get(other["id"])
        if theirs is None or theirs["id"] != p["id"]:
            problems.append({
                "kind": "one_sided", "who": p,
                "detail": f"asked for {other['guest_name']}, who asked for "
                          + ((theirs["guest_name"] + " instead")
                             if theirs else "nobody")})
        elif (p["assigned_room_id"] and other["assigned_room_id"]
              and p["assigned_room_id"] != other["assigned_room_id"]):
            problems.append({
                "kind": "split_pair", "who": p,
                "detail": f"asked for {other['guest_name']} and they asked "
                          "for each other, but they are in different rooms"})

    for room_id, occupants in by_room.items():
        heads = sum(_room_party(o) for o in occupants)
        cap = occupants[0]["max_occupancy"] or 0
        if cap and heads > cap:
            problems.append({
                "kind": "overfull", "who": occupants[0],
                "detail": f"{occupants[0]['room_name']} has {heads} in it and "
                          f"sleeps {cap}"})
        solo = [o for o in occupants if o["occupancy_type"] == "solo"]
        if solo and len(occupants) > 1:
            problems.append({
                "kind": "solo_shared", "who": solo[0],
                "detail": f"{solo[0]['guest_name']} paid for a room alone and "
                          f"is sharing {solo[0]['room_name']}"})

    beds = sum(r["max_occupancy"] or 0 for r in rooms)
    heads = sum(_room_party(p) for p in people)
    return {"people": people, "rooms": rooms, "by_room": by_room,
            "unassigned": unassigned, "problems": problems,
            "beds": beds, "heads": heads,
            "rooms_needed": session_rooms_used(conn, session_id)}


def propose_rooming(conn, session_id):
    """A suggested arrangement for whoever is not yet placed.

    Never writes, and never moves anybody already assigned: somebody put
    them there on purpose and this does not know why. It fills in around
    what is already decided.

    The order is the priority. Mutual pairs first, because those are two
    people who have both asked; then anybody needing a room to themselves,
    because that is paid for; then everybody else, largest party first, so
    a party of three does not find only twin rooms left.
    """
    plan = rooming_plan(conn, session_id)
    taken = {rid: sum(_room_party(o) for o in occ)
             for rid, occ in plan["by_room"].items()}
    rooms = {r["id"]: r for r in plan["rooms"]}

    def free(room_id):
        return (rooms[room_id]["max_occupancy"] or 0) - taken.get(room_id, 0)

    def place(people_here, why):
        need = sum(_room_party(p) for p in people_here)
        # The smallest room that still fits, so a party of two does not take
        # the only room a party of four could have used.
        fits = sorted((r for r in rooms.values() if free(r["id"]) >= need),
                      key=lambda r: (free(r["id"]), r["sort_order"]))
        if not fits:
            return None
        room = fits[0]
        taken[room["id"]] = taken.get(room["id"], 0) + need
        return [{"booking": p, "room": room, "why": why} for p in people_here]

    names = {(p["guest_name"] or "").strip().lower(): p for p in plan["people"]}
    waiting = {p["id"]: p for p in plan["unassigned"]}
    moves, placed = [], set()

    # 1. mutual requests
    for p in list(waiting.values()):
        if p["id"] in placed:
            continue
        want = (p["requested_roommate"] or "").strip().lower()
        other = names.get(want) if want else None
        if not other or other["id"] not in waiting or other["id"] in placed:
            continue
        if (other["requested_roommate"] or "").strip().lower() != \
                (p["guest_name"] or "").strip().lower():
            continue
        if p["occupancy_type"] == "solo" or other["occupancy_type"] == "solo":
            # They asked for each other and one of them paid to be alone.
            # Not a thing to solve quietly.
            continue
        made = place([p, other], "they asked for each other")
        if made:
            moves.extend(made)
            placed.update({p["id"], other["id"]})

    # 2. anybody who paid to be on their own
    for p in list(waiting.values()):
        if p["id"] in placed or p["occupancy_type"] != "solo":
            continue
        made = place([p], "paid for a room alone")
        if made:
            moves.extend(made)
            placed.add(p["id"])

    # 3. the rest, biggest party first
    rest = sorted((p for p in waiting.values() if p["id"] not in placed),
                  key=lambda p: -_room_party(p))
    for p in rest:
        made = place([p], "next room that fits")
        if made:
            moves.extend(made)
            placed.add(p["id"])

    return {"moves": moves,
            "unplaced": [p for p in waiting.values() if p["id"] not in placed],
            "plan": plan}


def session_rooms_used(conn, session_id, exclude_id=None):
    """Rooms already spoken for on a session, from the occupancy each party chose."""
    query = """SELECT occupancy_type, party_size FROM workshop_bookings
               WHERE session_id = ? AND status IN ('pending', 'confirmed')"""
    params = [session_id]
    if exclude_id:
        query += " AND id != ?"
        params.append(exclude_id)
    return sum(rooms_needed(r["occupancy_type"], r["party_size"])
               for r in conn.execute(query, params).fetchall())


def session_room_error(conn, session_id, occupancy_type, party_size, exclude_id=None):
    """None if this party still fits on the session, else why not.

    Counts PEOPLE against the house's legal occupancy, not rooms against the
    nightly room list. A workshop takes over the whole château — is_range_
    available() blocks every room for its dates — so the binding limit is how
    many people may sleep here, and bookable_room_count() only knows the handful
    of rooms let nightly, which is fewer than the bedrooms that exist. Counting
    against it refused parties for want of rooms the château has.

    The ceiling is house_guest_capacity(), the same setting the nightly side
    uses, rather than a constant: it is a licensed number and it changes without
    a deploy. The handover spec hardcoded 15 — this keeps the one source.

    The session's own capacity is checked separately by the caller; this is the
    ceiling above it. Public forms only, as before: staff entering somebody by
    hand may know something the rules do not.
    """
    party = max(int(party_size or 0), 0)
    if not party:
        return None
    cap = house_guest_capacity(conn)

    query = """SELECT COALESCE(SUM(party_size), 0) AS n FROM workshop_bookings
               WHERE session_id = ? AND status IN ('pending', 'confirmed')"""
    params = [session_id]
    if exclude_id:
        query += " AND id != ?"
        params.append(exclude_id)
    booked = conn.execute(query, params).fetchone()["n"]

    if booked + party <= cap:
        return None
    left = max(cap - booked, 0)
    if left == 0:
        return "These dates are full. Join the waitlist and we will write if a place opens."
    return (f"Only {left} place{'' if left == 1 else 's'} left on these dates, "
            f"and you are booking for {party}. Contact the château and we will see "
            f"what we can do.")


def create_workshop_booking(conn, session_row, workshop, guest_name, guest_email, guest_phone, party_size,
                             notes, occupancy_type="double", requested_roommate=None, dietary_notes=None,
                             medical_notes=None, special_occasion=None, booking_id=None, promo_code=None):
    reference_code = make_workshop_reference_code()
    manage_token = secrets.token_urlsafe(24)
    subtotal, supplement = workshop_subtotal(workshop, party_size, occupancy_type)

    promo, discount_amount = None, 0.0
    if promo_code and subtotal:
        promo, discount_amount, _ = validate_promo_code(conn, promo_code, "workshop", subtotal)
    total_price = round(subtotal - discount_amount, 2) if subtotal else None
    # Deposit/balance are split from the already-discounted total, so the
    # discount flows through to every later Stripe checkout (deposit, then
    # balance) automatically — neither of those steps needs to know a promo
    # code was ever involved.
    deposit_percent = resolve_deposit_percent(conn, "workshop", session_row["start_date"], party_size, workshop["deposit_percent"])
    deposit_amount, balance_amount, balance_due_date = compute_workshop_payment_terms(
        total_price, deposit_percent, parse_date(session_row["start_date"])
    )
    conn.execute(
        """INSERT INTO workshop_bookings
           (session_id, reference_code, manage_token, guest_name, guest_email, guest_phone, party_size,
            notes, total_price, occupancy_type, requested_roommate, dietary_notes, medical_notes,
            special_occasion, deposit_amount, balance_amount, balance_due_date, booking_id, created_at,
            promo_code_id, discount_amount, single_supplement)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (session_row["id"], reference_code, manage_token, guest_name, guest_email, guest_phone or None,
         party_size, notes or None, total_price, occupancy_type, requested_roommate or None,
         dietary_notes or None, medical_notes or None, special_occasion or None,
         deposit_amount, balance_amount, balance_due_date, booking_id, datetime.now(timezone.utc).isoformat(),
         promo["id"] if promo else None, discount_amount or None, supplement or None),
    )
    booking_row_id = conn.execute("SELECT id FROM workshop_bookings WHERE manage_token = ?", (manage_token,)).fetchone()["id"]
    # Same transaction as the booking insert -- see the room-booking path
    # for why this must not be a separate commit.
    if promo:
        record_promo_redemption(conn, promo, "workshop", reference_code, guest_email, subtotal, discount_amount)
    conn.commit()

    date_line = format_date_human(session_row["start_date"])
    if session_row["end_date"] != session_row["start_date"]:
        date_line += f" to {format_date_human(session_row['end_date'])}"

    booking_row = conn.execute(
        """SELECT workshop_bookings.*, workshop_sessions.start_date, workshop_sessions.end_date, workshops.title
           FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.id = ?""",
        (booking_row_id,),
    ).fetchone()
    send_workshop_email(conn, booking_row, "workshop_registration_received", workshop_email_context(booking_row))
    conn.commit()

    notify_title = f"Workshop registration — {workshop['title']}, {guest_name} ({date_line})"
    notified_ids = set()
    owner_row = conn.execute("SELECT id FROM users WHERE role = 'owner' LIMIT 1").fetchone()
    if owner_row:
        send_notification(conn, owner_row["id"], "workshop_booking", notify_title, body=notes, link="/admin/workshops/registrations")
        notified_ids.add(owner_row["id"])
    if workshop["instructor_user_id"] and workshop["instructor_user_id"] not in notified_ids:
        send_notification(conn, workshop["instructor_user_id"], "workshop_booking", notify_title, body=notes, link="/admin/workshops/registrations")

    return reference_code, manage_token, booking_row_id


def workshop_balance_due(conn, booking_id):
    """Running balance from the ledger, anchored on the booking's base
    total_price — charges/discounts adjust what's owed, payments/refunds
    adjust what's been paid. Returns (balance_due, total_charged, total_paid),
    all rounded to cents."""
    booking = conn.execute("SELECT total_price FROM workshop_bookings WHERE id = ?", (booking_id,)).fetchone()
    total = booking["total_price"] or 0
    paid = 0
    for row in conn.execute(
        "SELECT kind, amount FROM workshop_transactions WHERE workshop_booking_id = ?", (booking_id,)
    ).fetchall():
        if row["kind"] == "charge":
            total += row["amount"]
        elif row["kind"] == "discount":
            total -= row["amount"]
        elif row["kind"] == "payment":
            paid += row["amount"]
        elif row["kind"] == "refund":
            paid -= row["amount"]
    return round(total - paid, 2), round(total, 2), round(paid, 2)


def add_workshop_transaction(conn, booking_id, kind, description, amount, method=None, user_id=None):
    conn.execute(
        """INSERT INTO workshop_transactions
           (workshop_booking_id, kind, description, amount, method, created_by_user_id, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (booking_id, kind, description, amount, method, user_id, datetime.now(timezone.utc).isoformat()),
    )


PLACEHOLDER_TEXT = re.compile(r"\bTEST\b|\bTODO\b|\bFIXME\b|\bXXX\b|lorem ipsum", re.I)


# WHICH MERGE TAGS EACH TEMPLATE MAY USE.
#
# These templates are DATA: the owner edits the wording in the app, and
# render_email_template substitutes a context dict into whatever they typed. A
# tag the sender does not pass is left in the text UNREPLACED rather than
# crashing the send -- deliberately, because losing a booking confirmation over
# a typo is worse -- which means the typo goes to a guest as visible braces.
#
# Nothing told the owner which tags were available, so the only way to find out
# was to send one and look. This is that list, and it is enforced two ways: the
# edit form refuses a tag that is not here, and a test compares this against
# what the senders actually pass so the two cannot drift.
EMAIL_TEMPLATE_TAGS = {
    "event_balance_reminder": ("balance_amount", "balance_due_date", "contact_name",
                               "event_date", "event_type", "manage_url", "reference_code"),
    "event_inquiry_confirmed": ("contact_name", "event_type", "manage_url",
                                "price_block", "reference_code"),
    "event_inquiry_declined": ("contact_name", "event_type", "manage_url",
                               "price_block", "reference_code"),
    "event_inquiry_received": ("contact_name", "event_type", "manage_url",
                               "price_block", "reference_code"),
    "pos_receipt": ("company_block", "guest_name", "items", "receipt_number",
                    "service_date", "status_line", "table", "totals"),
    "restaurant_cancelled": ("dietary_line", "dinner_date", "guest_name", "manage_url",
                             "party_size", "price_block", "reference_code", "refund_note"),
    "restaurant_confirmed": ("dietary_line", "dinner_date", "guest_name", "manage_url",
                             "party_size", "price_block", "reference_code", "refund_note"),
    "restaurant_declined": ("dietary_line", "dinner_date", "guest_name", "manage_url",
                            "party_size", "price_block", "reference_code", "refund_note"),
    "restaurant_reservation_received": ("dietary_line", "dinner_date", "guest_name",
                                        "manage_url", "party_size", "price_block",
                                        "reference_code", "refund_note"),
    "restaurant_waitlist_opening": ("book_url", "desired_date", "name", "party_size"),
    "room_feedback_request": ("feedback_url", "guest_name", "room_name"),
    "room_waitlist_opening": ("book_url", "desired_arrival", "desired_departure", "name"),
    "workshop_balance_reminder": ("balance_amount", "balance_due_date", "balance_line",
                                  "dates", "deposit_amount", "guest_name", "manage_url",
                                  "party_size", "price_block", "reference_code",
                                  "total_price", "workshop_title"),
    "workshop_cancelled": ("balance_amount", "balance_due_date", "balance_line", "dates",
                           "deposit_amount", "guest_name", "manage_url", "party_size",
                           "price_block", "reference_code", "total_price", "workshop_title"),
    "workshop_confirmed": ("balance_amount", "balance_due_date", "balance_line", "dates",
                           "deposit_amount", "guest_name", "manage_url", "party_size",
                           "price_block", "reference_code", "total_price", "workshop_title"),
    "workshop_declined": ("balance_amount", "balance_due_date", "balance_line", "dates",
                          "deposit_amount", "guest_name", "manage_url", "party_size",
                          "price_block", "reference_code", "total_price", "workshop_title"),
    "workshop_deposit_receipt": ("balance_amount", "balance_due_date", "balance_line",
                                 "dates", "deposit_amount", "guest_name", "manage_url",
                                 "party_size", "price_block", "reference_code",
                                 "total_price", "workshop_title"),
    "workshop_feedback_request": ("feedback_url", "guest_name", "workshop_title"),
    "workshop_registration_received": ("balance_amount", "balance_due_date", "balance_line",
                                       "dates", "deposit_amount", "guest_name", "manage_url",
                                       "party_size", "price_block", "reference_code",
                                       "total_price", "workshop_title"),
    "workshop_waitlist_opening": ("dates", "name", "register_url", "workshop_title"),
}


def unknown_merge_tags(template_key, subject, body):
    """Tags in this wording that nothing will fill. Sorted, empty when fine.

    An unlisted template returns nothing rather than everything: a key this map
    has not been told about must not have its wording refused on the strength of
    a list that does not cover it.
    """
    allowed = EMAIL_TEMPLATE_TAGS.get(template_key)
    if allowed is None:
        return []
    used = set(re.findall(r"\{(\w+)\}", (subject or "") + " " + (body or "")))
    return sorted(used - set(allowed))


def render_email_template(conn, template_key, context):
    """Merge-tag substitution against an admin-editable template. Falls back
    to the raw template text (tags left unreplaced) if the context is
    missing a key rather than crashing an email send over a typo.

    Placeholder wording never reaches a guest. These templates are DATA, so a
    stray edit shows up in no diff and no commit — the restaurant confirmation
    has sat reading "TEST SUBJECT {guest_name}" three separate times, and each
    time it was only caught by someone happening to look. A page that reports
    it is not enough: the send itself has to refuse. The shipped wording is
    used instead, and the substitution is recorded so it can be found later.
    """
    row = conn.execute("SELECT subject, body FROM email_templates WHERE template_key = ?", (template_key,)).fetchone()
    if not row:
        return None, None
    subject_src, body_src = row["subject"] or "", row["body"] or ""
    # A tag nothing fills is treated exactly like placeholder text: the shipped
    # wording goes instead. Leaving it in was the older behaviour and it is the
    # wrong trade -- the guest reads "{balance_amount}" and the house looks like
    # it cannot send an email, which is worse than sending wording the owner did
    # not write. The edit form refuses these, so reaching here means the row was
    # changed some other way.
    stray = unknown_merge_tags(template_key, subject_src, body_src)
    if stray:
        app.logger.error(
            "Email template %r uses merge tags nothing fills (%s); sending the "
            "shipped wording instead. Fix it at /management/email-templates.",
            template_key, ", ".join(stray))

    if stray or PLACEHOLDER_TEXT.search(subject_src + " " + body_src):
        shipped = next((d for d in DEFAULT_EMAIL_TEMPLATES if d[0] == template_key), None)
        if shipped:
            app.logger.error(
                "Email template %r holds placeholder text; sending the shipped "
                "wording instead. Fix it at /management/email-templates.", template_key)
            subject_src, body_src = shipped[2], shipped[3]
        else:
            app.logger.error("Email template %r holds placeholder text and has no "
                             "shipped original; not sending.", template_key)
            return None, None
    try:
        subject = subject_src.format(**context)
    except (KeyError, IndexError):
        subject = subject_src
    try:
        body = body_src.format(**context)
    except (KeyError, IndexError):
        body = body_src
    return subject, body


# The fields a campaign template can use. Kept to things we can reliably fill
# for any recipient — a merge tag that silently comes out blank is worse than
# not offering it.
CAMPAIGN_MERGE_FIELDS = {
    "first_name": "The guest's first name",
    "full_name": "Their full name",
    "email": "Their email address",
    "chateau": "Château de Gudanes",
}


def render_campaign(subject, body, context):
    """Fill {{merge_tags}} in a campaign template.

    Uses {{double braces}} rather than Python's {single} formatting because
    campaign copy is full of ordinary punctuation and prose — a stray brace or
    a price like {50} shouldn't blow up a send to two hundred people. Unknown
    tags are left visible rather than silently emptied, so a typo is obvious
    in the preview instead of arriving as a blank in someone's inbox.
    """
    def fill(text):
        if not text:
            return ""
        def sub(match):
            key = match.group(1).strip()
            value = context.get(key)
            return str(value) if value not in (None, "") else match.group(0)
        return re.sub(r"\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\}\}", sub, text)
    return fill(subject), fill(body)


def campaign_context_for(name, email):
    full = (name or "").strip()
    return {
        "first_name": full.split()[0] if full else "there",
        "full_name": full or email,
        "guest_name": full or "there",
        "email": email,
        "chateau": "Château de Gudanes",
    }


def campaign_audience(conn, segments, since_date_iso=None, include_optouts=False):
    """Who a campaign would go to: {email: name}, de-duplicated.

    Builds on the existing segment logic, then removes anyone who has opted
    out. A guest with a stay AND a dinner is emailed once, not twice.
    """
    recipients = dict(promo_blast_recipients(conn, segments, since_date_iso))
    if "profiles" in segments:
        for row in conn.execute(
            "SELECT email, name FROM guests WHERE email IS NOT NULL AND TRIM(email) != ''"
        ).fetchall():
            recipients.setdefault(row["email"], row["name"])

    recipients = {(e or "").strip().lower(): n for e, n in recipients.items() if e and e.strip()}
    if not include_optouts:
        opted_out = {r["email"] for r in conn.execute("SELECT email FROM email_optouts").fetchall()}
        recipients = {e: n for e, n in recipients.items() if e not in opted_out}
    return recipients


def campaign_unsubscribe_footer(conn, token):
    """The unsubscribe line appended to every campaign message.

    Marketing mail to people in the EU has to offer a working way out and to
    identify the sender by postal address; a bulk send without either also
    lands in spam folders. Only campaign and automated mail gets this — a
    guest's own booking confirmation is transactional and must keep arriving
    whatever their marketing preference.

    The address comes from Company Info rather than a constant, so it is the
    one the owner actually maintains; it is simply omitted while unset rather
    than shipping a placeholder to guests.
    """
    try:
        link = url_for("campaign_unsubscribe", token=token, _external=True)
    except RuntimeError:
        # No request context — the trigger job runs from the scheduler.
        link = f"{PUBLIC_BASE_URL or ''}/unsubscribe/{token}"
    row = conn.execute(
        "SELECT legal_name, registered_address FROM company_info WHERE id = 1"
    ).fetchone()
    who = "Château de Gudanes"
    if row and (row["registered_address"] or "").strip():
        who += " · " + " ".join((row["registered_address"] or "").split())
    return (
        "\n\n—\n"
        f"{who}\n"
        f"Prefer not to receive these? Unsubscribe: {link}\n"
        "This only affects announcements and offers — you'll still get emails "
        "about your own bookings."
    )


def send_campaign(conn, template, recipients, user_id, dedupe_key=None,
                  as_test=False, extra_context=None):
    """Send one campaign to a set of recipients, logging every one.

    `dedupe_key` makes an automated send idempotent — the same template for the
    same guest and the same trigger date won't go twice however often the job
    runs. Failures are recorded rather than raised so one bad address doesn't
    abandon the rest of the send half-way through.

    `as_test` still really sends (a test email that doesn't arrive proves
    nothing) but logs the row as a test, so trying a template on yourself
    doesn't show up in the send history as if guests had been mailed.
    """
    now_iso = datetime.now(timezone.utc).isoformat()
    sent = failed = skipped = 0
    for email, name in recipients.items():
        key = f"{dedupe_key}:{email}" if dedupe_key else None
        if key and conn.execute(
            "SELECT 1 FROM campaign_sends WHERE dedupe_key = ?", (key,)
        ).fetchone():
            skipped += 1
            continue
        context = campaign_context_for(name, email)
        if extra_context:
            context.update(extra_context)
        subject, body = render_campaign(template["subject"], template["body"], context)
        # Every marketing message carries its own unsubscribe key. Written
        # BEFORE the send so the link in the email is always one that resolves —
        # a footer pointing at a row that doesn't exist yet would 404 for anyone
        # quick off the mark.
        unsub_token = secrets.token_urlsafe(24)
        body = body + campaign_unsubscribe_footer(conn, unsub_token)
        try:
            ok = send_email(email, subject, body)
            status = ("test" if as_test else "sent") if ok is not False else "failed"
            detail = None if status != "failed" else "send_email reported a failure"
        except Exception as e:
            status, detail = "failed", str(e)[:200]
        conn.execute(
            """INSERT INTO campaign_sends (template_id, template_name, recipient_email,
               recipient_name, subject, status, detail, dedupe_key, sent_by_user_id,
               created_at, unsubscribe_token)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (template["id"], template["name"], email, name, subject, status, detail,
             key, user_id, now_iso, unsub_token),
        )
        # Committed per recipient, not after the loop. Held open, this row's
        # INSERT blocks the NEXT recipient's send from queueing its undelivered
        # message on its own connection — so a two hundred person campaign with
        # no provider configured dropped a hundred and ninety-nine held
        # messages and left campaign_sends rows saying "failed" with nothing to
        # retry from. Per-recipient durability is also what you want if the
        # loop dies halfway.
        conn.commit()
        if status in ("sent", "test"):
            sent += 1
        elif status == "failed":
            failed += 1
    return {"sent": sent, "failed": failed, "skipped": skipped, "total": len(recipients)}


def run_campaign_triggers_job(conn):
    """Send any template set to fire relative to a guest's arrival, departure
    or workshop start. Idempotent via the dedupe key, so a guest gets each
    automated message exactly once no matter how often this runs."""
    today = house_today()
    templates = conn.execute(
        """SELECT * FROM campaign_templates
           WHERE trigger_active = 1 AND trigger_event IS NOT NULL"""
    ).fetchall()
    if not templates:
        return "no active triggers"

    opted_out = {r["email"] for r in conn.execute("SELECT email FROM email_optouts").fetchall()}
    total = 0
    for t in templates:
        offset = t["trigger_offset_days"] or 0
        # Negative offset = before the event, positive = after.
        target = (today - timedelta(days=offset)).isoformat()
        if t["trigger_event"] == "arrival":
            rows = conn.execute(
                "SELECT guest_email AS e, guest_name AS n FROM bookings "
                "WHERE status='confirmed' AND arrival_date = ?", (target,)).fetchall()
        elif t["trigger_event"] == "departure":
            rows = conn.execute(
                "SELECT guest_email AS e, guest_name AS n FROM bookings "
                "WHERE status='confirmed' AND departure_date = ?", (target,)).fetchall()
        else:
            rows = conn.execute(
                """SELECT workshop_bookings.guest_email AS e, workshop_bookings.guest_name AS n
                   FROM workshop_bookings JOIN workshop_sessions
                     ON workshop_sessions.id = workshop_bookings.session_id
                   WHERE workshop_bookings.status='confirmed'
                     AND workshop_bookings.do_not_email = 0
                     AND workshop_sessions.start_date = ?""", (target,)).fetchall()

        audience = {
            (r["e"] or "").strip().lower(): r["n"] for r in rows
            if r["e"] and (r["e"] or "").strip().lower() not in opted_out
        }
        if not audience:
            continue
        result = send_campaign(conn, t, audience, user_id=None,
                               dedupe_key=f"trigger:{t['id']}:{target}")
        total += result["sent"]
    return f"{total} automated email(s) sent"


def log_workshop_message(conn, booking_id, subject, recipient, status):
    conn.execute(
        "INSERT INTO workshop_messages (workshop_booking_id, subject, recipient, status, created_at) VALUES (?, ?, ?, ?, ?)",
        (booking_id, subject, recipient, status, datetime.now(timezone.utc).isoformat()),
    )


def send_workshop_email(conn, booking, template_key, context):
    """Sends a lifecycle email built from the admin-editable template,
    honouring the guest's do-not-email opt-out and always leaving an
    auditable row in workshop_messages — sent, skipped, or failed — so the
    registration's message history is complete regardless of outcome."""
    subject, body = render_email_template(conn, template_key, context)
    if not subject:
        return
    if booking["do_not_email"]:
        log_workshop_message(conn, booking["id"], subject, booking["guest_email"], "skipped — opted out")
        return
    sent = send_email(booking["guest_email"], subject, body)
    log_workshop_message(conn, booking["id"], subject, booking["guest_email"], "sent" if sent else "failed")


def workshop_email_context(booking):
    """Common merge-tag values available to every workshop email template.
    Expects a workshop_bookings row joined with workshop_sessions (start_date,
    end_date) and workshops (title) — the same shape every admin/guest route
    already fetches."""
    date_line = format_date_human(booking["start_date"])
    if booking["end_date"] != booking["start_date"]:
        date_line += f" to {format_date_human(booking['end_date'])}"
    price_lines = []
    if booking["total_price"]:
        price_lines.append(f"Estimated total: €{booking['total_price']:.2f}")
    if booking["deposit_amount"]:
        price_lines.append(f"Deposit due now: €{booking['deposit_amount']:.2f}")
        if booking["balance_amount"]:
            price_lines.append(f"Balance of €{booking['balance_amount']:.2f} due {booking['balance_due_date'] or 'at check-in'}")
    return {
        "guest_name": booking["guest_name"],
        "workshop_title": booking["title"],
        "dates": date_line,
        "party_size": booking["party_size"],
        "reference_code": booking["reference_code"],
        "total_price": f"{booking['total_price']:.2f}" if booking["total_price"] else "0.00",
        "deposit_amount": f"{booking['deposit_amount']:.2f}" if booking["deposit_amount"] else "0.00",
        "balance_amount": f"{booking['balance_amount']:.2f}" if booking["balance_amount"] else "0.00",
        "balance_due_date": booking["balance_due_date"] or "at check-in",
        "balance_line": (f"Balance of €{booking['balance_amount']:.2f} due {booking['balance_due_date'] or 'at check-in'}."
                          if booking["balance_amount"] else "Paid in full."),
        "price_block": ("\n" + "\n".join(price_lines)) if price_lines else "",
        "manage_url": url_for("workshop_manage", manage_token=booking["manage_token"], _external=True),
    }


def start_workshop_stripe_payment(conn, booking_id, kind, amount_override=None):
    """Builds a Stripe Checkout Session for a workshop registration's
    deposit or balance and returns its URL, or None if Stripe isn't
    configured, nothing is due, or that amount is already paid — callers
    fall back to the non-payment confirmation flow in that case, same as
    the room-booking path when Stripe is off."""
    if not stripe_enabled():
        return None
    booking = conn.execute(
        """SELECT workshop_bookings.*, workshops.title FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.id = ?""",
        (booking_id,),
    ).fetchone()
    if not booking or booking["status"] in ("declined", "cancelled"):
        return None
    if kind == "deposit":
        amount = booking["deposit_amount"]
        blocked = bool(booking["deposit_paid_at"])
        label = "Deposit"
    else:
        # The balance can move after the deposit stage if the owner adds a
        # discount, extra charge, or partial payment — pull the live figure
        # from the ledger rather than the value computed at registration time.
        amount, _, _ = workshop_balance_due(conn, booking_id)
        if amount_override is not None:
            amount = amount_override
        blocked = not booking["deposit_paid_at"]  # can't pay the balance before the deposit
        label = "Part payment" if amount_override is not None else "Balance"
    if not amount or amount <= 0 or blocked:
        return None
    try:
        checkout_session = stripe.checkout.Session.create(
            mode="payment",
            payment_method_types=["card"],
            line_items=[{
                "price_data": {
                    "currency": "eur",
                    "product_data": {"name": f"{label} — {booking['title']} ({booking['reference_code']})"},
                    "unit_amount": int(round(amount * 100)),
                },
                "quantity": 1,
            }],
            # Keep the card at deposit time so the balance can be taken on the
            # due date without the guest coming back. Only on the deposit —
            # later payments reuse what this saved. A guest who has opted out
            # of automatic payment gets an ordinary one-off charge, so nothing
            # is stored that we have said we would not use.
            payment_intent_data=(
                {"setup_future_usage": "off_session"}
                if kind == "deposit" and not booking["autocharge_opt_out"] else {}),
            customer_email=booking["guest_email"],
            success_url=url_for("workshop_stripe_success", manage_token=booking["manage_token"], kind=kind, _external=True) + "&session_id={CHECKOUT_SESSION_ID}",
            cancel_url=url_for("workshop_stripe_cancel", manage_token=booking["manage_token"], _external=True),
            metadata={"workshop_booking_id": str(booking_id), "kind": f"workshop_{kind}"},
        )
    except Exception:
        return None
    return checkout_session.url


def remember_workshop_card(conn, booking_id, session):
    """Store the Stripe customer and payment method from a deposit.

    Split out so the failure is contained: if Stripe cannot be reached, or the
    PaymentIntent has no card attached (a guest who opted out of automatic
    payment), the deposit stays recorded and the balance is simply paid the
    ordinary way. Losing a €600 deposit record to a lookup failure would be a
    far worse trade than losing the convenience.
    """
    intent_id = sval(session, "payment_intent")
    if not intent_id or not stripe_enabled():
        return
    try:
        intent = stripe.PaymentIntent.retrieve(intent_id)
        customer_id = sval(intent, "customer")
        method_id = sval(intent, "payment_method")
    except Exception as e:
        print(f"[workshop card] could not read {intent_id}: {e}")
        return
    if not customer_id or not method_id:
        return
    conn.execute(
        "UPDATE workshop_bookings SET stripe_customer_id = ?, stripe_payment_method_id = ? "
        "WHERE id = ?", (customer_id, method_id, booking_id))


def mark_workshop_payment_paid(conn, session):
    """Shared by the success redirect and the webhook — whichever fires
    first wins via the WHERE ...IS NULL guard, so a race just means the
    second call's UPDATE affects zero rows. Also logs the payment to the
    ledger and, for a deposit, emails a receipt."""
    meta = smeta(session)
    kind = meta.get("kind", "")
    booking_id = meta.get("workshop_booking_id")
    if not booking_id or kind not in ("workshop_deposit", "workshop_balance"):
        return
    booking_id = int(booking_id)
    now = datetime.now(timezone.utc).isoformat()
    if kind == "workshop_deposit":
        cur = conn.execute(
            "UPDATE workshop_bookings SET deposit_paid_at = ?, deposit_stripe_session_id = ? "
            "WHERE id = ? AND deposit_paid_at IS NULL",
            (now, session["id"], booking_id),
        )
    else:
        cur = conn.execute(
            "UPDATE workshop_bookings SET balance_paid_at = ?, balance_stripe_session_id = ? "
            "WHERE id = ? AND balance_paid_at IS NULL",
            (now, session["id"], booking_id),
        )
    if cur.rowcount:
        label = "Deposit" if kind == "workshop_deposit" else "Balance"
        amount = (sval(session, "amount_total") or 0) / 100
        add_workshop_transaction(conn, booking_id, "payment", f"{label} — Stripe", amount, method="stripe")
        if kind == "workshop_deposit":
            # Keep the customer and the card the deposit was taken on, so the
            # balance can be charged on the due date. Both come off the
            # PaymentIntent rather than the session; a failure to fetch them
            # must not lose the payment we have just recorded, so it is caught
            # — the balance simply falls back to being paid by hand.
            remember_workshop_card(conn, booking_id, session)
            booking = conn.execute(
                """SELECT workshop_bookings.*, workshop_sessions.start_date, workshop_sessions.end_date, workshops.title
                   FROM workshop_bookings
                   JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
                   JOIN workshops ON workshops.id = workshop_sessions.workshop_id
                   WHERE workshop_bookings.id = ?""",
                (booking_id,),
            ).fetchone()
            # Commit the payment before sending the receipt. If no provider is
            # configured, send_email falls back to writing the message into
            # email_outbox on its own connection, which cannot take a write lock
            # while this transaction is open — so the guest's deposit receipt was
            # being lost to "database is locked" instead of held for later.
            conn.commit()
            send_workshop_email(conn, booking, "workshop_deposit_receipt",
                                workshop_email_context(booking))
    conn.commit()


@app.route("/workshops/stripe-success")
def workshop_stripe_success():
    manage_token = request.args.get("manage_token", "")
    kind = request.args.get("kind", "")
    session_id = request.args.get("session_id", "").strip()
    if not stripe_enabled() or not session_id or not manage_token:
        abort(404)
    try:
        session = stripe.checkout.Session.retrieve(session_id)
    except Exception:
        abort(404)
    if sval(session, "payment_status") == "paid":
        conn = get_db()
        mark_workshop_payment_paid(conn, session)
        conn.close()
        flash("Payment received, thank you.", "success")
    else:
        flash("That payment wasn't completed.", "error")
    return redirect(url_for("workshop_manage", manage_token=manage_token))


@app.route("/workshops/stripe-cancel/<manage_token>")
def workshop_stripe_cancel(manage_token):
    flash("Payment was cancelled.", "error")
    return redirect(url_for("workshop_manage", manage_token=manage_token))


@app.route("/workshops/pay-deposit/<manage_token>")
def workshop_pay_deposit(manage_token):
    conn = get_db()
    booking = conn.execute("SELECT id FROM workshop_bookings WHERE manage_token = ?", (manage_token,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    checkout_url = start_workshop_stripe_payment(conn, booking["id"], "deposit")
    conn.close()
    if not checkout_url:
        flash("This deposit can't be paid online right now — contact the château directly.", "error")
        return redirect(url_for("workshop_manage", manage_token=manage_token))
    return redirect(checkout_url, code=303)


@app.route("/workshops/pay-balance/<manage_token>", methods=["GET", "POST"])
def workshop_pay_balance(manage_token):
    conn = get_db()
    booking = conn.execute("SELECT id FROM workshop_bookings WHERE manage_token = ?", (manage_token,)).fetchone()
    if not booking:
        conn.close()
        abort(404)

    # An optional part-payment. Absent or unparseable means the whole balance,
    # which keeps every link already in a guest's inbox working unchanged.
    part = parse_money(request.form.get("amount")) if request.method == "POST" else None
    if part is not None:
        due, _, _ = workshop_balance_due(conn, booking["id"])
        # Never take more than is owed, and never take an amount so small the
        # card fee eats most of it.
        if part < PART_PAYMENT_MINIMUM or part > due:
            conn.close()
            flash(f"Enter an amount between €{PART_PAYMENT_MINIMUM:.0f} and €{due:.2f}.", "error")
            return redirect(url_for("workshop_manage", manage_token=manage_token))
    checkout_url = start_workshop_stripe_payment(conn, booking["id"], "balance", amount_override=part)
    conn.close()
    if not checkout_url:
        flash("This balance can't be paid online right now — contact the château directly.", "error")
        return redirect(url_for("workshop_manage", manage_token=manage_token))
    return redirect(checkout_url, code=303)


@app.route("/workshops")
def workshops_public():
    conn = get_db()
    today = house_today()
    # Workshops are not a fixed catalogue — they are added in the admin, run,
    # and finish. A finished one must come off the public page rather than sit
    # there forever saying "dates to be announced", which is what happens if
    # only the SESSIONS are filtered by date and the workshop itself is not.
    #
    # "Finished" and "announced but not yet dated" both look like zero upcoming
    # sessions, so they are told apart by whether any session ever existed:
    #
    #   upcoming > 0            -> show, with its dates
    #   none upcoming, some past -> it is over, hide it
    #   never had any            -> coming soon, show without dates
    all_active = conn.execute(
        "SELECT * FROM workshops WHERE active = 1 ORDER BY sort_order, title").fetchall()
    workshops = []
    sessions_by_workshop = {}
    for w in all_active:
        sessions = conn.execute(
            "SELECT * FROM workshop_sessions WHERE workshop_id = ? AND start_date >= ? ORDER BY start_date",
            (w["id"], today.isoformat()),
        ).fetchall()
        if not sessions:
            ever = conn.execute(
                "SELECT 1 FROM workshop_sessions WHERE workshop_id = ? LIMIT 1",
                (w["id"],)).fetchone()
            if ever:
                continue          # it has run and is over
        workshops.append(w)
        sessions_by_workshop[w["id"]] = [
            {"session": s, "remaining": workshop_session_remaining_capacity(conn, s["id"])} for s in sessions
        ]
    featured_reviews = conn.execute(
        """SELECT workshop_feedback.*, workshops.title AS workshop_title
             FROM workshop_feedback
           LEFT JOIN workshop_bookings ON workshop_bookings.id = workshop_feedback.workshop_booking_id
           LEFT JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           LEFT JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           -- Same rule as the rooms page, for the same reason.
           WHERE workshop_feedback.featured = 1 AND workshop_feedback.rating IS NOT NULL
             AND workshop_feedback.publish_consent = 1
           ORDER BY workshop_feedback.rating DESC, workshop_feedback.submitted_at DESC LIMIT 6"""
    ).fetchall()
    conn.close()
    return render_template(
        "workshops_public.html", workshops=workshops, sessions_by_workshop=sessions_by_workshop,
        featured_reviews=featured_reviews,
    )


@app.route("/workshops/<int:workshop_id>")
def workshop_detail(workshop_id):
    conn = get_db()
    workshop = conn.execute("SELECT * FROM workshops WHERE id = ? AND active = 1", (workshop_id,)).fetchone()
    if not workshop:
        conn.close()
        abort(404)
    today = house_today()
    sessions = conn.execute(
        "SELECT * FROM workshop_sessions WHERE workshop_id = ? AND start_date >= ? ORDER BY start_date",
        (workshop_id, today.isoformat()),
    ).fetchall()
    session_rows = [{"session": s, "remaining": workshop_session_remaining_capacity(conn, s["id"])} for s in sessions]
    # A finished workshop is off the public list, so its own page would be a
    # dead end reached from an old link or a search result. Send them to what
    # is actually on rather than showing dates that have all passed.
    if not sessions:
        ever = conn.execute(
            "SELECT 1 FROM workshop_sessions WHERE workshop_id = ? LIMIT 1",
            (workshop_id,)).fetchone()
        if ever:
            conn.close()
            flash(f"{workshop['title']} has finished — here is what is coming up.", "error")
            return redirect(url_for("workshops_public"))
    conn.close()
    return render_template("workshop_detail.html", workshop=workshop, session_rows=session_rows)


@app.route("/workshops/register/<int:session_id>", methods=["GET", "POST"])
def workshop_register(session_id):
    conn = get_db()
    session_row = conn.execute(
        """SELECT workshop_sessions.*, workshops.title, workshops.price_per_person, workshops.instructor_name,
               workshops.instructor_user_id, workshops.active, workshops.deposit_percent, workshops.inclusions,
               workshops.single_supplement
           FROM workshop_sessions JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_sessions.id = ?""",
        (session_id,),
    ).fetchone()
    if not session_row or not session_row["active"]:
        conn.close()
        abort(404)
    today = house_today()
    start_date = parse_date(session_row["start_date"])
    if not start_date or start_date < today:
        conn.close()
        abort(404)
    custom_fields = conn.execute(
        "SELECT * FROM workshop_custom_fields WHERE workshop_id = ? ORDER BY sort_order",
        (session_row["workshop_id"],),
    ).fetchall()

    # Everything the page needs regardless of which way the request goes. This
    # template is rendered from three places below, and passing each value by
    # hand is how one of them ends up missing a variable that the other two
    # have — so they are gathered once and splatted into all three.
    rooms_left = max(bookable_room_count(conn) - session_rooms_used(conn, session_id), 0)
    page = {
        "session": session_row,
        "custom_fields": custom_fields,
        "rooms_left": rooms_left,
        # Don't offer a private room the château cannot give: the same reason
        # a taken night is not clickable on the booking calendar.
        "solo_possible": rooms_left >= 1 or not bookable_room_count(conn),
    }

    if request.method == "POST":
        if rate_limited(conn, "register_workshop", BOOKING_RATE_LIMIT_PER_HOUR):
            conn.commit()
            conn.close()
            flash("Too many attempts from this connection — please try again in a bit, or contact the château directly.", "error")
            return render_template(
                "workshop_register.html", **page, fully_booked=False,
                **public_form_prefill(request.form, WORKSHOP_PREFILL))

        guest_name = request.form.get("guest_name", "").strip()
        guest_email = request.form.get("guest_email", "").strip().lower()
        guest_phone = phone_from_form("guest_phone")
        notes = request.form.get("notes", "").strip()[:500]
        party_size_raw = request.form.get("party_size", "").strip()
        party_size = int(party_size_raw) if party_size_raw.isdigit() else None
        occupancy_type = request.form.get("occupancy_type", "double").strip()
        # A private room is arranged with the château directly, not booked
        # online: what it costs depends on the atelier, the dates and what is
        # free, so it is quoted case by case rather than carrying a standing
        # supplement. The refusal is here rather than only in the form because
        # hiding an <option> stops nobody from posting the value — and 'solo'
        # with no supplement set is a private room given away for nothing.
        if occupancy_type not in PUBLIC_OCCUPANCY_TYPES:
            occupancy_type = "double"
        requested_roommate = request.form.get("requested_roommate", "").strip()[:200]
        dietary_notes = request.form.get("dietary_notes", "").strip()[:500]
        medical_notes = request.form.get("medical_notes", "").strip()[:500]
        special_occasion = request.form.get("special_occasion", "").strip()[:200]
        other_guest_names = [
            line.strip()[:200] for line in request.form.get("other_guest_names", "").splitlines() if line.strip()
        ][:19]  # party_size has no hard cap, but a sane ceiling keeps this from becoming a spam vector
        promo_code = request.form.get("promo_code", "").strip()

        error = None
        fully_booked = False
        if not guest_name or not guest_email:
            error = "Name and email are required."
        elif not EMAIL_RE.match(guest_email):
            error = "Enter a valid email address."
        elif not party_size or party_size < 1:
            error = "Party size is required."
        elif party_size > session_row["capacity"]:
            error = f"This session has {session_row['capacity']} spots total."
        elif claim_workshop_places(conn, session_id) < party_size:
            # claim_, not the bare count: this one is followed by an INSERT,
            # and without the lock two people taking the last two places both
            # read "room for you".
            error = "This session is fully booked — join the waitlist below, or choose another date."
            fully_booked = True
        else:
            # end_date is the last day the guests are still there (they check
            # out that morning, the same convention a workshop uses to hold
            # every room — see is_range_available), so it needs +1 day to
            # become the exclusive end peak_guests_in_house expects.
            session_end = parse_date(session_row["end_date"])
            error = house_capacity_error(
                conn, start_date, session_end + timedelta(days=1), party_size)
            # Heads fitting is not the same as rooms fitting: since a private
            # room is now something a guest pays extra for, we must not sell
            # one the château hasn't got.
            if not error:
                error = session_room_error(conn, session_id, occupancy_type, party_size)

        custom_values = {}
        if not error:
            for f in custom_fields:
                raw = request.form.get(f"custom_{f['id']}", "").strip()
                if f["required"] and not raw:
                    error = f"'{f['label']}' is required."
                    break
                custom_values[f["id"]] = raw

        if error:
            flash(error, "error")
            conn.commit()  # persist the rate-limit log entry even on a validation error
            conn.close()
            return render_template(
                "workshop_register.html", **page, fully_booked=fully_booked,
                **public_form_prefill(request.form, WORKSHOP_PREFILL),
            )

        workshop = conn.execute("SELECT * FROM workshops WHERE id = ?", (session_row["workshop_id"],)).fetchone()
        if promo_code and workshop["price_per_person"]:
            # Same subtotal the booking will use, supplement included — a code
            # with a minimum spend must not be judged against a smaller figure
            # than the one the guest is actually being charged.
            promo_preview, _, promo_error = validate_promo_code(
                conn, promo_code, "workshop", workshop_subtotal(workshop, party_size, occupancy_type)[0]
            )
            if not promo_preview:
                flash(f"Promo code not applied: {promo_error}", "error")
        reference_code, manage_token, booking_row_id = create_workshop_booking(
            conn, session_row, workshop, guest_name, guest_email, guest_phone or None, party_size, notes,
            occupancy_type=occupancy_type, requested_roommate=requested_roommate, dietary_notes=dietary_notes,
            medical_notes=medical_notes, special_occasion=special_occasion, promo_code=promo_code or None,
        )
        now_iso = datetime.now(timezone.utc).isoformat()
        conn.execute(
            "INSERT INTO workshop_booking_guests (workshop_booking_id, guest_name, is_lead, created_at) VALUES (?, ?, 1, ?)",
            (booking_row_id, guest_name, now_iso),
        )
        for other_name in other_guest_names:
            conn.execute(
                "INSERT INTO workshop_booking_guests (workshop_booking_id, guest_name, is_lead, created_at) VALUES (?, ?, 0, ?)",
                (booking_row_id, other_name, now_iso),
            )
        for field_id, value in custom_values.items():
            if value:
                conn.execute(
                    "INSERT INTO workshop_custom_field_responses (workshop_booking_id, custom_field_id, value, created_at) VALUES (?, ?, ?, ?)",
                    (booking_row_id, field_id, value, now_iso),
                )
        conn.commit()

        checkout_url = start_workshop_stripe_payment(conn, booking_row_id, "deposit")
        conn.close()
        if checkout_url:
            return redirect(checkout_url, code=303)
        return redirect(url_for("workshop_confirmation", manage_token=manage_token))

    conn.close()
    return render_template(
        "workshop_register.html", **page, fully_booked=False,
        **public_form_prefill(request.args, {
            **{k: k for k in WORKSHOP_PREFILL},          # blank unless linked with one
            "name": "name", "email": "email", "phone": "phone",
            "party_size": "party_size",
        }),
    )


