@app.route("/admin/feedback")
@owner_required
def admin_feedback():
    conn = get_db()
    entries = conn.execute(
        """SELECT guest_feedback.*, bookings.reference_code, rooms.name AS room_name
           FROM guest_feedback
           LEFT JOIN bookings ON bookings.id = guest_feedback.booking_id
           LEFT JOIN rooms ON rooms.id = bookings.room_id
           ORDER BY guest_feedback.submitted_at DESC"""
    ).fetchall()
    avg_rating = conn.execute("SELECT AVG(rating) AS a FROM guest_feedback").fetchone()["a"]
    permissions = publishable_reviews(conn)
    conn.close()

    def verdict(e):
        """Grouped by what it means, not by the number. Nobody comes to this
        page looking for "the fours" — they come looking for what went wrong."""
        r = e["rating"] or 0
        if r <= 2:
            return "Unhappy"
        return "Fine" if r == 3 else "Delighted"

    lv = list_view(
        entries, request.args,
        search=["guest_name", "comment", "room_name", "reference_code"],
        search_hint="Search guest, room, reference or what they said",
        facets=[
            facet("verdict", "Verdict", verdict, order=["Unhappy", "Fine", "Delighted"]),
            facet("room", "Room", lambda e: e["room_name"], limit=10),
            facet("said", "Wrote something",
                  lambda e: "With a comment" if (e["comment"] or "").strip() else "Rating only",
                  order=["With a comment", "Rating only"]),
            # Three states, not two. "Featured" used to mean published;
            # it now means chosen, and the difference between chosen and
            # published is a letter somebody has to write.
            facet("featured", "On the website",
                  lambda e: ("Not featured" if not e["featured"]
                             else ("Published" if e["publish_consent"] == 1
                                   else ("They said no" if e["publish_consent"] == 0
                                         else "Waiting to be asked"))),
                  order=["Waiting to be asked", "Published", "They said no",
                         "Not featured"]),
        ],
        sorts=[
            sort_option("recent", "Most recent first", lambda e: e["submitted_at"] or "",
                        reverse=True),
            sort_option("worst", "Worst first", lambda e: (e["rating"] or 0,
                                                           e["submitted_at"] or "")),
            sort_option("best", "Best first", lambda e: e["rating"] or 0, reverse=True),
        ],
        default_sort="recent",
    )
    return render_template(
        "admin_feedback.html", entries=lv["rows"], lv=lv,
        avg_rating=round(avg_rating, 1) if avg_rating is not None else None,
        unasked=len(permissions["unasked"]),
    )


@app.route("/admin/feedback/<int:feedback_id>/reply", methods=["POST"])
@owner_required
def reply_to_feedback(feedback_id):
    """Answer a guest's review, and mark it dealt with.

    A review used to be either invisible or featured on the front page, with
    nothing in between and no way to say anything back. A complaint answered
    well reads better to the next guest than no complaint at all \u2014 and the
    guest who wrote it hears from a person rather than from nobody.

    Marking it read without writing anything is allowed on purpose. Some
    reviews want a phone call instead, and forcing a written reply into the
    app to clear the warning would produce written replies nobody meant.
    """
    conn = get_db()
    row = conn.execute(
        """SELECT guest_feedback.*, bookings.guest_email, bookings.guest_name AS booked_name
             FROM guest_feedback
             LEFT JOIN bookings ON bookings.id = guest_feedback.booking_id
            WHERE guest_feedback.id = ?""", (feedback_id,)).fetchone()
    if not row:
        conn.close()
        abort(404)
    reply = (request.form.get("reply", "") or "").strip()[:2000]
    now_iso = datetime.now(timezone.utc).isoformat()
    conn.execute(
        """UPDATE guest_feedback
              SET reply = COALESCE(?, reply),
                  replied_at = CASE WHEN ? IS NOT NULL THEN ? ELSE replied_at END,
                  acknowledged_at = COALESCE(acknowledged_at, ?),
                  acknowledged_by_user_id = COALESCE(acknowledged_by_user_id, ?)
            WHERE id = ?""",
        (reply or None, reply or None, now_iso, now_iso,
         (current_user()["id"] if current_user() else None), feedback_id))
    log_audit(conn, "feedback_answered" if reply else "feedback_marked_read",
              target=row["guest_name"] or str(feedback_id),
              details=f"{row['rating']}/5")
    conn.commit()
    conn.close()

    if reply and row["guest_email"]:
        send_email(
            row["guest_email"],
            "About your stay at Ch\u00e2teau de Gudanes",
            f"Dear {(row['booked_name'] or row['guest_name'] or 'guest').split(' ')[0]},\n\n"
            f"Thank you for telling us how it went. You wrote:\n\n"
            f"  \u201c{(row['comment'] or '').strip() or 'no comment'}\u201d\n\n"
            f"{reply}\n\n\u2014 Ch\u00e2teau de Gudanes")
        flash("Replied, and sent to them.", "success")
    else:
        flash("Marked as read." if not reply else "Reply saved.", "success")
    return redirect(url_for("admin_feedback"))


