@app.route("/admin/bookings")
@owner_required
def admin_bookings():
    status_filter = request.args.get("status", "").strip()
    room_filter = request.args.get("room_id", "").strip()
    q = request.args.get("q", "").strip()

    conn = get_db()
    rooms = conn.execute("SELECT * FROM rooms ORDER BY sort_order, name").fetchall()

    # Needed by the facets below, which run before the block that used to
    # compute it.
    today_iso_pre = house_today_iso()

    all_bookings = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name,
                  booking_parties.name AS party_name
             FROM bookings
             JOIN rooms ON rooms.id = bookings.room_id
             LEFT JOIN booking_parties ON booking_parties.id = bookings.party_id
           ORDER BY (bookings.status = 'pending') DESC,
                    (bookings.departure_date < date('now')) ASC,
                    bookings.arrival_date"""
    ).fetchall()

    # THE HOUSE RULE, applied to the one list that never had it: every list
    # gets list_view -- search, counted chips, sort -- rather than another
    # one-off search box. This page had its own, so it was the only list in the
    # app with no counts on its filters, no sort, and no saved views.
    #
    # THE OLD PARAMETERS STILL WORK. ?status=pending and ?room_id=3 are in
    # bookmarks, in links somebody has sent, and on the second screen at the
    # desk; a conversion that quietly stopped honouring them would look like the
    # filters had broken. They are mapped onto the facet keys below rather than
    # kept as a second code path.
    room_names = {r["id"]: r["name"] for r in rooms}
    legacy = request.args.to_dict()
    if status_filter and not legacy.get("state"):
        legacy["state"] = status_filter.capitalize()
    if room_filter.isdigit() and not legacy.get("room"):
        legacy["room"] = room_names.get(int(room_filter), "")

    lv = list_view(
        all_bookings, legacy,
        search=["guest_name", "guest_email", "reference_code", "room_name"],
        search_hint="Search guest, email, reference or room",
        facets=[
            # Pending first: a request nobody has answered is the only thing on
            # this page with a clock running on it.
            facet("state", "Status", lambda b: (b["status"] or "").capitalize(),
                  order=["Pending", "Confirmed", "Checked_in", "Departed",
                         "Cancelled", "Declined"]),
            facet("room", "Room", lambda b: b["room_name"], limit=12),
            facet("when", "When", lambda b: (
                "Here now" if (b["arrival_date"] or "") <= today_iso_pre
                              < (b["departure_date"] or "")
                else "Still to come" if (b["arrival_date"] or "") > today_iso_pre
                else "Been and gone"),
                  order=["Here now", "Still to come", "Been and gone"]),
        ],
        sorts=[
            sort_option("arrival", "Arriving soonest",
                        lambda b: b["arrival_date"] or "9999-12-31"),
            sort_option("recent", "Booked most recently",
                        lambda b: b["created_at"] or "", reverse=True),
            sort_option("name", "By guest",
                        lambda b: (b["guest_name"] or "").casefold()),
        ],
        default_sort="arrival",
    )
    bookings = lv["rows"]

    today = house_today()
    today_iso = today.isoformat()
    week_ahead_iso = (today + timedelta(days=7)).isoformat()
    active = [b for b in all_bookings if b["status"] in ("pending", "confirmed")]
    arriving_today = [b for b in active if b["arrival_date"] == today_iso]
    departing_today = [b for b in active if b["departure_date"] == today_iso]
    arriving_this_week = [b for b in active if today_iso < b["arrival_date"] <= week_ahead_iso]

    counts = {
        "pending": sum(1 for b in all_bookings if b["status"] == "pending"),
        "confirmed": sum(1 for b in all_bookings if b["status"] == "confirmed"),
        "total_rooms": len(rooms),
    }
    confirmed_counts_by_email = {}
    confirmed_spend_by_email = {}
    for b in all_bookings:
        if b["status"] == "confirmed" and b["guest_email"]:
            confirmed_counts_by_email[b["guest_email"]] = confirmed_counts_by_email.get(b["guest_email"], 0) + 1
            confirmed_spend_by_email[b["guest_email"]] = confirmed_spend_by_email.get(b["guest_email"], 0) + (b["total_price"] or 0)
    returning_emails = {email for email, count in confirmed_counts_by_email.items() if count > 1}
    employees = conn.execute("SELECT * FROM users WHERE role = 'employee' ORDER BY name").fetchall()
    scheduled_by_date = {}
    for row in conn.execute("SELECT shift_date, user_id FROM shifts WHERE shift_date >= ?", (today_iso,)).fetchall():
        scheduled_by_date.setdefault(row["shift_date"], set()).add(row["user_id"])
    # How much has already been handed back per booking, so the refund form can
    # show what's actually left rather than the original total.
    refunded_by_booking = {
        r["booking_id"]: round(r["total"], 2) for r in conn.execute(
            "SELECT booking_id, SUM(amount) AS total FROM refunds WHERE category = 'room' GROUP BY booking_id"
        ).fetchall()
    }
    # A caution against the rows it applies to. Gathered ONCE for the page and
    # matched in Python, not looked up per booking: a query per row is the
    # mistake the timesheet page had to be fixed for, and this list is long.
    cautioned = {}
    for row in conn.execute(
            """SELECT * FROM guests WHERE COALESCE(caution_level, '') != ''
                 AND merged_into_id IS NULL""").fetchall():
        if (row["email"] or "").strip():
            cautioned["e:" + (row["email"] or "").strip().casefold()] = row
        if (row["name"] or "").strip():
            cautioned["n:" + " ".join((row["name"] or "").casefold().split())] = row
    caution_by_booking = {}
    for b in bookings:
        hit = (cautioned.get("e:" + (b["guest_email"] or "").strip().casefold())
               or cautioned.get("n:" + " ".join((b["guest_name"] or "").casefold().split())))
        if hit:
            caution_by_booking[b["id"]] = hit

    conn.close()
    return render_template(
        "admin_bookings.html", bookings=bookings, counts=counts, rooms=rooms, employees=employees,
        lv=lv,
        caution_by_booking=caution_by_booking, caution_levels=CAUTION_LEVELS,
        # status_filter / room_filter are no longer handed over: the toolbar renders
        # the filters now, and they survive in the route only to map the old links
        # onto the facets. q stays because the page heading still uses it.
        q=q,
        arriving_today=arriving_today, departing_today=departing_today, arriving_this_week=arriving_this_week,
        returning_emails=returning_emails, confirmed_spend_by_email=confirmed_spend_by_email,
        scheduled_by_date=scheduled_by_date, today_iso=today_iso,
        refunded_by_booking=refunded_by_booking,
    )


def current_language():
    """The language to render in, for whoever is reading.

    Three sources, most specific first:

      1. A signed-in person's saved language. Staff read the app every day, so
         the choice belongs to the account rather than the browser session — a
         housekeeper should not re-pick French each login, and must not inherit
         Spanish because somebody browsed the public site on the same laptop.
      2. An explicit choice made through the switcher, remembered in the
         session. This is how a guest, who has no account, picks a language.
      3. The browser's own Accept-Language, so a French visitor gets French
         without having to find the switcher at all.

    Falls back to English. A missing translation falls back to English too, so
    a partly-filled language is always safe to serve.
    """
    if not has_request_context():
        return "en"
    # g caches it for the request: this is called once per page by the context
    # processor and again by every t() in the template, and it must not be a
    # query each time.
    cached = getattr(g, "_lang", None)
    if cached:
        return cached
    lang = None
    user = current_user()
    if user is not None:
        try:
            saved = user["language"]
        except (KeyError, IndexError):
            saved = None            # older database, before the column existed
        if saved in translations.LANGUAGES:
            lang = saved
    if lang is None:
        chosen = session.get("lang")
        if chosen in translations.LANGUAGES:
            lang = chosen
    if lang is None:
        lang = request.accept_languages.best_match(list(translations.LANGUAGES)) or "en"
    g._lang = lang
    return lang


def t(text, **kwargs):
    """Translate for the current language, then fill in any placeholders.

    Formatting happens after the lookup so a translation can move a value to
    where that language wants it — French and Spanish do not put numbers and
    nouns in the same order English does.
    """
    out = translations.translate(text, current_language())
    if kwargs:
        try:
            return out.format(**kwargs)
        except (KeyError, IndexError):
            # A translation with a typo'd placeholder must not blank the page.
            return text.format(**kwargs)
    return out


_SHELL_VERSION = None


def shell_cache_version():
    """A cache name that changes whenever anything precached does.

    THE BUG THIS FIXES. sw.js carried `var CACHE = 'gudanes-shell-v1'` and a
    comment saying to bump it by hand when the precached list changed. The
    activate handler deletes every cache whose name is not the current one, so
    that constant is the ONLY thing that can clear an installed shell — and it
    stayed at v1 through every deploy.

    The shell precaches both stylesheets. So a phone or an iPad with the app on
    its home screen has been serving the CSS from whenever it first installed,
    and ten design handovers were invisible on exactly the devices the house
    actually uses. Nothing errored; the pages simply looked like last month.

    Computed from the CONTENTS of sw.js and of every /static/ file it lists, so
    it cannot be forgotten: change a stylesheet and the name changes with it.
    The list is read out of sw.js rather than repeated here, because two lists
    would drift and the drift would be silent.

    Computed once. The files cannot change inside a running process, and a
    deploy restarts it — which is the moment the name needs to move.
    """
    global _SHELL_VERSION
    if _SHELL_VERSION:
        return _SHELL_VERSION
    static_dir = os.path.join(BASE_DIR, "static")
    digest = hashlib.sha256()
    try:
        with io.open(os.path.join(static_dir, "sw.js"), "rb") as fh:
            source = fh.read()
    except OSError:
        return "unversioned"
    digest.update(source)
    for rel in re.findall(rb"'/static/([^']+)'", source):
        try:
            with io.open(os.path.join(static_dir, rel.decode("utf-8")), "rb") as fh:
                digest.update(fh.read())
        except OSError:
            # A missing file still has to change the name, or removing one from
            # the shell would leave the old copy cached for good.
            digest.update(b"missing:" + rel)
    _SHELL_VERSION = digest.hexdigest()[:12]
    return _SHELL_VERSION


@app.route("/sw.js")
def service_worker():
    """The service worker, served from the site root rather than /static/.

    A worker's scope defaults to the directory it is served from, so at
    /static/sw.js it could only ever control pages under /static/ — it never
    saw /today or /arrive, and the offline page it falls back to could not
    appear on any page a staff member actually opens. Served from here its
    scope is the whole site, which is what makes the offline handling work at
    all. The file itself still lives in static/.

    Rendered rather than sent, so the cache name carries a hash of what is
    actually in the shell. See shell_cache_version.
    """
    static_dir = os.path.join(BASE_DIR, "static")
    try:
        with io.open(os.path.join(static_dir, "sw.js"), "r", encoding="utf-8") as fh:
            source = fh.read()
    except OSError:
        abort(404)
    source = source.replace("'gudanes-shell-v1'",
                            f"'gudanes-shell-{shell_cache_version()}'")
    response = app.response_class(source, mimetype="application/javascript")
    # The browser is meant to re-fetch this to notice a new worker at all. A
    # cached sw.js is a shell that can never be replaced.
    response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    return response


@app.route("/language/<code>")
def set_language(code):
    """Switch language and return the reader to the page they were on.

    For a signed-in person this writes to their account, so the choice sticks
    across logins and devices rather than living in one browser's session. For
    a guest, who has no account, the session is the only place to put it.
    """
    if code in translations.LANGUAGES:
        session["lang"] = code
        user = current_user()
        if user is not None:
            conn = get_db()
            conn.execute("UPDATE users SET language = ? WHERE id = ?", (code, user["id"]))
            conn.commit()
            conn.close()
        # The request already resolved a language before this ran, and the
        # redirect target is rendered by a fresh request, but clearing the
        # cache keeps this honest if that ever stops being true.
        if hasattr(g, "_lang"):
            del g._lang
    target = request.referrer or url_for("dashboard")
    # Never bounce to another site on the strength of a header: referrer is
    # attacker-settable, and an open redirect from a one-click link is exactly
    # the shape phishing wants.
    if urlparse(target).netloc and urlparse(target).netloc != request.host:
        target = url_for("dashboard")
    return redirect(target)


def guest_portal_token(conn, email):
    """The guest's own standing link, minted once and kept.

    Every other guest link in this app is per-booking: a stay, a registration
    and a dinner each carry their own manage token, so somebody who has been
    three times is holding three unrelated URLs and no way to see themselves.
    This is the one address that is *them* — the account behind the email,
    with no password to forget.

    Keyed on the guests profile, which is already one row per person (see the
    find-or-create in confirm_booking_by_id). Returns None when there is no
    profile yet: a link nobody could reach is not worth minting.
    """
    email = (email or "").strip().lower()
    if not email:
        return None
    row = conn.execute("SELECT id, portal_token FROM guests WHERE email = ? COLLATE NOCASE",
                       (email,)).fetchone()
    if not row:
        return None
    if row["portal_token"]:
        return row["portal_token"]
    token = secrets.token_urlsafe(24)
    conn.execute("UPDATE guests SET portal_token = ? WHERE id = ?", (token, row["id"]))
    return token


def guest_portal_contents(conn, email):
    """Everything of this guest's, in the order they would look for it.

    Deliberately the same sources the owner's history page reads, so the two
    cannot disagree about what a guest has — minus the parts that are the
    château's business rather than theirs: promo redemptions, lifetime spend,
    owner notes.
    """
    stays = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.guest_email = ? COLLATE NOCASE
             AND bookings.status IN ('pending', 'confirmed')
           ORDER BY bookings.arrival_date DESC""", (email,)).fetchall()
    dinners = conn.execute(
        """SELECT * FROM restaurant_bookings
           WHERE guest_email = ? COLLATE NOCASE AND status IN ('pending', 'confirmed')
           ORDER BY dinner_date DESC""", (email,)).fetchall()
    ateliers = conn.execute(
        """SELECT workshop_bookings.*, workshops.title AS workshop_title,
                  workshop_sessions.start_date, workshop_sessions.end_date
           FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.guest_email = ? COLLATE NOCASE
             AND workshop_bookings.status IN ('pending', 'confirmed')
           ORDER BY workshop_sessions.start_date DESC""", (email,)).fetchall()
    return stays, dinners, ateliers


@app.route("/my/<token>")
def guest_portal(token):
    """One link, everything of theirs. No password — the token is the secret,
    exactly as it is for the per-booking manage links this sits above."""
    conn = get_db()
    profile = conn.execute("SELECT * FROM guests WHERE portal_token = ?", (token,)).fetchone()
    if not profile:
        conn.close()
        abort(404)
    stays, dinners, ateliers = guest_portal_contents(conn, profile["email"])
    bills = {}
    for stay in stays:
        bill = booking_bill(conn, stay["id"])
        if bill and bill["owed"] > 0:
            bills[stay["id"]] = bill
    conn.close()
    return render_template(
        "guest_portal.html", profile=profile, stays=stays, dinners=dinners,
        ateliers=ateliers, bills=bills,
        today=house_today_iso(),
    )


@app.route("/admin/bookings/guest/<email>")
@owner_required
def guest_booking_history(email):
    conn = get_db()
    bookings = conn.execute(
        # Matched on the normalised address. An exact comparison made
        # "Ben@Chateau.com" and "ben@chateau.com" two different guests, which
        # for a returning one splits their history and halves the lifetime
        # spend shown right underneath it.
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
           JOIN rooms ON rooms.id = bookings.room_id
           WHERE LOWER(TRIM(guest_email)) = LOWER(TRIM(?))
           ORDER BY arrival_date DESC""",
        (email,),
    ).fetchall()
    dinners = conn.execute(
        "SELECT * FROM restaurant_bookings WHERE guest_email = ? ORDER BY dinner_date DESC", (email,)
    ).fetchall()
    workshop_regs = conn.execute(
        """SELECT workshop_bookings.*, workshops.title AS workshop_title, workshop_sessions.start_date
           FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.guest_email = ? ORDER BY workshop_sessions.start_date DESC""",
        (email,),
    ).fetchall()
    events = conn.execute(
        "SELECT * FROM event_inquiries WHERE contact_email = ? ORDER BY created_at DESC", (email,)
    ).fetchall()
    promo_redemptions = conn.execute(
        """SELECT promo_code_redemptions.*, promo_codes.code
           FROM promo_code_redemptions JOIN promo_codes ON promo_codes.id = promo_code_redemptions.promo_code_id
           WHERE promo_code_redemptions.guest_email = ? ORDER BY promo_code_redemptions.redeemed_at DESC""",
        (email,),
    ).fetchall()
    profile = conn.execute("SELECT * FROM guests WHERE email = ?", (email,)).fetchone()
    # So the owner can send a guest their own link when they ask for one.
    portal_token = guest_portal_token(conn, email)
    conn.commit()
    conn.close()
    # A profile with no activity yet is still a legitimate page to open.
    if not bookings and not dinners and not workshop_regs and not events and not profile:
        abort(404)
    lifetime_spend = sum(b["total_price"] or 0 for b in bookings if b["status"] == "confirmed")
    lifetime_spend += sum(d["total_price"] or 0 for d in dinners if d["status"] == "confirmed")
    lifetime_spend += sum(w["total_price"] or 0 for w in workshop_regs if w["status"] == "confirmed")
    lifetime_spend += sum(e["quoted_price"] or 0 for e in events if e["status"] == "confirmed")
    return render_template(
        "guest_booking_history.html", email=email, profile=profile, bookings=bookings, dinners=dinners,
        workshop_regs=workshop_regs, events=events, promo_redemptions=promo_redemptions,
        lifetime_spend=lifetime_spend, portal_token=portal_token,
    )


def confirm_booking_by_id(conn, booking_id):
    """Core confirm logic shared by the single-booking and bulk-confirm
    routes. Only acts on a still-pending booking (so a stray double-submit
    or a stale bulk selection can't re-send the confirmation email), and
    re-validates the room is still actually free for those dates before
    committing to 'confirmed' — two overlapping pending requests for the
    same room can both exist (nothing blocks *requesting* the same dates
    twice), so this is the point where a double-booking would otherwise
    slip through un-noticed. Returns (ok, reason); reason is set on
    failure. Leaves commit/close to the caller."""
    booking = conn.execute("SELECT * FROM bookings WHERE id = ? AND status = 'pending'", (booking_id,)).fetchone()
    if not booking:
        return False, "not found or not pending"

    # A CAUTION STOPS THIS TOO. The walk-in form honoured one and this did not,
    # so a standing instruction not to accept somebody was enforced at the desk
    # and ignored the moment they booked online -- and bulk-confirm would wave a
    # whole morning's requests through without anybody reading a name.
    #
    # Refused here rather than warned, for the same reason as at the desk: the
    # owner recorded an instruction, and the way to overrule it is to lift it on
    # the guest's page deliberately.
    caution = guest_caution_for(conn, email=booking["guest_email"],
                                name=booking["guest_name"])
    if caution and caution["caution_level"] == "refuse":
        return False, (f"there is a standing instruction not to accept a booking "
                       f"from {caution['name']} ({caution['caution']}) — lift it "
                       "on their profile if that has changed")
    arrival, departure = parse_date(booking["arrival_date"]), parse_date(booking["departure_date"])
    available, conflict_reason = claim_range(
        conn, booking["room_id"], arrival, departure, exclude_booking_id=booking_id, include_pending=False
    )
    if not available:
        return False, conflict_reason
    room = conn.execute("SELECT * FROM rooms WHERE id = ?", (booking["room_id"],)).fetchone()

    # Find-or-create the guest's standing profile, keyed on email. This used to
    # insert a fresh per-stay row every time, so a returning guest accumulated a
    # new "guest" per visit and their history was invisible. The profile holds
    # nothing stay-specific -- dates and party size stay on the booking.
    # guest_email is NOT NULL but '' satisfies that, and an empty string is not
    # an identity -- matching on it would either fail or, worse, mint a brand
    # new profile on every single confirm, reinstating the per-stay pile-up this
    # refactor removed. Lower-cased so casing can't split one person in two.
    guest_email = (booking["guest_email"] or "").strip().lower() or None
    guest_id = booking["linked_guest_id"]
    if not guest_id and guest_email:
        existing = conn.execute(
            "SELECT id FROM guests WHERE email = ? COLLATE NOCASE", (guest_email,)
        ).fetchone()
        guest_id = existing["id"] if existing else None
    if not guest_id:
        cur = conn.execute(
            """INSERT INTO guests (name, email, phone, notes, created_at)
               VALUES (?, ?, ?, ?, ?)""",
            (booking["guest_name"], guest_email,
             booking["guest_phone"] or None, None,
             datetime.now(timezone.utc).isoformat()),
        )
        guest_id = cur.lastrowid

    cur = conn.execute(
        "UPDATE bookings SET status='confirmed', decided_at=?, linked_guest_id=? WHERE id=? AND status='pending'",
        (datetime.now(timezone.utc).isoformat(), guest_id, booking_id),
    )
    if cur.rowcount == 0:
        # Lost a race with another confirm/decline for this same booking —
        # the guest record insert above is harmless to leave in place
        # (guest_id just goes unused), but the email below must not fire.
        return False, "not found or not pending"
    # This is the moment the guest gets a standing profile, so it is also the
    # moment their own link becomes real — and this email is the one place a
    # first-time guest is certain to see it. Built in code rather than from a
    # template, so no wording anybody has edited is disturbed by adding it.
    portal_token = guest_portal_token(conn, booking["guest_email"])
    account_line = ""
    if portal_token:
        account_line = (
            "\nEverything you have with us — this stay, any ateliers or dinners — "
            "is always here:\n"
            f"{url_for('guest_portal', token=portal_token, _external=True)}\n")
    # Commit before sending. With no email provider configured send_email falls
    # back to email_outbox on its own connection, which cannot take a write lock
    # while this transaction is open — so the guest's confirmation, with its
    # calendar invite and check-in link, was being dropped instead of held.
    # Same fault already fixed in add_extra and mark_workshop_payment_paid.
    # Safe for bulk_confirm_bookings too: it confirms in a loop, and each
    # booking being durable as it goes is what you want if the loop dies.
    conn.commit()
    send_email(
        booking["guest_email"],
        f"Booking confirmed — {room['name']}",
        f"Hi {booking['guest_name']},\n\nYour booking for {room['name']} "
        f"({format_date_human(booking['arrival_date'])} to {format_date_human(booking['departure_date'])}) "
        f"is confirmed. We look forward to hosting you.\n\n"
        f"Reference code: {booking['reference_code']}\n"
        f"Check in online — confirm your arrival time, tell us about any requests"
        f"{' and your airport transfer details' if booking_has_transfer(booking) else ''}: "
        f"{url_for('guest_checkin', manage_token=booking['manage_token'], _external=True)}\n"
        f"{account_line}\n"
        f"— Château de Gudanes",
        ics_content=generate_booking_ics(booking, room["name"]),
        ics_filename=f"{booking['reference_code']}.ics",
    )
    return True, None


@app.route("/admin/bookings/<int:booking_id>/confirm", methods=["POST"])
@owner_required
def confirm_booking(booking_id):
    conn = get_db()
    ok, reason = confirm_booking_by_id(conn, booking_id)
    if not ok:
        conn.commit()
        conn.close()
        if reason == "not found or not pending":
            abort(404)
        flash(f"Could not confirm: {reason}", "error")
        return redirect(url_for("admin_bookings"))
    conn.commit()
    conn.close()
    flash("Booking confirmed and added to the guest list.", "success")
    return redirect(url_for("admin_bookings"))


@app.route("/admin/bookings/bulk-confirm", methods=["POST"])
@owner_required
def bulk_confirm_bookings():
    booking_ids = [int(i) for i in request.form.getlist("booking_ids") if i.isdigit()]
    conn = get_db()
    # The references before anything moves, so a refusal can name the booking.
    # A count on its own tells the owner something was skipped and leaves them
    # to find out which of forty rows it was.
    refs = {}
    if booking_ids:
        refs = {r["id"]: r["reference_code"] for r in conn.execute(
            f"SELECT id, reference_code FROM bookings "
            f"WHERE id IN ({','.join('?' * len(booking_ids))})",
            tuple(booking_ids))}
    confirmed, skipped = 0, []
    for bid in booking_ids:
        ok, reason = confirm_booking_by_id(conn, bid)
        if ok:
            confirmed += 1
            continue
        # This exact string is a sentinel: the single-booking route turns it
        # into a 404, so it cannot be reworded where it is raised. In a list of
        # ten it means somebody else has already dealt with that one -- which
        # is worth saying, and used to be dropped from the count entirely.
        if reason == "not found or not pending":
            reason = "already dealt with by somebody else"
        skipped.append((refs.get(bid, f"#{bid}"), reason))
    conn.commit()
    conn.close()
    flash(*bulk_message("Confirmed", "booking", confirmed, skipped))
    return redirect(url_for("admin_bookings"))


@app.route("/admin/bookings/<int:booking_id>/checkout", methods=["POST"])
@owner_required
def checkout_booking(booking_id):
    assigned_to = request.form.get("assigned_to_user_id", "")
    if not assigned_to.isdigit():
        flash("Choose who the turnover task goes to.", "error")
        return redirect(url_for("admin_bookings"))

    conn = get_db()
    booking = conn.execute("SELECT * FROM bookings WHERE id = ?", (booking_id,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    room = conn.execute("SELECT * FROM rooms WHERE id = ?", (booking["room_id"],)).fetchone()

    now = datetime.now(timezone.utc)
    # A single conditional UPDATE is the whole guard — no separate
    # check-then-write race window, since a double-click (or two staff
    # checking the same guest out at once) would otherwise duplicate the
    # entire turnover checklist and double-send the feedback-request email.
    cur = conn.execute(
        "UPDATE bookings SET checked_out_at = ? WHERE id = ? AND checked_out_at IS NULL",
        (now.isoformat(), booking_id),
    )
    if cur.rowcount == 0:
        conn.close()
        flash("This booking was already checked out.", "error")
        return redirect(url_for("admin_bookings"))
    room_note = f"{booking['guest_name']} checked out, party of {booking['party_size']}."
    for i, title in enumerate(CHECKOUT_CHECKLIST):
        # booking_id has been on this table the whole time and neither
        # checklist set it, so which room a turnover task belonged to could
        # only be guessed from a prefix on its title.
        conn.execute(
            """INSERT INTO tasks (assigned_to_user_id, title, room_note, priority,
               due_date, created_at, origin, booking_id)
               VALUES (?, ?, ?, 'high', ?, ?, 'checklist', ?)""",
            (int(assigned_to), f"{room['name']}: {title}", room_note,
             now.date().isoformat(), now.isoformat(), booking_id),
        )
    conn.commit()
    conn.close()
    if booking["guest_email"]:
        feedback_url = url_for("guest_feedback", token=booking["manage_token"], _external=True)
        send_email(
            booking["guest_email"], "How was your stay at Château de Gudanes?",
            f"Hi {booking['guest_name']},\n\n"
            f"We hope you enjoyed your stay. If you have a moment, we'd love to hear how it went:\n"
            f"{feedback_url}\n\n"
            f"— Château de Gudanes",
        )
    flash(f"Checked out. {len(CHECKOUT_CHECKLIST)} turnover tasks assigned for {room['name']}.", "success")
    return redirect(url_for("admin_bookings"))


