MENU_CATEGORIES = ["starter", "main", "dessert", "drink"]
# The public page speaks in four categories; the till speaks in nine courses.
# This maps one onto the other so a dish entered once appears correctly in both.
COURSE_TO_CATEGORY = {
    "aperitif": "drink", "starter": "starter", "main": "main", "side": "main",
    "cheese": "dessert", "dessert": "dessert", "wine": "drink", "drink": "drink",
    "coffee": "drink",
}


@app.route("/admin/restaurant/menu")
@owner_required
def admin_restaurant_menu():
    conn = get_db()
    items = conn.execute(
        "SELECT * FROM menu_items ORDER BY sort_order, name").fetchall()
    stock_items = conn.execute(
        "SELECT id, name, unit FROM stock_items WHERE active = 1 ORDER BY name").fetchall()
    rates = {i["id"]: menu_vat_rate(conn, i) for i in items}
    pours = {}
    for i in items:
        if i["parent_item_id"]:
            pours.setdefault(i["parent_item_id"], []).append(i)
    conn.close()

    off = [i for i in items if not i["available"]]
    # A pour is shown nested under its wine, not as its own row in the list —
    # it has no independent identity worth searching or filtering on.
    top_level = [i for i in items if not i["parent_item_id"]]
    lv = list_view(
        top_level, request.args,
        search=["name", "description", "allergens", "dietary_tags"],
        search_hint="Search dish, description or allergen",
        facets=[
            # A dish that is off tonight is the first thing a waiter needs to
            # know and the last thing an alphabetical list tells them.
            facet("state", "Tonight",
                  lambda i: "Off" if not i["available"] else ("On" if i["active"] else "Hidden"),
                  order=["Off", "On", "Hidden"]),
            facet("course", "Course", lambda i: MENU_COURSES.get(i["course"], i["course"] or "Plats"),
                  order=list(MENU_COURSES.values())),
            facet("till", "On the POS",
                  lambda i: "Sold on the POS" if i["sold_in_pos"] else "Not on the POS",
                  order=["Sold on the POS", "Not on the POS"]),
            facet("allergen", "Contains",
                  lambda i: (i["allergens"] or "").split(",")[0].strip() or None, limit=8),
        ],
        sorts=[
            sort_option("course", "Course order",
                        lambda i: (COURSE_ORDER.index(i["course"])
                                   if i["course"] in COURSE_ORDER else 99,
                                   i["sort_order"] or 0, (i["name"] or "").lower())),
            sort_option("name", "Name", lambda i: (i["name"] or "").lower()),
            sort_option("price", "Dearest first", lambda i: i["price"] or 0, reverse=True),
        ],
        default_sort="course",
    )
    by_course = {}
    for i in lv["rows"]:
        by_course.setdefault(i["course"] or "main", []).append(i)
    by_course = {c: by_course[c] for c in COURSE_ORDER if c in by_course} | {
        c: v for c, v in by_course.items() if c not in COURSE_ORDER}
    return render_template(
        "admin_restaurant_menu.html", by_course=by_course, lv=lv, off=off,
        courses=MENU_COURSES, allergens=ALLERGENS, stock_items=stock_items,
        vat_rates=rates, pours=pours, serve_sizes=SERVE_SIZES,
        pour_loss_hint=STANDARD_POUR_LOSS_HINT)


@app.route("/admin/restaurant/menu/<int:item_id>/pour", methods=["POST"])
@owner_required
def add_menu_pour(item_id):
    """Add a serve size — glass, carafe, half-bottle — to a wine.

    The parent supplies the stock link and the bottle volume; this supplies
    only the size and the price. What it depletes is computed from the two,
    which is the whole reason forty wines sold two ways is no longer eighty
    hand-maintained rows.
    """
    serve_size = request.form.get("serve_size", "")
    if serve_size not in SERVE_SIZES:
        abort(400)

    def number(field):
        raw = (request.form.get(field, "") or "").strip().replace(",", ".")
        try:
            return float(raw) if raw else None
        except ValueError:
            return None

    volume, price = number("serve_volume_ml"), number("price")
    conn = get_db()
    parent = conn.execute("SELECT * FROM menu_items WHERE id = ?", (item_id,)).fetchone()
    if not parent:
        conn.close()
        abort(404)
    # arrêté du 27 mars 1987: wine by the glass, in a pichet or a carafe must
    # show its volume. Refused rather than saved half-right, because the
    # printed card is generated from this and would carry the omission.
    if (parent["course"] or "") == "wine" and not volume:
        conn.close()
        flash("Wine by the glass or carafe has to show its volume — French law "
              "requires it on the card.", "error")
        return redirect(url_for("admin_restaurant_menu"))
    if not parent["container_ml"]:
        conn.close()
        flash(f"Set the bottle size on {parent['name']} first, or a pour can't know "
              "how much of it it takes.", "error")
        return redirect(url_for("admin_restaurant_menu"))
    add_beverage_pour(conn, item_id, serve_size=serve_size, serve_volume_ml=volume,
                      price=price or 0, user_id=session.get("user_id"))
    conn.commit()
    conn.close()
    flash(f"{SERVE_SIZES[serve_size]} added to {parent['name']}.", "success")
    return redirect(url_for("admin_restaurant_menu"))


@app.route("/admin/restaurant/menu/new", methods=["POST"])
@owner_required
def new_menu_item():
    name = request.form.get("name", "").strip()
    description = request.form.get("description", "").strip()
    category = request.form.get("category", "").strip()
    dietary_tags = request.form.get("dietary_tags", "").strip()
    price_raw = request.form.get("price", "").strip()

    if not name:
        flash("Dish name is required.", "error")
        return redirect(url_for("admin_restaurant_menu"))
    if category not in MENU_CATEGORIES:
        category = "main"
    try:
        price = float(price_raw) if price_raw else None
    except ValueError:
        price = None

    course = request.form.get("course", "main").strip()
    if course not in MENU_COURSES:
        course = "main"
    # The public /restaurant page groups by `category`, and no form has ever
    # set it — so every dish added since the POS rewrite landed under "main"
    # and the page showed one undifferentiated list. Derive it from the course
    # the owner actually chose.
    category = COURSE_TO_CATEGORY.get(course, "main")
    allergens = ",".join(a for a in request.form.getlist("allergens") if a in ALLERGENS)
    stock_item_id = (request.form.get("stock_item_id", "") or "").strip()
    stock_item_id = int(stock_item_id) if stock_item_id.isdigit() else None
    try:
        stock_qty = float((request.form.get("stock_qty_per_unit", "1") or "1").replace(",", "."))
    except ValueError:
        stock_qty = 1.0
    try:
        prep = int(request.form.get("prep_minutes", "") or 0) or None
    except ValueError:
        prep = None
    vat_raw = (request.form.get("vat_rate", "") or "").strip().replace(",", ".")
    try:
        vat = float(vat_raw) if vat_raw else None
    except ValueError:
        vat = None
    sold_in_pos = 1 if request.form.get("sold_in_pos") else 0

    def _bev(field):
        raw = (request.form.get(field, "") or "").strip().replace(",", ".")
        try:
            return float(raw) if raw else None
        except ValueError:
            return None

    container_ml = _bev("container_ml")
    pour_loss = _bev("pour_loss_percent") or 0

    conn = get_db()
    if stock_item_id is not None and missing_row(conn, "stock_items", stock_item_id):
        conn.close()
        flash("That stock item no longer exists — pick another, or leave the "
              "dish unlinked.", "error")
        return redirect(url_for("admin_restaurant_menu"))
    max_order = conn.execute(
        "SELECT COALESCE(MAX(sort_order), -1) AS m FROM menu_items WHERE course = ?", (course,)
    ).fetchone()["m"]
    conn.execute(
        """INSERT INTO menu_items (name, description, category, course, dietary_tags, allergens,
           price, vat_rate, prep_minutes, stock_item_id, stock_qty_per_unit, sold_in_pos,
           container_ml, pour_loss_percent, available, sort_order, created_at)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?,?)""",
        (name, description or None, category, course, dietary_tags or None, allergens or None,
         price, vat, prep, stock_item_id, stock_qty, sold_in_pos, container_ml, pour_loss,
         max_order + 1, datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
    conn.close()
    flash(f"{name} added to the menu.", "success")
    return redirect(url_for("admin_restaurant_menu"))


@app.route("/admin/restaurant/menu/<int:item_id>/edit", methods=["POST"])
@owner_required
def edit_menu_item(item_id):
    name = request.form.get("name", "").strip()
    description = request.form.get("description", "").strip()
    category = request.form.get("category", "").strip()
    dietary_tags = request.form.get("dietary_tags", "").strip()
    price_raw = request.form.get("price", "").strip()

    conn = get_db()
    item = conn.execute("SELECT * FROM menu_items WHERE id = ?", (item_id,)).fetchone()
    if not item:
        conn.close()
        abort(404)
    if not name:
        conn.close()
        flash("Dish name is required.", "error")
        return redirect(url_for("admin_restaurant_menu"))
    if category not in MENU_CATEGORIES:
        category = item["category"]
    try:
        price = float(price_raw) if price_raw else None
    except ValueError:
        price = None
    course = request.form.get("course", item["course"] or "main").strip()
    if course not in MENU_COURSES:
        course = item["course"] or "main"
    category = COURSE_TO_CATEGORY.get(course, item["category"] or "main")
    allergens = ",".join(a for a in request.form.getlist("allergens") if a in ALLERGENS)
    stock_item_id = (request.form.get("stock_item_id", "") or "").strip()
    stock_item_id = int(stock_item_id) if stock_item_id.isdigit() else None
    try:
        stock_qty = float((request.form.get("stock_qty_per_unit", "1") or "1").replace(",", "."))
    except ValueError:
        stock_qty = 1.0
    try:
        prep = int(request.form.get("prep_minutes", "") or 0) or None
    except ValueError:
        prep = None
    vat_raw = (request.form.get("vat_rate", "") or "").strip().replace(",", ".")
    try:
        vat = float(vat_raw) if vat_raw else None
    except ValueError:
        vat = None

    def _bev(field, fallback=None):
        raw = (request.form.get(field, "") or "").strip().replace(",", ".")
        try:
            return float(raw) if raw else fallback
        except ValueError:
            return fallback

    # Fall back to what the row already holds, so a form that omits these
    # fields does not silently unset a bottle size and leave every pour of
    # that wine depleting a whole unit.
    container_ml = _bev("container_ml", item["container_ml"])
    pour_loss = _bev("pour_loss_percent", item["pour_loss_percent"]) or 0

    conn.execute(
        """UPDATE menu_items SET name=?, description=?, category=?, course=?, dietary_tags=?,
           allergens=?, price=?, vat_rate=?, prep_minutes=?, stock_item_id=?,
           stock_qty_per_unit=?, sold_in_pos=?, container_ml=?, pour_loss_percent=?
           WHERE id=?""",
        (name, description or None, category, course, dietary_tags or None,
         allergens or None, price, vat, prep, stock_item_id, stock_qty,
         1 if request.form.get("sold_in_pos") else 0, container_ml, pour_loss, item_id),
    )
    # Changing the bottle size or the loss has to move every pour of that wine
    # at once — that is the entire point of computing depletion rather than
    # typing it into eighty rows.
    for pour in conn.execute("SELECT * FROM menu_items WHERE parent_item_id = ?",
                             (item_id,)).fetchall():
        conn.execute(
            "UPDATE menu_items SET stock_item_id = ?, stock_qty_per_unit = ? WHERE id = ?",
            (stock_item_id,
             pour_stock_qty(pour["serve_volume_ml"], container_ml, pour_loss), pour["id"]))
    conn.commit()
    conn.close()
    flash("Menu item updated.", "success")
    return redirect(url_for("admin_restaurant_menu"))


@app.route("/admin/restaurant/menus")
@owner_required
def menu_history():
    """Every card ever served, searchable by the dish that was on it.

    Menus grow by one a day and for ever, and the only way to reach an old one
    was clicking back a night at a time. After one season that is unusable —
    and the whole reason for keeping dated cards was being able to answer
    "when did we last do the pigeon" and "what did we serve the Duponts".
    """
    conn = get_db()
    menus = conn.execute(
        """SELECT menus.*,
                  (SELECT COUNT(*) FROM menu_dishes WHERE menu_id = menus.id) AS dish_count,
                  (SELECT GROUP_CONCAT(name, ' · ') FROM menu_dishes
                    WHERE menu_id = menus.id) AS dish_names
           FROM menus ORDER BY service_date DESC, id DESC LIMIT 400""").fetchall()
    today = service_day_iso()

    def when(m):
        if m["service_date"] > today:
            return "Still to come"
        return "Tonight" if m["service_date"] == today else "Served"

    lv = list_view(
        menus, request.args,
        # Searching the dishes is the point — you remember the dish, not the date.
        search=["title", "formule_label", "dish_names", "service_date", "notes"],
        search_hint="Search a dish, a date or a menu name",
        facets=[
            facet("when", "When", when, order=["Still to come", "Tonight", "Served"]),
            facet("status", "State", lambda m: m["status"].capitalize(),
                  order=["Draft", "Published", "Archived"]),
            facet("service", "Service", lambda m: (m["service"] or "").capitalize()),
            facet("kind", "Pricing",
                  lambda m: "Set menu" if m["formule_price"] else "À la carte",
                  order=["Set menu", "À la carte"]),
            facet("source", "Entered by",
                  lambda m: {"manual": "Typed in", "pdf": "Read from a file",
                             "paste": "Pasted in", "copy": "Copied forward",
                             "template": "From the template"}.get(m["source"], m["source"])),
        ],
        sorts=[
            sort_option("recent", "Most recent first", lambda m: m["service_date"] or "",
                        reverse=True),
            sort_option("oldest", "Oldest first", lambda m: m["service_date"] or ""),
            sort_option("price", "Dearest set menu", lambda m: m["formule_price"] or 0,
                        reverse=True),
        ],
        default_sort="recent",
    )
    conn.close()
    published = [m for m in menus if m["status"] == "published"]
    drafts = [m for m in menus if m["status"] == "draft"]
    overview = [
        overview_cell("Cards kept", len(menus)),
        overview_cell("Published", len(published)),
        overview_cell("Drafts waiting", len(drafts), alert=bool(drafts),
                      hint="not on the POS"),
        overview_cell("Set menus", len([m for m in menus if m["formule_price"]])),
    ]
    return render_template("menu_history.html", menus=lv["rows"], lv=lv, overview=overview,
                           today=today)


@app.route("/admin/restaurant/menu/day")
@owner_required
def menu_day():
    """Tonight's card: build it, publish it, print it.

    Defaults to tonight's service, not to the calendar date — at two in the
    morning the chef wanting the card in front of them wants the one being
    served, not an empty tomorrow.
    """
    on = parse_date(request.args.get("date", "")) or service_day()
    service = request.args.get("service", "dinner")
    if service not in ("lunch", "dinner"):
        service = "dinner"
    conn = get_db()
    menu = conn.execute(
        """SELECT * FROM menus WHERE service_date = ? AND service = ? AND status != 'archived'
           ORDER BY (status = 'draft') DESC, id DESC LIMIT 1""",
        (on.isoformat(), service)).fetchone()
    dishes = menu_dishes_for(conn, menu["id"]) if menu else {}
    # What was on recently, to copy from. Most of a château card repeats.
    recent = conn.execute(
        """SELECT * FROM menus WHERE status = 'published' AND service_date < ?
           ORDER BY service_date DESC LIMIT 8""", (on.isoformat(),)).fetchall()
    standing = conn.execute(
        """SELECT COUNT(*) AS c FROM menu_items
           WHERE active = 1 AND sold_in_pos = 1 AND always_available = 1""").fetchone()["c"]
    capacity = card_capacity(conn, menu["id"], on, service) if menu else None
    clashes = dietary_clashes(conn, menu["id"], on) if menu else []
    conn.close()
    return render_template(
        "menu_day.html", menu=menu, dishes=dishes, on=on, service=service,
        courses=MENU_COURSES, allergens=ALLERGENS, recent=recent, standing=standing,
        capacity=capacity, clashes=clashes,
        prev_day=on - timedelta(days=1), next_day=on + timedelta(days=1))


