# Events included. Both promo tables had CHECKs listing the other three, so a
# code could not be scoped to an event and an event redemption could not be
# written -- and a discount with no redemption row bypasses max_redemptions
# entirely, which is how a "first ten couples" code stays live forever.
PROMO_APPLIES_TO = ["all", "room", "restaurant", "workshop", "event"]


@app.route("/admin/promo-codes")
@owner_required
def admin_promo_codes():
    conn = get_db()
    codes = conn.execute("SELECT * FROM promo_codes ORDER BY active DESC, created_at DESC").fetchall()
    # Why each code would be refused right now, for the owner. Guests are told
    # only that a code "isn't recognized, or can't be used" — deliberately, so
    # the public field can't be used to discover which codes exist — so the
    # real reason has to be visible somewhere, or "my code doesn't work" becomes
    # unanswerable. An infinite subtotal so a minimum spend never trips: this is
    # about the code's own state, not any one booking, and each code is judged
    # against its own category so "only applies to room bookings" — a setting,
    # not a fault — never shows up here as a problem.
    status = {c["code"]: promo_refusal_reason(conn, c["code"], c["applies_to"], float("inf"))
              for c in codes}
    conn.close()
    today = house_today_iso()

    def usable(c):
        """Whether a guest could actually use this code right now.

        The `active` flag alone is not the answer, and reading it as if it
        were is how a code that expired in March sits at the top of the list
        looking live. Expired, not started, and used up are all "off" — but
        they are off for different reasons, and each has a different fix.
        """
        if not c["active"]:
            return "Switched off"
        if c["valid_until"] and c["valid_until"] < today:
            return "Expired"
        if c["valid_from"] and c["valid_from"] > today:
            return "Not started yet"
        if c["max_redemptions"] and (c["redemption_count"] or 0) >= c["max_redemptions"]:
            return "Used up"
        return "Live"

    lv = list_view(
        codes, request.args,
        search=["code", "description"],
        search_hint="Search code or description",
        facets=[
            facet("state", "Usable now", usable,
                  order=["Live", "Not started yet", "Expired", "Used up", "Switched off"]),
            facet("applies", "Applies to", lambda c: c["applies_to"],
                  labels={"all": "Anything", "room": "Rooms", "restaurant": "Restaurant",
                          "workshop": "Workshops"},
                  order=PROMO_APPLIES_TO),
            facet("kind", "Discount",
                  lambda c: "Percentage off" if c["discount_type"] == "percent" else "Fixed amount"),
            facet("used", "Take-up",
                  lambda c: "Never used" if not (c["redemption_count"] or 0) else "Has been used",
                  order=["Never used", "Has been used"]),
        ],
        sorts=[
            sort_option("used", "Most redeemed", lambda c: c["redemption_count"] or 0, reverse=True),
            sort_option("ending", "Expiring soonest", lambda c: c["valid_until"] or "9999"),
            sort_option("code", "Code", lambda c: (c["code"] or "").lower()),
            sort_option("new", "Newest", lambda c: c["created_at"] or "", reverse=True),
        ],
        default_sort="used",
    )
    return render_template("admin_promo_codes.html", codes=lv["rows"], lv=lv,
                           status=status, applies_to_options=PROMO_APPLIES_TO)


def _parse_promo_form():
    """Shared parsing/validation for the new- and edit-promo-code forms —
    returns (fields_dict, None) on success or (None, error_message) on a
    bad submission."""
    code = request.form.get("code", "").strip().upper()
    description = request.form.get("description", "").strip()
    discount_type = request.form.get("discount_type", "percent").strip()
    applies_to = request.form.get("applies_to", "all").strip()
    if not code:
        return None, "A code is required."
    if discount_type not in ("percent", "fixed"):
        discount_type = "percent"
    if applies_to not in PROMO_APPLIES_TO:
        applies_to = "all"
    try:
        discount_value = float(request.form.get("discount_value", "").strip())
        if discount_value <= 0:
            raise ValueError
    except ValueError:
        return None, "Enter a discount value greater than 0."
    if discount_type == "percent" and discount_value > 100:
        return None, "A percent discount can't exceed 100."
    try:
        max_discount_amount = float(request.form.get("max_discount_amount", "").strip()) or None
    except ValueError:
        max_discount_amount = None
    try:
        min_spend = float(request.form.get("min_spend", "").strip()) or None
    except ValueError:
        min_spend = None
    max_redemptions_raw = request.form.get("max_redemptions", "").strip()
    max_redemptions = int(max_redemptions_raw) if max_redemptions_raw.isdigit() else None

    return {
        "code": code, "description": description or None, "discount_type": discount_type,
        "discount_value": discount_value, "max_discount_amount": max_discount_amount,
        "applies_to": applies_to, "min_spend": min_spend, "max_redemptions": max_redemptions,
        "valid_from": request.form.get("valid_from", "").strip() or None,
        "valid_until": request.form.get("valid_until", "").strip() or None,
    }, None


@app.route("/admin/promo-codes/new", methods=["POST"])
@owner_required
def new_promo_code():
    fields, error = _parse_promo_form()
    if error:
        flash(error, "error")
        return redirect(url_for("admin_promo_codes"))
    conn = get_db()
    user = current_user()
    try:
        conn.execute(
            """INSERT INTO promo_codes
               (code, description, discount_type, discount_value, max_discount_amount, applies_to,
                min_spend, max_redemptions, valid_from, valid_until, active, created_by_user_id, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)""",
            (fields["code"], fields["description"], fields["discount_type"], fields["discount_value"],
             fields["max_discount_amount"], fields["applies_to"], fields["min_spend"], fields["max_redemptions"],
             fields["valid_from"], fields["valid_until"], user["id"], datetime.now(timezone.utc).isoformat()),
        )
        conn.commit()
        flash(f"Promo code {fields['code']} created.", "success")
    except sqlite3.IntegrityError:
        flash(f"A code called {fields['code']} already exists.", "error")
    conn.close()
    return redirect(url_for("admin_promo_codes"))


