# ---------------------------------------------------------------------------
# Workshops — the in-house replacement for RetreatGuru. A workshop is a
# catalog entry (title, instructor, price, description); a session is a
# specific scheduled running of it with its own dates and capacity — the
# same two-level shape RetreatGuru uses (a "program" with multiple
# "occurrences"). Registrations reuse the reference-code + manage-token
# pattern from the room and restaurant booking engines for a consistent
# guest self-service experience across all three.
# ---------------------------------------------------------------------------

# Far enough ahead that something can still be ordered. A shortfall found
# the evening before is not a warning, it is an apology.
WORKSHOP_MATERIALS_WARN_DAYS = 10


def session_materials(conn, session_id):
    """What this running of the workshop needs, against what is on the shelf.

    Counted on confirmed heads, the same figure the minimum-to-run uses and
    for the same reason: somebody who has not paid a deposit does not use
    two kilos of clay.

    Per-session quantities do not scale -- eight aprons is eight aprons
    whether four people come or ten -- and per-person ones do. A list that
    only had one of the two would force every entry into the wrong shape,
    and whoever fills it in rounds, which is how a list stops being read.
    """
    session = conn.execute(
        """SELECT workshop_sessions.*, workshops.title
             FROM workshop_sessions
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_sessions.id = ?""", (session_id,)).fetchone()
    if not session:
        return None

    heads = conn.execute(
        """SELECT COALESCE(SUM(party_size), 0) AS c FROM workshop_bookings
            WHERE session_id = ? AND status = 'confirmed'""",
        (session_id,)).fetchone()["c"]

    rows = conn.execute(
        """SELECT workshop_materials.*, stock_items.name, stock_items.unit,
                  stock_items.unit_cost, stock_items.active
             FROM workshop_materials
             JOIN stock_items ON stock_items.id = workshop_materials.stock_item_id
            WHERE workshop_materials.workshop_id = ?
            ORDER BY stock_items.name""",
        (session["workshop_id"],)).fetchall()
    if not rows:
        return {"session": session, "heads": heads, "lines": [], "short": [],
                "taken_out": False, "cost": 0.0}

    levels = stock_levels(conn, [r["stock_item_id"] for r in rows])

    # Already taken out? Asked once for the session rather than per line.
    taken = {r["stock_item_id"]: r["d"] for r in conn.execute(
        """SELECT stock_item_id, COALESCE(SUM(delta), 0) AS d
             FROM stock_movements WHERE workshop_session_id = ?
            GROUP BY stock_item_id""", (session_id,)).fetchall()}

    lines, short, cost = [], [], 0.0
    for r in rows:
        need = (r["qty_per_session"] or 0) + (r["qty_per_person"] or 0) * heads
        have = levels.get(r["stock_item_id"], 0)
        line = {
            "material": r, "name": r["name"], "unit": r["unit"],
            "need": round(need, 3), "have": round(have, 3),
            "shortfall": round(max(0, need - have), 3),
            # An item taken out of stock for this session already. Kept as a
            # signed figure because that is what the ledger holds.
            "already_out": round(abs(taken.get(r["stock_item_id"], 0)), 3),
            "cost": round(need * (r["unit_cost"] or 0), 2),
            "retired": not r["active"],
        }
        cost += line["cost"]
        lines.append(line)
        if line["shortfall"] > 0:
            short.append(line)

    return {"session": session, "heads": heads, "lines": lines, "short": short,
            # Anything at all written against this session means the button
            # has been pressed. Not "every line", because an item can
            # legitimately net to nothing.
            "taken_out": bool(taken),
            "cost": round(cost, 2)}


def consume_session_materials(conn, session_id, user_id=None):
    """Take the materials out of stock, once.

    Idempotent by looking for movements already written against this
    session. The alternative -- a flag on the session -- is a second place
    the truth lives, and the ledger already knows.

    Recorded as a sale, because that is what it is: the guest paid for the
    workshop and the clay was part of what they bought. The other reasons
    would each be a lie -- wastage says it was spoiled, correction says the
    figures were wrong.
    """
    plan = session_materials(conn, session_id)
    if plan is None:
        return None
    if plan["taken_out"]:
        return {"written": 0, "already": True, "plan": plan}

    label = f"{plan['session']['title']} — {plan['session']['start_date']}"
    written = 0
    for line in plan["lines"]:
        if line["need"] <= 0:
            continue
        record_stock_movement(
            conn, line["material"]["stock_item_id"], -abs(line["need"]), "sale",
            unit_cost=line["material"]["unit_cost"],
            note=label, user_id=user_id, workshop_session_id=session_id)
        written += 1
    return {"written": written, "already": False, "plan": plan}


def shopping_basket(conn, today=None, days=None):
    """Everything worth buying, and why, grouped by supplier.

    Two reasons a thing is on this list, and an item wanted for both
    appears ONCE with both reasons named. Buying something twice because
    two parts of the app asked separately is the exact failure this
    replaces.
    """
    today = today or house_today()
    days = WORKSHOP_MATERIALS_WARN_DAYS if days is None else days

    items = {i["id"]: i for i in conn.execute(
        "SELECT * FROM stock_items WHERE active = 1").fetchall()}
    if not items:
        return {"vendors": [], "total": 0.0, "lines": 0}
    levels = stock_levels(conn, list(items))

    # {item_id: {"workshop": qty, "sessions": [names]}}
    wanted = {}
    for plan in sessions_short_of_materials(conn, today, days):
        for line in plan["short"]:
            iid = line["material"]["stock_item_id"]
            slot = wanted.setdefault(iid, {"workshop": 0.0, "sessions": []})
            # The NEED, not the shortfall: the shortfall is measured against
            # a shelf this list is about to refill, and adding shortfalls
            # across two sessions that each want the same eight kilos would
            # buy sixteen.
            slot["workshop"] += line["need"]
            label = (f"{plan['session']['title']} "
                     f"{format_date_short(plan['session']['start_date'])}")
            if label not in slot["sessions"]:
                slot["sessions"].append(label)

    by_vendor = {}
    total, lines = 0.0, 0
    for iid, item in items.items():
        have = levels.get(iid, 0)
        keep = item["reorder_level"] or 0
        need = wanted.get(iid, {}).get("workshop", 0.0)

        # Cover the sessions AND leave the reorder level on the shelf. Buying
        # only the shortfall empties the shelf the moment the workshop runs.
        buy = round(max(0.0, need + keep - have), 3)
        if buy <= 0:
            continue

        why = []
        if need:
            why.append("for " + ", ".join(wanted[iid]["sessions"][:2])
                       + (f" and {len(wanted[iid]['sessions']) - 2} more"
                          if len(wanted[iid]["sessions"]) > 2 else ""))
        if have <= keep:
            why.append(f"below the {keep:g} {item['unit']} to keep on the shelf")

        cost = round(buy * (item["unit_cost"] or 0), 2)
        total += cost
        lines += 1
        key = item["vendor_id"] or 0
        by_vendor.setdefault(key, []).append({
            "item": item, "buy": buy, "have": round(have, 3), "keep": keep,
            "workshop_need": round(need, 3), "cost": cost,
            "why": why,
            # A thing wanted for both reasons is one line, said once.
            "both": bool(need) and have <= keep,
        })

    names = {v["id"]: v for v in conn.execute("SELECT * FROM vendors").fetchall()}
    out = []
    for vid, rows in by_vendor.items():
        rows.sort(key=lambda r: -r["cost"])
        out.append({
            "vendor": names.get(vid),
            "rows": rows,
            "total": round(sum(r["cost"] for r in rows), 2),
        })
    # Somebody to ring first; the ones with no supplier on file last, because
    # they are a different job -- find out who sells this.
    out.sort(key=lambda g: (g["vendor"] is None, -g["total"]))
    return {"vendors": out, "total": round(total, 2), "lines": lines}


def sessions_short_of_materials(conn, today=None, days=None):
    """Sessions coming up without enough on the shelf to run them.

    Only the ones close enough to matter and far enough away to fix: a
    shortfall found the evening before is not a warning, it is an apology.
    """
    today = today or house_today()
    days = WORKSHOP_MATERIALS_WARN_DAYS if days is None else days
    rows = conn.execute(
        """SELECT workshop_sessions.id FROM workshop_sessions
            WHERE workshop_sessions.start_date >= ?
              AND workshop_sessions.start_date <= ?
              AND EXISTS (SELECT 1 FROM workshop_materials
                           WHERE workshop_materials.workshop_id =
                                 workshop_sessions.workshop_id)
            ORDER BY workshop_sessions.start_date""",
        (today.isoformat(), (today + timedelta(days=days)).isoformat())).fetchall()
    out = []
    for r in rows:
        plan = session_materials(conn, r["id"])
        # Already taken out of stock is not a shortfall — the shelf is low
        # BECAUSE the workshop has had it.
        if plan and plan["short"] and not plan["taken_out"]:
            out.append(plan)
    return out


WORKSHOP_DECIDE_BY_DAYS = 21

# Once the decision date is inside a week, a session that is still short is
# not "coming up" — it is a decision somebody is failing to make.
WORKSHOP_DECISION_URGENT_DAYS = 7


def sessions_at_risk(conn, today=None):
    """Sessions that will not reach their minimum, while something can be done.

    Confirmed heads only. A pending registration has not paid a deposit, and
    counting it makes the figure look better without making anybody turn up.
    It is returned alongside so the owner can see it and chase it — never
    added in.

    The waitlist is read in the same breath, because it changes the answer.
    Three short with four waiting is a telephone call, not a cancellation,
    and the row says which.
    """
    today = today or house_today()
    rows = conn.execute(
        """SELECT workshop_sessions.*, workshops.title, workshops.price_per_person,
                  workshops.instructor_name,
                  (SELECT COALESCE(SUM(party_size), 0) FROM workshop_bookings
                    WHERE session_id = workshop_sessions.id
                      AND status = 'confirmed') AS confirmed,
                  (SELECT COALESCE(SUM(party_size), 0) FROM workshop_bookings
                    WHERE session_id = workshop_sessions.id
                      AND status = 'pending') AS pending,
                  (SELECT COUNT(*) FROM workshop_waitlist
                    WHERE session_id = workshop_sessions.id
                      AND status = 'open') AS waiting,
                  (SELECT COALESCE(SUM(COALESCE(party_size, 1)), 0)
                     FROM workshop_waitlist
                    WHERE session_id = workshop_sessions.id
                      AND status = 'open') AS waiting_heads
             FROM workshop_sessions
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_sessions.min_participants > 0
              AND workshop_sessions.start_date >= ?
            ORDER BY workshop_sessions.start_date""",
        (today.isoformat(),)).fetchall()

    out = []
    for r in rows:
        if r["confirmed"] >= r["min_participants"]:
            continue
        start = parse_date(r["start_date"])
        if not start:
            continue
        decide_by = start - timedelta(days=r["decide_by_days"] or 0)
        days_left = (decide_by - today).days
        short = r["min_participants"] - r["confirmed"]
        price = r["price_per_person"] or 0
        out.append({
            "session": r,
            "title": r["title"],
            "start": start,
            "confirmed": r["confirmed"],
            "pending": r["pending"],
            "minimum": r["min_participants"],
            "short": short,
            "decide_by": decide_by,
            "days_left": days_left,
            # Past its own deadline and still short is a worse state than
            # heading towards one, and reads differently on the page.
            "overdue": days_left < 0,
            "urgent": days_left <= WORKSHOP_DECISION_URGENT_DAYS,
            "waiting": r["waiting"],
            "waiting_heads": r["waiting_heads"],
            # The whole point of reading the waitlist here. If the people
            # already waiting would close the gap, the action is to ring
            # them, and saying "cancel this" would be wrong.
            "waitlist_could_fill": r["waiting_heads"] >= short,
            "taken": round(r["confirmed"] * price, 2),
            "at_minimum": round(r["min_participants"] * price, 2),
            "gap": round(short * price, 2),
        })
    return out


def claim_workshop_places(conn, session_id, exclude_id=None):
    """Remaining places, with nobody else able to answer at the same time.

    The workshop half of claim_range, and it exists for the same bug. Every
    guest path asked how many places were left and then wrote, with nothing
    joining the two: a bare SELECT takes no write lock, so two people taking
    the last two places at the same instant both read "room for you" and both
    get one. Nothing errors. The public page says "when a session reads as
    full, it is full".

    The UPDATE is the mechanism, not bookkeeping -- writing any row takes
    SQLite's RESERVED lock, so the count that follows and the INSERT that
    follows that are one write transaction. A second connection blocks on its
    own UPDATE until the first commits, and then counts a world that includes
    it. Released by the caller's own conn.commit(), which every caller
    already does before it sends anything.

    READ-ONLY CALLERS MUST NOT USE THIS. The session lists, the public page
    and the alternative-dates suggestion all ask the same question without
    acting on it, and making them take the write lock would put every visitor
    behind whoever is mid-registration.
    """
    conn.execute("UPDATE booking_write_lock SET held_at = ? WHERE id = 1",
                 (datetime.now(timezone.utc).isoformat(),))
    return workshop_session_remaining_capacity(conn, session_id, exclude_id)


def workshop_session_remaining_capacity(conn, session_id, exclude_id=None):
    session = conn.execute("SELECT * FROM workshop_sessions WHERE id = ?", (session_id,)).fetchone()
    if not session:
        return 0
    query = """SELECT COALESCE(SUM(party_size), 0) AS t FROM workshop_bookings
               WHERE session_id = ? AND status IN ('pending', 'confirmed')"""
    params = [session_id]
    if exclude_id:
        query += " AND id != ?"
        params.append(exclude_id)
    used = conn.execute(query, params).fetchone()["t"]
    return session["capacity"] - used


@app.route("/admin/workshops")
@owner_required
def admin_workshops():
    conn = get_db()
    workshops = conn.execute("SELECT * FROM workshops ORDER BY sort_order, title").fetchall()
    today = house_today()
    period = period_from_request()
    overview = workshops_overview(conn, period, today)
    total_rooms = conn.execute("SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"]
    # Sessions used to be filtered to end_date >= today, so a workshop that had
    # already run vanished from the admin page entirely — no way to see who
    # attended or what it took. Past sessions are now loaded too and split out
    # below, with attendance so the history is worth having. The PUBLIC
    # workshops page still shows upcoming only, which is correct there.
    # Read once for the whole page and keyed by session, rather than asked
    # per session inside the loop below.
    at_risk_by_session = {w["session"]["id"]: w for w in sessions_at_risk(conn, today)}
    materials_by_workshop = {}
    for row in conn.execute(
        """SELECT workshop_materials.*, stock_items.name, stock_items.unit,
                  stock_items.active AS item_active
             FROM workshop_materials
             JOIN stock_items ON stock_items.id = workshop_materials.stock_item_id
            ORDER BY stock_items.name""").fetchall():
        materials_by_workshop.setdefault(row["workshop_id"], []).append(row)
    # Only offered where there is something to pick from.
    stock_choices = conn.execute(
        "SELECT id, name, unit FROM stock_items WHERE active = 1 ORDER BY name"
    ).fetchall()
    sessions_by_workshop, past_by_workshop = {}, {}
    for w in workshops:
        sessions = conn.execute(
            "SELECT * FROM workshop_sessions WHERE workshop_id = ? ORDER BY start_date",
            (w["id"],),
        ).fetchall()
        rows, past_rows = [], []
        for s in sessions:
            rooms_assigned = conn.execute(
                """SELECT COUNT(DISTINCT assigned_room_id) AS c FROM workshop_bookings
                   WHERE session_id = ? AND status IN ('pending', 'confirmed') AND assigned_room_id IS NOT NULL""",
                (s["id"],),
            ).fetchone()["c"]
            entry = {
                "session": s, "remaining": workshop_session_remaining_capacity(conn, s["id"]),
                "rooms_assigned": rooms_assigned,
                "at_risk": at_risk_by_session.get(s["id"]),
                # Only where there is a list to plan against, so a workshop
                # with no materials costs nothing per session.
                "materials": (session_materials(conn, s["id"])
                              if materials_by_workshop.get(w["id"]) else None),
            }
            if (s["end_date"] or s["start_date"]) >= today.isoformat():
                rows.append(entry)
            else:
                entry["attended"] = conn.execute(
                    """SELECT COALESCE(SUM(party_size), 0) AS c FROM workshop_bookings
                       WHERE session_id = ? AND status = 'confirmed'""",
                    (s["id"],),
                ).fetchone()["c"]
                past_rows.append(entry)
        past_rows.reverse()  # most recent first
        sessions_by_workshop[w["id"]] = rows
        past_by_workshop[w["id"]] = past_rows
    custom_fields_by_workshop = {}
    for row in conn.execute("SELECT * FROM workshop_custom_fields ORDER BY sort_order").fetchall():
        custom_fields_by_workshop.setdefault(row["workshop_id"], []).append(row)
    # Totalled here rather than in the template: the old version accumulated
    # inside a Jinja {% for %}, where a {% set %} doesn't escape the loop, so
    # both figures always came out as zero however many sessions were listed.
    upcoming_rows = [r for rows in sessions_by_workshop.values() for r in rows]
    upcoming_count = len(upcoming_rows)
    spots_remaining = sum(r["remaining"] for r in upcoming_rows)
    conn.close()
    return render_template(
        "admin_workshops.html", workshops=workshops, sessions_by_workshop=sessions_by_workshop,
        past_by_workshop=past_by_workshop,
        today=today, total_rooms=total_rooms,
        custom_fields_by_workshop=custom_fields_by_workshop,
                           materials_by_workshop=materials_by_workshop,
                           stock_choices=stock_choices,
        overview=overview, period=period,
        upcoming_count=upcoming_count, spots_remaining=spots_remaining,
    )


@app.route("/admin/workshops/new", methods=["GET", "POST"])
@owner_required
def new_workshop():
    if request.method == "POST":
        title = request.form.get("title", "").strip()
        description = request.form.get("description", "").strip()
        instructor_name = request.form.get("instructor_name", "").strip()
        instructor_user_id = request.form.get("instructor_user_id", "").strip()
        price_raw = request.form.get("price_per_person", "").strip()
        capacity_raw = request.form.get("default_capacity", "").strip()
        deposit_percent_raw = request.form.get("deposit_percent", "").strip()
        inclusions = request.form.get("inclusions", "").strip()
        itinerary = request.form.get("itinerary", "").strip()
        supplement = parse_money(request.form.get("single_supplement", ""))

        if not title:
            flash("Workshop title is required.", "error")
            return render_template("workshop_form.html", workshop=None, instructors=known_instructor_list())

        conn = get_db()
        instructor_id = int(instructor_user_id) if instructor_user_id.isdigit() else None
        if instructor_id is not None and missing_row(conn, "users", instructor_id):
            conn.close()
            flash("That instructor is no longer on the team — pick another, or "
                  "leave it blank and type a name.", "error")
            return render_template("workshop_form.html", workshop=None,
                                   instructors=known_instructor_list())
        max_order = conn.execute("SELECT COALESCE(MAX(sort_order), -1) AS m FROM workshops").fetchone()["m"]
        conn.execute(
            """INSERT INTO workshops (title, description, instructor_name, instructor_user_id, price_per_person,
               default_capacity, sort_order, deposit_percent, inclusions, itinerary, single_supplement, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (title, description, instructor_name or None,
             instructor_id,
             float(price_raw) if price_raw else 0,
             int(capacity_raw) if capacity_raw.isdigit() and int(capacity_raw) > 0
             else DEFAULT_WORKSHOP_CAPACITY,
             max_order + 1,
             int(deposit_percent_raw) if deposit_percent_raw.isdigit() else 30,
             inclusions or None, itinerary or None, supplement,
             datetime.now(timezone.utc).isoformat()),
        )
        conn.commit()
        conn.close()
        flash(f"{title} added.", "success")
        return redirect(url_for("admin_workshops"))

    return render_template("workshop_form.html", workshop=None, instructors=known_instructor_list())


def known_instructor_list():
    conn = get_db()
    instructors = conn.execute("SELECT * FROM users WHERE role IN ('owner', 'employee') ORDER BY role DESC, name").fetchall()
    conn.close()
    return instructors


@app.route("/admin/workshops/<int:workshop_id>/edit", methods=["GET", "POST"])
@owner_required
def edit_workshop(workshop_id):
    conn = get_db()
    workshop = conn.execute("SELECT * FROM workshops WHERE id = ?", (workshop_id,)).fetchone()
    if not workshop:
        conn.close()
        abort(404)

    if request.method == "POST":
        title = request.form.get("title", "").strip()
        description = request.form.get("description", "").strip()
        instructor_name = request.form.get("instructor_name", "").strip()
        instructor_user_id = request.form.get("instructor_user_id", "").strip()
        price_raw = request.form.get("price_per_person", "").strip()
        capacity_raw = request.form.get("default_capacity", "").strip()
        deposit_percent_raw = request.form.get("deposit_percent", "").strip()
        inclusions = request.form.get("inclusions", "").strip()
        itinerary = request.form.get("itinerary", "").strip()
        active = 1 if request.form.get("active") == "on" else 0
        supplement = parse_money(request.form.get("single_supplement", ""))

        if not title:
            conn.close()
            flash("Workshop title is required.", "error")
            return redirect(url_for("edit_workshop", workshop_id=workshop_id))

        conn.execute(
            """UPDATE workshops SET title=?, description=?, instructor_name=?, instructor_user_id=?,
               price_per_person=?, default_capacity=?, deposit_percent=?, inclusions=?, itinerary=?,
               single_supplement=?, active=? WHERE id=?""",
            (title, description, instructor_name or None,
             int(instructor_user_id) if instructor_user_id.isdigit() else None,
             float(price_raw) if price_raw else 0,
             int(capacity_raw) if capacity_raw.isdigit() and int(capacity_raw) > 0 else workshop["default_capacity"],
             int(deposit_percent_raw) if deposit_percent_raw.isdigit() else workshop["deposit_percent"],
             inclusions or None, itinerary or None, supplement, active, workshop_id),
        )
        conn.commit()
        conn.close()
        flash("Workshop updated.", "success")
        return redirect(url_for("admin_workshops"))

    instructors = conn.execute("SELECT * FROM users WHERE role IN ('owner', 'employee') ORDER BY role DESC, name").fetchall()
    conn.close()
    return render_template("workshop_form.html", workshop=workshop, instructors=instructors)


@app.route("/admin/workshops/<int:workshop_id>/delete", methods=["POST"])
@owner_required
def delete_workshop(workshop_id):
    conn = get_db()
    in_use = conn.execute(
        """SELECT COUNT(*) AS c FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           WHERE workshop_sessions.workshop_id = ?""",
        (workshop_id,),
    ).fetchone()["c"]
    if in_use:
        conn.close()
        flash("Can't delete a workshop with existing registrations — deactivate it instead.", "error")
        return redirect(url_for("admin_workshops"))
