def session_sheet_viewer(conn, session_id, user):
    """The session, if this person is allowed to see its sheet.

    Any member of staff, not only whoever teaches it. The kitchen cooks
    around the dietary notes, whoever does the rooms needs the rooming, and
    somebody on the desk answers the telephone about a guest they have
    never heard of -- none of them is the instructor.

    That is safe here and would not have been on the admin registrations
    page, which is the whole reason this exists separately: this loads no
    money. A sheet carrying balances and refund buttons is an admin screen,
    and widening one of those to the whole staff is how a guest's
    outstanding balance ends up on a phone in the kitchen.

    Returns None rather than raising, so the caller decides between 404 and
    403. A session that does not exist is not distinguished from one there
    is nothing to show for.
    """
    row = conn.execute(
        """SELECT workshop_sessions.*, workshops.title, workshops.instructor_name,
                  workshops.instructor_user_id, workshops.id AS workshop_id,
                  workshops.nights_label, workshops.sample_day
             FROM workshop_sessions
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_sessions.id = ?""", (session_id,)).fetchone()
    if not row:
        return None
    # Anybody logged in and on the staff. The route already requires a
    # login, and current_user() refuses an account marked inactive.
    return row


def session_sheet(conn, session_id):
    """Everybody coming, and what the person teaching needs to know.

    No money. Not hidden money -- money that is never loaded, so no future
    edit to the template can put a guest's balance in front of an instructor.
    """
    people = conn.execute(
        """SELECT workshop_bookings.*, rooms.name AS room_name
             FROM workshop_bookings
             LEFT JOIN rooms ON rooms.id = workshop_bookings.assigned_room_id
            WHERE workshop_bookings.session_id = ?
              AND workshop_bookings.status = 'confirmed'
            ORDER BY workshop_bookings.guest_name""", (session_id,)).fetchall()

    ids = [p["id"] for p in people]
    party, answers = {}, {}
    if ids:
        marks = ",".join("?" * len(ids))
        for r in conn.execute(
            f"""SELECT * FROM workshop_booking_guests
                 WHERE workshop_booking_id IN ({marks})
                 ORDER BY is_lead DESC, id""", ids).fetchall():
            party.setdefault(r["workshop_booking_id"], []).append(r)
        for r in conn.execute(
            f"""SELECT workshop_custom_field_responses.*, workshop_custom_fields.label
                  FROM workshop_custom_field_responses
                  JOIN workshop_custom_fields
                    ON workshop_custom_fields.id =
                       workshop_custom_field_responses.custom_field_id
                 WHERE workshop_custom_field_responses.workshop_booking_id IN ({marks})
                   AND COALESCE(workshop_custom_field_responses.value, '') != ''
                 ORDER BY workshop_custom_fields.sort_order""", ids).fetchall():
            answers.setdefault(r["workshop_booking_id"], []).append(r)

    rows, heads = [], 0
    for p in people:
        heads += p["party_size"] or 1
        rows.append({
            "booking": p,
            "party": party.get(p["id"], []),
            "answers": answers.get(p["id"], []),
        })

    # The kitchen needs the aggregate, not one line per guest. Somebody
    # cooking for fourteen reads "two coeliac, one no dairy" -- they do not
    # read fourteen rows to work that out, and asked to, they miss one.
    kitchen = []
    for r in rows:
        note = (r["booking"]["dietary_notes"] or "").strip()
        if note:
            kitchen.append({"who": r["booking"]["guest_name"], "note": note})
    medical = [{"who": r["booking"]["guest_name"],
                "note": (r["booking"]["medical_notes"] or "").strip()}
               for r in rows if (r["booking"]["medical_notes"] or "").strip()]
    occasions = [{"who": r["booking"]["guest_name"],
                  "note": (r["booking"]["special_occasion"] or "").strip()}
                 for r in rows if (r["booking"]["special_occasion"] or "").strip()]
    return {"rows": rows, "heads": heads, "kitchen": kitchen,
            "medical": medical, "occasions": occasions}


@app.route("/workshops/<int:session_id>/sheet")
@login_required
def workshop_running_sheet(session_id):
    """What the instructor takes into the room.

    Deliberately not under /admin: it is not an admin page, and the people
    who need it are not administrators.
    """
    user = current_user()
    conn = get_db()
    session_row = session_sheet_viewer(conn, session_id, user)
    if not session_row:
        conn.close()
        abort(404)
    sheet = session_sheet(conn, session_id)
    conn.close()
    return render_template("workshop_sheet.html", session=session_row,
                           sheet=sheet)


@app.route("/admin/workshops/registrations")
@owner_required
def admin_workshop_registrations():
    conn = get_db()
    status_filter = request.args.get("status", "")
    session_filter = request.args.get("session_id", "")
    query = """SELECT workshop_bookings.*, workshop_sessions.start_date, workshop_sessions.end_date,
                   workshops.title, rooms.name AS assigned_room_name FROM workshop_bookings
               JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
               JOIN workshops ON workshops.id = workshop_sessions.workshop_id
               LEFT JOIN rooms ON rooms.id = workshop_bookings.assigned_room_id
               WHERE 1=1"""
    params = []
    if status_filter:
        query += " AND workshop_bookings.status = ?"
        params.append(status_filter)
    if session_filter.isdigit():
        query += " AND workshop_bookings.session_id = ?"
        params.append(int(session_filter))
    query += " ORDER BY workshop_sessions.start_date, workshop_bookings.created_at"
    registrations = conn.execute(query, params).fetchall()
    pending_count = conn.execute("SELECT COUNT(*) AS c FROM workshop_bookings WHERE status = 'pending'").fetchone()["c"]
    rooms = conn.execute("SELECT * FROM rooms WHERE active = 1 ORDER BY sort_order, name").fetchall()
    guests_by_booking = {}
    for row in conn.execute(
        "SELECT * FROM workshop_booking_guests ORDER BY is_lead DESC, id"
    ).fetchall():
        guests_by_booking.setdefault(row["workshop_booking_id"], []).append(row)
    custom_responses_by_booking = {}
    for row in conn.execute(
        """SELECT workshop_custom_field_responses.*, workshop_custom_fields.label
           FROM workshop_custom_field_responses
           JOIN workshop_custom_fields ON workshop_custom_fields.id = workshop_custom_field_responses.custom_field_id
           WHERE workshop_custom_field_responses.value IS NOT NULL AND workshop_custom_field_responses.value != ''
           ORDER BY workshop_custom_fields.sort_order"""
    ).fetchall():
        custom_responses_by_booking.setdefault(row["workshop_booking_id"], []).append(row)
    transactions_by_booking = {}
    balance_by_booking = {}
    for r in registrations:
        txns = conn.execute(
            "SELECT * FROM workshop_transactions WHERE workshop_booking_id = ? ORDER BY created_at", (r["id"],)
        ).fetchall()
        transactions_by_booking[r["id"]] = txns
        balance_by_booking[r["id"]] = workshop_balance_due(conn, r["id"])
    messages_by_booking = {}
    for row in conn.execute("SELECT * FROM workshop_messages ORDER BY created_at DESC").fetchall():
        messages_by_booking.setdefault(row["workshop_booking_id"], []).append(row)
    # What each registration has actually paid (from its ledger) and what has
    # already been handed back, so the refund form knows its ceiling.
    refunded_by_registration = {
        r["booking_id"]: round(r["total"], 2) for r in conn.execute(
            "SELECT booking_id, SUM(amount) AS total FROM refunds WHERE category = 'workshop' GROUP BY booking_id"
        ).fetchall()
    }
    # Gross payments per registration, in ONE grouped query rather than a
    # lookup per row. (Gross, not the net figure from balance_by_booking -- see
    # amount_paid_for() for why netting refunds off here double-counts them.)
    paid_by_registration = {
        r["workshop_booking_id"]: round(r["paid"], 2) for r in conn.execute(
            """SELECT workshop_booking_id, SUM(amount) AS paid FROM workshop_transactions
               WHERE kind = 'payment' GROUP BY workshop_booking_id"""
        ).fetchall()
    }
    conn.close()
    return render_template(
        "admin_workshop_registrations.html", registrations=registrations, status_filter=status_filter,
        pending_count=pending_count, rooms=rooms,
        guests_by_booking=guests_by_booking, custom_responses_by_booking=custom_responses_by_booking,
        transactions_by_booking=transactions_by_booking, balance_by_booking=balance_by_booking,
        messages_by_booking=messages_by_booking,
        refunded_by_registration=refunded_by_registration, paid_by_registration=paid_by_registration,
    )


@app.route("/admin/workshops/registrations/<int:registration_id>/occupancy", methods=["POST"])
@owner_required
def set_workshop_occupancy(registration_id):
    """Record a private room that was arranged with the château directly.

    Solo is not bookable on the public form: what a private room costs depends
    on the atelier, the dates and what is free, so it is quoted per enquiry.
    This is where that quote is entered once it has been agreed — the guest
    who phoned up is on the same registration as everyone else, just with an
    occupancy and a supplement staff set by hand.

    The supplement is per person, matching workshop_subtotal(), and repricing
    goes through the same arithmetic as the booking itself so the two cannot
    drift. An existing discount is preserved as the amount already agreed
    rather than re-derived from the new subtotal.
    """
    conn = get_db()
    reg = conn.execute(
        """SELECT workshop_bookings.*, workshop_sessions.start_date, workshops.price_per_person,
                  workshops.deposit_percent
           FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.id = ?""", (registration_id,)).fetchone()
    if not reg:
        conn.close()
        abort(404)

    occupancy = (request.form.get("occupancy_type", "") or "").strip()
    if occupancy not in ALL_OCCUPANCY_TYPES:
        conn.close()
        flash("Choose a room arrangement.", "error")
        return redirect(url_for("admin_workshop_registrations"))

    supplement = parse_money(request.form.get("single_supplement", "")) or 0.0
    if occupancy != "solo":
        supplement = 0.0   # only a private room carries one

    # Staff can override capacity, but not silently: a solo booking needs a
    # room per guest, and if the session has not got them somebody has to know
    # before the guest is told yes.
    room_problem = session_room_error(conn, reg["session_id"], occupancy, reg["party_size"],
                                      exclude_id=registration_id)

    price = reg["price_per_person"] or 0
    subtotal = round((price + supplement) * reg["party_size"], 2) if price else 0
    discount = reg["discount_amount"] or 0.0
    total_price = round(subtotal - discount, 2) if subtotal else None
    deposit_percent = resolve_deposit_percent(
        conn, "workshop", reg["start_date"], reg["party_size"], reg["deposit_percent"])
    deposit_amount, balance_amount, balance_due_date = compute_workshop_payment_terms(
        total_price, deposit_percent, parse_date(reg["start_date"]))
    # A deposit already paid is not re-taken; only what is still owed moves.
    if reg["deposit_paid_at"]:
        deposit_amount = reg["deposit_amount"]
        balance_amount = round((total_price or 0) - (deposit_amount or 0), 2)

    conn.execute(
        """UPDATE workshop_bookings
           SET occupancy_type = ?, single_supplement = ?, total_price = ?,
               deposit_amount = ?, balance_amount = ?, balance_due_date = ?
           WHERE id = ?""",
        (occupancy, supplement or None, total_price, deposit_amount, balance_amount,
         balance_due_date, registration_id))
    log_audit(conn, "workshop_occupancy_set", target=reg["reference_code"],
              details=f"{occupancy}, supplement €{supplement:.2f}")
    conn.commit()
    conn.close()

    if room_problem:
        flash(f"Saved — but note: {room_problem}", "error")
    else:
        flash(f"Room arrangement saved for {reg['reference_code']}.", "success")
    return redirect(url_for("admin_workshop_registrations"))


@app.route("/admin/workshops/registrations/<int:registration_id>/confirm", methods=["POST"])
@owner_required
def confirm_workshop_registration(registration_id):
    conn = get_db()
    booking = conn.execute(
        """SELECT workshop_bookings.*, workshop_sessions.start_date, workshop_sessions.end_date,
               workshop_sessions.capacity, workshops.title FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.id = ?""",
        (registration_id,),
    ).fetchone()
    if not booking:
        conn.close()
        abort(404)
    cur = conn.execute(
        "UPDATE workshop_bookings SET status = 'confirmed', decided_at = ? WHERE id = ? AND status = 'pending'",
        (datetime.now(timezone.utc).isoformat(), registration_id),
    )
    if cur.rowcount == 0:
        conn.close()
        abort(404)
    log_audit(conn, "workshop_registration_confirmed", target=booking["reference_code"])
    conn.commit()

    confirmed_total = conn.execute(
        "SELECT COALESCE(SUM(party_size), 0) AS t FROM workshop_bookings WHERE session_id = ? AND status = 'confirmed'",
        (booking["session_id"],),
    ).fetchone()["t"]
    # NOT guarded by claim_workshop_places, on purpose. This writes and then
    # says "over the cap", which is a staff override with a warning attached
    # -- the same reasoning as entering a booking by hand, where somebody may
    # know something the rules do not. What the public promise is about is a
    # GUEST being told there is room and then finding there was not, and that
    # is the path that takes the lock.
    capacity_note = ""
    if confirmed_total > booking["capacity"]:
        capacity_note = f" Heads up — confirmed registrations for this session now total {confirmed_total}, over the {booking['capacity']}-spot cap."

    send_workshop_email(conn, booking, "workshop_confirmed", workshop_email_context(booking))
    conn.commit()
    conn.close()
    flash("Registration confirmed." + capacity_note, "success" if not capacity_note else "error")
    return redirect(url_for("admin_workshop_registrations"))


