@app.route("/management/money-ahead")
@owner_required
def money_ahead_page():
    days = request.args.get("days", "90")
    days = int(days) if days.isdigit() else 90
    conn = get_db()
    ahead = money_ahead(conn, days=days)
    conn.close()
    overview = [
        overview_cell("Expected in", euro(ahead["total_in"]),
                      hint=f"over {ahead['days']} days"),
        # Split, because an agreed invoice and a bill somebody may yet reject
        # are not the same kind of certain, and one figure covering both gets
        # planned against as though it were.
        overview_cell("Expected out", euro(ahead["total_out"]),
                      hint=(f"{euro(ahead['agreed_out'])} agreed"
                            + (f", {euro(ahead['undecided_out'])} awaiting a decision"
                               if ahead["undecided_out"] else "")
                            if ahead["agreed_out"] or ahead["undecided_out"] else None)),
        overview_cell("Difference", euro(ahead["net"]), alert=ahead["net"] < 0,
                      hint="not a balance" if ahead["opening"] is None else None),
    ]
    if ahead["opening"] is not None:
        overview.append(overview_cell("Where that leaves you", euro(ahead["closing"]),
                                      alert=ahead["closing"] < 0))
    return render_template("money_ahead.html", ahead=ahead, overview=overview, days=days)


def _save_money_setting(key, raw, *, cleared_msg, saved_msg, audit):
    """Store one of the two figures the owner sets, or clear it."""
    raw = (raw or "").strip().replace(",", ".").replace(" ", "")
    conn = get_db()
    if not raw:
        conn.execute("DELETE FROM app_settings WHERE key = ?", (key,))
        conn.commit()
        conn.close()
        flash(cleared_msg, "success")
        return
    try:
        value = round(float(raw), 2)
    except ValueError:
        conn.close()
        flash("That is not a number.", "error")
        return
    conn.execute(
        """INSERT INTO app_settings (key, value) VALUES (?, ?)
           ON CONFLICT(key) DO UPDATE SET value = excluded.value""",
        (key, f"{value:.2f}"))
    conn.commit()
    log_audit(conn, audit, details=f"€{value:.2f}")
    conn.commit()
    conn.close()
    flash(saved_msg, "success")


