# ---------------------------------------------------------------------------
# Money ahead.
#
# Every figure below already exists, on five different screens: a room booking
# knows what it is worth and what has been paid, a workshop registration knows
# its balance and the date that balance falls due, recurring costs know when
# they next go out, insurance knows its renewal. Nobody has ever put them on
# one timeline, so the question a house funding a restoration actually asks —
# what is coming in, what is going out, and which month is tight — has no
# answer anywhere in the app.
#
# What this deliberately does NOT claim: that it knows the bank balance. It
# does not. Without an opening figure the running line is a CHANGE, not a
# balance, and saying otherwise would be inventing the most important number
# on the page. The opening balance is a setting; until it is set, the page
# says so plainly rather than implying a total it cannot know.
# ---------------------------------------------------------------------------

OPENING_BALANCE_SETTING = "money_ahead_opening_balance"
# Wages, as a figure the owner sets rather than one this app works out.
#
# It could try: there are hours, shifts and pay rates. But pay_rate and
# pay_type are free text, estimated_hourly_cost() says in its own docstring
# that it is "never a payroll or payslip figure", and most people on the books
# have no usable rate at all. Deriving a wage bill from that would put a guess
# on the one page that promises only money somebody has committed to. A figure
# the owner types is worth more than a figure we infer, because they know
# which it is.
MONTHLY_STAFF_COST_SETTING = "money_ahead_monthly_staff"


def _month_starts(first, last):
    """Every month start from first to last inclusive, as dates."""
    out, cur = [], first.replace(day=1)
    while cur <= last:
        out.append(cur)
        cur = (date(cur.year + 1, 1, 1) if cur.month == 12
               else date(cur.year, cur.month + 1, 1))
    return out


def _recurring_dates(next_due, frequency, first, last):
    """When a standing cost falls due inside the window.

    Walked forward from its own next-due date rather than from today, so a
    cost due on the 8th stays on the 8th. A cost whose next-due date is in the
    past is treated as due now — it has not stopped being owed.
    """
    if not next_due:
        return []
    step_months = 12 if frequency == "annual" else 1
    out, cur = [], next_due
    while cur < first:
        cur = _add_months(cur, step_months)
    while cur <= last:
        out.append(cur)
        cur = _add_months(cur, step_months)
    return out


def _add_months(d, months):
    total = d.month - 1 + months
    year, month = d.year + total // 12, total % 12 + 1
    return date(year, month, min(d.day, monthrange(year, month)[1]))


def money_ahead(conn, *, days=90, today=None):
    """What is expected in and out over the window, and when.

    Only money that is genuinely expected: a confirmed booking with something
    still to pay, a workshop balance with a due date, a standing cost, an
    insurance renewal. Nothing is forecast from averages or last year — a
    guess dressed as a figure is worse than a gap, because it gets budgeted
    against.
    """
    today = today or house_today()
    if isinstance(today, str):
        today = parse_date(today)
    last = today + timedelta(days=max(1, min(730, days)))
    incoming, outgoing = [], []

    # Rooms. Settled on arrival, so that is the date the money is expected.
    for b in conn.execute(
            """SELECT bookings.*, rooms.name AS room_name FROM bookings
                 LEFT JOIN rooms ON rooms.id = bookings.room_id
                WHERE bookings.status = 'confirmed'
                  AND bookings.arrival_date >= ? AND bookings.arrival_date <= ?""",
            (today.isoformat(), last.isoformat())).fetchall():
        due = round((b["total_price"] or 0) + (b["city_tax"] or 0)
                    - (b["discount_amount"] or 0) - (b["amount_paid"] or 0), 2)
        if due > 0.01:
            incoming.append({"date": b["arrival_date"], "amount": due,
                             "label": f"{b['guest_name']} — {b['room_name'] or 'room'}",
                             "kind": "Room", "ref": b["reference_code"]})

    # Workshops. The deposit is due when they register and the balance on its
    # own date, so an unpaid one of either is money genuinely still to come.
    for w in conn.execute(
            """SELECT workshop_bookings.*, workshops.title,
                      workshop_sessions.start_date
                 FROM workshop_bookings
                 JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
                 JOIN workshops ON workshops.id = workshop_sessions.workshop_id
                WHERE workshop_bookings.status IN ('confirmed', 'pending')""").fetchall():
        if (w["deposit_amount"] or 0) > 0 and not w["deposit_paid_at"]:
            when = w["balance_due_date"] or w["start_date"]
            if when and today.isoformat() <= when <= last.isoformat():
                incoming.append({"date": when, "amount": round(w["deposit_amount"], 2),
                                 "label": f"{w['guest_name']} — {w['title']} deposit",
                                 "kind": "Workshop", "ref": w["reference_code"]})
        if (w["balance_amount"] or 0) > 0 and not w["balance_paid_at"]:
            when = w["balance_due_date"] or w["start_date"]
            if when and today.isoformat() <= when <= last.isoformat():
                incoming.append({"date": when, "amount": round(w["balance_amount"], 2),
                                 "label": f"{w['guest_name']} — {w['title']} balance",
                                 "kind": "Workshop", "ref": w["reference_code"]})

    # The restaurant. Paid on the night, less any deposit already taken.
    for r in conn.execute(
            """SELECT * FROM restaurant_bookings
                WHERE status = 'confirmed' AND no_show_at IS NULL
                  AND dinner_date >= ? AND dinner_date <= ?
                  AND COALESCE(total_price, 0) > 0""",
            (today.isoformat(), last.isoformat())).fetchall():
        due = round((r["total_price"] or 0) - (r["discount_amount"] or 0)
                    - (r["deposit_amount"] or 0), 2)
        if due > 0.01 and r["payment_status"] != "paid":
            incoming.append({"date": r["dinner_date"], "amount": due,
                             "label": f"{r['guest_name']} — dinner, {r['party_size']} covers",
                             "kind": "Restaurant", "ref": r["reference_code"]})

    # Standing costs, expanded across the window on their own dates.
    for c in conn.execute(
            "SELECT * FROM recurring_costs WHERE active = 1").fetchall():
        for when in _recurring_dates(parse_date(c["next_due_date"] or ""),
                                     c["frequency"], today, last):
            outgoing.append({"date": when.isoformat(), "amount": round(c["amount"] or 0, 2),
                             "label": c["label"], "kind": "Standing cost", "ref": None})

    # Insurance renewals. The premium falls due when the policy expires.
    for p in conn.execute(
            "SELECT * FROM insurance_policies WHERE COALESCE(premium, 0) > 0").fetchall():
        for when in _recurring_dates(parse_date(p["expiry_date"] or ""),
                                     p["premium_frequency"] or "annual", today, last):
            outgoing.append({"date": when.isoformat(), "amount": round(p["premium"], 2),
                             "label": f"{p['provider']} — {p['coverage_type'] or 'insurance'}",
                             "kind": "Insurance", "ref": p["policy_number"]})

    # AGREED AND DATED. An approved invoice is a debt the house has accepted;
    # it is the most certain thing in this whole forecast. It used not to be
    # here at all — only 'pending' was counted — so approving an invoice made
    # the money ahead look better, which is exactly backwards. It could not
    # have been placed anywhere sensible before either: invoices carried no
    # due date, and putting a bill due in five weeks onto today would have
    # been its own kind of wrong.
    for e in conn.execute(
            """SELECT * FROM expenses
                WHERE status = 'approved' AND paid_at IS NULL
                  AND COALESCE(amount, 0) > 0""").fetchall():
        # Staff are not suppliers. Somebody who spent their own money on the
        # house is owed it now, not on a supplier's thirty-day clock.
        if e["kind"] == "staff_expense":
            when, label, kind = today, "owed back to our own people", "Reimbursement"
        else:
            due = parse_date(e["due_date"] or "") or today
            when = max(due, today)          # an overdue bill is owed today, not in the past
            label, kind = e["vendor_name"] or e["description"], "Supplier invoice"
        if not (today <= when <= last):
            continue
        outgoing.append({
            "date": when.isoformat(), "amount": round(e["amount"], 2),
            "label": f"{label}"
                     + (f" — {e['invoice_number']}" if e["invoice_number"] else ""),
            "kind": kind, "ref": e["invoice_number"] or None})

    # BEING ASKED FOR, not yet agreed. It might be rejected or queried, so it
    # is labelled as undecided rather than counted as certain — but leaving it
    # out entirely would mean the queue of bills on somebody's desk was money
    # the forecast had never heard of.
    for e in conn.execute(
            """SELECT * FROM expenses WHERE status = 'pending'
                 AND COALESCE(amount, 0) > 0""").fetchall():
        outgoing.append({"date": today.isoformat(), "amount": round(e["amount"], 2),
                         "label": f"{e['vendor_name'] or e['description']} — awaiting your decision",
                         "kind": "Awaiting approval", "ref": None})

    # Wages, if a monthly figure has been set. Dated to the end of each month,
    # which is when French salaries are usually paid, and only for whole months
    # inside the window — half a month of wages on a part month would be a
    # figure nobody could check against a bank statement.
    staff = conn.execute(
        "SELECT value FROM app_settings WHERE key = ?",
        (MONTHLY_STAFF_COST_SETTING,)).fetchone()
    try:
        staff = round(float(staff["value"]), 2) if staff and staff["value"] else None
    except (TypeError, ValueError):
        staff = None
    if staff:
        for start in _month_starts(today, last):
            payday = date(start.year, start.month, monthrange(start.year, start.month)[1])
            if today <= payday <= last:
                outgoing.append({"date": payday.isoformat(), "amount": staff,
                                 "label": "Wages — the monthly figure you set",
                                 "kind": "Wages", "ref": None})

    incoming.sort(key=lambda x: (x["date"], -x["amount"]))
    outgoing.sort(key=lambda x: (x["date"], -x["amount"]))

    opening = conn.execute(
        "SELECT value FROM app_settings WHERE key = ?",
        (OPENING_BALANCE_SETTING,)).fetchone()
    try:
        opening = round(float(opening["value"]), 2) if opening and opening["value"] else None
    except (TypeError, ValueError):
        opening = None

    months, running = [], opening or 0.0
    for start in _month_starts(today, last):
        end = _add_months(start, 1)
        window = (max(start, today).isoformat(), min(end, last + timedelta(days=1)).isoformat())
        m_in = round(sum(i["amount"] for i in incoming if window[0] <= i["date"] < window[1]), 2)
        m_out = round(sum(o["amount"] for o in outgoing if window[0] <= o["date"] < window[1]), 2)
        running = round(running + m_in - m_out, 2)
        months.append({"label": start.strftime("%B %Y"), "start": start.isoformat(),
                       "in": m_in, "out": m_out, "net": round(m_in - m_out, 2),
                       "running": running,
                       # Only meaningful once an opening balance is known. Without
                       # one this is a change, and calling a change a shortfall
                       # would be the page's first lie.
                       "short": opening is not None and running < 0})

    total_in = round(sum(i["amount"] for i in incoming), 2)
    # Work already on the upkeep schedule that falls due inside the window.
    #
    # Kept OUT of the totals and out of the running line, deliberately. The
    # rest of this page is money somebody has committed to; this is money the
    # house has committed to SPENDING, priced from what the same job cost last
    # time. That is a projection from last year, which is exactly what the
    # figures above promise not to be — so it sits in its own list, with its
    # own subtotal, and the reader is told which is which.
    upcoming_work = []
    for sched in conn.execute(
            "SELECT * FROM maintenance_schedules WHERE active = 1").fetchall():
        due = maintenance_next_due(sched)
        if not due or not (today <= due <= last):
            continue
        # Only where a real cost was recorded. Inventing a price for a job
        # nobody has ever paid for would be a guess inside a guess.
        priced = conn.execute(
            """SELECT cost, done_on FROM maintenance_visits
               WHERE schedule_id = ? AND COALESCE(cost, 0) > 0
               ORDER BY done_on DESC LIMIT 1""", (sched["id"],)).fetchone()
        upcoming_work.append({
            "date": due.isoformat(), "label": sched["name"],
            "amount": round(priced["cost"], 2) if priced else None,
            "since": priced["done_on"] if priced else None,
            "required": sched["required_by"] != "none",
        })
    upcoming_work.sort(key=lambda w: w["date"])
    work_total = round(sum(w["amount"] for w in upcoming_work if w["amount"]), 2)
    work_unpriced = len([w for w in upcoming_work if not w["amount"]])

    total_out = round(sum(o["amount"] for o in outgoing), 2)
    # Not all "out" is the same kind of out. An agreed invoice and a bill
    # somebody may yet reject are both money, and reporting them as one figure
    # invites planning against a number that includes things that will never
    # happen.
    agreed_out = round(sum(o["amount"] for o in outgoing
                           if o["kind"] in ("Supplier invoice", "Reimbursement")), 2)
    undecided_out = round(sum(o["amount"] for o in outgoing
                              if o["kind"] == "Awaiting approval"), 2)
    return {
        "agreed_out": agreed_out, "undecided_out": undecided_out,
        "upcoming_work": upcoming_work, "work_total": work_total,
        "work_unpriced": work_unpriced,
        "from": today.isoformat(), "to": last.isoformat(), "days": (last - today).days,
        "incoming": incoming, "outgoing": outgoing, "months": months,
        "total_in": total_in, "total_out": total_out,
        "net": round(total_in - total_out, 2),
        "opening": opening, "monthly_staff": staff,
        "closing": round((opening or 0) + total_in - total_out, 2) if opening is not None else None,
    }


@app.route("/management/outlook")
@owner_required
def management_outlook():
    """Committed out against expected in, by month.

    Sits beside the financials rather than inside them because it answers a
    different question: not what the house made, but what it has already
    promised and been promised.
    """
    try:
        months = max(1, min(12, int(request.args.get("months", "6"))))
    except ValueError:
        months = 6
    conn = get_db()
    outlook = cash_outlook(conn, months=months)
    costs = conn.execute(
        """SELECT * FROM recurring_costs WHERE active = 1
           ORDER BY frequency, amount DESC""").fetchall()
    conn.close()
    negative = [r for r in outlook["rows"] if r["net"] < 0]
    overview = [
        overview_cell("Expected in", euro(outlook["money_in"]),
                      sub=f"over {months} month{'s' if months != 1 else ''}",
                      hint="already booked, not a forecast"),
        overview_cell("Committed out", euro(outlook["money_out"]),
                      hint="contracts and the rota"),
        overview_cell("Difference", euro(outlook["net"]),
                      alert=outlook["net"] < 0),
        overview_cell("Months in the red", len(negative), alert=len(negative),
                      hint="on committed figures alone"),
    ]
    return render_template("management_outlook.html", outlook=outlook,
                           overview=overview, months=months, costs=costs)


def walk_in_options(conn, rooms, arrival, departure):
    """Each room with what it would cost for these nights and whether it is free.

    Reception should be choosing from what is actually available, not from a
    list of every room with the answer arriving after they press the button
    with somebody standing in front of them. `why` carries the reason a room is
    out, because "taken" and "closed for the season" want different responses.
    """
    out = []
    for room in rooms:
        free, why = (False, "Enter both dates.")
        price = 0.0
        if arrival and departure and departure > arrival:
            free, why = is_range_available(conn, room["id"], arrival, departure)
            price = compute_room_total(conn, room, arrival, departure)
        out.append({"room": room, "free": bool(free), "why": why or "",
                    "price": price, "sleeps": room["max_occupancy"]})
    return out


def send_booking_to_pennylane(conn, booking, user_id=None):
    """One stay, as a customer invoice. Returns (ok, message).

    Refuses before it reaches the network in four cases, and each one is a
    thing that would otherwise be discovered by reading a ledger later:

      ALREADY SENT. The guard is a UNIQUE row rather than a flag on the
      booking, so a double press, a retried request and a second person on
      another screen all collapse to one invoice.

      NOTHING TO INVOICE. A cancelled stay, or one that came to nothing.

      NOT CONFIGURED. Without a token this would fail at the socket, and the
      person pressing the button should be told which setting is missing rather
      than shown a network error.

      NO CUSTOMER. Pennylane files an invoice against somebody; if the customer
      call fails there is nothing to attach it to and sending a half-formed one
      is worse than not sending.

    The row is written AFTER Pennylane accepts it, not before. Getting that
    backwards would mark a stay as filed when it is not, and nothing would ever
    look at it again.
    """
    if not pennylane_configured():
        return False, "Pennylane is not connected yet — add PENNYLANE_API_TOKEN."
    existing = pennylane_already_sent(conn, "booking", booking["id"])
    if existing:
        return False, (f"Already sent on {house_date_iso(existing['sent_at'])}"
                       + (f" as {existing['pennylane_id']}" if existing["pennylane_id"] else "")
                       + ".")
    if booking["status"] in ("cancelled", "declined"):
        return False, "That stay was cancelled, so there is nothing to invoice."

    statement = guest_statement(conn, booking)
    total = round(float(statement["total"] or 0), 2)
    if total <= 0:
        return False, "There is nothing on that stay to invoice."
    lines = booking_pennylane_lines(conn, statement)
    if not lines:
        return False, "Nothing on that stay could be turned into invoice lines."

    ok, customer = pennylane_find_customer(booking["guest_name"], booking["guest_email"])
    if not ok or not customer:
        return False, f"Could not file a customer for {booking['guest_name']}: {customer}"

    tax = round(sum(float(b["vat"] or 0) for b in statement["vat"]), 2)
    ok, payload = pennylane_import_customer_invoice(
        customer_id=customer,
        date=booking["departure_date"] or booking["arrival_date"],
        deadline=booking["balance_due_date"] or booking["departure_date"],
        amount=total, tax=tax, lines=lines,
        invoice_number=booking["reference_code"],
        external_reference=booking["reference_code"],
    )
    if not ok:
        return False, f"Pennylane refused it: {payload}"

    conn.execute(
        """INSERT OR IGNORE INTO pennylane_exports (kind, source_id, pennylane_id,
           amount, sent_at, sent_by_user_id) VALUES ('booking', ?, ?, ?, ?, ?)""",
        (booking["id"], str((payload or {}).get("id") or ""), total,
         datetime.now(timezone.utc).isoformat(), user_id))
    return True, f"Sent €{total:.2f} for {booking['reference_code']}."


def pos_day_pennylane_lines(conn, closure):
    """A day's takings as accounting lines, one per VAT rate.

    Straight off the closure's own vat_json rather than recounted from the
    tabs. That figure was hashed into the Z-report when the day was closed and
    cannot move afterwards; recounting could quietly disagree with the report
    the house already signed off, which is the one thing a ledger must never do.

    One invoice for the day, not one per diner. A table of two who paid cash
    and left is not a customer you invoice, and forty of them would be forty
    customer records nobody will ever look at.
    """
    bands = json.loads(closure["vat_json"] or "{}")
    # F&B covers the restaurant and the till both -- one category, because
    # that is how the owner reads it and how the accountant asked for it.
    code = revenue_account_for(conn, "fnb")
    lines = []
    for rate, band in sorted(bands.items(), key=lambda kv: float(kv[0])):
        net = round(float(band.get("net") or 0), 2)
        vat = round(float(band.get("vat") or 0), 2)
        if not net and not vat:
            continue
        line = {"currency_amount": f"{net:.2f}", "currency_tax": f"{vat:.2f}",
                "vat_rate": pennylane_vat_code(rate),
                "label": f"Restaurant takings at {rate}%"[:200]}
        if code:
            line["ledger_account_number"] = code
        lines.append(line)
    return lines


def send_workshop_to_pennylane(conn, booking, user_id=None):
    """One workshop registration, as a customer invoice. Returns (ok, message).

    Charged on what the LEDGER says, not on the sticker price. A registration
    picks up charges and discounts of its own — an extra night, a returning
    guest's reduction — and workshop_balance_due is the one place those are
    reckoned. Invoicing total_price would bill the advertised figure and leave
    every adjustment out of the accounts.

    Sent once the session has finished rather than when it is booked. A place
    held eight months out with a deposit against it is not revenue yet, and an
    atelier that gets cancelled after being invoiced is a credit note somebody
    has to raise by hand.
    """
    if not pennylane_configured():
        return False, "Pennylane is not connected yet — add PENNYLANE_API_TOKEN."
    existing = pennylane_already_sent(conn, "workshop", booking["id"])
    if existing:
        return False, (f"Already sent on {house_date_iso(existing['sent_at'])}"
                       + (f" as {existing['pennylane_id']}" if existing["pennylane_id"] else "")
                       + ".")
    if booking["status"] in ("cancelled", "declined"):
        return False, "That registration was cancelled, so there is nothing to invoice."

    _balance, charged, _paid = workshop_balance_due(conn, booking["id"])
    total = round(float(charged or 0), 2)
    if total <= 0:
        return False, "There is nothing on that registration to invoice."

    rate = tax_rate(conn, "vat_workshops")
    rate = float(rate) if rate is not None else 20.0
    net = round(total / (1 + rate / 100), 2) if rate else total
    line = {"currency_amount": f"{net:.2f}", "currency_tax": f"{round(total - net, 2):.2f}",
            "vat_rate": pennylane_vat_code(rate),
            "label": (booking["workshop_title"] or "Atelier")[:200]}
    code = revenue_account_for(conn, "workshops")
    if code:
        line["ledger_account_number"] = code

    ok, customer = pennylane_find_customer(booking["guest_name"], booking["guest_email"])
    if not ok or not customer:
        return False, f"Could not file a customer for {booking['guest_name']}: {customer}"

    when = booking["end_date"] or booking["start_date"]
    ok, payload = pennylane_import_customer_invoice(
        customer_id=customer, date=when, deadline=when,
        amount=total, tax=round(total - net, 2), lines=[line],
        invoice_number=booking["reference_code"],
        external_reference=booking["reference_code"],
    )
    if not ok:
        return False, f"Pennylane refused it: {payload}"
    conn.execute(
        """INSERT OR IGNORE INTO pennylane_exports (kind, source_id, pennylane_id,
           amount, sent_at, sent_by_user_id) VALUES ('workshop', ?, ?, ?, ?, ?)""",
        (booking["id"], str((payload or {}).get("id") or ""), total,
         datetime.now(timezone.utc).isoformat(), user_id))
    return True, f"Sent €{total:.2f} for {booking['reference_code']}."


@app.route("/management/revenue-to-send/workshop/<int:booking_id>", methods=["POST"])
@owner_required
def send_workshop_revenue(booking_id):
    conn = get_db()
    booking = conn.execute(
        """SELECT workshop_bookings.*, workshops.title AS workshop_title,
                  workshop_sessions.start_date, workshop_sessions.end_date
             FROM workshop_bookings
             JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE workshop_bookings.id = ?""", (booking_id,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    ok, message = send_workshop_to_pennylane(conn, booking, user_id=session.get("user_id"))
    if ok:
        log_audit(conn, "workshop_revenue_sent_to_pennylane", target=booking["reference_code"])
    conn.commit()
    conn.close()
    flash(message, "success" if ok else "error")
    return redirect(url_for("revenue_to_send"))


def send_event_to_pennylane(conn, event, user_id=None):
    """One event, as a customer invoice. Returns (ok, message).

    Dated on the event itself rather than on when it was quoted: a wedding
    agreed in January and held in August belongs in August's books.

    Only a confirmed event that has been priced. A quote is not revenue, and an
    enquiry that came to nothing is not either.
    """
    if not pennylane_configured():
        return False, "Pennylane is not connected yet — add PENNYLANE_API_TOKEN."
    existing = pennylane_already_sent(conn, "event", event["id"])
    if existing:
        return False, (f"Already sent on {house_date_iso(existing['sent_at'])}"
                       + (f" as {existing['pennylane_id']}" if existing["pennylane_id"] else "")
                       + ".")
    if event["status"] != "confirmed":
        return False, "Only a confirmed event is revenue."
    bill = event_bill(conn, event["id"])
    total = round(float(bill["quoted"] if bill else 0), 2)
    if total <= 0:
        return False, "Put a price on the event before invoicing it."

    rate = tax_rate(conn, "vat_events")
    rate = float(rate) if rate is not None else 20.0
    net = round(total / (1 + rate / 100), 2) if rate else total
    line = {"currency_amount": f"{net:.2f}",
            "currency_tax": f"{round(total - net, 2):.2f}",
            "vat_rate": pennylane_vat_code(rate),
            "label": (f"{event['event_type']} — "
                      f"{event['preferred_date'] or 'date to confirm'}")[:200]}
    code = revenue_account_for(conn, "events")
    if code:
        line["ledger_account_number"] = code

    ok, customer = pennylane_find_customer(event["contact_name"], event["contact_email"])
    if not ok or not customer:
        return False, f"Could not file a customer for {event['contact_name']}: {customer}"

    when = event["preferred_date"] or house_date_iso(event["created_at"])
    ok, payload = pennylane_import_customer_invoice(
        customer_id=customer, date=when,
        deadline=event["balance_due_date"] or when,
        amount=total, tax=round(total - net, 2), lines=[line],
        invoice_number=event["reference_code"] or f"EVT-{event['id']}",
        external_reference=event["reference_code"] or f"EVT-{event['id']}",
    )
    if not ok:
        return False, f"Pennylane refused it: {payload}"
    conn.execute(
        """INSERT OR IGNORE INTO pennylane_exports (kind, source_id, pennylane_id,
           amount, sent_at, sent_by_user_id) VALUES ('event', ?, ?, ?, ?, ?)""",
        (event["id"], str((payload or {}).get("id") or ""), total,
         datetime.now(timezone.utc).isoformat(), user_id))
    return True, f"Sent €{total:.2f} for {event['reference_code'] or event['event_type']}."


