@app.route("/management/revenue-to-send")
@owner_required
def revenue_to_send():
    """Stays the accountant has not been given yet.

    Only expenses ever reached Pennylane — money going out. Everything coming
    in reached the accountant as a CSV somebody remembered to export, or not at
    all.

    Departed stays only. A booking still to come is not revenue, and one that
    is halfway through can still change.
    """
    conn = get_db()
    today = house_today_iso()
    rows = []
    for booking in conn.execute(
            """SELECT bookings.*, rooms.name AS room_name FROM bookings
                 LEFT JOIN rooms ON rooms.id = bookings.room_id
                WHERE bookings.status = 'confirmed'
                  AND bookings.departure_date < ?
                ORDER BY bookings.departure_date DESC LIMIT 300""", (today,)).fetchall():
        sent = pennylane_already_sent(conn, "booking", booking["id"])
        statement = guest_statement(conn, booking)
        rows.append({"booking": booking, "total": round(float(statement["total"] or 0), 2),
                     "sent": sent})
    ateliers = []
    for booking in conn.execute(
            """SELECT workshop_bookings.*, workshops.title AS workshop_title,
                      workshop_sessions.start_date, workshop_sessions.end_date
                 FROM workshop_bookings
                 JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
                 JOIN workshops ON workshops.id = workshop_sessions.workshop_id
                WHERE workshop_bookings.status = 'confirmed'
                  AND COALESCE(workshop_sessions.end_date, workshop_sessions.start_date) < ?
                ORDER BY workshop_sessions.start_date DESC LIMIT 200""", (today,)).fetchall():
        _b, charged, _p = workshop_balance_due(conn, booking["id"])
        ateliers.append({"booking": booking, "total": round(float(charged or 0), 2),
                         "sent": pennylane_already_sent(conn, "workshop", booking["id"])})

    events = []
    for event in conn.execute(
            """SELECT * FROM event_inquiries WHERE status = 'confirmed'
                  AND COALESCE(preferred_date, '') < ?
                ORDER BY preferred_date DESC LIMIT 200""", (today,)).fetchall():
        bill = event_bill(conn, event["id"])
        events.append({"event": event,
                       "total": round(float(bill["quoted"] if bill else 0), 2),
                       "sent": pennylane_already_sent(conn, "event", event["id"])})

    # Read before the close, like the stays above it.
    days = []
    for closure in conn.execute(
            """SELECT * FROM pos_closures WHERE kind = 'day'
                ORDER BY period DESC LIMIT 120""").fetchall():
        days.append({"closure": closure,
                     "total": round(float(closure["gross_total"] or 0), 2),
                     "sent": pennylane_already_sent(conn, "pos_day", closure["id"])})
    conn.close()
    waiting = [r for r in rows if not r["sent"] and r["total"] > 0]
    days_waiting = [d for d in days if not d["sent"] and d["total"] > 0]
    ateliers_waiting = [w for w in ateliers if not w["sent"] and w["total"] > 0]
    events_waiting = [e for e in events if not e["sent"] and e["total"] > 0]
    return render_template(
        "revenue_to_send.html", rows=rows, waiting=waiting, days=days,
        days_waiting=days_waiting, ateliers=ateliers,
        ateliers_waiting=ateliers_waiting,
        waiting_total=round(sum(r["total"] for r in waiting)
                            + sum(d["total"] for d in days_waiting)
                            + sum(w["total"] for w in ateliers_waiting)
                            + sum(e["total"] for e in events_waiting), 2),
        configured=pennylane_configured())


