@app.route("/management/vouchers")
@owner_required
def management_vouchers():
    """Every gift voucher the house has sold, and what is left on each.

    A voucher is a liability: money taken for a stay or a dinner that has not
    happened yet. It belongs on this side of the app next to what the house is
    owed, not filed under marketing.
    """
    conn = get_db()
    rows = []
    for voucher in conn.execute(
            "SELECT * FROM gift_vouchers ORDER BY created_at DESC").fetchall():
        ledger = voucher_ledger(conn, voucher["id"])
        rows.append({"voucher": voucher, **{k: v for k, v in ledger.items()
                                            if k != "voucher"}})
    conn.close()

    lv = list_view(
        rows, request.args,
        search=[lambda r: r["voucher"]["code"],
                lambda r: r["voucher"]["purchaser_name"] or "",
                lambda r: r["voucher"]["recipient_name"] or "",
                lambda r: r["voucher"]["purchaser_email"] or ""],
        search_hint="Search code, who bought it or who it is for",
        facets=[
            # Outstanding first: those are the ones that are still a liability.
            facet("state", "State", lambda r: {
                "active": "Still to spend", "spent": "Spent",
                "expired": "Expired", "void": "Cancelled"}.get(r["state"], r["state"]),
                  order=["Still to spend", "Expired", "Spent", "Cancelled"]),
        ],
        sorts=[
            sort_option("newest", "Newest first",
                        lambda r: r["voucher"]["created_at"] or "", reverse=True),
            sort_option("largest", "Most left first", lambda r: r["balance"],
                        reverse=True),
            sort_option("expiring", "Expiring soonest",
                        lambda r: r["voucher"]["expires_on"] or "9999-12-31"),
        ],
        default_sort="newest",
    )
    outstanding = round(sum(r["balance"] for r in rows if r["state"] == "active"), 2)
    overview = [
        overview_cell("Still to spend", euro(outstanding),
                      hint="money taken for something that has not happened yet"),
        overview_cell("Vouchers out",
                      sum(1 for r in rows if r["state"] == "active")),
        overview_cell("Sold, all time", euro(round(sum(r["original"] for r in rows), 2))),
        overview_cell("Spent", euro(round(sum(r["spent"] for r in rows), 2))),
    ]
    return render_template("management_vouchers.html", lv=lv, overview=overview)


@app.route("/management/vouchers/new", methods=["POST"])
@owner_required
def new_gift_voucher():
    amount_raw = (request.form.get("amount", "") or "").strip().replace(",", ".")
    expires_raw = (request.form.get("expires_on", "") or "").strip()
    try:
        amount = round(float(amount_raw), 2)
    except ValueError:
        amount = 0
    if amount <= 0:
        flash("Enter what the voucher is worth.", "error")
        return redirect(url_for("management_vouchers"))
    expires_on = None
    if expires_raw:
        parsed = parse_date(expires_raw)
        if not parsed:
            flash("Choose a valid expiry date, or leave it blank.", "error")
            return redirect(url_for("management_vouchers"))
        if parsed <= house_today():
            flash("An expiry date in the past would make the voucher worthless "
                  "the moment it is sold.", "error")
            return redirect(url_for("management_vouchers"))
        expires_on = parsed.isoformat()

    issuer = current_user()
    conn = get_db()
    voucher = issue_gift_voucher(
        conn, amount,
        purchaser_name=(request.form.get("purchaser_name", "") or "").strip(),
        purchaser_email=(request.form.get("purchaser_email", "") or "").strip(),
        recipient_name=(request.form.get("recipient_name", "") or "").strip(),
        message=(request.form.get("message", "") or "").strip(),
        expires_on=expires_on,
        note=(request.form.get("note", "") or "").strip(),
        issued_by_user_id=issuer["id"] if issuer else None)
    log_audit(conn, "voucher_issued", target=voucher["code"], details=f"{amount:.2f}")
    conn.commit()
    conn.close()
    flash(f"Voucher {voucher['code']} issued.", "success")
    return redirect(url_for("gift_voucher_detail", voucher_id=voucher["id"]))


@app.route("/management/vouchers/<int:voucher_id>")
@owner_required
def gift_voucher_detail(voucher_id):
    conn = get_db()
    ledger = voucher_ledger(conn, voucher_id)
    if not ledger:
        conn.close()
        abort(404)
    # Stays with something still owing, so a voucher can be put against one from
    # here rather than from a list of every booking the house has ever taken.
    owing = []
    if ledger["spendable"]:
        for booking in conn.execute(
                """SELECT bookings.*, rooms.name AS room_name FROM bookings
                     LEFT JOIN rooms ON rooms.id = bookings.room_id
                    WHERE bookings.status = 'confirmed'
                    ORDER BY bookings.arrival_date""").fetchall():
            bill = booking_bill(conn, booking["id"])
            if bill and bill["owed"] > 0.005:
                owing.append({"booking": booking, "owed": bill["owed"]})
    conn.close()
    return render_template("voucher_detail.html", ledger=ledger, owing=owing[:40],
                           kinds=VOUCHER_KINDS)


@app.route("/management/vouchers/<int:voucher_id>/spend", methods=["POST"])
@owner_required
def spend_gift_voucher(voucher_id):
    """Take an amount off a voucher, optionally against a stay.

    With a booking, it becomes a payment on that stay so the bill, the chase and
    the outstanding list all see it. Without one, it is recorded against
    whatever it was spent on -- the till, a dinner -- so the voucher's own
    history still reconciles.
    """
    booking_raw = (request.form.get("booking_id", "") or "").strip()
    amount_raw = (request.form.get("amount", "") or "").strip().replace(",", ".")
    kind = (request.form.get("kind", "") or "other").strip()
    user = current_user()
    user_id = user["id"] if user else None

    conn = get_db()
    if booking_raw.isdigit():
        ok, message, _taken = redeem_voucher_against_booking(
            conn, voucher_id, int(booking_raw), amount_raw, taken_by_user_id=user_id)
    else:
        ok, message, _taken = redeem_voucher(
            conn, voucher_id, amount_raw, kind=kind,
            reference=(request.form.get("reference", "") or "").strip() or None,
            taken_by_user_id=user_id)
    if ok:
        log_audit(conn, "voucher_spent", target=str(voucher_id), details=message)
    conn.commit()
    conn.close()
    flash(message, "success" if ok else "error")
    return redirect(url_for("gift_voucher_detail", voucher_id=voucher_id))


@app.route("/management/vouchers/<int:voucher_id>/void", methods=["POST"])
@owner_required
def void_gift_voucher(voucher_id):
    """Cancel a voucher without deleting it.

    Deleting would take its redemptions with it and leave money that has been
    spent with nothing to account for it. A cancelled voucher keeps its history
    and simply stops being spendable.
    """
    conn = get_db()
    ledger = voucher_ledger(conn, voucher_id)
    if not ledger:
        conn.close()
        abort(404)
    new_status = "active" if ledger["voucher"]["status"] == "void" else "void"
    conn.execute("UPDATE gift_vouchers SET status = ? WHERE id = ?",
                 (new_status, voucher_id))
    log_audit(conn, "voucher_status", target=ledger["voucher"]["code"],
              details=new_status)
    conn.commit()
    conn.close()
    flash("Voucher cancelled." if new_status == "void" else "Voucher reinstated.",
          "success")
    return redirect(url_for("gift_voucher_detail", voucher_id=voucher_id))


@app.route("/vouchers", methods=["GET", "POST"])
def check_gift_voucher():
    """What is left on a voucher, for whoever is holding it.

    Rate limited, and it says nothing about who bought it or who it was for: a
    voucher code is a bearer instrument, so somebody who has found one should
    learn what it is worth and nothing about the household it came from.
    """
    result, code = None, ""
    if request.method == "POST":
        code = (request.form.get("code", "") or "").strip()
        conn = get_db()
        if rate_limited(conn, "check_voucher", 10):
            conn.commit()
            conn.close()
            flash("Too many attempts from this connection — please try again "
                  "in a bit.", "error")
            return render_template("voucher_check.html", result=None, code="")
        voucher = voucher_by_code(conn, code)
        ledger = voucher_ledger(conn, voucher["id"]) if voucher else None
        conn.commit()
        conn.close()
        if not ledger or ledger["state"] == "void":
            flash("We could not find a voucher with that code.", "error")
        else:
            result = {
                "balance": ledger["balance"], "original": ledger["original"],
                "state": ledger["state"],
                "expires_on": ledger["voucher"]["expires_on"],
                "code": ledger["voucher"]["code"],
            }
    return render_template("voucher_check.html", result=result, code=code)


@app.route("/management/outstanding/<int:booking_id>/payment", methods=["POST"])
@owner_required
def record_manual_booking_payment(booking_id):
    """Record money taken by hand: cash, a bank transfer, a card in person.

    This did not exist. Both callers of record_booking_payment were Stripe
    paths, so a guest who handed over two hundred euros at the desk could not
    be credited for it at all — the stay went on showing the whole balance and
    the reminder job went on asking them for it.

    Part of a stay is fine HERE, and only here. A guest is offered the whole
    balance because a stay is quoted as a price and paid as one; the house
    taking half of it in cash is a different act, made by somebody who can see
    the bill.

    Recorded as a line of its own — how it was taken, any reference, and who
    took it — rather than only as a bigger number on the stay. Three months on,
    a bank statement has to be matched to a booking by somebody who was not
    there.

    An amount over what is owed is refused rather than clamped. On the guest's
    own button, clamping is a kindness — they meant "all of it". Typed at this
    desk it is far more likely to be a slip, and quietly taking less than the
    number in front of you is how a till and a bill start disagreeing.
    """
    conn = get_db()
    booking = conn.execute("SELECT * FROM bookings WHERE id = ?", (booking_id,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    bill = booking_bill(conn, booking_id)
    raw = (request.form.get("amount", "") or "").strip().replace(",", ".")
    try:
        amount = round(float(raw), 2)
    except ValueError:
        amount = 0
    if amount <= 0:
        conn.close()
        flash("Enter how much was taken.", "error")
        return redirect(url_for("management_outstanding"))
    if bill and amount > bill["owed"] + 0.01:
        conn.close()
        flash(f"That is more than the €{bill['owed']:.2f} outstanding on this stay.",
              "error")
        return redirect(url_for("management_outstanding"))
    reference = (request.form.get("reference", "") or "").strip() or None
    method = (request.form.get("method", "") or "").strip() or "cash"
    if method not in MANUAL_PAYMENT_METHODS:
        method = "cash"
    # A line of its own, then the running total. booking_bill reads `paid` from
    # bookings.amount_paid, so this row is a record rather than a second count
    # of the same money — it is what answers "when, how, and who took it" three
    # months later when a bank statement has to be matched to a stay.
    conn.execute(
        """INSERT INTO booking_payments (booking_id, amount, method, reference,
           taken_by_user_id, created_at) VALUES (?, ?, ?, ?, ?, ?)""",
        (booking_id, amount, method, reference, session.get("user_id"),
         datetime.now(timezone.utc).isoformat()))
    # Without the reference: record_booking_payment stows one in
    # stripe_payment_intent_id, which is the right home for a Stripe id and the
    # wrong one for "cash at the desk".
    record_booking_payment(conn, booking_id, amount)
    log_audit(conn, "booking_payment_recorded", target=booking["reference_code"],
              details=f"€{amount:.2f}" + (f" ({reference})" if reference else ""))
    conn.commit()
    left = booking_bill(conn, booking_id)
    conn.close()
    remaining = left["owed"] if left else 0
    flash(f"€{amount:.2f} recorded against {booking['guest_name']}."
          + (f" €{remaining:.2f} still to pay." if remaining > 0.005 else " Settled."),
          "success")
    return redirect(url_for("management_outstanding"))


@app.route("/management/outstanding/<int:booking_id>/chase", methods=["POST"])
@owner_required
def chase_outstanding_balance(booking_id):
    """Ask one guest for what is still on their stay.

    By hand, because the automatic reminder will never reach these: it looks
    only at balances due before arrival, and somebody who has already left is
    past every date it checks.
    """
    conn = get_db()
    booking = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
             LEFT JOIN rooms ON rooms.id = bookings.room_id
            WHERE bookings.id = ?""", (booking_id,)).fetchone()
    if not booking:
        conn.close()
        abort(404)
    bill = booking_bill(conn, booking_id)
    if not bill or bill["owed"] <= 0.005:
        conn.close()
        flash("There is nothing outstanding on that stay.", "error")
        return redirect(url_for("management_outstanding"))
    if not (booking["guest_email"] or "").strip():
        conn.close()
        flash("That booking has no email address on it.", "error")
        return redirect(url_for("management_outstanding"))
    departed = (booking["departure_date"] or "") < house_today_iso()
    subject, body = balance_request_email(booking, bill, departed=departed)
    conn.close()
    if send_email(booking["guest_email"], subject, body):
        flash(f"Asked {booking['guest_name']} for \u20ac{bill['owed']:.2f}.", "success")
    else:
        flash("No email provider is connected yet, so that is being held and "
              "will go out once one is.", "error")
    return redirect(url_for("management_outstanding"))


@app.route("/management/financials")
@owner_required
def management_financials():
    today = house_today()
    conn = get_db()
    months = []
    cursor = today.replace(day=1)
    for _ in range(6):
        month_end = date(cursor.year + 1, 1, 1) if cursor.month == 12 else date(cursor.year, cursor.month + 1, 1)
        summary = financial_month_summary(conn, cursor, month_end)
        summary["occupancy_rate"] = compute_month_stats(conn, cursor)["occupancy_rate"]
        months.append(summary)
        cursor = date(cursor.year - 1, 12, 1) if cursor.month == 1 else date(cursor.year, cursor.month - 1, 1)
    months.reverse()
    current = months[-1]
    month_end_for_current = date(today.year + 1, 1, 1) if today.month == 12 else date(today.year, today.month + 1, 1)
    room_revenue = room_revenue_breakdown(conn, today.replace(day=1), month_end_for_current)
    expense_breakdown = expense_category_breakdown(conn, today.replace(day=1), month_end_for_current)
    ytd = financial_month_summary(conn, date(today.year, 1, 1), today + timedelta(days=1))

    last_year_start = date(today.year - 1, today.month, 1)
    last_year_end = date(last_year_start.year + 1, 1, 1) if last_year_start.month == 12 else date(last_year_start.year, last_year_start.month + 1, 1)
    last_year = financial_month_summary(conn, last_year_start, last_year_end)
    last_year["occupancy_rate"] = compute_month_stats(conn, last_year_start)["occupancy_rate"]

    def pct_change(now_val, then_val):
        if not then_val:
            return None
        return round((now_val - then_val) / then_val * 100, 1)

    yoy = {
        "revenue_pct": pct_change(current["revenue"], last_year["revenue"]),
        "occupancy_pct": pct_change(current["occupancy_rate"], last_year["occupancy_rate"]),
    }
    conn.close()
    return render_template(
        "management_financials.html", months=months, current=current, today=today,
        room_revenue=room_revenue, ytd=ytd, expense_breakdown=expense_breakdown,
        last_year=last_year, last_year_start=last_year_start, yoy=yoy,
    )


@app.route("/management/financials/annual-summary")
@owner_required
def annual_summary():
    try:
        year = int(request.args.get("year", "") or datetime.now(timezone.utc).year)
    except ValueError:
        year = datetime.now(timezone.utc).year
    year_start = date(year, 1, 1)
    year_end = date(year + 1, 1, 1)

    conn = get_db()
    financials = financial_month_summary(conn, year_start, year_end)

    room_count = conn.execute("SELECT COUNT(*) AS c FROM rooms WHERE active = 1").fetchone()["c"]
    days_in_year = (year_end - year_start).days
    overlapping = conn.execute(
        """SELECT arrival_date, departure_date FROM bookings
           WHERE status = 'confirmed' AND room_id IN (SELECT id FROM rooms WHERE active = 1)
           AND arrival_date < ? AND departure_date > ?""",
        (year_end.isoformat(), year_start.isoformat()),
    ).fetchall()
    booked_nights = 0
    for b in overlapping:
        b_start, b_end = parse_date(b["arrival_date"]), parse_date(b["departure_date"])
        if not b_start or not b_end:
            continue
        overlap_start, overlap_end = max(b_start, year_start), min(b_end, year_end)
        booked_nights += max(0, (overlap_end - overlap_start).days)
    total_possible_nights = days_in_year * room_count
    occupancy_rate = round(booked_nights / total_possible_nights * 100) if total_possible_nights else 0

    room_revenue = room_revenue_breakdown(conn, year_start, year_end)
    expense_breakdown = expense_category_breakdown(conn, year_start, year_end)
    top_vendors = conn.execute(
        """SELECT vendor_name, SUM(amount) AS total FROM expenses
           WHERE kind = 'supplier_invoice' AND status IN ('approved','paid') AND vendor_name IS NOT NULL
           AND submitted_at >= ? AND submitted_at < ? GROUP BY vendor_name ORDER BY total DESC LIMIT 10""",
        (year_start.isoformat(), year_end.isoformat()),
    ).fetchall()
    feedback_row = conn.execute(
        "SELECT AVG(rating) AS a, COUNT(*) AS c FROM guest_feedback WHERE submitted_at >= ? AND submitted_at < ?",
        (year_start.isoformat(), year_end.isoformat()),
    ).fetchone()
    booking_count = conn.execute(
        "SELECT COUNT(*) AS c FROM bookings WHERE status = 'confirmed' AND arrival_date >= ? AND arrival_date < ?",
        (year_start.isoformat(), year_end.isoformat()),
    ).fetchone()["c"]
    conn.close()

    return render_template(
        "annual_summary.html", year=year, financials=financials, occupancy_rate=occupancy_rate,
        room_revenue=room_revenue, expense_breakdown=expense_breakdown, top_vendors=top_vendors,
        feedback_avg=round(feedback_row["a"], 1) if feedback_row["a"] is not None else None,
        feedback_count=feedback_row["c"], booking_count=booking_count,
    )


