@app.route("/management/breakages", methods=["GET", "POST"])
@login_required
def management_breakages():
    """What guests broke or took, and what the house did about it.

    Recording is open to any member of staff, because the person who finds
    the broken lamp is whoever is turning the room round. Deciding whether
    to charge is the owner's, and lives on a separate route.
    """
    conn = get_db()
    user = current_user()

    if request.method == "POST":
        what = (request.form.get("what", "") or "").strip()[:200]
        room_raw = (request.form.get("room_id", "") or "").strip()
        booking_raw = (request.form.get("booking_id", "") or "").strip()
        cost = parse_money(request.form.get("replacement_cost", ""))
        note = (request.form.get("note", "") or "").strip()[:400]
        found = parse_date(request.form.get("found_on", "")) \
            or house_today()

        if not what:
            conn.close()
            flash("Say what was broken or missing.", "error")
            return redirect(url_for("management_breakages"))

        conn.execute(
            """INSERT INTO breakages (booking_id, room_id, what, found_on,
                       found_by_user_id, replacement_cost, note, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
            (int(booking_raw) if booking_raw.isdigit() else None,
             int(room_raw) if room_raw.isdigit() else None,
             what, found.isoformat(), user["id"], cost, note or None,
             datetime.now(timezone.utc).isoformat()))
        log_audit(conn, "breakage_recorded", target=what)
        conn.commit()
        conn.close()
        flash("Written down. Whether to say anything about it is a separate "
              "decision.", "success")
        return redirect(url_for("management_breakages"))

    today = house_today()
    summary = breakage_summary(conn, today=today)
    rooms = conn.execute(
        "SELECT id, name FROM rooms ORDER BY sort_order, name").fetchall()
    # Stays that have recently ended, to attach one to. A breakage found in
    # a room nobody has been in belongs to no stay, which is why the field
    # is optional.
    recent = conn.execute(
        """SELECT id, guest_name, arrival_date, departure_date, room_id
             FROM bookings
            WHERE status = 'confirmed'
              AND departure_date <= ? AND departure_date >= ?
            ORDER BY departure_date DESC LIMIT 40""",
        (today.isoformat(), (today - timedelta(days=60)).isoformat())).fetchall()
    conn.close()

    overview = [
        overview_cell("Recorded", summary["count"], hint="in the last year"),
        overview_cell("Not decided", summary["undecided"],
                      alert=bool(summary["undecided"])),
        overview_cell("The house absorbed",
                      f"\u20ac{summary['absorbed']:,.2f}",
                      hint="replacement cost less anything recovered"),
    ]
    return render_template("management_breakages.html", summary=summary,
                           rooms=rooms, recent=recent, overview=overview,
                           # BREAKAGE_DECISIONS is not passed: the template
                           # writes the two outcomes out with their own
                           # wording, and a map it never opens is work done
                           # on every page load for nobody.
                           today=today,
                           is_owner=(user["role"] == "owner"))


@app.route("/management/breakages/<int:breakage_id>/decide", methods=["POST"])
@owner_required
def decide_breakage(breakage_id):
    """Say what the house is doing about one.

    The owner's, not any member of staff's, and never automatic. Charging a
    guest for damage is the same shape of decision as refusing a refund:
    the house's position is that somebody makes it.
    """
    conn = get_db()
    row = conn.execute("SELECT * FROM breakages WHERE id = ?",
                       (breakage_id,)).fetchone()
    if not row:
        conn.close()
        abort(404)

    decision = request.form.get("decision", "")
    if decision not in BREAKAGE_DECISIONS or decision == "undecided":
        conn.close()
        flash("Choose whether it is being charged or let go.", "error")
        return redirect(url_for("management_breakages"))

    amount = parse_money(request.form.get("charged_amount", "")) \
        if decision == "charged" else None
    if decision == "charged" and not amount:
        conn.close()
        flash("Say how much is being charged.", "error")
        return redirect(url_for("management_breakages"))

    user = current_user()
    conn.execute(
        """UPDATE breakages SET charge_decision = ?, charged_amount = ?,
                  decided_by_user_id = ?, decided_at = ? WHERE id = ?""",
        (decision, amount, user["id"],
         datetime.now(timezone.utc).isoformat(), breakage_id))
    log_audit(conn, "breakage_decided", target=row["what"],
              details=f"{decision}"
                      + (f" \u20ac{amount:.2f}" if amount else ""))
    conn.commit()
    conn.close()
    # Nothing is charged to a card from here. Taking the money is a
    # separate, deliberate act on the bill, the same way a refund is.
    flash("Recorded. Nothing has been taken from anybody \u2014 charging it is "
          "a line on their bill." if decision == "charged"
          else "Let go, and still on the record.", "success")
    return redirect(url_for("management_breakages"))


@app.route("/management/filings", methods=["GET", "POST"])
@owner_required
def management_filings():
    """What has to be filed or paid, and when.

    Dates the owner or their accountant sets. The regime a house is on
    varies and changes, and an app that asserted French tax law would be
    confidently wrong for somebody — which is worse than saying nothing.
    """
    conn = get_db()

    if request.method == "POST":
        name = (request.form.get("name", "") or "").strip()[:120]
        authority = (request.form.get("authority", "") or "").strip()[:120]
        every = request.form.get("every", "monthly")
        due = parse_date(request.form.get("due_on", ""))
        warn_raw = (request.form.get("warn_days", "") or "").strip()
        note = (request.form.get("note", "") or "").strip()[:300]

        if not name or not due or every not in FILING_FREQUENCIES:
            conn.close()
            flash("A filing needs a name, a date and how often.", "error")
            return redirect(url_for("management_filings"))

        conn.execute(
            """INSERT INTO filing_obligations (name, authority, every, due_on,
                       due_day, warn_days, note, active, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?)""",
            (name, authority or None, every, due.isoformat(), due.day,
             int(warn_raw) if warn_raw.isdigit() else 14, note or None,
             datetime.now(timezone.utc).isoformat()))
        log_audit(conn, "filing_added", target=name, details=due.isoformat())
        conn.commit()
        conn.close()
        flash(f"{name} added.", "success")
        return redirect(url_for("management_filings"))

    today = house_today()
    rows = conn.execute(
        "SELECT * FROM filing_obligations WHERE active = 1 ORDER BY due_on"
    ).fetchall()
    due_now = filings_due(conn, today)
    recent = conn.execute(
        """SELECT filings_made.*, filing_obligations.name
             FROM filings_made
             JOIN filing_obligations
               ON filing_obligations.id = filings_made.obligation_id
            ORDER BY filings_made.filed_on DESC LIMIT 20""").fetchall()
    conn.close()

    late = [d for d in due_now if d["late"]]
    overview = [
        overview_cell("On the calendar", len(rows), alert=not rows,
                      hint="nothing here is asserted by the app"),
        overview_cell("Due now", len(due_now), alert=bool(due_now)),
        overview_cell("Late", len(late), alert=bool(late),
                      hint="penalties, not a telling-off"),
    ]
    return render_template("management_filings.html", rows=rows,
                           due=due_now, recent=recent, overview=overview,
                           frequencies=FILING_FREQUENCIES, today=today)


@app.route("/management/filings/<int:filing_id>/filed", methods=["POST"])
@owner_required
def record_filing(filing_id):
    """Say this one has been filed, and roll the obligation forward."""
    conn = get_db()
    row = conn.execute("SELECT * FROM filing_obligations WHERE id = ?",
                       (filing_id,)).fetchone()
    if not row:
        conn.close()
        abort(404)

    due = parse_date(row["due_on"])
    filed_on = parse_date(request.form.get("filed_on", "")) \
        or house_today()
    amount = parse_money(request.form.get("amount", ""))
    reference = (request.form.get("reference", "") or "").strip()[:120]

    user = current_user()
    conn.execute(
        """INSERT OR IGNORE INTO filings_made (obligation_id, covered_due_on,
                   filed_on, amount, reference, created_by_user_id, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?)""",
        (filing_id, row["due_on"], filed_on.isoformat(), amount,
         reference or None, user["id"],
         datetime.now(timezone.utc).isoformat()))

    # Roll to the next one. Clamped against the day it is REALLY due on
    # rather than the day this one landed, so a deadline on the 31st does
    # not quietly become the 28th the first February and stay there.
    nxt = next_filing_due(due, row["every"], due_day=row["due_day"])
    conn.execute("UPDATE filing_obligations SET due_on = ? WHERE id = ?",
                 (nxt.isoformat(), filing_id))
    log_audit(conn, "filing_recorded", target=row["name"],
              details=f"covering {row['due_on']}, filed {filed_on.isoformat()}")
    conn.commit()
    conn.close()
    flash(f"{row['name']} filed. The next is due {format_date_short(nxt.isoformat())}.",
          "success")
    return redirect(url_for("management_filings"))


@app.route("/management/filings/<int:filing_id>/stop", methods=["POST"])
@owner_required
def stop_filing(filing_id):
    """Take it off the calendar without losing what was already filed."""
    conn = get_db()
    row = conn.execute("SELECT name FROM filing_obligations WHERE id = ?",
                       (filing_id,)).fetchone()
    if not row:
        conn.close()
        abort(404)
    conn.execute("UPDATE filing_obligations SET active = 0 WHERE id = ?",
                 (filing_id,))
    log_audit(conn, "filing_stopped", target=row["name"])
    conn.commit()
    conn.close()
    # Deactivated rather than deleted: the filings already made against it
    # are a record of what the house did, and they outlive the obligation.
    flash(f"{row['name']} is off the calendar. What was filed against it is kept.",
          "success")
    return redirect(url_for("management_filings"))


