@app.route("/management/budget", methods=["GET", "POST"])
@owner_required
def management_budget():
    """Twelve targets, and how the year is going against them.

    Per month OF THE YEAR rather than per calendar month: the house's shape
    repeats, and a budget keyed to 2026-02 would need retyping every
    January to stay true.
    """
    conn = get_db()

    if request.method == "POST":
        now_iso = datetime.now(timezone.utc).isoformat()
        changed = 0
        for n in range(1, 13):
            revenue = parse_money(request.form.get(f"revenue_{n}", ""))
            cost = parse_money(request.form.get(f"cost_{n}", ""))
            note = (request.form.get(f"note_{n}", "") or "").strip()[:120] or None
            if revenue is None and cost is None and not note:
                # Cleared on purpose. A month with nothing against it has to
                # read as "not set", never as a target of zero, which is met
                # by doing nothing.
                conn.execute("DELETE FROM monthly_budgets WHERE month = ?", (n,))
                continue
            conn.execute(
                """INSERT INTO monthly_budgets (month, revenue, cost, note, updated_at)
                   VALUES (?, ?, ?, ?, ?)
                   ON CONFLICT(month) DO UPDATE SET
                       revenue = excluded.revenue, cost = excluded.cost,
                       note = excluded.note, updated_at = excluded.updated_at""",
                (n, revenue, cost, note, now_iso))
            changed += 1
        log_audit(conn, "budget_set", details=f"{changed} month(s)")
        conn.commit()
        conn.close()
        flash(f"{changed} month{'' if changed == 1 else 's'} set.", "success")
        return redirect(url_for("management_budget"))

    today = house_today()
    rows = budget_table(conn)

    # The last twelve months against their targets. Actuals per month are
    # what makes the page worth opening rather than a form to fill in.
    year = []
    cursor = today.replace(day=1)
    for _ in range(12):
        nxt = (cursor + timedelta(days=31)).replace(day=1)
        summary = financial_month_summary(conn, cursor, nxt)
        # The same definition of "what it cost" that the month summary
        # already uses for net: expenses plus labour. A second cost
        # figure beside the first would leave the owner working out
        # which one net was built from.
        spent = round((summary["expenses_total"] or 0)
                      + (summary["labour_cost"] or 0), 2)
        year.append({
            "month": cursor,
            "revenue": summary["revenue"] or 0,
            "spent": spent,
            **budget_variance(conn, cursor, summary["revenue"] or 0, spent or 0),
        })
        cursor = (cursor - timedelta(days=1)).replace(day=1)
    year.reverse()

    set_count = len([r for r in rows if r["revenue"] is not None
                     or r["cost"] is not None])
    behind = [y for y in year if y["revenue_delta"] is not None
              and y["revenue_delta"] < 0]
    overview = [
        overview_cell("Months set", f"{set_count}/12",
                      alert=set_count == 0,
                      hint="a month with nothing set is not a month that met "
                           "its target"),
        overview_cell("Behind on revenue", len(behind),
                      alert=bool(behind), hint="of the twelve just gone"),
    ]
    conn.close()
    return render_template("management_budget.html", rows=rows, year=year,
                           overview=overview, months=MONTH_NAMES)


@app.route("/management/recurring-costs")
@owner_required
def management_recurring_costs():
    conn = get_db()
    costs = conn.execute(
        """SELECT recurring_costs.*, vendors.name AS vendor_name,
                  vendors.payment_terms, vendors.email AS vendor_email
             FROM recurring_costs
             LEFT JOIN vendors ON vendors.id = recurring_costs.vendor_id
            ORDER BY (recurring_costs.active = 0), recurring_costs.category,
                     recurring_costs.label"""
    ).fetchall()
    vendor_list = conn.execute("SELECT id, name FROM vendors ORDER BY name").fetchall()
    # Standing costs with nobody attached. Not a fault — most were entered
    # before there was anywhere to put it — but it is the reason the supplier
    # totals are short, so it is worth saying rather than leaving to be noticed.
    unattached = [c for c in costs if c["active"] and not c["vendor_id"]]
    conn.close()
    monthly_equivalent = round(sum(
        c["amount"] if c["frequency"] == "monthly" else c["amount"] / 12
        for c in costs if c["active"]
    ), 2)
    today = house_today_iso()

    def due(c):
        if not c["active"]:
            return None
        d = c["next_due_date"]
        if not d:
            return "No date set"
        if d < today:
            return "Overdue"
        return "Due within 30 days" if d <= _iso_plus_days(today, 30) else "Later"

    lv = list_view(
        costs, request.args,
        search=["label", "category", "notes", "ledger_code"],
        search_hint="Search label, category, note or account code",
        facets=[
            facet("state", "Status", lambda c: "Live" if c["active"] else "Stopped",
                  order=["Live", "Stopped"]),
            # What is about to be taken out of the account is a different
            # question from what it is for, and only one of them is urgent.
            facet("due", "Next payment", due,
                  order=["Overdue", "Due within 30 days", "Later", "No date set"]),
            facet("category", "Category", lambda c: (c["category"] or "").strip() or None,
                  limit=10),
            facet("frequency", "How often", lambda c: (c["frequency"] or "").strip() or None),
            facet("coded", "Account code",
                  lambda c: "Coded" if (c["ledger_code"] or "").strip() else "Not coded yet",
                  order=["Not coded yet", "Coded"]),
            # Who it goes to, so the ones with nobody attached can be found
            # and fixed rather than only counted.
            facet("supplier", "Supplier",
                  lambda c: c["vendor_name"] or "Not linked",
                  order=["Not linked"], limit=10),
        ],
        sorts=[
            sort_option("cost", "Most expensive a year",
                        lambda c: c["amount"] * (12 if c["frequency"] == "monthly" else 1),
                        reverse=True),
            sort_option("due", "Next payment first", lambda c: c["next_due_date"] or "9999"),
            sort_option("label", "Name", lambda c: (c["label"] or "").lower()),
            sort_option("category", "Category",
                        lambda c: ((c["category"] or "").lower(), (c["label"] or "").lower())),
        ],
        default_sort="cost",
    )
    return render_template(
        "management_recurring_costs.html", costs=lv["rows"], lv=lv,
        monthly_equivalent=monthly_equivalent, vendors=vendor_list,
        unattached=unattached,
    )


def _recurring_vendor_id(conn):
    """The supplier chosen on the form, if it is a real one.

    Silently dropping an id that does not exist rather than storing it: a
    dangling vendor_id would show as "not linked" on the page while looking
    set in the database, which is the worst of both.
    """
    raw = (request.form.get("vendor_id", "") or "").strip()
    if not raw.isdigit():
        return None
    row = conn.execute("SELECT id FROM vendors WHERE id = ?", (int(raw),)).fetchone()
    return row["id"] if row else None


