# ---------------------------------------------------------------------------
# The estate's maintenance.
#
# Everything the house has for upkeep is reactive: a room issue or a vehicle
# fault is something a person noticed and reported. That works for a tap that
# drips. It does not work for a chimney, a boiler or an extinguisher, because
# an unswept chimney does not report itself — and the first anyone hears of it
# can be an insurer asking for the certificate after a fire.
#
# So: schedules that generate their own work, the same shape as the social
# plans. A visit is recorded when the work is actually done, the certificate
# with it, and the next date follows from the date it was done rather than
# from the date it was due — six weeks late does not mean the next one is six
# weeks early.
#
# What is NOT here is any assertion about what French law or an insurer
# requires. That varies by commune, by policy and by whether a house takes
# paying guests, and writing a legal requirement into somebody's data because
# it is usually true is how they stop checking. `required_by` is theirs to set.
# ---------------------------------------------------------------------------

MAINTENANCE_CATEGORIES = {
    "building": "The building",
    "heating": "Heating and hot water",
    "safety": "Fire and safety",
    "grounds": "Grounds and gardens",
    "water": "Water and drainage",
    "electrical": "Electrical",
    "equipment": "Equipment",
}

MAINTENANCE_REQUIRED_BY = {
    "none": "Nobody — we choose to",
    "insurance": "Our insurer asks for it",
    "law": "Required by law",
    "both": "Both",
}

# Offered on the page as a starting list, never inserted on anybody's behalf.
# Frequencies are the common ones for a house like this; the page says plainly
# that they are a starting point to confirm, not a rule we are asserting.
MAINTENANCE_SUGGESTIONS = [
    ("Ramonage — chimney sweeping", "heating", 12,
     "Usually annual, and usually the certificate an insurer asks for after a fire. "
     "Confirm the frequency with your commune and your policy."),
    ("Boiler service", "heating", 12, "Annual is typical for a gas or oil boiler."),
    ("Fire extinguishers checked", "safety", 12,
     "Annual inspection by an approved company is the usual requirement where a "
     "house takes paying guests."),
    ("Smoke and heat detectors tested", "safety", 6, "Tested, batteries replaced."),
    ("Electrical installation inspected", "electrical", 60,
     "Periodic inspection. The interval depends on the installation and on whether "
     "the house is treated as receiving the public."),
    ("Gutters cleared", "building", 12, "Before winter, after the leaves come down."),
    ("Roof inspected", "building", 12, "After winter, before the next one."),
    ("Septic tank / fosse septique emptied", "water", 48,
     "Every three to four years is typical; the commune may set its own interval."),
    ("Legionella — water system checked", "water", 12,
     "Where there are guest bathrooms standing unused between stays."),
    ("Trees inspected", "grounds", 12, "Deadwood and storm damage, before winter."),
    ("Alarm and emergency lighting tested", "safety", 6, None),
    ("Kitchen extraction cleaned", "safety", 12,
     "Grease in a restaurant extraction system is a fire risk and an insurer's question."),
]


def maintenance_next_due(schedule):
    """When this is next owed.

    From the date it was last DONE, not from the date it was last due. A
    service six weeks late does not make the following one six weeks early.
    """
    if schedule["next_due_on"]:
        return parse_date(schedule["next_due_on"])
    last = parse_date(schedule["last_done_on"] or "")
    if not last:
        return None
    return _add_months(last, max(1, schedule["every_months"] or 12))


def maintenance_status(schedule, today=None):
    """overdue / due soon / scheduled / never done, with the days involved."""
    today = today or house_today()
    due = maintenance_next_due(schedule)
    if not due:
        return {"state": "unknown", "due": None, "days": None,
                "label": "never recorded"}
    days = (due - today).days
    if days < 0:
        return {"state": "overdue", "due": due, "days": days,
                "label": f"{abs(days)} day{'s' if abs(days) != 1 else ''} overdue"}
    if days <= max(0, schedule["lead_days"] or 0):
        return {"state": "soon", "due": due, "days": days,
                "label": "due now" if days == 0 else f"due in {days} days"}
    return {"state": "scheduled", "due": due, "days": days,
            "label": f"due {due.strftime('%d %b %Y')}"}


def maintenance_task_title(schedule):
    where = (schedule["location"] or "").strip()
    return f"{schedule['name']}{' — ' + where if where else ''}"


def generate_maintenance_tasks(conn, *, today=None, user_id=None):
    """Raise a task for anything falling due inside its notice period.

    One task per schedule at a time: the point is that somebody books the
    sweep, not that the list fills with the same line every morning. A
    schedule already carrying an open task is left alone.
    """
    today = today or house_today()
    if isinstance(today, str):
        today = parse_date(today)
    now_iso = datetime.now(timezone.utc).isoformat()
    made = 0
    for sched in conn.execute(
            "SELECT * FROM maintenance_schedules WHERE active = 1 ORDER BY id").fetchall():
        status = maintenance_status(sched, today)
        if status["state"] not in ("overdue", "soon"):
            continue
        title = maintenance_task_title(sched)
        if conn.execute(
                """SELECT 1 FROM tasks
                   WHERE origin = 'maintenance' AND title = ? AND status != 'done'""",
                (title,)).fetchone():
            continue
        # Overdue work an insurer or the law expects is not a normal task.
        urgent = status["state"] == "overdue" and sched["required_by"] != "none"
        note = (sched["notes"] or "").strip() or None
        if sched["required_by"] != "none":
            asked = MAINTENANCE_REQUIRED_BY.get(sched["required_by"], sched["required_by"])
            note = f"{note + chr(10) + chr(10) if note else ''}{asked}. Keep the certificate."
        conn.execute(
            """INSERT INTO tasks (assigned_to_user_id, title, notes, priority, due_date,
                 status, origin, created_at)
               VALUES (?, ?, ?, ?, ?, 'open', 'maintenance', ?)""",
            (sched["assigned_to_user_id"], title, note,
             "high" if urgent else "normal",
             status["due"].isoformat(), now_iso))
        made += 1
    conn.commit()
    return made


# Only the blocking kind become tasks. A warning worth reading is not the same
# as a job worth putting on somebody's list, and a task list that fills with
# things nobody is expected to act on is a list people stop opening.
# Fifteen is what the house takes on an atelier. Ten was the seeded default
# and was never a decision anybody made. Named here because the column default
# only reaches a database created after it changed — every existing one keeps
# handing out the old number until the code stops asking.
DEFAULT_WORKSHOP_CAPACITY = 15

WATCH_TASK_ORIGIN = "watch"

# Per kind, not overall: one very bad week of rota should not push a fault
# with a guest in the room off the list. Anything dropped is reported rather
# than silently trimmed — the pages carry the full set.
WATCH_TASK_CAP = 5

# Each blocking finding has a kind, and each kind has somebody who can actually
# end it. The owner reads the warnings panel; the owner is rarely the person who
# moves a shift, fixes a radiator or rings the insurer. Routing is what makes a
# task different from the panel it came from — without it every one of these
# lands on nobody's list and the whole generator is the panel again, in a
# second place.
WATCH_TASK_KINDS = {
    "certification": "Rostered without a current certificate",
    "cover": "A day with guests and nobody on",
    "fault": "A sold room with an open fault",
    "insurer": "The insurer has not been told",
    "backup": "No backup is arriving",
    "job": "An automation job keeps failing",
    "vehicle": "A vehicle without valid papers",
    "policy": "Insurance that has run out",
    "workshop": "A workshop short of the number it needs",
    "materials": "A workshop without the materials to run",
    "filing": "A return or payment that is due",
    "celebration": "A guest with something to celebrate while they are here",
    "access": "A guest who told us something, in a room that asks something",
    "agreement": "An agreement about to roll over while nobody decided",
}

# One failure is a mail server having a bad morning. Two in a row, on jobs that
# mostly run daily, is nobody coming.
JOB_FAILURE_STREAK = 2
WATCH_ASSIGNEE_PREFIX = "watch_task_assignee_"


def watch_task_assignees(conn):
    """kind -> user id, for kinds the owner has routed to somebody.

    Deliberately joined against users rather than read raw: a route pointing at
    somebody who has since left would otherwise send the task to an account
    nobody opens, which is worse than leaving it unassigned — unassigned at
    least still shows on the owner's own list. Someone leaving silently hands
    their routes back.
    """
    rows = conn.execute(
        """SELECT app_settings.key AS key, users.id AS uid
             FROM app_settings
             JOIN users ON users.id = CAST(app_settings.value AS INTEGER)
            WHERE app_settings.key LIKE ? AND users.status = 'active'""",
        (WATCH_ASSIGNEE_PREFIX + "%",)).fetchall()
    out = {}
    for r in rows:
        kind = r["key"][len(WATCH_ASSIGNEE_PREFIX):]
        if kind in WATCH_TASK_KINDS:
            out[kind] = r["uid"]
    return out


# Far enough ahead to book a garage, near enough that it is not noise. A
# contrôle technique slot in the Ariège in August is not a same-week booking.
VEHICLE_PAPERS_WARN_DAYS = 30


# Long enough to get a quote and argue about it, short enough not to be noise.
INSURANCE_WARN_DAYS = 45


# Six months, which is what the arrêté requires the fiches to be kept for.
# Not longer "in case": a register held beyond its purpose is a register held
# without one.
POLICE_REGISTER_KEEP_MONTHS = 6

# Guests the register does not apply to. Stored as a nationality string
# because that is what a person writes on the form; matched case-insensitively
# and on either language, since a French guest writes "française" and an
# English-speaking one writes "French" about the same person.
FRENCH_NATIONALITY_WORDS = {"fr", "france", "french", "francais", "française",
                            "francaise", "française"}


def is_french_national(nationality):
    """Whether the register applies. Unknown is NOT French.

    The obligation is on the house, so an unrecorded nationality has to read
    as "this fiche is still needed" rather than as "no fiche required". The
    safe default and the lazy default point in opposite directions here.
    """
    if not nationality:
        return False
    return str(nationality).strip().lower().rstrip(".") in FRENCH_NATIONALITY_WORDS


def police_register_needed(conn, booking_id):
    """How many fiches this stay still wants.

    party_size is the count of people staying, and the register is per person.
    A stay with three guests and one fiche is two fiches short, and nothing
    anywhere said so.
    """
    booking = conn.execute("SELECT * FROM bookings WHERE id = ?", (booking_id,)).fetchone()
    if not booking:
        return None
    have = conn.execute(
        "SELECT * FROM police_register WHERE booking_id = ? ORDER BY id", (booking_id,)).fetchall()
    # Only foreign guests need one, and the only way to know is to have asked.
    # So a stay with nobody recorded is "not asked yet" rather than "nobody
    # needs one" — which is why the count below starts from the party size.
    exempt = sum(1 for f in have if is_french_national(f["nationality"]))
    party = booking["party_size"] or 1
    return {"booking": booking, "fiches": have, "party": party,
            "recorded": len(have), "exempt": exempt,
            "outstanding": max(0, party - len(have))}


def stays_missing_fiches(conn, today=None, days_back=30):
    """Stays that have started and have nobody on the register.

    Looked at from the arrival rather than the booking, because the fiche is
    completed on arrival — a stay three weeks out with no fiches is not late,
    it has not happened.
    """
    day = today or house_today()
    since = (day - timedelta(days=max(1, days_back))).isoformat()
    out = []
    for b in conn.execute(
            """SELECT bookings.*, rooms.name AS room_name FROM bookings
                 JOIN rooms ON rooms.id = bookings.room_id
                WHERE bookings.status = 'confirmed'
                  AND bookings.arrival_date <= ? AND bookings.arrival_date >= ?
                ORDER BY bookings.arrival_date""",
            (day.isoformat(), since)).fetchall():
        state = police_register_needed(conn, b["id"])
        if state and state["outstanding"]:
            out.append(state)
    return out


def purge_police_register(conn, today=None):
    """Delete fiches older than the law allows them to be kept.

    Dated from the DEPARTURE, not from when the fiche was written: the six
    months runs from the end of the stay, and a fiche filled in on arrival for
    a fortnight's stay would otherwise go a fortnight early.
    """
    day = today or house_today()
    cutoff = (day - timedelta(days=POLICE_REGISTER_KEEP_MONTHS * 31)).isoformat()
    cur = conn.execute(
        """DELETE FROM police_register WHERE booking_id IN (
               SELECT id FROM bookings
                WHERE departure_date IS NOT NULL AND departure_date < ?)""",
        (cutoff,))
    return {"police register entries": cur.rowcount}


# Tables that are not a guest's, whatever columns they have. Staff, job
# applicants, suppliers and the house's own contacts are all people, and none
# of them is answered by a GUEST asking what is held about them — a staff
# member's record is answered under a different process with different rules.
NOT_GUEST_TABLES = {
    "users", "candidates", "vendors", "contacts", "company_info",
    "user_languages", "documents", "absences", "time_entries",
}

# Kept even when somebody asks for erasure, because French accounting law
# requires the record of a sale. The person is removed from them; the money
# stays. Anything not listed here is deleted outright.
ANONYMISE_RATHER_THAN_DELETE = {
    "bookings": ("guest_name", "guest_email", "guest_phone"),
    "restaurant_bookings": ("guest_name", "guest_email", "guest_phone"),
    "workshop_bookings": ("guest_name", "guest_email", "guest_phone"),
    "refunds": ("guest_name", "guest_email"),
    "promo_code_redemptions": ("guest_email",),
}

ERASED_MARKER = "[erased at the guest's request]"


# How loudly a caution should be read. Three levels rather than a flag,
# because "they smoke in the room" and "do not accept a booking from this
# person" are not the same instruction and a single boolean makes them look it.
# Where a booking came from.
#
# Recorded by the path that made it rather than chosen on a form: a field
# somebody has to remember to set is a field that is mostly wrong, and the app
# already knows which door each booking came through. The desk can correct it
# afterwards -- a walk-in who says they came off an agent's listing is the one
# case the app cannot know.
#
# "direct" covers the website and the telephone alike, because both are business
# the house did not pay a commission on, which is the distinction that matters.
BOOKING_SOURCES = {
    "direct": "Direct",
    "desk": "At the door or by telephone",
    "returning": "A guest who had stayed before",
    "agent": "Through an agent or platform",
    "event": "Part of an event or wedding",
    "other": "Something else",
}


def booking_source_for(conn, email, fallback):
    """The source to stamp, promoting a repeat guest ahead of the raw path.

    A returning guest booking through the website is worth knowing about
    separately from a stranger doing the same: one is the house's own audience
    and the other is new business, and lumping them together hides whether the
    place is growing or just retaining.
    """
    email = (email or "").strip().casefold()
    if email:
        # ALREADY DEPARTED, not merely confirmed. A guest with a confirmed stay
        # still ahead of them who books a second one is the same person planning
        # one trip, not somebody the house has won back -- and counting them as
        # returning would make a good week of forward bookings look like
        # loyalty.
        seen = conn.execute(
            """SELECT 1 FROM bookings
                WHERE LOWER(TRIM(guest_email)) = ? AND status = 'confirmed'
                  AND departure_date <= ?
                LIMIT 1""",
            (email, house_today_iso())).fetchone()
        if seen:
            return "returning"
    return fallback


CAUTION_LEVELS = {
    "note": "Worth knowing",
    "care": "Handle with care",
    "refuse": "Do not accept a booking",
}


def guest_notes(conn, guest_id):
    """The running note on a guest, newest first.

    APPEND-ONLY, which is the whole point. guests.notes is one free-text box, so
    whoever types last silently replaces what the last person wrote -- and the
    thing that gets lost is always the older observation nobody thought to
    repeat. Each entry here keeps who wrote it and when, because "prefers the
    quiet side" from the housekeeper and from the guest's own email are worth
    different amounts.
    """
    return conn.execute(
        """SELECT guest_notes.*, users.name AS author
             FROM guest_notes LEFT JOIN users ON users.id = guest_notes.written_by_user_id
            WHERE guest_id = ? ORDER BY guest_notes.created_at DESC, guest_notes.id DESC""",
        (guest_id,)).fetchall()


def add_guest_note(conn, guest_id, body, user_id=None):
    body = (body or "").strip()
    if not body:
        return False
    conn.execute(
        """INSERT INTO guest_notes (guest_id, body, written_by_user_id, created_at)
           VALUES (?, ?, ?, ?)""",
        (guest_id, body[:2000], user_id, datetime.now(timezone.utc).isoformat()))
    return True


def parse_day_month(raw):
    """A birthday as MM-DD, from whatever somebody typed. None if unreadable.

    Accepts a full date and throws the year away rather than storing it. The
    house wants to know that the 3rd of June matters to somebody, and has no use
    for the year they were born -- and data you have no use for is data you have
    to justify holding.
    """
    raw = (raw or "").strip()
    if not raw:
        return None
    for fmt, take in (("%Y-%m-%d", True), ("%d/%m/%Y", True),
                      ("%m-%d", False), ("%d/%m", False)):
        try:
            parsed = datetime.strptime(raw, fmt)
        except ValueError:
            continue
        return f"{parsed.month:02d}-{parsed.day:02d}"
    return None


def day_month_human(value):
    """MM-DD as "3 June", or "" if there is nothing there."""
    value = (value or "").strip()
    if not value:
        return ""
    try:
        parsed = datetime.strptime(value, "%m-%d")
    except ValueError:
        return value
    return f"{parsed.day} {parsed.strftime('%B')}"


# 06-03 is a storage format, not something to show a person. Registered here
# rather than beside the other filters: module level runs top to bottom, and a
# filter registered above its own function is a NameError at import.
app.jinja_env.filters["day_month"] = day_month_human


def upcoming_guest_dates(conn, within_days=30, today=None):
    """Birthdays and anniversaries coming up, soonest first.

    Wrapped round the year: on the 20th of December, the 3rd of January is
    fourteen days away and not three hundred and fifty. Getting that wrong is
    how a list like this quietly stops showing anything in the last fortnight of
    the year, which is exactly when the house is fullest.

    A date only appears if the person has a profile the house can act on -- an
    anniversary with no email and no stay coming up is a fact, not a job.
    """
    today = today or service_day()
    rows = []
    for guest in conn.execute(
            """SELECT * FROM guests
                WHERE merged_into_id IS NULL
                  AND (COALESCE(birthday, '') != '' OR COALESCE(anniversary, '') != '')
             """).fetchall():
        for kind, value in (("birthday", guest["birthday"]),
                            ("anniversary", guest["anniversary"])):
            if not (value or "").strip():
                continue
            try:
                month, day = (int(x) for x in value.split("-"))
            except (ValueError, TypeError):
                continue
            for year in (today.year, today.year + 1):
                try:
                    when = date(year, month, day)
                except ValueError:
                    # 29 February in a year that has none. Marked on the 1st of
                    # March rather than dropped: the guest still has a birthday.
                    try:
                        when = date(year, 3, 1)
                    except ValueError:
                        continue
                days = (when - today).days
                if 0 <= days <= within_days:
                    rows.append({"guest": guest, "kind": kind, "when": when,
                                 "days": days})
                    break
    rows.sort(key=lambda r: (r["days"], r["guest"]["name"] or ""))
    return rows


def guest_caution_for(conn, email=None, name=None):
    """Any caution on the person a booking is being taken for, or None.

    Looked up by ADDRESS FIRST and then by name. A caution that only matched on
    the email address would be lifted by the guest using a different one, which
    is the first thing somebody does after being turned down.

    Compared with casefold in Python rather than LOWER in SQL: these are French
    names, and SQLite's LOWER is ASCII-only.
    """
    email = (email or "").strip().casefold()
    name_key = " ".join((name or "").casefold().split())
    if not email and not name_key:
        return None
    for row in conn.execute(
            """SELECT * FROM guests
                WHERE COALESCE(caution_level, '') != '' AND merged_into_id IS NULL"""
    ).fetchall():
        if email and (row["email"] or "").strip().casefold() == email:
            return row
        if name_key and " ".join((row["name"] or "").casefold().split()) == name_key:
            return row
    return None


def possible_duplicate_guests(conn, name, email=None, phone=None, exclude_id=None):
    """Profiles that might already be this person.

    Run BEFORE a second profile exists, because merging afterwards is somebody
    noticing -- and the duplicate that never gets noticed is the one where the
    guest's history, their allergy and the note about the dog all sit on the
    profile nobody opened.

    A same-email match is impossible (there is a unique index), so the useful
    signals are the phone number and the name. Compared with casefold in Python:
    SQLite's LOWER is ASCII-only and these are French names.
    """
    name_key = " ".join((name or "").casefold().split())
    phone_key = "".join(ch for ch in (phone or "") if ch.isdigit())[-9:]
    email_key = (email or "").strip().casefold()
    hits = []
    for row in conn.execute(
            "SELECT * FROM guests WHERE merged_into_id IS NULL").fetchall():
        if exclude_id and row["id"] == exclude_id:
            continue
        why = []
        if email_key and (row["email"] or "").strip().casefold() == email_key:
            why.append("the same email")
        row_phone = "".join(ch for ch in (row["phone"] or "") if ch.isdigit())[-9:]
        if phone_key and len(phone_key) >= 6 and row_phone == phone_key:
            why.append("the same phone number")
        if name_key and " ".join((row["name"] or "").casefold().split()) == name_key:
            why.append("the same name")
        if why:
            hits.append({"guest": row, "why": why})
    return hits


def duplicate_guest_pairs(conn, limit=60):
    """Every pair of profiles that might be one person, across the whole book.

    possible_duplicate_guests answers the question for ONE profile, which only
    helps somebody who has already opened it. This asks it of the book, so the
    duplicates nobody has looked at can be found at all.

    ONE ROW PER PAIR, not two. Listing A-matches-B and B-matches-A doubles the
    length of the list and makes it read as twice the problem; the pair is keyed
    on the two ids in order.

    The stronger signal is put first -- a shared phone number is a much better
    reason to think two profiles are one person than a shared name, and a house
    in France will have several Martins who are not related.
    """
    by_phone, by_name, pairs = {}, {}, {}
    profiles = conn.execute(
        "SELECT * FROM guests WHERE merged_into_id IS NULL ORDER BY id").fetchall()
    for row in profiles:
        phone = "".join(ch for ch in (row["phone"] or "") if ch.isdigit())[-9:]
        if len(phone) >= 6:
            by_phone.setdefault(phone, []).append(row)
        name = " ".join((row["name"] or "").casefold().split())
        if name:
            by_name.setdefault(name, []).append(row)

    def add(rows, why, strength):
        for i, a in enumerate(rows):
            for b in rows[i + 1:]:
                key = (min(a["id"], b["id"]), max(a["id"], b["id"]))
                entry = pairs.setdefault(
                    key, {"a": a if a["id"] < b["id"] else b,
                          "b": b if a["id"] < b["id"] else a,
                          "why": [], "strength": 0})
                if why not in entry["why"]:
                    entry["why"].append(why)
                entry["strength"] = max(entry["strength"], strength)

    for rows in by_phone.values():
        if len(rows) > 1:
            add(rows, "the same phone number", 2)
    for rows in by_name.values():
        if len(rows) > 1:
            add(rows, "the same name", 1)

    ordered = sorted(pairs.values(),
                     key=lambda e: (-len(e["why"]), -e["strength"],
                                    e["a"]["name"] or ""))
    return {"pairs": ordered[:limit], "total": len(ordered),
            "shown": min(len(ordered), limit), "profiles": len(profiles)}


def merge_guest_profiles(conn, keep_id, merge_id, user_id=None):
    """Fold one profile into another. Returns (ok, message).

    The same person under two addresses, or one profile with none at all -- a
    walk-in taken at the desk, then the same family booking online next year.
    The unique index stops two profiles sharing an email, and does nothing about
    this.

    WHAT MOVES: notes, and any booking linked by id. WHAT IS KEPT: every field on
    the survivor that is already filled, filling its blanks from the other. A
    merge that overwrote a good address with an older one would be a data loss
    dressed as a tidy-up.

    NOTHING IS DELETED. The absorbed profile stays, pointing at its survivor,
    because a booking, an invoice or a conversation may reference it and a row
    that vanishes takes the explanation with it.
    """
    if keep_id == merge_id:
        return False, "That is the same profile."
    keep = conn.execute("SELECT * FROM guests WHERE id = ?", (keep_id,)).fetchone()
    merge = conn.execute("SELECT * FROM guests WHERE id = ?", (merge_id,)).fetchone()
    if not keep or not merge:
        return False, "One of those profiles no longer exists."
    if merge["merged_into_id"]:
        return False, f"{merge['name']} has already been merged."
    if keep["merged_into_id"]:
        return False, f"{keep['name']} has itself been merged into another profile."

    # Blanks on the survivor are filled from the other; anything already there
    # is left alone.
    fills = {}
    for column in ("email", "phone", "dietary_notes", "preferences",
                   "name_pronunciation", "birthday", "anniversary",
                   "caution", "caution_level"):
        if column not in keep.keys():
            continue
        if not (keep[column] or "").strip() and (merge[column] or "").strip():
            fills[column] = merge[column]
    # The email is the one field a unique index can refuse. Only take it if the
    # survivor has none, and the merged profile's has to be released first or
    # the index refuses the update.
    if "email" in fills:
        conn.execute("UPDATE guests SET email = NULL WHERE id = ?", (merge_id,))
    if fills:
        sets = ", ".join(f"{c} = ?" for c in fills)
        conn.execute(f"UPDATE guests SET {sets} WHERE id = ?",
                     list(fills.values()) + [keep_id])

    conn.execute("UPDATE guest_notes SET guest_id = ? WHERE guest_id = ?",
                 (keep_id, merge_id))
    moved = conn.execute("SELECT changes() AS c").fetchone()["c"]
    # The old profile's free-text note is kept as a dated entry rather than
    # thrown away or pasted over the survivor's.
    if (merge["notes"] or "").strip():
        add_guest_note(conn, keep_id,
                       f"From the merged profile for {merge['name']}: "
                       f"{merge['notes'].strip()}", user_id)
    # linked_guest_id is the CERTAIN link -- guest_record treats a match on the
    # email address as an inference and says so. Moving these is the point of a
    # merge: the survivor inherits the stays somebody deliberately attached to
    # the profile being folded in.
    conn.execute(
        "UPDATE bookings SET linked_guest_id = ? WHERE linked_guest_id = ?",
        (keep_id, merge_id))
    moved_stays = conn.execute("SELECT changes() AS c").fetchone()["c"]

    # Dinners and ateliers are matched to a profile by EMAIL ADDRESS, not by an
    # id -- so folding an address onto the survivor is what carries them across,
    # and an address left behind on the absorbed profile takes that history with
    # it. Where the survivor already had its own address the other one is kept
    # as a note, because the guest genuinely used both and somebody looking for
    # a dinner booked under the old one needs to know it existed.
    other_email = (merge["email"] or "").strip()
    if other_email and (keep["email"] or "").strip().casefold() != other_email.casefold():
        add_guest_note(
            conn, keep_id,
            f"Also booked as {other_email} — dinners and ateliers under that "
            "address are theirs too.", user_id)

    conn.execute(
        "UPDATE guests SET merged_into_id = ?, caution = NULL, caution_level = NULL "
        "WHERE id = ?", (keep_id, merge_id))
    add_guest_note(conn, keep_id,
                   f"Merged the duplicate profile for {merge['name']} into this one.",
                   user_id)
    # The audit entry is written by the ROUTE, not here. log_audit reads the
    # request to record who and from where, and this has to be callable without
    # one -- a merge run from a script or a test is still a merge.
    parts = []
    if moved:
        parts.append(f"{moved} note(s)")
    if moved_stays:
        parts.append(f"{moved_stays} stay(s)")
    return True, (f"{merge['name']} folded into {keep['name']}"
                  + (" — " + " and ".join(parts) + " moved" if parts else "") + ".")


def guest_record(conn, guest_id):
    """Everything the house knows about one person, in one structure.

    The money is summed from each booking's own bill rather than recomputed,
    so there is one definition of what a stay costs and this is not a second.
    """
    guest = conn.execute("SELECT * FROM guests WHERE id = ?", (guest_id,)).fetchone()
    if not guest:
        return None
    email = (guest["email"] or "").strip().lower()

    # Two ways in, and the record keeps track of which. A linked booking is
    # certain; one matched on the address is an inference, and a page that
    # blurs the two is a page that will one day show somebody else's stay.
    linked = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name, 'linked' AS matched_by
             FROM bookings JOIN rooms ON rooms.id = bookings.room_id
            WHERE bookings.linked_guest_id = ?""", (guest_id,)).fetchall()
    by_email = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name, 'address' AS matched_by
             FROM bookings JOIN rooms ON rooms.id = bookings.room_id
            WHERE ? != '' AND LOWER(TRIM(bookings.guest_email)) = ?
              AND (bookings.linked_guest_id IS NULL OR bookings.linked_guest_id != ?)""",
        (email, email, guest_id)).fetchall()
    stays = sorted(list(linked) + list(by_email),
                   key=lambda b: b["arrival_date"] or "", reverse=True)

    dinners = conn.execute(
        """SELECT * FROM restaurant_bookings
            WHERE ? != '' AND LOWER(TRIM(guest_email)) = ?
            ORDER BY dinner_date DESC""", (email, email)).fetchall()
    workshops = conn.execute(
        """SELECT workshop_bookings.*, workshops.title, workshop_sessions.start_date
             FROM workshop_bookings
             JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
             JOIN workshops ON workshops.id = workshop_sessions.workshop_id
            WHERE ? != '' AND LOWER(TRIM(workshop_bookings.guest_email)) = ?
            ORDER BY workshop_sessions.start_date DESC""", (email, email)).fetchall()
    events = conn.execute(
        """SELECT * FROM event_inquiries
            WHERE ? != '' AND LOWER(TRIM(contact_email)) = ?
            ORDER BY COALESCE(preferred_date, '') DESC""", (email, email)).fetchall()

    # THE MONEY. Per stay from its own bill, so the figures here and the
    # figures on the guest's own statement cannot disagree.
    bills, spent, owed, paid = {}, 0.0, 0.0, 0.0
    for b in stays:
        bill = booking_bill(conn, b["id"])
        if not bill:
            continue
        bills[b["id"]] = bill
        if b["status"] != "cancelled":
            spent += bill["total"]
            owed += bill["owed"]
            paid += bill["paid"]
    for w in workshops:
        if w["status"] != "cancelled":
            spent += float(w["total_price"] or 0)
    for d in dinners:
        if d["status"] == "confirmed":
            spent += float(d["total_price"] or 0) if "total_price" in d.keys() else 0.0

    said = conn.execute(
        """SELECT guest_feedback.*, bookings.reference_code
             FROM guest_feedback
             JOIN bookings ON bookings.id = guest_feedback.booking_id
            WHERE bookings.id IN ({})
            ORDER BY guest_feedback.submitted_at DESC""".format(
                ",".join("?" * len(stays)) or "NULL"),
        tuple(b["id"] for b in stays)).fetchall() if stays else []

    return {
        "guest": guest, "stays": stays, "dinners": dinners,
        "workshops": workshops, "events": events, "bills": bills,
        "feedback": said,
        "linked_count": len(linked), "by_email_count": len(by_email),
        "spent": round(spent, 2), "owed": round(owed, 2), "paid": round(paid, 2),
        "nights": sum(
            max(0, ((parse_date(b["departure_date"]) - parse_date(b["arrival_date"])).days
                    if b["arrival_date"] and b["departure_date"]
                    and parse_date(b["arrival_date"]) and parse_date(b["departure_date"])
                    else 0))
            for b in stays if b["status"] != "cancelled"),
        "first_seen": min((b["arrival_date"] for b in stays if b["arrival_date"]),
                          default=None),
        "last_seen": max((b["departure_date"] for b in stays if b["departure_date"]),
                         default=None),
    }


def guest_messages(conn, guest, limit=60):
    """Every word the house has sent this person, in one list.

    Mail, texts and campaign sends live in three tables and no page has ever
    put them together — so "have we written to them about this" could only be
    answered by opening three screens and holding the dates in your head.

    Read-only and by address or number: these are records of what went out,
    not a mailbox, and nothing here can be replied to from this page.
    """
    email = (guest["email"] or "").strip().lower()
    phone = normalise_phone(guest["phone"] or "") or (guest["phone"] or "").strip()
    out = []

    if email:
        for r in conn.execute(
                """SELECT subject, body, created_at, sent_at, reason
                     FROM email_outbox WHERE LOWER(TRIM(to_address)) = ?
                    ORDER BY id DESC LIMIT ?""", (email, limit)).fetchall():
            out.append({"kind": "email", "when": r["created_at"],
                        "subject": r["subject"], "body": r["body"],
                        # Held is not sent. A page that showed both the same
                        # way would say the house had written to somebody it
                        # had not.
                        "sent": bool(r["sent_at"]), "note": r["reason"]})
        for r in conn.execute(
                """SELECT template_name, subject, status, detail, created_at
                     FROM campaign_sends
                    WHERE LOWER(TRIM(recipient_email)) = ?
                    ORDER BY id DESC LIMIT ?""", (email, limit)).fetchall():
            out.append({"kind": "campaign", "when": r["created_at"],
                        "subject": r["subject"] or r["template_name"] or "A campaign",
                        "body": "",
                        # status carries whether it actually went; a campaign
                        # that failed is not a campaign the guest received.
                        "sent": (r["status"] or "") == "sent",
                        "note": r["detail"] or r["template_name"]})
    if phone:
        for r in conn.execute(
                """SELECT body, purpose, reason, created_at, sent_at
                     FROM sms_outbox WHERE phone = ?
                    ORDER BY id DESC LIMIT ?""", (phone, limit)).fetchall():
            out.append({"kind": "text", "when": r["created_at"],
                        "subject": r["purpose"], "body": r["body"],
                        "sent": bool(r["sent_at"]), "note": r["reason"]})

    out.sort(key=lambda x: x["when"] or "", reverse=True)
    return out[:limit]


def party_for_booking(conn, booking_id):
    """The party a booking belongs to, with every stay in it.

    Returns None for a booking that is on its own, which is most of them —
    a house of seven rooms does not want a party wrapper round every single
    reservation.
    """
    row = conn.execute(
        """SELECT booking_parties.* FROM booking_parties
             JOIN bookings ON bookings.party_id = booking_parties.id
            WHERE bookings.id = ?""", (booking_id,)).fetchone()
    if not row:
        return None
    return party_detail(conn, row["id"])


def party_detail(conn, party_id):
    """A party, its stays, and what the whole group owes.

    The money is summed from each booking's own bill rather than recomputed:
    there is one definition of what a stay costs and this is not a second one.
    """
    party = conn.execute("SELECT * FROM booking_parties WHERE id = ?",
                         (party_id,)).fetchone()
    if not party:
        return None
    stays = conn.execute(
        """SELECT bookings.*, rooms.name AS room_name FROM bookings
             JOIN rooms ON rooms.id = bookings.room_id
            WHERE bookings.party_id = ?
            ORDER BY bookings.arrival_date, rooms.name""", (party_id,)).fetchall()
    total = owed = paid = 0.0
    for b in stays:
        bill = booking_bill(conn, b["id"])
        if not bill:
            continue
        total += bill["total"]
        owed += bill["owed"]
        paid += bill["paid"]
    arrivals = [parse_date(b["arrival_date"]) for b in stays if b["arrival_date"]]
    departures = [parse_date(b["departure_date"]) for b in stays if b["departure_date"]]
    return {
        "party": party, "stays": stays, "rooms": len(stays),
        "guests": sum((b["party_size"] or 1) for b in stays),
        "total": round(total, 2), "owed": round(owed, 2), "paid": round(paid, 2),
        # The span of the whole group, which is not any one booking's dates.
        "arrival": min(arrivals).isoformat() if arrivals else None,
        "departure": max(departures).isoformat() if departures else None,
        # Whoever the house talks to. Falls back to the earliest arrival, so
        # there is always somebody rather than nobody.
        "lead": next((b for b in stays if b["id"] == party["lead_booking_id"]),
                     stays[0] if stays else None),
    }


def party_lead_bookings(conn, booking_ids):
    """Of a set of bookings, the ones that should be written to.

    A party gets ONE arrival text and one confirmation, not one per room. The
    lead is written to; the others are in the message. Anything not in a party
    is its own lead, so a single booking behaves exactly as it always did.
    """
    keep, seen_parties = [], set()
    for bid in booking_ids:
        row = conn.execute("SELECT id, party_id FROM bookings WHERE id = ?",
                           (bid,)).fetchone()
        if not row:
            continue
        if not row["party_id"]:
            keep.append(bid)
            continue
        if row["party_id"] in seen_parties:
            continue
        seen_parties.add(row["party_id"])
        party = conn.execute("SELECT lead_booking_id FROM booking_parties WHERE id = ?",
                             (row["party_id"],)).fetchone()
        lead = party["lead_booking_id"] if party else None
        # If the lead is not in the set being written to, the first of the set
        # stands in — better one message to somebody in the party than none.
        keep.append(lead if lead in booking_ids else bid)
    return keep


def empty_nights(conn, *, days=90, today=None):
    """Every unsold room-night in the window, and the runs they form.

    A night counts as sold if a confirmed OR pending booking covers it, and
    unsellable if a block covers it. Pending counts because somebody has asked
    for it and the calendar is already holding it — showing it as free is how
    the same night gets offered twice.
    """
    day = today or house_today()
    last = day + timedelta(days=max(1, min(730, days)))

    rooms = conn.execute(
        "SELECT * FROM rooms WHERE active = 1 ORDER BY sort_order, name").fetchall()
    taken = {r["id"]: set() for r in rooms}

    for b in conn.execute(
            """SELECT room_id, arrival_date, departure_date FROM bookings
                WHERE status IN ('confirmed', 'pending')
                  AND departure_date > ? AND arrival_date < ?""",
            (day.isoformat(), last.isoformat())).fetchall():
        start, end = parse_date(b["arrival_date"]), parse_date(b["departure_date"])
        if not start or not end:
            continue
        night = max(start, day)
        while night < min(end, last):
            taken.setdefault(b["room_id"], set()).add(night)
            night += timedelta(days=1)

    blocked = {r["id"]: set() for r in rooms}
    for bl in conn.execute(
            """SELECT room_id, start_date, end_date FROM blocked_dates
                WHERE end_date > ? AND start_date < ?""",
            (day.isoformat(), last.isoformat())).fetchall():
        start, end = parse_date(bl["start_date"]), parse_date(bl["end_date"])
        if not start or not end:
            continue
        night = max(start, day)
        while night < min(end, last):
            blocked.setdefault(bl["room_id"], set()).add(night)
            night += timedelta(days=1)

    runs, free_by_night, total_value, free_count = [], {}, 0.0, 0
    for room in rooms:
        rate = float(room["price_per_night"] or 0)
        current = []
        night = day
        while night < last:
            busy = night in taken.get(room["id"], ()) or night in blocked.get(room["id"], ())
            if busy:
                if current:
                    runs.append({"room": room,
                                 # ISO, like every other date this app hands a
                                 # template: date_short takes a string.
                                 "from": current[0].isoformat(),
                                 "to": current[-1].isoformat(),
                                 "nights": len(current),
                                 "value": round(rate * len(current), 2),
                                 # A run shorter than the room's own minimum
                                 # cannot be sold as it stands, which is a
                                 # different problem from an empty week.
                                 "below_minimum": bool(room["min_nights"]
                                                       and len(current) < room["min_nights"])})
                    current = []
            else:
                current.append(night)
                free_by_night[night.isoformat()] = free_by_night.get(night.isoformat(), 0) + 1
                free_count += 1
                total_value += rate
            night += timedelta(days=1)
        if current:
            runs.append({"room": room, "from": current[0].isoformat(),
                         "to": current[-1].isoformat(),
                         "nights": len(current), "value": round(rate * len(current), 2),
                         "below_minimum": bool(room["min_nights"]
                                               and len(current) < room["min_nights"])})

    # Longest first: a week between two bookings is something a guest can
    # actually take, and a stray Tuesday is not.
    runs.sort(key=lambda r: (-r["nights"], r["from"]))
    sellable = [r for r in runs if not r["below_minimum"]]
    possible = len(rooms) * (last - day).days
    return {
        "from": day.isoformat(), "to": last.isoformat(), "days": (last - day).days,
        "rooms": len(rooms), "runs": runs, "sellable": sellable,
        "free_nights": free_count, "possible_nights": possible,
        "occupancy": round((possible - free_count) / possible * 100) if possible else 0,
        # At today's rate, and said as that. Not "lost": a house is never full,
        # and a figure labelled lost gets subtracted from a plan that was never
        # real.
        "value_at_rate": round(total_value, 2),
    }


def room_board(conn, today=None):
    """Every room, and whether a guest can walk into it.

    Derived from the checklist tasks rather than from a status somebody sets.
    A room_status column would be a second thing to keep in agreement, and the
    two would part company the first time somebody ticked the last item and
    forgot the dropdown. Open work means not ready; no open work means ready.

    The states, in the order they matter on a changeover morning:

      occupied      somebody is in it tonight and is not leaving today
      turnover      they have gone and there is work outstanding
      arriving      empty, work done, and somebody is coming today
      ready         empty, work done, nobody due
    """
    day = today or house_today()
    iso = day.isoformat()
    out = []
    for room in conn.execute(
            "SELECT * FROM rooms WHERE active = 1 ORDER BY sort_order, name").fetchall():
        # Somebody who ARRIVES today is not in the room at eight in the
        # morning — they are the reason it has to be ready. Counting them as
        # occupied is how a changeover room disappears off the board on the
        # one morning it matters.
        here = conn.execute(
            """SELECT * FROM bookings
                WHERE room_id = ? AND status = 'confirmed'
                  AND arrival_date < ? AND departure_date > ?""",
            (room["id"], iso, iso)).fetchone()
        leaving = conn.execute(
            """SELECT * FROM bookings
                WHERE room_id = ? AND status = 'confirmed' AND departure_date = ?""",
            (room["id"], iso)).fetchone()
        arriving = conn.execute(
            """SELECT * FROM bookings
                WHERE room_id = ? AND status = 'confirmed' AND arrival_date = ?""",
            (room["id"], iso)).fetchone()
        open_work = conn.execute(
            """SELECT tasks.* FROM tasks
                 JOIN bookings ON bookings.id = tasks.booking_id
                WHERE tasks.origin = 'checklist' AND tasks.status != 'done'
                  AND bookings.room_id = ?
                ORDER BY tasks.id""", (room["id"],)).fetchall()

        if here:
            state = "occupied"
        elif open_work:
            state = "turnover"
        elif arriving:
            state = "arriving"
        else:
            state = "ready"

        out.append({
            "room": room, "state": state, "in_house": here, "leaving": leaving,
            "arriving": arriving, "open_work": open_work,
            "outstanding": len(open_work),
            # The one that decides whether somebody has to run: a guest coming
            # today into a room with work still open on it.
            "urgent": bool(arriving and open_work),
        })
    return out


def guest_data_tables(conn):
    """Every table with a column that could hold a guest's email address.

    Asked of the schema rather than listed here. A list is correct on the day
    it is written and silently wrong the first time somebody adds a table — and
    an incomplete answer to "what do you hold about me" is worse than no answer,
    because it claims to be everything.
    """
    out = {}
    for row in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table' "
            "AND name NOT LIKE 'sqlite_%'").fetchall():
        table = row["name"]
        if table in NOT_GUEST_TABLES:
            continue
        cols = [c[1] for c in conn.execute(f"PRAGMA table_info({table})")]
        keys = [c for c in cols
                if c.lower() in ("email", "guest_email", "contact_email",
                                 "to_address", "recipient_email")]
        if keys:
            out[table] = keys
    return out


def guest_data_export(conn, email):
    """Everything held about one person, by email and by what hangs off it.

    Two passes, because not everything carries an address. A review is tied to
    a booking, a fiche to a stay, a workshop guest to a registration — none of
    them has an email of its own, and an export that only searched for the
    address would quietly leave out the most personal rows in the database.
    """
    email = (email or "").strip().lower()
    if not email:
        return None
    found = {}

    for table, keys in guest_data_tables(conn).items():
        where = " OR ".join(f"LOWER(TRIM({k})) = ?" for k in keys)
        rows = conn.execute(f"SELECT * FROM {table} WHERE {where}",
                            tuple(email for _ in keys)).fetchall()
        if rows:
            found[table] = [dict(r) for r in rows]

    # What hangs off a booking. Named explicitly because the relationship is
    # the thing that makes them personal, and a schema sweep cannot see it.
    booking_ids = [r["id"] for r in found.get("bookings", [])]
    if booking_ids:
        marks = ",".join("?" * len(booking_ids))
        for table, column in (("guest_feedback", "booking_id"),
                              ("booking_extras", "booking_id"),
                              ("police_register", "booking_id")):
            try:
                rows = conn.execute(
                    f"SELECT * FROM {table} WHERE {column} IN ({marks})",
                    tuple(booking_ids)).fetchall()
            except sqlite3.OperationalError:
                continue                     # table not in this database yet
            if rows:
                found.setdefault(table, []).extend(dict(r) for r in rows)

    workshop_ids = [r["id"] for r in found.get("workshop_bookings", [])]
    if workshop_ids:
        marks = ",".join("?" * len(workshop_ids))
        for table, column in (("workshop_feedback", "workshop_booking_id"),
                              ("workshop_booking_guests", "workshop_booking_id")):
            try:
                rows = conn.execute(
                    f"SELECT * FROM {table} WHERE {column} IN ({marks})",
                    tuple(workshop_ids)).fetchall()
            except sqlite3.OperationalError:
                continue
            if rows:
                found.setdefault(table, []).extend(dict(r) for r in rows)

    return {
        "email": email,
        "taken_at": datetime.now(timezone.utc).isoformat(),
        "tables": found,
        "row_count": sum(len(v) for v in found.values()),
        # Said out loud, because "we searched for your email" and "we found
        # everything about you" are different claims and only the first is
        # one this can make honestly.
        "searched": sorted(guest_data_tables(conn)),
    }


def guest_data_erase(conn, email):
    """Remove a person from the records, keeping what the law says to keep.

    A booking is not deleted. French accounting law requires the record of a
    sale, and deleting invoices to honour a privacy request breaks one law to
    keep another. So those rows are ANONYMISED — the money stays, the person
    goes — and everything else is deleted outright.

    Returns what happened to each, because "we have deleted everything" would
    not be true, and somebody exercising this right is entitled to know
    precisely what remains and why.
    """
    email = (email or "").strip().lower()
    if not email:
        return None
    deleted, anonymised = {}, {}

    for table, keys in guest_data_tables(conn).items():
        where = " OR ".join(f"LOWER(TRIM({k})) = ?" for k in keys)
        params = tuple(email for _ in keys)
        if table in ANONYMISE_RATHER_THAN_DELETE:
            cols = ANONYMISE_RATHER_THAN_DELETE[table]
            have = {c[1] for c in conn.execute(f"PRAGMA table_info({table})")}
            sets = ", ".join(f"{c} = ?" for c in cols if c in have)
            if not sets:
                continue
            # An empty string rather than NULL: several of these columns are
            # NOT NULL, and a privacy request that fails on a constraint is a
            # privacy request that does not happen. Empty reads as "not held",
            # which is what is true, and the name keeps a marker so the row is
            # legible as erased rather than looking like bad data.
            values = tuple(ERASED_MARKER if c.endswith("name") else ""
                           for c in cols if c in have)
            cur = conn.execute(f"UPDATE {table} SET {sets} WHERE {where}",
                               values + params)
            if cur.rowcount:
                anonymised[table] = cur.rowcount
        else:
            cur = conn.execute(f"DELETE FROM {table} WHERE {where}", params)
            if cur.rowcount:
                deleted[table] = cur.rowcount

    # The fiche is deleted outright: it is held under a legal obligation with
    # its own six-month clock, not under the accounting rules, and once the
    # person is gone from the booking it identifies nobody anyway.
    for table, column in (("police_register", "booking_id"),
                          ("guest_feedback", "booking_id")):
        try:
            cur = conn.execute(
                f"""DELETE FROM {table} WHERE {column} IN (
                        SELECT id FROM bookings WHERE guest_name = ?)""",
                (ERASED_MARKER,))
        except sqlite3.OperationalError:
            continue
        if cur.rowcount:
            deleted[table] = deleted.get(table, 0) + cur.rowcount

    return {"deleted": deleted, "anonymised": anonymised,
            "kept_because": "French accounting law requires the record of a "
                            "sale to be kept. The money stays; the person has "
                            "been removed from it."}


def insurance_cover(conn, today=None):
    """Every policy, and whether the house is actually covered by it.

    Three states rather than one number, because "renew this in a fortnight"
    and "you have not been covered since March" are not the same news and the
    band that counted them together could not say which it meant.

    A policy with no expiry date is its own state. It is not covered and it is
    not lapsed — it is a record nobody finished, and treating it as either
    would be inventing a fact about the house's insurance.
    """
    day = today or house_today()
    soon = day + timedelta(days=INSURANCE_WARN_DAYS)
    out = []
    for p in conn.execute(
            """SELECT insurance_policies.*, vehicles.name AS vehicle_name
                 FROM insurance_policies
                 LEFT JOIN vehicles ON vehicles.id = insurance_policies.vehicle_id
                ORDER BY COALESCE(insurance_policies.expiry_date, '9999-12-31')""").fetchall():
        expires = parse_date(p["expiry_date"] or "")
        if not expires:
            state, days = "no_date", None
        elif expires < day:
            state, days = "lapsed", (day - expires).days
        elif expires <= soon:
            state, days = "expiring", (expires - day).days
        else:
            state, days = "ok", (expires - day).days
        out.append({"policy": p, "expires": expires, "state": state, "days": days,
                    "what": p["coverage_type"] or "cover",
                    "on": p["vehicle_name"]})
    return out


def lapsed_cover(conn, today=None, include_vehicles=True):
    """Policies that have run out. Optionally without the vehicle ones.

    The vehicle check reports the CAR, by name, which is the more useful
    sentence — "the Berline is not legal to drive" beats "policy P-4471 has
    expired". So the owner's home page asks for these without them, or one
    lapsed van policy produces two lines about the same problem and the panel
    starts looking padded.
    """
    return [c for c in insurance_cover(conn, today)
            if c["state"] == "lapsed"
            and (include_vehicles or not c["policy"]["vehicle_id"])]


def vehicle_papers(conn, today=None):
    """Every vehicle, and whether it is legal to put a guest in it.

    Two dates, from two places, because one of them already had a home. The
    contrôle technique is on the vehicle; the insurance is a policy, which is
    where it has always been — insurance_policies.vehicle_id has existed since
    that table was built and nothing ever read the two together.

    Returns a row per vehicle with the worst state it is in, so a page can
    show one line rather than making somebody join it up in their head.
    """
    day = today or house_today()
    soon = day + timedelta(days=VEHICLE_PAPERS_WARN_DAYS)
    out = []
    for v in conn.execute("SELECT * FROM vehicles ORDER BY name").fetchall():
        policy = conn.execute(
            """SELECT * FROM insurance_policies
                WHERE vehicle_id = ? AND expiry_date IS NOT NULL AND expiry_date != ''
                ORDER BY expiry_date DESC LIMIT 1""", (v["id"],)).fetchone()
        ct = parse_date(v["ct_expires_on"] or "")
        ins = parse_date(policy["expiry_date"] or "") if policy else None

        problems = []
        # Order matters: expired first, because "expires in three weeks" read
        # above "expired last month" is how the urgent one gets skimmed past.
        if ct and ct < day:
            problems.append(("expired", "contrôle technique", ct))
        if ins and ins < day:
            problems.append(("expired", "insurance", ins))
        if ct and day <= ct <= soon:
            problems.append(("due", "contrôle technique", ct))
        if ins and day <= ins <= soon:
            problems.append(("due", "insurance", ins))
        if not ct:
            problems.append(("unknown", "contrôle technique", None))
        if not policy:
            problems.append(("unknown", "insurance", None))

        worst = ("ok", None, None)
        for state in ("expired", "due", "unknown"):
            hit = next((p for p in problems if p[0] == state), None)
            if hit:
                worst = hit
                break
        out.append({
            "vehicle": v, "policy": policy, "ct_expires": ct, "insurance_expires": ins,
            "problems": problems, "state": worst[0], "worst_what": worst[1],
            "worst_when": worst[2],
            # Off the road on purpose is not a problem to chase. A car up on
            # blocks with no CT is somebody's decision, not an oversight.
            "chase": worst[0] in ("expired", "due") and not v["off_road"],
        })
    return out


def watch_task_findings(conn, today=None):
    """The blocking findings, as (kind, title, note, due, priority) tuples.

    Titles have to be stable: they are the dedupe key, so the same problem on
    the same day must produce the same string every run or the list grows a
    duplicate every morning. That is also why nothing that moves on its own —
    an age in days, a countdown — belongs in a title; it goes in the note,
    which is rewritten in place instead.

    The kind is who it goes to: see WATCH_TASK_KINDS.
    """
    today = today or house_today()
    horizon = today + timedelta(days=14)
    found, dropped = [], {}

    def take(kind, items):
        if len(items) > WATCH_TASK_CAP:
            dropped[kind] = len(items) - WATCH_TASK_CAP
        return items[:WATCH_TASK_CAP]

    # A birthday or an anniversary belonging to somebody who will be IN THE
    # HOUSE for it. Not every date in the book: a card for a guest who is not
    # coming is a nice thought and not a job, and a list of those every morning
    # is how a list stops being read.
    #
    # Titled by the guest and the occasion rather than the date, because the
    # title is the dedupe key -- "in 3 days" in it would raise a fresh task
    # every morning until it happened.
    celebrations = []
    for row in upcoming_guest_dates(conn, within_days=14, today=today):
        guest = row["guest"]
        email = (guest["email"] or "").strip().casefold()
        here = conn.execute(
            """SELECT 1 FROM bookings
                WHERE status = 'confirmed'
                  AND (linked_guest_id = ?
                       OR (? != '' AND LOWER(TRIM(guest_email)) = ?))
                  AND arrival_date <= ? AND departure_date > ?
                LIMIT 1""",
            (guest["id"], email, email, row["when"].isoformat(),
             row["when"].isoformat())).fetchone()
        if not here:
            continue
        occasion = "birthday" if row["kind"] == "birthday" else "anniversary"
        celebrations.append((
            "celebration",
            f"{guest['name']} has a {occasion} while they are here",
            f"{format_date_human(row['when'].isoformat())}"
            + (" — VIP" if guest["vip"] else ""),
            row["when"].isoformat(),
            2,
        ))
    found.extend(take("celebration", celebrations))

    # Somebody has told us what they need and has been put somewhere that
    # asks something of them. Not an error -- eleven steps may be perfectly
    # fine for them, and only they know -- so the task is to ring and ask.
    #
    # WHAT THE GUEST SAID IS NOT IN IT. A task title is the least private
    # thing in the app: it goes on the calendar, into a notification, and
    # onto whoever it is assigned to. This names the booking and the room and
    # stops there. Reading the rest means opening a page that is the owner's.
    #
    # Titled by the booking rather than by the date, because the title is the
    # dedupe key and a date in it would raise a fresh task every morning.
    access = []
    for c in take("access", access_to_check(conn, days=45, today=today)):
        b = c["booking"]
        access.append((
            "access",
            f"Ring {b['reference_code']} before they arrive about the room",
            f"{b['room_name'] or 'No room allocated'} \u2014 {c['why']}. "
            "They have told us something about what they need; it is on "
            "What the house can manage.",
            b["arrival_date"],
            2,
        ))
    found.extend(access)

    # An agreement whose notice window is closing. Raised against the LAST
    # DAY NOTICE CAN BE GIVEN, not the renewal date -- by the time a renewal
    # is close enough to notice, the decision was taken months ago by nobody.
    #
    # Only the ones somebody can still act on. An agreement past its notice
    # date has renewed; that is a fact about the year ahead, not a job, and
    # asking every morning for a cancellation nobody can make any more is
    # how a list stops being read.
    agreements = []
    for a in take("agreement", agreements_to_decide(conn, within_days=60,
                                                    today=today)):
        r = a["row"]
        agreements.append((
            "agreement",
            f"Decide about {r['what']} before notice closes",
            f"Rolls over on {format_date_human(a['renews'].isoformat())}"
            + (f" at around \u20ac{r['annual_value']:,.0f} a year" if r["annual_value"] else "")
            + f". Notice has to be given by "
              f"{format_date_human(a['deadline'].isoformat())}"
            + (f" \u2014 {r['vendor_name']}." if r["vendor_name"] else "."),
            a["deadline"].isoformat(),
            2,
        ))
    found.extend(agreements)

    # A vehicle without valid papers. Titled by the vehicle and the document
    # rather than by a date, because the title is the dedupe key: putting
    # "expires in 12 days" in it would raise a fresh task every morning.
    # A policy running out, or already gone. Vehicle policies are left to the
    # vehicle finding, which says which car it is.
    for c in take("policy", [x for x in insurance_cover(conn, today)
                             if x["state"] in ("lapsed", "expiring")
                             and not x["policy"]["vehicle_id"]]):
        gone = c["state"] == "lapsed"
        found.append((
            "policy",
            f"{c['policy']['provider']} \u2014 {c['what']} "
            + ("has run out" if gone else "runs out soon"),
            (f"Policy {c['policy']['policy_number'] or '(no number)'}"
             + (f" ran out on {c['expires'].isoformat()}." if gone and c["expires"]
                else f" runs out on {c['expires'].isoformat()}." if c["expires"] else ".")
             + ("\n\nThe house is open to the public. This is cover it does not "
                "have, today." if gone else
                "\n\nRenew it, or record the new dates when the renewal comes in.")),
            (c["expires"].isoformat() if c["expires"] else today.isoformat()),
            "high" if gone else "normal"))

    # Short of its minimum with the decision date in sight. Self-closing like
    # the rest: one more confirmed booking and the next run drops it, which
    # is the honest behaviour -- the session is no longer at risk, whatever
    # a list of past problems might say.
    # Self-closing: record the filing and the obligation rolls to the next
    # one, so the finding is gone on the next run without anybody closing
    # a task by hand.
    for f in take("filing", filings_due(conn, today)):
        ob = f["obligation"]
        found.append((
            "filing",
            f"{ob['name']} \u2014 "
            + ("was due " if f["late"] else "due ") + f["due"].isoformat(),
            ((f"{-f['days']} day{'' if f['days'] == -1 else 's'} late. "
              "A late return is penalties and interest, not a telling-off."
              if f["late"] else
              f"Due in {f['days']} day{'' if f['days'] == 1 else 's'}.")
             + (f"\n\nTo: {ob['authority']}." if ob["authority"] else "")
             + (f"\n\n{ob['note']}" if ob["note"] else "")),
            f["due"].isoformat(),
            "high" if f["late"] else "normal"))

    # Self-closing like the rest: buy the clay and the next run drops it.
    for plan in take("materials", sessions_short_of_materials(conn, today)):
        missing = ", ".join(
            f"{l['shortfall']:g} {l['unit']} of {l['name']}"
            for l in plan["short"][:4])
        found.append((
            "materials",
            f"{plan['session']['title']} on {plan['session']['start_date']} "
            f"\u2014 not enough to run it",
            (f"Short of: {missing}"
             + (f", and {len(plan['short']) - 4} more" if len(plan["short"]) > 4
                else "")
             + f".\n\nCounted on {plan['heads']} confirmed "
               f"{'place' if plan['heads'] == 1 else 'places'}. More bookings "
               "means more of it."),
            plan["session"]["start_date"],
            "normal"))

    for w in take("workshop", [w for w in sessions_at_risk(conn, today) if w["urgent"]]):
        ring = w["waitlist_could_fill"]
        found.append((
            "workshop",
            f"{w['title']} on {w['start'].isoformat()} \u2014 {w['confirmed']} of "
            f"{w['minimum']} needed",
            (f"Short by {w['short']}. "
             + (f"{w['pending']} more registered without paying a deposit; "
                "they are not counted here because they have not paid. "
                if w["pending"] else "")
             + (f"\n\n{w['waiting']} on the waiting list, enough to cover it. "
                "Ring them before deciding anything else."
                if ring else
                f"\n\n{w['waiting']} on the waiting list, not enough to cover it."
                if w["waiting"] else
                "\n\nNobody is on the waiting list.")
             + (f"\n\nThe date for deciding passed on {w['decide_by'].isoformat()}."
                if w["overdue"] else
                f"\n\nDecide by {w['decide_by'].isoformat()}.")
             + f"\n\nRunning it as it stands takes \u20ac{w['taken']:.2f} against "
               f"\u20ac{w['at_minimum']:.2f} at the minimum."),
            w["decide_by"].isoformat(),
            "normal" if ring else "high" if w["overdue"] else "normal"))

    papers = [p for p in vehicle_papers(conn, today) if p["chase"]]
    for p in take("vehicle", papers):
        v, what, when = p["vehicle"], p["worst_what"], p["worst_when"]
        gone = p["state"] == "expired"
        found.append((
            "vehicle",
            f"{v['name']} \u2014 {what} {'has expired' if gone else 'runs out soon'}",
            (f"{what.capitalize()} "
             + (f"expired on {when.isoformat()}." if gone and when
                else f"expires on {when.isoformat()}." if when else "date not recorded.")
             + ("\n\nAn insurer can decline a claim on a vehicle with no valid "
                "contr\u00f4le technique, so this is not only a fine \u2014 it is a car "
                "carrying guests uninsured." if "technique" in what and gone
                else "\n\nBook it before the date, or mark the vehicle off the road."
                if not gone else
                "\n\nDo not carry guests in it until this is settled.")),
            (when.isoformat() if when else today.isoformat()),
            "high" if gone else "normal"))

    clashes = [c for c in rota_conflicts(conn, today, horizon)
               if c["kind"] == "certification"]
    for c in take("certification", clashes):
        found.append((
            "certification",
            f"Not qualified for the shift — {c['employee_name']}, {c['shift_date']}",
            f"{c['detail']}\n\nMove the shift or get the certificate renewed before then.",
            c["shift_date"], "high"))

    gaps = [g for g in cover_gaps(conn, today, horizon)
            if g["uncovered"] and (g["in_house"] or g["arrivals"])]
    for g in take("cover", gaps):
        who = (f"{g['in_house']} guest(s) in the house" if g["in_house"]
               else f"{g['arrivals']} arriving")
        found.append((
            "cover",
            f"Nobody rostered — {g['date']}",
            f"{who}, and nobody on the rota who can work that day.",
            g["date"], "high"))

    faults = [f for f in rooms_sold_with_a_fault(conn, today=today, days=14)
              if f["in_house"] or (f["days_away"] or 99) <= 7]
    for f in take("fault", faults):
        found.append((
            "fault",
            f"Open fault in a sold room — {f['room_name']}, {f['reference_code']}",
            f"{f['title']}. {f['guest_name']} "
            + ("is in the room now." if f["in_house"]
               else f"arrives {f['arrival_date']}.")
            + "\n\nFix it, move them, or tell them.",
            (today.isoformat() if f["in_house"] else f["arrival_date"]), "high"))

    overdue = incidents_awaiting_insurer(conn)["overdue"]
    for i in take("insurer", overdue):
        found.append((
            "insurer",
            f"Insurer not told — incident {i['id']}",
            f"{i['summary']}\n\n{i['age_days']:.0f} days ago; the window was "
            f"{i['allowed_days']}."
            + (" 48 hours is statutory for a workplace accident."
               if i["statutory"] else ""),
            today.isoformat(), "high"))

    # A blocker on the panel since the panel existed, and the only one that was
    # never raised as a job. It is also the one nobody trips over in the course
    # of a day: a broken radiator announces itself, a backup that stopped
    # arriving four months ago announces itself once, on the morning the
    # database is gone.
    age_h = backup_age_hours(conn)
    if age_h is None or age_h > BACKUP_STALE_HOURS:
        found.append((
            "backup", "No backup is arriving",
            f"The last full backup: {backup_gap_detail(age_h)}.\n\n"
            + backup_job_failure_note(conn)
            + "Admin → Backup takes one now. Admin → Automation says whether the "
              "scheduled one is switched on and whether it is failing.",
            today.isoformat(), "high"))

    # Jobs that have failed more than once running. Excludes the backup, which
    # the finding above already owns and describes better: "no copy has left
    # the building since the ninth" is the fact that matters, and raising a
    # second task saying the send failed would be the same problem twice.
    failing = [r for r in conn.execute(
        """SELECT job_name, last_message, consecutive_failures AS fails, last_ok_at
             FROM automation_runs
            WHERE last_status = 'failed' AND consecutive_failures >= ?
            ORDER BY consecutive_failures DESC, job_name""",
        (JOB_FAILURE_STREAK,)).fetchall() if r["job_name"] != "backup_email"]
    for j in take("job", failing):
        label = AUTOMATION_JOB_LABELS.get(j["job_name"], j["job_name"])
        found.append((
            "job", f"Automation stopped working — {j['job_name']}",
            f"{label}.\n\nFailed {j['fails']} runs in a row. Last worked: "
            + (house_date_iso(j["last_ok_at"]) if j["last_ok_at"] else "never")
            + f".\nIt reports: {j['last_message'] or 'no message'}"
            + "\n\nAdmin → Automation has the switch and a Run now button to "
              "try it while you watch.",
            today.isoformat(), "high"))

    return found, dropped


def generate_watch_tasks(conn, today=None):
    """Raise a task per blocking finding, and tick off any that have gone.

    Self-healing on purpose: nothing here has a "done" action of its own, so
    the second half is what stops the list rotting. A task raised for Tuesday
    disappears when Tuesday is covered, without anybody closing it by hand.

    Now that these are routed to a person they do carry a tick box, on that
    person's own list. Ticking one is not wrong and is not blocked: it just
    does not settle anything, because the next run finds the problem still
    true and raises it again. Which is the honest answer — the shift is still
    uncovered whatever the list says about it.
    """
    today = today or house_today()
    now_iso = datetime.now(timezone.utc).isoformat()
    found, dropped = watch_task_findings(conn, today)
    wanted = {title: (kind, note, due, prio) for kind, title, note, due, prio in found}
    routing = watch_task_assignees(conn)

    open_now = {r["title"]: r for r in conn.execute(
        """SELECT id, title, notes, priority, due_date, assigned_to_user_id
             FROM tasks WHERE origin = ? AND status != 'done'""",
        (WATCH_TASK_ORIGIN,)).fetchall()}

    made, moved = 0, 0
    for title, (kind, note, due, prio) in wanted.items():
        who = routing.get(kind)
        row = open_now.get(title)
        if row is None:
            conn.execute(
                """INSERT INTO tasks (assigned_to_user_id, title, notes, priority, due_date,
                     status, origin, created_at)
                   VALUES (?, ?, ?, ?, ?, 'open', ?, ?)""",
                (who, title, note, prio, due, WATCH_TASK_ORIGIN, now_iso))
            made += 1
            continue
        # The task is already open and stays open, but what it says about the
        # problem may have moved on — an age in days, or a route the owner has
        # since changed. Rewriting in place beats closing and re-raising, which
        # would read as the problem having been fixed and come back.
        if (row["assigned_to_user_id"] != who or row["notes"] != note
                or row["priority"] != prio or row["due_date"] != due):
            conn.execute(
                """UPDATE tasks SET assigned_to_user_id = ?, notes = ?, priority = ?,
                     due_date = ? WHERE id = ?""",
                (who, note, prio, due, row["id"]))
            moved += 1

    # The half that matters. Without it the list is a record of every problem
    # the house has ever had, which nobody reads twice.
    # Closed by TITLE, not by the id that happened to survive open_now.
    #
    # open_now is a dict keyed on title, so two watch rows sharing one title
    # collapse to a single entry and only that one was ever closed. The other
    # became permanent: nothing in this pass could reach it, and a watch task
    # has no "done" action of its own, so it sat on the list for good. That is
    # precisely the failure this half exists to prevent — a list that is a
    # record of every problem the house has ever had, which nobody reads twice.
    #
    # Duplicating a watch task from the tasks page was one way to make two.
    # That no longer copies the origin, but any pair already in the database
    # needs closing, and keying the close on title rather than id does both.
    closed = 0
    for title in list(open_now):
        if title in wanted:
            continue
        cur = conn.execute(
            """UPDATE tasks SET status = 'done', completed_at = ?
               WHERE origin = ? AND title = ? AND status != 'done'""",
            (now_iso, WATCH_TASK_ORIGIN, title))
        closed += cur.rowcount or 0

    conn.commit()
    return {"made": made, "closed": closed, "moved": moved,
            "open": len(wanted), "dropped": dropped}


def run_watch_tasks_job(conn):
    """Daily. Everything it raises has at least a day of notice, and running it
    oftener would only mean the same list rewritten."""
    r = generate_watch_tasks(conn)
    bits = []
    if r["made"]:
        bits.append(f"{r['made']} raised")
    if r["closed"]:
        bits.append(f"{r['closed']} closed — no longer true")
    if r["moved"]:
        bits.append(f"{r['moved']} rewritten (reassigned or restated)")
    if r["dropped"]:
        # Never silent: the pages carry the full set, and a capped list that
        # says nothing reads as a complete one.
        bits.append("capped at %d per kind (%s not raised)" % (
            WATCH_TASK_CAP,
            ", ".join(f"{v} more {k}" for k, v in sorted(r["dropped"].items()))))
    return ", ".join(bits) or "nothing to raise"


def record_maintenance_visit(conn, schedule_id, *, done_on, done_by=None, cost=None,
                             certificate=None, notes=None, user_id=None):
    """The work was done. Move the schedule on and close its task."""
    sched = conn.execute("SELECT * FROM maintenance_schedules WHERE id = ?",
                         (schedule_id,)).fetchone()
    if not sched:
        return None
    done = parse_date(done_on) if isinstance(done_on, str) else done_on
    if not done:
        return None
    task = conn.execute(
        """SELECT id FROM tasks WHERE origin = 'maintenance' AND title = ?
             AND status != 'done' ORDER BY id DESC LIMIT 1""",
        (maintenance_task_title(sched),)).fetchone()
    conn.execute(
        """INSERT INTO maintenance_visits (schedule_id, done_on, done_by, cost,
             certificate_filename, notes, task_id, recorded_by_user_id, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (schedule_id, done.isoformat(), done_by, cost, certificate, notes,
         task["id"] if task else None, user_id, datetime.now(timezone.utc).isoformat()))
    # Counted from the day it was done. A sweep six weeks late does not make
    # next year's sweep six weeks early.
    conn.execute(
        """UPDATE maintenance_schedules SET last_done_on = ?, next_due_on = ?
           WHERE id = ?""",
        (done.isoformat(),
         _add_months(done, max(1, sched["every_months"] or 12)).isoformat(),
         schedule_id))
    if task:
        conn.execute(
            "UPDATE tasks SET status = 'done', completed_at = ? WHERE id = ?",
            (datetime.now(timezone.utc).isoformat(), task["id"]))
    conn.commit()
    return True


def run_maintenance_job(conn):
    made = generate_maintenance_tasks(conn)
    return f"raised {made} maintenance task(s)"


@app.route("/management/maintenance")
@owner_required
def maintenance_page():
    """What the house is owed, soonest first, with anything overdue at the top."""
    conn = get_db()
    rows = [dict(r) for r in conn.execute(
        """SELECT maintenance_schedules.*, users.name AS assignee_name,
                  vendors.name AS vendor_name
             FROM maintenance_schedules
             LEFT JOIN users ON users.id = maintenance_schedules.assigned_to_user_id
             LEFT JOIN vendors ON vendors.id = maintenance_schedules.vendor_id
            ORDER BY active DESC, name""").fetchall()]
    for r in rows:
        r["status"] = maintenance_status(r)
        r["last_visit"] = conn.execute(
            """SELECT * FROM maintenance_visits WHERE schedule_id = ?
               ORDER BY done_on DESC LIMIT 1""", (r["id"],)).fetchone()
        r["visit_count"] = conn.execute(
            "SELECT COUNT(*) AS c FROM maintenance_visits WHERE schedule_id = ?",
            (r["id"],)).fetchone()["c"]
    # Overdue first, then whatever is nearest. A list ordered by name is a list
    # where the thing that matters is halfway down.
    order = {"overdue": 0, "soon": 1, "unknown": 2, "scheduled": 3}
    rows.sort(key=lambda r: (not r["active"], order.get(r["status"]["state"], 4),
                             r["status"]["days"] if r["status"]["days"] is not None else 9999))
    live = [r for r in rows if r["active"]]
    overdue = [r for r in live if r["status"]["state"] == "overdue"]
    # The two facts nobody puts together: this is overdue, AND somebody
    # outside the house expects it to have been done.
    exposed = [r for r in overdue if r["required_by"] != "none"]
    employees = conn.execute(
        "SELECT id, name FROM users WHERE status = 'active' ORDER BY name").fetchall()
    vendor_list = conn.execute("SELECT id, name FROM vendors ORDER BY name").fetchall()
    policies = conn.execute(
        "SELECT id, provider, coverage_type FROM insurance_policies ORDER BY provider").fetchall()
    conn.close()
    overview = [
        overview_cell("On a schedule", len(live)),
        overview_cell("Due soon", len([r for r in live if r["status"]["state"] == "soon"])),
        overview_cell("Overdue", len(overdue), alert=bool(overdue)),
        overview_cell("Somebody is expecting it", len(exposed), alert=bool(exposed),
                      hint="overdue and required"),
    ]
    return render_template(
        "maintenance.html", schedules=rows, overview=overview, exposed=exposed,
        employees=employees, vendors=vendor_list, policies=policies,
        categories=MAINTENANCE_CATEGORIES, required_by=MAINTENANCE_REQUIRED_BY,
        suggestions=MAINTENANCE_SUGGESTIONS, today=house_today())


@app.route("/admin/rota-clashes")
@owner_required
def rota_clashes_page():
    """Shifts that collide with something already on record.

    Forward-looking on purpose. The working-time checker answers "what went
    wrong last month"; this answers "what is about to", while there is still
    time to move somebody.
    """
    conn = get_db()
    today = house_today()
    try:
        days = max(1, min(180, int(request.args.get("days", 28))))
    except (TypeError, ValueError):
        days = 28
    end = today + timedelta(days=days)
    rows = rota_conflicts(conn, today, end)

    # Behind as well as ahead. A clash that already happened is not fixable,
    # but it is the evidence that this list is worth reading.
    past = rota_conflicts(conn, today - timedelta(days=14), today - timedelta(days=1))
    shifts_ahead = conn.execute(
        "SELECT COUNT(*) AS c FROM shifts WHERE shift_date >= ? AND shift_date <= ?",
        (today.isoformat(), end.isoformat())).fetchone()["c"]
    conn.close()

    by_kind = {}
    for r in rows:
        by_kind.setdefault(r["kind"], []).append(r)

    overview = [
        overview_cell("Shifts in the window", shifts_ahead),
        overview_cell("Cannot legally work", len(by_kind.get("certification", [])),
                      alert=bool(by_kind.get("certification")),
                      hint="a requirement of the role is missing or expired"),
        overview_cell("Rostered on approved leave", len(by_kind.get("leave", [])),
                      alert=bool(by_kind.get("leave"))),
        overview_cell("Rostered while absent", len(by_kind.get("absence", [])),
                      alert=bool(by_kind.get("absence"))),
        overview_cell("Went unnoticed", len(past), hint="last fortnight"),
    ]
    return render_template("rota_clashes.html", rows=rows, overview=overview,
                           by_kind=by_kind, kinds=ROTA_CONFLICT_KINDS,
                           past=past, days=days, today=today)


@app.route("/admin/cover")
@owner_required
def cover_gaps_page():
    """Days with work happening and nobody on to do it."""
    conn = get_db()
    today = house_today()
    try:
        days = max(1, min(180, int(request.args.get("days", 28))))
    except (TypeError, ValueError):
        days = 28
    end = today + timedelta(days=days)
    rows = cover_gaps(conn, today, end)

    gaps = [r for r in rows if r["uncovered"]]
    # The obvious next question on an uncovered day, answered on the same page
    # rather than left as an exercise. Only the nearest few: a list of every
    # free person for every gap is a wall of names nobody reads.
    for g in gaps[:5]:
        g["could_cover"] = who_could_cover(conn, g["date"])[:6]
    # Somebody IS rostered, but every one of them is on leave, absent or not
    # currently qualified. Worth separating: it reads as staffed on the rota,
    # which is exactly why nobody catches it.
    hollow = [r for r in gaps if r["people_count"] > 0]
    guests = [r for r in gaps if r["in_house"] or r["arrivals"]]

    conn.close()
    overview = [
        overview_cell("Days with work", len(rows)),
        overview_cell("Nobody on", len(gaps), alert=bool(gaps)),
        overview_cell("Looks staffed but isn't", len(hollow), alert=bool(hollow),
                      hint="everyone rostered is unable to work it"),
        overview_cell("With guests in the house", len(guests), alert=bool(guests)),
    ]
    return render_template("cover_gaps.html", rows=rows, gaps=gaps, hollow=hollow,
                           overview=overview, days=days, today=today)


