# Which part of the house a template belongs to, and where in a guest's
# progress it sits. Both are already in the key — they were just never used,
# so seventeen unrelated messages sat in one flat alphabetical list.
TEMPLATE_AREAS = [
    ("workshop", "Workshops"), ("restaurant", "Restaurant"),
    ("event", "Events"), ("room", "Rooms"),
]
TEMPLATE_STAGES = [
    ("received", "Enquiry received"), ("confirmed", "Confirmed"),
    ("deposit", "Deposit"), ("reminder", "Reminder"), ("balance", "Balance due"),
    ("waitlist", "Waitlist"), ("declined", "Declined"), ("cancelled", "Cancelled"),
    ("feedback", "After the stay"),
]


def template_area(key):
    for prefix, label in TEMPLATE_AREAS:
        if key.startswith(prefix):
            return label
    return "Other"


def template_stage(key):
    for token, label in TEMPLATE_STAGES:
        if token in key:
            return label
    return "Other"


def template_state(row, defaults):
    """Shipped wording, edited, or holding placeholder text.

    The third is the one worth being able to filter to: it means a guest is
    about to be sent "TEST SUBJECT". The send now refuses and substitutes the
    original, but that is a safety net, not a fix — the row still needs sorting.
    """
    if PLACEHOLDER_TEXT.search((row["subject"] or "") + " " + (row["body"] or "")):
        return "Needs fixing"
    want = defaults.get(row["template_key"])
    if want and (row["subject"], row["body"]) != want:
        return "Edited"
    return "Original wording"


@app.route("/management/email-templates")
@owner_required
def management_email_templates():
    conn = get_db()
    templates = conn.execute("SELECT * FROM email_templates ORDER BY label").fetchall()
    conn.close()
    defaults = {key: (subject, body) for key, _label, subject, body in DEFAULT_EMAIL_TEMPLATES}
    # Which ones have been changed from the original wording, so the editor can
    # offer a way back only where there is something to go back to.
    edited = {t["template_key"] for t in templates
              if t["template_key"] in defaults
              and (t["subject"], t["body"]) != defaults[t["template_key"]]}
    states = {t["template_key"]: template_state(t, defaults) for t in templates}
    # The merge tags each template actually uses. A single global list is
    # worse than none: this page carried the workshop tags above restaurant
    # and event templates that cannot use half of them.
    tags = {t["template_key"]: sorted(set(re.findall(
        r"\{(\w+)\}", (t["subject"] or "") + " " + (t["body"] or "")))) for t in templates}
    # And which ones are AVAILABLE, which is the half that was missing: the page
    # showed what each template used and never what it could use, so the only
    # way to find out was to guess a tag, save it, send one and look.
    available = {t["template_key"]: list(EMAIL_TEMPLATE_TAGS.get(t["template_key"], ()))
                 for t in templates}

    lv = list_view(
        templates, request.args,
        search=["label", "subject", "body"],
        search_hint="Search wording, subject or name",
        facets=[
            facet("area", "Part of the house", lambda t: template_area(t["template_key"]),
                  order=[label for _p, label in TEMPLATE_AREAS] + ["Other"]),
            facet("stage", "Stage", lambda t: template_stage(t["template_key"]),
                  order=[label for _t, label in TEMPLATE_STAGES] + ["Other"]),
            facet("state", "Wording", lambda t: states[t["template_key"]],
                  order=["Needs fixing", "Edited", "Original wording"]),
        ],
        sorts=[
            sort_option("area", "Part of the house",
                        lambda t: (template_area(t["template_key"]), t["label"] or "")),
            sort_option("name", "Name", lambda t: (t["label"] or "").lower()),
            sort_option("edited", "Recently edited", lambda t: t["updated_at"] or "",
                        reverse=True),
        ],
        default_sort="area",
    )
    return render_template("management_email_templates.html", templates=lv["rows"], lv=lv,
                           edited=edited, states=states, tags=tags,
                           available=available)


@app.route("/management/email-templates/<template_key>/restore", methods=["POST"])
@owner_required
def restore_email_template(template_key):
    """Put one template back to the wording it shipped with.

    Editing these is a one-way door otherwise: the originals only ever get
    written when the row is absent, so a template rewritten badly — or left
    holding test text — stays that way and goes out to guests.
    """
    default = next((d for d in DEFAULT_EMAIL_TEMPLATES if d[0] == template_key), None)
    if not default:
        abort(404)
    _key, _label, subject, body = default
    conn = get_db()
    conn.execute(
        "UPDATE email_templates SET subject = ?, body = ?, updated_at = NULL "
        "WHERE template_key = ?", (subject, body, template_key))
    log_audit(conn, "email_template_restored", target=template_key)
    conn.commit()
    conn.close()
    flash("Restored to the original wording.", "success")
    return redirect(url_for("management_email_templates"))


@app.route("/management/email-templates/<template_key>/edit", methods=["POST"])
@owner_required
def edit_email_template(template_key):
    subject = request.form.get("subject", "").strip()
    body = request.form.get("body", "").strip()
    if not subject or not body:
        flash("Subject and body are both required.", "error")
        return redirect(url_for("management_email_templates"))

    # REFUSED HERE, at the moment of the mistake. A tag nothing fills used to be
    # saved happily and only showed itself in a guest's inbox, and by then the
    # only person who could see it was the guest.
    stray = unknown_merge_tags(template_key, subject, body)
    if stray:
        allowed = ", ".join("{%s}" % t for t in EMAIL_TEMPLATE_TAGS.get(template_key, ()))
        flash("Nothing fills " + ", ".join("{%s}" % t for t in stray)
              + " in this message, so a guest would read it exactly like that. "
              + (f"This one can use: {allowed}." if allowed else ""), "error")
        return redirect(url_for("management_email_templates"))

    conn = get_db()
    existing = conn.execute("SELECT 1 FROM email_templates WHERE template_key = ?", (template_key,)).fetchone()
    if not existing:
        conn.close()
        abort(404)
    conn.execute(
        "UPDATE email_templates SET subject = ?, body = ?, updated_at = ? WHERE template_key = ?",
        (subject, body, datetime.now(timezone.utc).isoformat(), template_key),
    )
    log_audit(conn, "email_template_edited", target=template_key)
    conn.commit()
    conn.close()
    flash("Template updated.", "success")
    return redirect(url_for("management_email_templates"))


@app.route("/management/company-info", methods=["GET", "POST"])
@owner_required
def management_company_info():
    conn = get_db()
    if request.method == "POST":
        fields = [
            "legal_name", "registration_number", "vat_number", "registered_address",
            "incorporation_date", "accountant_name", "accountant_phone", "accountant_email",
            "insurance_broker_name", "insurance_broker_phone", "insurance_broker_email",
        ]
        values = [request.form.get(f, "").strip() or None for f in fields]
        conn.execute(
            f"""INSERT INTO company_info (id, {', '.join(fields)}, updated_at)
                VALUES (1, {', '.join(['?'] * len(fields))}, ?)
                ON CONFLICT(id) DO UPDATE SET {', '.join(f'{f} = excluded.{f}' for f in fields)}, updated_at = excluded.updated_at""",
            (*values, datetime.now(timezone.utc).isoformat()),
        )
        # Lives in app_settings rather than company_info: it isn't a fact about
        # the company, it's a number the booking forms enforce, and it belongs
        # with the other single-value settings the app already reads that way.
        capacity_raw = request.form.get("house_guest_capacity", "").strip()
        if capacity_raw.isdigit() and int(capacity_raw) > 0:
            conn.execute(
                """INSERT INTO app_settings (key, value) VALUES ('house_guest_capacity', ?)
                   ON CONFLICT(key) DO UPDATE SET value = excluded.value""",
                (capacity_raw,))
        log_audit(conn, "company_info_updated")
        conn.commit()
        conn.close()
        flash("Company info updated.", "success")
        return redirect(url_for("management_company_info"))
    info = conn.execute("SELECT * FROM company_info WHERE id = 1").fetchone()
    capacity = house_guest_capacity(conn)
    # Insurance lives here rather than on a page of its own. The broker was
    # already listed on this form while the policies sat somewhere else, which
    # is two places to look for one answer.
    policies = conn.execute(
        "SELECT * FROM insurance_policies ORDER BY expiry_date IS NULL, expiry_date").fetchall()
    conn.close()
    return render_template("management_company_info.html", info=info,
                           house_guest_capacity=capacity, policies=policies)


