# ---------------------------------------------------------------------------
# Backup — the database now holds bookings and guest contact details, not
# just staff records, so this matters more than it used to. Uses SQLite's
# own backup API for a consistent snapshot rather than copying the raw file,
# which could in principle catch a write mid-flight.
# ---------------------------------------------------------------------------

# What kind of thing an audit entry is. The action names are already
# structured — "vault_reveal", "employee_deleted", "backup_download" — so this
# is reading what is there rather than inventing a taxonomy.
AUDIT_KINDS = [
    ("Deletions", ("delete", "removed", "purge")),
    ("Secrets seen", ("vault", "reveal", "bank_detail", "password")),
    ("Money", ("refund", "payout", "invoice", "expense", "pay_rate", "payroll")),
    ("People", ("employee", "user", "role", "contract", "access")),
    ("Bookings", ("booking", "reservation", "registration", "no_show", "waitlist")),
    ("Backups & export", ("backup", "export", "download")),
]


def audit_kind(action):
    a = (action or "").lower()
    for label, tokens in AUDIT_KINDS:
        if any(t in a for t in tokens):
            return label
    return "Other"


def audit_list_view(conn, args):
    """The audit log as the page and the export both see it.

    Shared deliberately: the export button says "export this view", and a
    button that says that while writing a CSV of everything is worse than one
    that doesn't offer it.
    """
    # The old page took the most recent 200 and said so in small print. On a
    # compliance record that is the wrong shape: you come here asking "who
    # revealed a bank detail in March", and the answer was silently outside
    # the window. Filter first, cap afterwards, and say when a cap was hit.
    entries = conn.execute(
        """SELECT audit_log.*, users.name AS actor_name FROM audit_log
           LEFT JOIN users ON users.id = audit_log.actor_user_id
           ORDER BY audit_log.created_at DESC"""
    ).fetchall()

    today = house_today()

    def when(row):
        stamp = house_date_iso(row["created_at"])
        if not stamp:
            return None
        if stamp == today.isoformat():
            return "Today"
        if stamp >= (today - timedelta(days=7)).isoformat():
            return "Last 7 days"
        if stamp >= (today - timedelta(days=30)).isoformat():
            return "Last 30 days"
        if stamp >= (today - timedelta(days=365)).isoformat():
            return "This year"
        return "Older"

    return list_view(
        entries, args,
        search=["action", "target", "details", "actor_name"],
        search_hint="Search action, target, detail or who",
        facets=[
            facet("kind", "Kind", lambda e: audit_kind(e["action"]),
                  order=[label for label, _t in AUDIT_KINDS] + ["Other"]),
            facet("who", "Who", lambda e: e["actor_name"] or "Unknown", limit=8),
            facet("when", "When", when,
                  order=["Today", "Last 7 days", "Last 30 days", "This year", "Older"]),
            facet("action", "Action", lambda e: (e["action"] or "").replace("_", " "),
                  limit=10),
        ],
        sorts=[
            sort_option("recent", "Most recent first", lambda e: e["created_at"] or "",
                        reverse=True),
            sort_option("oldest", "Oldest first", lambda e: e["created_at"] or ""),
            sort_option("who", "Who did it",
                        lambda e: ((e["actor_name"] or "~").lower(), e["created_at"] or "")),
        ],
        default_sort="recent",
    )


@app.route("/admin/audit-log")
@owner_required
def audit_log():
    conn = get_db()
    lv = audit_list_view(conn, request.args)
    conn.close()
    cap = 400
    return render_template("audit_log.html", entries=lv["rows"][:cap], lv=lv, cap=cap,
                           capped=len(lv["rows"]) > cap)


@app.route("/admin/audit-log/export.csv")
@owner_required
def export_audit_log_csv():
    conn = get_db()
    # Same filters as the page, so "export this view" means it.
    lv = audit_list_view(conn, request.args)
    conn.close()
    fieldnames = ["created_at", "actor_name", "action", "target", "details"]
    name = "audit_log_filtered.csv" if lv["filtered"] else "audit_log.csv"
    return csv_response(fieldnames, lv["rows"], name)


def readiness_checks(conn):
    """Everything that has to be true before this is somebody's real business
    system, and what is merely optional.

    Written as data rather than prose because the answer changes as env vars
    get set — a checklist in DEPLOY.md goes stale the moment something is
    configured, and can't tell you that the owner password is still the seeded
    one. Severity is 'blocker' (do not go live), 'warn' (works, but you will
    regret it) or 'info' (optional feature, off).
    """
    out = []

    def add(severity, area, label, ok, detail):
        out.append({"severity": severity, "area": area, "label": label,
                    "ok": ok, "detail": detail})

    # Presence is not enough. The instruction for this variable is "run this
    # command and paste the result", and pasting the command itself is an easy
    # slip that looks completely fine: sessions persist, logins survive a
    # restart, nothing errors. But the value is then a string anybody can
    # guess, and a guessable session key means forged cookies — worse than no
    # key at all, because it fails silently instead of loudly.
    raw_secret = os.environ.get("FLASK_SECRET_KEY") or ""
    looks_like_command = any(
        marker in raw_secret.lower()
        for marker in ("python", "secrets.", "print(", "$(", "token_hex", "openssl"))
    too_short = 0 < len(raw_secret) < 32
    secret_ok = bool(raw_secret) and not looks_like_command and not too_short
    if not raw_secret:
        secret_detail = ("NOT set. A new key is generated every start, so everyone is "
                         "logged out each time the app restarts, and 'remember me' never works.")
    elif looks_like_command:
        secret_detail = ("Set to what looks like the COMMAND that generates a key, not the "
                         "key itself. Run it in a terminal and paste its output — a 64-character "
                         "hex string. As it stands the value is guessable, so session cookies "
                         "can be forged.")
    elif too_short:
        secret_detail = (f"Only {len(raw_secret)} characters. Use at least 32 — "
                         "`python -c \"import secrets; print(secrets.token_hex(32))\"`.")
    else:
        secret_detail = "Set — logins survive a restart."
    add("blocker", "Core", "Session secret key", secret_ok, secret_detail)

    add("blocker", "Core", "Debug mode off", not DEBUG_MODE,
        "Off." if not DEBUG_MODE else
        "ON. Anyone hitting an error gets an interactive Python console on your server.")

    add("warn", "Core", "Public web address", bool(PUBLIC_BASE_URL),
        f"{PUBLIC_BASE_URL}" if PUBLIC_BASE_URL else
        "Not set. Links in automated email (balance reminders, campaigns) will "
        "point at localhost and be useless to the recipient.")

    email_ok = email_enabled()
    held = conn.execute(
        "SELECT COUNT(*) AS c FROM email_outbox WHERE sent_at IS NULL").fetchone()["c"]
    if email_ok:
        email_detail = ("Resend" if resend_enabled() else "SMTP") + " configured."
    else:
        email_detail = "Not configured. No booking confirmations, no reminders, no campaigns."
        if held:
            email_detail += (f" {held} message{'' if held == 1 else 's'} "
                             f"{'is' if held == 1 else 'are'} being held until this is set up.")
    add("blocker", "Email", "Outbound email", email_ok, email_detail)

    # Guest-facing wording, checked by the app rather than only by the tests.
    # The restaurant confirmation has twice been left reading "TEST SUBJECT
    # {guest_name}" after someone exercised the template editor — it is data,
    # not code, so nothing in a diff or a commit shows it, and it would have
    # gone to every confirmed diner. A template that has lost a placeholder is
    # the same class of fault: no {guest_name} means "Hi ," to a paying guest.
    placeholder_templates, broken_templates = [], []
    defaults = {k: (subj, body) for k, _label, subj, body in DEFAULT_EMAIL_TEMPLATES}
    for row in conn.execute("SELECT template_key, subject, body FROM email_templates").fetchall():
        text = (row["subject"] or "") + " " + (row["body"] or "")
        if PLACEHOLDER_TEXT.search(text):
            placeholder_templates.append(row["template_key"])
        want = defaults.get(row["template_key"])
        if want and set(re.findall(r"\{(\w+)\}", want[0] + want[1])) - set(
                re.findall(r"\{(\w+)\}", text)):
            broken_templates.append(row["template_key"])
    if placeholder_templates:
        add("blocker", "Email", "Test text in guest email", False,
            f"{', '.join(placeholder_templates)} still contains placeholder wording. "
            "Guests receive this. Management → Email templates → Restore original wording.")
    if broken_templates:
        add("warn", "Email", "Email template missing a field", False,
            f"{', '.join(broken_templates)} has lost a placeholder like {{guest_name}}, "
            "so that detail arrives blank. Restore the original wording to fix it.")

    # Worth its own line: with a provider configured, anything still held is
    # mail that was actually rejected, which the email check above would
    # otherwise show as a clean pass.
    if held:
        add("warn" if email_ok else "info", "Email", "Held email", False,
            f"{held} message{'' if held == 1 else 's'} could not be sent and "
            f"{'is' if held == 1 else 'are'} waiting. Review them under Emails → Held email.")

    stripe_ok = stripe_enabled()
    add("warn", "Payments", "Stripe", stripe_ok,
        "Configured." if stripe_ok else
        "Not configured. Guests can still book; nobody can pay online.")
    if stripe_ok:
        add("blocker", "Payments", "Stripe webhook secret", bool(STRIPE_WEBHOOK_SECRET),
            "Set." if STRIPE_WEBHOOK_SECRET else
            "MISSING while Stripe is live. Payments will be taken and the booking "
            "never confirmed, because the confirmation arrives by webhook.")

    add("warn", "Security", "Vault encryption key", vault_enabled(),
        "Set." if vault_enabled() else
        "Not set. The Vault can't store anything, so codes and passwords have "
        "nowhere safe to live.")

    owner = conn.execute(
        "SELECT id, email, password_hash FROM users WHERE role = 'owner' LIMIT 1").fetchone()
    default_pw = bool(owner) and check_password_hash(owner["password_hash"], "changeme")
    add("blocker", "Security", "Owner password changed", not default_pw,
        "Changed." if not default_pw else
        "STILL THE SEEDED PASSWORD. Anyone who has seen the setup notes can log "
        "in as you.")

    # The setting is `terms_and_conditions`; an earlier version of this check
    # read a key that doesn't exist, so it reported "still a draft" for ever,
    # including after the terms had been replaced.
    terms = conn.execute(
        "SELECT value FROM app_settings WHERE key = 'terms_and_conditions'").fetchone()
    terms_draft = not terms or "DRAFT" in (terms["value"] or "")[:400]
    add("warn", "Legal", "Terms & conditions", not terms_draft,
        "Replaced." if not terms_draft else
        "Still the placeholder draft. Guests are agreeing to it at booking.")

    company = conn.execute(
        "SELECT registered_address FROM company_info WHERE id = 1").fetchone()
    has_address = bool(company and (company["registered_address"] or "").strip())
    add("warn", "Legal", "Registered address", has_address,
        "On file." if has_address else
        "Not set. Marketing email has to identify the sender by postal address; "
        "the footer currently omits it.")

    last_backup = conn.execute(
        "SELECT created_at FROM audit_log WHERE action IN ('backup_downloaded', 'backup_auto_sent') "
        "ORDER BY id DESC LIMIT 1").fetchone()
    days = None
    if last_backup:
        d = house_date(last_backup["created_at"])
        days = (house_today() - d).days if d else None
    add("warn", "Data", "Recent backup", days is not None and days <= 30,
        f"Last taken {days} day{'s' if days != 1 else ''} ago." if days is not None else
        "Never downloaded.")

    broken = conn.execute(
        """SELECT COUNT(*) AS c FROM time_entries
           WHERE clock_out_at IS NOT NULL AND clock_out_at < clock_in_at""").fetchone()["c"]
    add("warn", "Data", "Timesheets sane", broken == 0,
        "No impossible shifts." if not broken else
        f"{broken} shift{'s' if broken != 1 else ''} end before they start — "
        "payroll export is blocked until they're fixed.")

    # A private room is not bookable online, so an unset supplement is no
    # longer a way to give one away: the registration form offers shared
    # occupancy only and the route refuses 'solo' whatever is posted. What
    # matters instead is that a solo booking staff entered by hand actually
    # carries a price, since that one WAS quoted to somebody.
    unpriced_solo = conn.execute(
        """SELECT COUNT(*) AS c FROM workshop_bookings
           WHERE occupancy_type = 'solo'
             AND status NOT IN ('declined', 'cancelled')
             AND COALESCE(single_supplement, 0) = 0""").fetchone()["c"]
    if unpriced_solo == 1:
        solo_detail = ("1 solo registration carries no supplement, so that private "
                       "room is being given away. Set the agreed amount on it.")
    else:
        solo_detail = (f"{unpriced_solo} solo registrations carry no supplement, so those "
                       "private rooms are being given away. Set the agreed amount on each.")
    add("warn", "Workshops", "Private rooms arranged by hand", unpriced_solo == 0,
        "Every solo registration carries a supplement." if not unpriced_solo else solo_detail)

    # The backup job writes an audit line only when a send SUCCEEDS. With no
    # mail account configured it returns "no owner email configured" into the
    # automation log and stops — no error, no flag, nothing on any page. The
    # only honest question is therefore not "did it fail" but "did it happen":
    # if something scheduled every 24 hours has not happened in twice that,
    # it is broken whether or not anything ever complained.
    #
    # Deliberately measured against the configured interval rather than a
    # fixed number of days, so slowing the job down doesn't turn this check
    # into a permanent red light.
    auto = get_automation_settings(conn)
    backup_on = auto.get("automation_backup_email_enabled") == "1"
    try:
        interval_h = max(1.0, float(auto.get("automation_backup_interval_hours") or 24))
    except (TypeError, ValueError):
        interval_h = 24.0
    grace_h = max(48.0, interval_h * 2)

    last_backup = conn.execute(
        "SELECT created_at FROM audit_log WHERE action IN ('backup_downloaded', 'backup_auto_sent') "
        "ORDER BY created_at DESC LIMIT 1"
    ).fetchone()
    last_backup_at = last_backup["created_at"] if last_backup else None

    age_h = None
    if last_backup_at:
        stamp = parse_datetime_iso(last_backup_at)
        if stamp:
            age_h = (datetime.now(timezone.utc) - stamp).total_seconds() / 3600

    if not backup_on:
        # Off on purpose is a decision, not a fault. Still worth stating,
        # because "we have backups" and "backups are running" differ.
        add("warn", "Data", "Backups arriving", False,
            "Automatic backups are switched off. Nothing is being copied off the server — "
            "if the volume goes, so do the records. Admin - Automation turns it back on.")
    elif age_h is None:
        add("warn", "Data", "Backups arriving", False,
            "No backup has ever been taken. The job is switched on, so either it has not run "
            "yet or it cannot send — check Admin - Automation for what it last returned.")
    elif age_h > grace_h:
        # It used to say the job failed silently, which was true when it was
        # written and is not any more: every run records its outcome, its
        # message and how many it has failed in a row. So this says WHY rather
        # than speculating, and "check Automation" becomes the last resort
        # instead of the whole answer.
        days = age_h / 24
        run = conn.execute(
            """SELECT last_status, last_message, consecutive_failures AS fails
                 FROM automation_runs WHERE job_name = 'backup_email'""").fetchone()
        head = (f"Last backup was {days:.0f} day(s) ago, but one is meant to be taken "
                f"every {interval_h:.0f}h. ")
        if run and run["last_status"] == "failed":
            why = (f"The job has failed {run['fails']} run(s) in a row and reports: "
                   f"{run['last_message'] or 'no message'}")
        elif run and run["last_status"] == "ok":
            # The worst of the three: the job believes it worked, so the copy
            # is being made and is not arriving. That is an address problem or
            # a mailbox problem, not a job problem.
            why = ("The job reports success, so a copy is being made and is not "
                   "arriving — check the address it goes to, and that mailbox.")
        elif run:
            why = ("The job has run but recorded no outcome, which means it last ran "
                   "before outcomes were recorded. Admin - Automation has a Run now "
                   "button that will say.")
        else:
            why = ("The job has never run. Admin - Automation has a Run now button "
                   "that will say why.")
        add("warn", "Data", "Backups arriving", False, head + why)
    else:
        add("warn", "Data", "Backups arriving", True,
            f"Last backup {age_h:.0f}h ago, on a {interval_h:.0f}h schedule.")

    for label, token, why in (
        ("Kiosk display token", OFFICE_DISPLAY_TOKEN,
         "the wall display has to be logged in by hand and drops out after 12 hours"),
        ("Calendar sync token", ICAL_SYNC_TOKEN, "iCal sync can't be triggered on a schedule"),
        ("Daily digest token", DIGEST_TOKEN, "the daily summary email can't be triggered"),
        ("Outlook add-in token", GUEST_LOOKUP_TOKEN, "the Outlook add-in can't look anything up"),
    ):
        add("info", "Optional", label, bool(token), "Set." if token else f"Not set — {why}.")

    add("info", "Optional", "Mailbox scanning (Microsoft Graph)", graph_enabled(),
        f"{len(MS_GRAPH_MAILBOXES)} mailbox(es)." if graph_enabled() else
        "Not connected — inbox flags and reply drafting are off.")
    add("info", "Optional", "Reply drafting (Claude)", claude_configured(),
        "Configured." if claude_configured() else "Not configured.")
    return out


@app.route("/admin/readiness")
@owner_required
def admin_readiness():
    conn = get_db()
    checks = readiness_checks(conn)
    conn.close()
    blockers = [c for c in checks if c["severity"] == "blocker" and not c["ok"]]
    warnings = [c for c in checks if c["severity"] == "warn" and not c["ok"]]
    by_area = {}
    for c in checks:
        by_area.setdefault(c["area"], []).append(c)
    overview = [
        overview_cell("Must fix", len(blockers), alert=len(blockers)),
        overview_cell("Worth fixing", len(warnings), alert=len(warnings)),
        overview_cell("Checks passing", sum(1 for c in checks if c["ok"]),
                      sub=f"/{len(checks)}"),
    ]
    return render_template("admin_readiness.html", by_area=by_area, overview=overview,
                           blockers=blockers, warnings=warnings)


def build_backup_zip(include_media=True, skipped_out=None):
    """A zip of the database, and optionally the uploaded documents and room
    photos alongside it. Shared by the owner's manual download and the
    automated email job, so there is exactly one place that knows what a
    backup contains.

    `skipped_out`, if given a list, receives the name of every media file
    that could not be read. The zip already says so in FILES_SKIPPED.txt, but
    only to whoever opens it; this is how a caller can tell the owner on the
    day instead — the manual download writes it to the audit log, and the
    scheduled job puts it in the line recorded against the run.

    The database is the exception and is never skipped. A zip without it is
    not a backup, so if that copy fails the error is raised and the caller
    finds out."""
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        tmp_db_path = os.path.join(BASE_DIR, f"_backup_tmp_{secrets.token_hex(6)}.db")
        try:
            src = sqlite3.connect(DB_PATH)
            dst = sqlite3.connect(tmp_db_path)
            src.backup(dst)
            dst.close()
            src.close()
            zf.write(tmp_db_path, "gudanes_hr.db")
        finally:
            if os.path.exists(tmp_db_path):
                os.remove(tmp_db_path)

        missing = []
        if include_media:
            # A file that disappears between the listing and the write is
            # skipped, not fatal.
            #
            # os.walk lists what is on disk and zf.write reads it a moment
            # later; anything removed in between raises and, before this,
            # abandoned the whole backup. The app runs eight threads, so a
            # backup taken while somebody deletes an expense receipt — or
            # while the health-notes purge does its rounds — lost EVERYTHING
            # over one absent attachment. A backup missing one file is worth
            # having; no backup is not.
            #
            # What was skipped goes into the zip as a note, so a short backup
            # is visibly short rather than quietly incomplete — whoever
            # restores it can see that files were left out and how many.
            skipped = []
            for folder, arc_prefix in ((UPLOAD_DIR, "uploads"), (ROOM_PHOTO_DIR, "room_photos")):
                for root, _dirs, files in os.walk(folder):
                    for fname in files:
                        full = os.path.join(root, fname)
                        rel = os.path.relpath(full, folder)
                        try:
                            zf.write(full, os.path.join(arc_prefix, rel))
                        except (OSError, ValueError) as exc:
                            skipped.append(f"{arc_prefix}/{rel}: {exc}")
            if skipped:
                app.logger.warning("backup skipped %d unreadable file(s)",
                                   len(skipped))
                zf.writestr(
                    "FILES_SKIPPED.txt",
                    "These files were listed on disk but could not be read "
                    "when this backup was taken, so they are NOT in it.\n"
                    "Everything else, including the database, is.\n\n"
                    + "\n".join(skipped) + "\n")
            missing.extend(skipped)
        if skipped_out is not None:
            # The zip says what was left out, but only to whoever opens it.
            # This is how the caller can tell the owner today instead.
            skipped_out.extend(missing)
    return buf.getvalue()


@app.route("/admin/backup")
@owner_required
def download_backup():
    audit_conn = get_db()
    log_audit(audit_conn, "backup_downloaded")

    skipped = []
    zip_bytes = build_backup_zip(include_media=True, skipped_out=skipped)
    if skipped:
        # A download has nowhere to show a message, so the only place the owner
        # could ever learn this is the audit log. The zip says so as well.
        log_audit(audit_conn, "backup_files_skipped",
                  details=f"{len(skipped)}: " + "; ".join(skipped[:20]))
    audit_conn.commit()
    audit_conn.close()
    filename = f"gudanes-backup-{datetime.now(timezone.utc).strftime('%Y-%m-%d')}.zip"
    return app.response_class(
        zip_bytes, mimetype="application/zip",
        headers={"Content-Disposition": f'attachment; filename="{filename}"'},
    )


# A backup email lands in a real inbox outside Railway entirely, which is the
# point — the volume and the mailbox fail independently. Most providers cap
# an incoming message around 25MB; this stays well under that even after
# base64 inflates it by roughly a third.
BACKUP_EMAIL_MAX_BYTES = 15 * 1024 * 1024

# What a database-only backup has to say for itself. A named constant rather
# than a string inside the job, because the thing worth checking is that this
# sentence still names what is missing — and a test looking for the words
# anywhere in that function found them in its own return line and stayed green
# while the sentence itself was gutted.
BACKUP_MEDIA_OMITTED_NOTE = (
    "The database is attached, but uploaded documents and room photos were "
    "left out this time because the full backup was too large to email. "
    "Use Admin → Backup to download everything, including media.")


def send_backup_email(to_address, zip_bytes, filename, note=""):
    """Emails one backup zip as an attachment.

    Deliberately separate from send_email(): that function is on the
    critical path for every guest-facing message and only knows how to
    attach an .ics file. Backups are lower-stakes to get wrong (a failed
    send just tries again next tick) and don't belong sharing a code path
    with a booking confirmation."""
    if not to_address:
        return False, "no owner email configured"
    if resend_enabled():
        payload = {
            "from": RESEND_FROM, "to": [to_address],
            "subject": "Château de Gudanes — automated backup",
            "text": note or "Attached: a full backup of the database and uploaded files.",
            "attachments": [{
                "filename": filename,
                "content": base64.b64encode(zip_bytes).decode("ascii"),
            }],
        }
        try:
            req = Request(
                "https://api.resend.com/emails",
                data=json.dumps(payload).encode("utf-8"),
                headers={"Authorization": f"Bearer {RESEND_API_KEY}", "Content-Type": "application/json"},
                method="POST",
            )
            with urlopen(req, timeout=30) as resp:
                resp.read()
            return True, None
        except Exception as e:
            return False, str(e)
    if not email_enabled():
        return False, "no email provider configured"
    try:
        msg = EmailMessage()
        msg["Subject"] = "Château de Gudanes — automated backup"
        msg["From"] = SMTP_FROM
        msg["To"] = to_address
        msg.set_content(note or "Attached: a full backup of the database and uploaded files.")
        msg.add_attachment(zip_bytes, maintype="application", subtype="zip", filename=filename)
        context = ssl.create_default_context()
        with smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=30) as server:
            server.starttls(context=context)
            server.login(SMTP_USERNAME, SMTP_PASSWORD)
            server.send_message(msg)
        return True, None
    except Exception as e:
        return False, str(e)


# The fields the privacy notice promises to clear once the event is over, and
# the date column that says whether it is. Written as data so the notice and
# the code can be checked against each other by reading one list.
HEALTH_NOTE_FIELDS = [
    ("restaurant_bookings", ["dietary_notes"], "dinner_date"),
    ("workshop_bookings", ["dietary_notes", "medical_notes"], None),
]


def purge_health_notes(conn, today=None):
    """Clear dietary and medical notes once the thing they were for has passed.

    Health data under GDPR, kept only to cook for somebody safely, with no
    reason to hold it afterwards. The privacy notice says this happens; this
    is what makes that true.

    Returns a count per table. What was deleted is never logged — an audit
    line quoting the allergy it just removed would defeat the point.
    """
    today = today or house_today()
    iso = today.isoformat()
    cleared = {}

    n = conn.execute(
        """UPDATE restaurant_bookings SET dietary_notes = NULL
            WHERE dinner_date < ?
              AND dietary_notes IS NOT NULL AND TRIM(dietary_notes) != ''""",
        (iso,)).rowcount
    cleared["restaurant_bookings"] = n

    # Workshops date through their session rather than carrying one.
    n = conn.execute(
        """UPDATE workshop_bookings
              SET dietary_notes = NULL, medical_notes = NULL
            WHERE session_id IN (
                    SELECT id FROM workshop_sessions
                     WHERE COALESCE(end_date, start_date) < ?)
              AND ((dietary_notes IS NOT NULL AND TRIM(dietary_notes) != '')
                OR (medical_notes IS NOT NULL AND TRIM(medical_notes) != ''))""",
        (iso,)).rowcount
    cleared["workshop_bookings"] = n

    # The same note was copied into notifications.body when the booking was
    # made. Cleared by age rather than by dinner date, because a notification
    # carries no link back to the booking — 90 days is well past the longest
    # lead time the restaurant takes, so the service has certainly happened.
    cleared["notifications"] = conn.execute(
        """UPDATE notifications SET body = NULL
            WHERE kind = 'restaurant_booking'
              AND body IS NOT NULL AND TRIM(body) != ''
              AND created_at < ?""",
        ((datetime.now(timezone.utc) - timedelta(days=90)).isoformat(),)).rowcount

    total = sum(cleared.values())
    if total:
        log_audit(conn, "health_notes_purged", details=f"{total} record(s)")
    conn.commit()
    return cleared


# Long enough that nobody is deleting a live conversation, short enough to be
# a real answer to "how long do you keep it". Stated in the privacy notice, so
# changing it here means changing it there.
ENQUIRY_RETENTION_MONTHS = 12


def purge_dead_enquiries(conn, today=None):
    """Delete enquiries and waitlist requests that plainly came to nothing.

    Never touches a confirmed enquiry: that is the record of an event that
    took place, it carries a price, and it falls under accounting retention
    rather than this rule.

    A request is dead when the date it was for is long past, or when it was
    cancelled long ago. Both are judged from the date the guest cared about,
    not the date we happened to file it.
    """
    today = today or house_today()
    cutoff = _add_months(today, -ENQUIRY_RETENTION_MONTHS).isoformat()
    cleared = {}

    # Cancelled long ago, or a request for a date that passed long ago and was
    # never taken up. COALESCE because an enquiry may name only one date.
    cleared["event_inquiries"] = conn.execute(
        """DELETE FROM event_inquiries
            WHERE status != 'confirmed'
              AND COALESCE(end_date, preferred_date, alternate_date,
                           SUBSTR(created_at, 1, 10)) < ?""",
        (cutoff,)).rowcount

    cleared["waitlist_entries"] = conn.execute(
        """DELETE FROM waitlist_entries
            WHERE COALESCE(desired_departure, desired_arrival,
                           SUBSTR(created_at, 1, 10)) < ?""",
        (cutoff,)).rowcount

    cleared["restaurant_waitlist"] = conn.execute(
        """DELETE FROM restaurant_waitlist
            WHERE COALESCE(desired_date, SUBSTR(created_at, 1, 10)) < ?""",
        (cutoff,)).rowcount

    # Workshop waitlists date through their session, and a request against a
    # session that no longer exists is dead by definition.
    cleared["workshop_waitlist"] = conn.execute(
        """DELETE FROM workshop_waitlist
            WHERE session_id IS NULL
               OR session_id NOT IN (SELECT id FROM workshop_sessions)
               OR session_id IN (
                    SELECT id FROM workshop_sessions
                     WHERE COALESCE(end_date, start_date) < ?)""",
        (cutoff,)).rowcount

    total = sum(cleared.values())
    if total:
        log_audit(conn, "dead_enquiries_purged", details=f"{total} record(s)")
    conn.commit()
    return cleared


def run_health_notes_purge_job(conn):
    """The retention pass, daily. Everything the privacy notice promises to
    delete is deleted here, so the notice can be checked against one function
    rather than hunted for across the app.

    Nothing here is urgent to the hour: a day late is a day of data nobody
    needed rather than a service failure.
    """
    cleared = purge_health_notes(conn)
    cleared.update(purge_dead_enquiries(conn))
    cleared.update(purge_police_register(conn))
    cleared.update(purge_stale_access_needs(conn))
    done = {k: v for k, v in cleared.items() if v}
    if not done:
        return "nothing to clear"
    return ", ".join(f"{k}: {v}" for k, v in done.items())


def run_backup_email_job(conn):
    """Emails a backup zip to the owner on a schedule, so a lost or
    corrupted Railway volume isn't the only copy. Falls back to the
    database alone if the full zip (with uploads and room photos) is too
    big to email — a smaller backup that actually arrives beats a bigger
    one that a mail provider silently drops."""
    to_address = owner_email(conn)
    if not to_address:
        raise JobFailed("no owner email configured, so there is nowhere to send a backup")
    date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    skipped = []
    zip_bytes = build_backup_zip(include_media=True, skipped_out=skipped)
    note = ""
    if len(zip_bytes) > BACKUP_EMAIL_MAX_BYTES:
        zip_bytes = build_backup_zip(include_media=False)
        note = BACKUP_MEDIA_OMITTED_NOTE
        if len(zip_bytes) > BACKUP_EMAIL_MAX_BYTES:
            raise JobFailed(
                f"even the database alone is {len(zip_bytes) // (1024 * 1024)}MB, "
                "too large to email — take one from Admin → Backup instead")
    filename = f"gudanes-backup-{date_str}.zip"
    ok, error = send_backup_email(to_address, zip_bytes, filename, note)
    if not ok:
        raise JobFailed(f"send failed: {error}")
    log_audit(conn, "backup_auto_sent")
    conn.commit()
    short = f", {len(skipped)} file(s) unreadable and left out" if skipped else ""
    return (f"sent to {to_address} ({len(zip_bytes) // 1024}KB)"
            f"{' (database only)' if note else ''}{short}")


