@app.route("/admin/approvals")
@owner_required
def admin_approvals():
    conn = get_db()
    period = period_from_request()
    overview = financial_overview(conn, period, house_today())
    leave = conn.execute(
        """SELECT leave_requests.*, users.name AS employee_name FROM leave_requests
           JOIN users ON users.id = leave_requests.user_id
           WHERE leave_requests.status = 'pending'"""
    ).fetchall()
    expenses = conn.execute(
        """SELECT expenses.*, users.name AS submitter_name FROM expenses
           LEFT JOIN users ON users.id = expenses.submitted_by_user_id
           WHERE expenses.status = 'pending'"""
    ).fetchall()
    # Timesheet corrections are a third thing an employee submits and waits on
    # a decision for, but they lived in their own page, so "Approvals" wasn't
    # actually the list of everything awaiting the owner.
    corrections = conn.execute(
        """SELECT timesheet_corrections.*, users.name AS employee_name,
                  time_entries.clock_in_at, time_entries.clock_out_at
           FROM timesheet_corrections
           JOIN users ON users.id = timesheet_corrections.user_id
           LEFT JOIN time_entries ON time_entries.id = timesheet_corrections.time_entry_id
           WHERE timesheet_corrections.status = 'pending'"""
    ).fetchall()
    conn.close()
    queue = (
        [{"kind": "leave", "sort_at": r["requested_at"], "row": r} for r in leave]
        + [{"kind": "expense", "sort_at": r["submitted_at"], "row": r} for r in expenses]
        + [{"kind": "correction", "sort_at": r["created_at"], "row": r} for r in corrections]
    )
    queue.sort(key=lambda item: item["sort_at"] or "")
    return render_template("admin_approvals.html", queue=queue,
                           overview=overview, period=period)


@app.route("/admin/approvals/bulk", methods=["POST"])
@owner_required
def bulk_approve_queue():
    items = request.form.getlist("items")
    conn = get_db()
    now = datetime.now(timezone.utc).isoformat()
    leave_count, expense_count = 0, 0
    skipped = []
    to_notify = []
    for item in items:
        kind, _, raw_id = item.partition(":")
        if not raw_id.isdigit():
            skipped.append((item[:30], "not something that can be approved"))
            continue
        item_id = int(raw_id)
        if kind == "leave":
            # Fetched WITHOUT the pending filter on purpose, so an item somebody
            # else has already decided can be told apart from one that has gone.
            # Both were the same silent `continue`, and the commonest case by far
            # is two people working the queue at once.
            req = conn.execute(
                "SELECT * FROM leave_requests WHERE id = ?", (item_id,)
            ).fetchone()
            who = conn.execute("SELECT name FROM users WHERE id = ?",
                               (req["user_id"],)).fetchone() if req else None
            if not req:
                skipped.append((f"time off #{item_id}", "no longer there"))
                continue
            if req["status"] != "pending":
                skipped.append((who["name"] if who else f"time off #{item_id}",
                                f"already {req['status']}"))
                continue
            conn.execute(
                "UPDATE leave_requests SET status = 'approved', decided_at = ? WHERE id = ?",
                (now, item_id),
            )
            leave_count += 1
            employee = conn.execute("SELECT * FROM users WHERE id = ?", (req["user_id"],)).fetchone()
            if employee:
                to_notify.append((employee["email"], employee["name"], req["start_date"], req["end_date"]))
        elif kind == "expense":
            row = conn.execute(
                "SELECT id, status FROM expenses WHERE id = ?", (item_id,)
            ).fetchone()
            if not row:
                skipped.append((f"expense #{item_id}", "no longer there"))
                continue
            if row["status"] != "pending":
                skipped.append((f"expense #{item_id}",
                                f"already {row['status']}"))
                continue
            conn.execute(
                "UPDATE expenses SET status = 'approved', decided_at = ? WHERE id = ?",
                (now, item_id),
            )
            expense_count += 1
        else:
            # Neither kind. Silently ignored before, which meant a stale page
            # posting an item type that no longer exists looked like a success.
            skipped.append((item[:30], "not something this queue approves"))
    conn.commit()
    conn.close()
    for email, name, start_date, end_date in to_notify:
        send_email(
            email, "Your time off request has been approved",
            f"Hi {name.split(' ')[0]},\n\n"
            f"Your time off request for {start_date} to {end_date} has been approved.\n\n"
            f"— Château de Gudanes",
        )
    # The breakdown stays -- two kinds of thing go through this one queue and
    # the owner wants to know which -- but it is no longer the whole message.
    detail = (f"{leave_count} time off, {expense_count} expense"
              f"{'' if expense_count == 1 else 's'}")
    flash(*bulk_message("Approved", "item", leave_count + expense_count,
                        skipped, detail=detail))
    return redirect(url_for("admin_approvals"))


@app.route("/admin/leave/settings", methods=["POST"])
@owner_required
def save_leave_settings():
    """The two figures that differ by convention collective."""
    raw_rate = (request.form.get("leave_accrual_days_per_month", "") or "").strip().replace(",", ".")
    raw_month = (request.form.get("leave_year_start_month", "") or "").strip()
    try:
        rate = round(float(raw_rate), 3)
    except ValueError:
        flash("Days per month has to be a number, like 2.5.", "error")
        return redirect(url_for("admin_leave"))
    if not (0 < rate <= 31):
        flash("Days per month has to be more than nothing and less than a month.", "error")
        return redirect(url_for("admin_leave"))
    try:
        month = int(raw_month)
    except ValueError:
        month = 1
    month = min(max(month, 1), 12)
    conn = get_db()
    for key, value in (("leave_accrual_days_per_month", f"{rate:g}"),
                       ("leave_year_start_month", str(month))):
        conn.execute(
            """INSERT INTO app_settings (key, value) VALUES (?, ?)
               ON CONFLICT(key) DO UPDATE SET value = excluded.value""", (key, value))
    log_audit(conn, "leave_settings_changed",
              details=f"{rate:g} days per month, year starts month {month}")
    conn.commit()
    conn.close()
    flash("Saved. It applies to everybody from now on.", "success")
    return redirect(url_for("admin_leave"))


@app.route("/admin/leave")
@owner_required
def admin_leave():
    conn = get_db()
    requests_ = conn.execute(
        """SELECT leave_requests.*, users.name AS employee_name FROM leave_requests
           JOIN users ON users.id = leave_requests.user_id
           ORDER BY (leave_requests.status = 'pending') DESC, start_date DESC"""
    ).fetchall()
    # Shifts and open tasks already scheduled during a requested range —
    # surfaced so the owner sees the clash before approving, not after.
    conflicts = {}
    task_conflicts = {}
    for r in requests_:
        clashing = conn.execute(
            "SELECT * FROM shifts WHERE user_id = ? AND shift_date >= ? AND shift_date <= ? ORDER BY shift_date",
            (r["user_id"], r["start_date"], r["end_date"]),
        ).fetchall()
        if clashing:
            conflicts[r["id"]] = clashing
        clashing_tasks = conn.execute(
            """SELECT * FROM tasks WHERE assigned_to_user_id = ? AND status != 'done'
               AND due_date >= ? AND due_date <= ? ORDER BY due_date""",
            (r["user_id"], r["start_date"], r["end_date"]),
        ).fetchall()
        if clashing_tasks:
            task_conflicts[r["id"]] = clashing_tasks
    # What the house is actually doing that week. Approving leave is a
    # staffing decision, and it was being made with none of the staffing
    # information — their own shifts, but not the twenty-cover dinner, the
    # workshop, or the fact that two other people are already off.
    # Only for the ones still to decide; the rest is history.
    impact = {r["id"]: leave_impact(conn, r["start_date"], r["end_date"], r["user_id"])
              for r in requests_ if r["status"] == "pending"}
    # What each person has EARNED so far, beside what they have booked. The
    # balance alone answers "how much of the allowance is left", which is the
    # wrong question for anybody who did not work the whole year.
    accrual_rate = leave_setting(conn, "leave_accrual_days_per_month")
    leave_year_start = int(leave_setting(conn, "leave_year_start_month", float))
    accruals = {
        u["id"]: leave_accrual(conn, u)
        for u in conn.execute(
            "SELECT * FROM users WHERE role = 'employee' AND status = 'active'").fetchall()
    }
    balances = {
        u["id"]: leave_balance(conn, u["id"], u["annual_leave_days"])
        for u in conn.execute("SELECT id, annual_leave_days FROM users WHERE role = 'employee'").fetchall()
    }
    conn.close()
    return render_template(
        "admin_leave.html", requests=requests_, conflicts=conflicts, task_conflicts=task_conflicts,
        balances=balances, impact=impact, accruals=accruals, accrual_rate=accrual_rate,
        leave_year_start=leave_year_start,
        months_of_year=[(i, date(2000, i, 1).strftime("%B")) for i in range(1, 13)],
    )


@app.route("/admin/leave/export.csv")
@owner_required
def export_leave_csv():
    conn = get_db()
    rows = conn.execute(
        """SELECT leave_requests.*, users.name AS employee_name FROM leave_requests
           JOIN users ON users.id = leave_requests.user_id
           ORDER BY (leave_requests.status = 'pending') DESC, start_date DESC"""
    ).fetchall()
    conn.close()
    fieldnames = ["employee_name", "leave_type", "start_date", "end_date", "status", "reason", "requested_at"]
    return csv_response(fieldnames, rows, "leave_requests.csv")


@app.route("/admin/leave/<int:request_id>/decide", methods=["POST"])
@owner_required
def decide_leave(request_id):
    status = request.form.get("status", "")
    if status not in ("approved", "declined"):
        abort(400)
    conn = get_db()
    req = conn.execute("SELECT * FROM leave_requests WHERE id = ?", (request_id,)).fetchone()
    if not req:
        conn.close()
        abort(404)
    cur = conn.execute(
        "UPDATE leave_requests SET status = ?, decided_at = ? WHERE id = ? AND status = 'pending'",
        (status, datetime.now(timezone.utc).isoformat(), request_id),
    )
    conn.commit()
    if cur.rowcount == 0:
        conn.close()
        flash("Already decided.", "success")
        return redirect(url_for("admin_leave"))
    employee = conn.execute("SELECT * FROM users WHERE id = ?", (req["user_id"],)).fetchone()
    if employee:
        send_email(
            employee["email"],
            f"Your time off request has been {status}",
            f"Hi {employee['name'].split(' ')[0]},\n\n"
            f"Your time off request for {req['start_date']} to {req['end_date']} has been {status}.\n\n"
            f"— Château de Gudanes",
        )
        send_notification(
            conn, employee["id"], "leave_decided", f"Your time off request has been {status}",
            body=f"{req['start_date']} to {req['end_date']}", link="/leave",
        )
    conn.close()
    flash(f"Request {status}.", "success")
    return redirect(url_for("admin_leave"))


