# ---------------------------------------------------------------------------
# Outlook add-in — a small taskpane shown when reading an email, so opening
# a message from a past or prospective guest surfaces their room/dinner/
# workshop bookings without switching to the app. Works in Outlook desktop,
# Outlook on the web, and Outlook on mobile — "on the web" is what covers
# Safari, since Office Add-ins don't have a separate Safari-specific build.
# The manifest and taskpane are public URLs (Outlook's own client fetches
# them directly, unauthenticated, the same way a browser fetches any page)
# but the actual guest data endpoint is gated by GUEST_LOOKUP_TOKEN, entered
# once into the taskpane and stored in the user's own Outlook profile —
# never baked into the page source.
# ---------------------------------------------------------------------------

OUTLOOK_ADDIN_GUID = "31db9023-97b7-4519-8829-c0b1e3bed58e"


def guest_lookup_by_email(conn, email):
    rooms = conn.execute(
        """SELECT bookings.reference_code, rooms.name AS room_name, bookings.arrival_date,
                  bookings.departure_date, bookings.party_size, bookings.status,
                  bookings.payment_status, bookings.total_price, bookings.special_requests
           FROM bookings JOIN rooms ON rooms.id = bookings.room_id
           WHERE bookings.guest_email = ? ORDER BY bookings.arrival_date DESC LIMIT 10""",
        (email,),
    ).fetchall()
    restaurant = conn.execute(
        """SELECT reference_code, dinner_date, party_size, status, payment_status, dietary_notes
           FROM restaurant_bookings WHERE guest_email = ? ORDER BY dinner_date DESC LIMIT 10""",
        (email,),
    ).fetchall()
    workshops = conn.execute(
        """SELECT workshop_bookings.reference_code, workshops.title, workshop_sessions.start_date,
                  workshop_sessions.end_date, workshop_bookings.party_size, workshop_bookings.status
           FROM workshop_bookings
           JOIN workshop_sessions ON workshop_sessions.id = workshop_bookings.session_id
           JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshop_bookings.guest_email = ? ORDER BY workshop_sessions.start_date DESC LIMIT 10""",
        (email,),
    ).fetchall()
    return {
        "email": email,
        "rooms": [dict(r) for r in rooms],
        "restaurant": [dict(r) for r in restaurant],
        "workshops": [dict(r) for r in workshops],
    }


def claude_configured():
    return bool(ANTHROPIC_API_KEY)


def current_offerings_snapshot(conn):
    """A short, current snapshot of what's actually on offer right now --
    the same kind of ground truth guess_email_conflict cross-references,
    just not tied to matching one specific category. Deliberately narrow to
    guest-facing pricing/availability and policy text -- nothing from HR,
    financials, or the vault belongs in a prompt like this."""
    today = house_today_iso()
    rooms = conn.execute(
        "SELECT name, price_per_night, max_occupancy FROM rooms WHERE active = 1 ORDER BY name"
    ).fetchall()
    workshop_sessions = conn.execute(
        """SELECT workshops.title, workshops.price_per_person, workshop_sessions.start_date, workshop_sessions.end_date
           FROM workshop_sessions JOIN workshops ON workshops.id = workshop_sessions.workshop_id
           WHERE workshops.active = 1 AND workshop_sessions.start_date >= ?
           ORDER BY workshop_sessions.start_date LIMIT 10""",
        (today,),
    ).fetchall()
    restaurant_settings = get_restaurant_settings(conn)
    terms_row = conn.execute("SELECT value FROM app_settings WHERE key = 'terms_and_conditions'").fetchone()
    return {
        "active_rooms": [dict(r) for r in rooms],
        "upcoming_workshop_sessions": [dict(w) for w in workshop_sessions],
        "restaurant": dict(restaurant_settings) if restaurant_settings else None,
        "terms_and_conditions": terms_row["value"] if terms_row else "",
    }


def gather_reply_context(conn, recipient_email):
    return {
        "guest_history": guest_lookup_by_email(conn, recipient_email) if recipient_email else None,
        "current_offerings": current_offerings_snapshot(conn),
    }


# ---------------------------------------------------------------------------
# Taxe de séjour and VAT.
#
# Taxe de séjour is NOT revenue. It is collected from the guest on the
# commune's behalf and owed onward — a liability, outside VAT, and it must
# appear as its own line on the bill. Folding it into the room price would
# overstate turnover AND have the château declaring VAT on a tax it merely
# collects.
#
# VAT is not one rate either. In France accommodation and restaurant food are
# 10%, alcohol is 20%. A single hardcoded rate overstates deductible VAT on
# roughly half of what this business sells.
# ---------------------------------------------------------------------------

TAX_DEFAULTS = {
    "city_tax_per_adult_per_night": "0.80",
    "city_tax_exempt_under_age": "18",
    "vat_accommodation": "10",
    "vat_food": "10",
    "vat_alcohol": "20",
    "vat_workshops": "20",
    "vat_extras": "20",
    "vat_events": "20",
    "city_tax_account": "",          # where the collected tax is parked
}

# Where each kind of income lands. Revenue is class 7 in the plan comptable,
# and only the accountant knows which of the 154 revenue accounts is right for a
# workshop -- so the account against each of these is set on /admin/pennylane.
#
# THESE ARE THE SEED, NOT THE LIST. The live list is the revenue_categories
# table, because the owner adds to it and renames it as their own chart changes.
# The KEY is what the app maps a stream to and never changes; the LABEL is
# theirs to edit. Renaming "F&B" does not silently unhook the till.
#
# What each key is fed by, so a reader can check nothing is orphaned:
#   nightly   room stays
#   fnb       restaurant reservations and the till
#   transport transfers -- an extra whose revenue_category says so
#   extras    every other extra
#   workshops atelier registrations
#   events    weddings and hire
#   city_tax  taxe de sejour, collected for the commune
#   taxes     nothing automatically; here because the owner asked for it, and
#             something has to be pointed at it by hand before it fills up
REVENUE_CATEGORY_SEED = [
    ("nightly", "Nightly", 10, 1),
    ("fnb", "F&B", 20, 1),
    ("transport", "Transport", 30, 1),
    ("extras", "Extras", 40, 1),
    ("workshops", "Workshops", 50, 1),
    ("events", "Events", 60, 1),
    ("city_tax", "City tax", 70, 1),
    ("taxes", "Taxes", 80, 1),
]

# The old key for each new one, so an account already mapped is carried across
# rather than silently emptied. rooms and restaurant/pos were the previous
# names; pennylane_account_* was a SECOND set of keys that the senders read and
# the page never wrote -- which is the bug this replaces.
REVENUE_CATEGORY_MIGRATION = {
    "nightly": ("revenue_account_rooms", "pennylane_account_accommodation"),
    "fnb": ("revenue_account_restaurant", "revenue_account_pos",
            "pennylane_account_restaurant"),
    "extras": ("revenue_account_extras", "pennylane_account_extras"),
    "workshops": ("revenue_account_workshops", "pennylane_account_workshops"),
    "events": ("revenue_account_events", "pennylane_account_events"),
    "city_tax": ("pennylane_account_city_tax",),
}


def seed_revenue_categories(conn):
    """Put the built-in categories in place, once, carrying old mappings over.

    Idempotent: an existing row is left exactly as the owner edited it. Only the
    ledger account is filled in, and only when it is still blank, so a category
    they have already pointed somewhere is never repointed by a deploy.
    """
    existing = {r["key"] for r in conn.execute(
        "SELECT key FROM revenue_categories").fetchall()}
    now = datetime.now(timezone.utc).isoformat()
    for key, label, order, builtin in REVENUE_CATEGORY_SEED:
        if key in existing:
            continue
        account = ""
        for old_key in REVENUE_CATEGORY_MIGRATION.get(key, ()):
            row = conn.execute("SELECT value FROM app_settings WHERE key = ?",
                               (old_key,)).fetchone()
            if row and (row["value"] or "").strip():
                account = row["value"].strip()
                break
        conn.execute(
            """INSERT INTO revenue_categories (key, label, ledger_account,
               sort_order, active, builtin, created_at)
               VALUES (?, ?, ?, ?, 1, ?, ?)""",
            (key, label, account or None, order, builtin, now))
    conn.commit()


def revenue_categories(conn, include_inactive=False):
    sql = "SELECT * FROM revenue_categories"
    if not include_inactive:
        sql += " WHERE active = 1"
    return conn.execute(sql + " ORDER BY sort_order, label").fetchall()


def revenue_account_for(conn, key):
    """The ledger account for a category, or "" if nobody has set one.

    Blank is returned rather than a guess. An invoice line with no account is a
    line the accountant codes; a line with the WRONG account is one nobody
    notices, and unpicking it later means finding every invoice it went on.
    """
    row = conn.execute(
        "SELECT ledger_account FROM revenue_categories WHERE key = ?",
        (key,)).fetchone()
    return ((row["ledger_account"] if row else "") or "").strip()


def revenue_category_label(conn, key):
    row = conn.execute("SELECT label FROM revenue_categories WHERE key = ?",
                       (key,)).fetchone()
    return (row["label"] if row else key) or key

